-- BSB verses (5422). Requires books and chapters first.
insert into public.verses (chapter_id, number, osis_ref, text)
select c.id, x.verse, x.ref, x.body
from (values
('PSA', 13, 3, 'PSA.13.3', 'Consider me and respond, O LORD my God. Give light to my eyes, lest I sleep in death,'),
('PSA', 13, 4, 'PSA.13.4', 'lest my enemy say, “I have overcome him,” and my foes rejoice when I fall.'),
('PSA', 13, 5, 'PSA.13.5', 'But I have trusted in Your loving devotion; my heart will rejoice in Your salvation.'),
('PSA', 13, 6, 'PSA.13.6', 'I will sing to the LORD, for He has been good to me.'),
('PSA', 14, 1, 'PSA.14.1', 'For the choirmaster. Of David. The fool says in his heart, “There is no God.” They are corrupt; their acts are vile. There is no one who does good.'),
('PSA', 14, 2, 'PSA.14.2', 'The LORD looks down from heaven upon the sons of men to see if any understand, if any seek God.'),
('PSA', 14, 3, 'PSA.14.3', 'All have turned away, they have together become corrupt; there is no one who does good, not even one.'),
('PSA', 14, 4, 'PSA.14.4', 'Will the workers of iniquity never learn? They devour my people like bread; they refuse to call upon the LORD.'),
('PSA', 14, 5, 'PSA.14.5', 'There they are, overwhelmed with dread, for God is in the company of the righteous.'),
('PSA', 14, 6, 'PSA.14.6', 'You sinners frustrate the plans of the oppressed, yet the LORD is their shelter.'),
('PSA', 14, 7, 'PSA.14.7', 'Oh, that the salvation of Israel would come from Zion! When the LORD restores His captive people, let Jacob rejoice, let Israel be glad!'),
('PSA', 15, 1, 'PSA.15.1', 'A Psalm of David. O LORD, who may abide in Your tent? Who may dwell on Your holy mountain?'),
('PSA', 15, 2, 'PSA.15.2', 'He who walks with integrity and practices righteousness, who speaks the truth from his heart,'),
('PSA', 15, 3, 'PSA.15.3', 'who has no slander on his tongue, who does no harm to his neighbor, who casts no scorn on his friend,'),
('PSA', 15, 4, 'PSA.15.4', 'who despises the vile but honors those who fear the LORD, who does not revise a costly oath,'),
('PSA', 15, 5, 'PSA.15.5', 'who lends his money without interest and refuses a bribe against the innocent. He who does these things will never be shaken.'),
('PSA', 16, 1, 'PSA.16.1', 'A Miktam of David. Preserve me, O God, for in You I take refuge.'),
('PSA', 16, 2, 'PSA.16.2', 'I said to the LORD, “You are my Lord; apart from You I have no good thing.”'),
('PSA', 16, 3, 'PSA.16.3', 'As for the saints in the land, they are the excellence in whom all my delight resides.'),
('PSA', 16, 4, 'PSA.16.4', 'Sorrows will multiply to those who chase other gods. I will not pour out their libations of blood, or speak their names with my lips.'),
('PSA', 16, 5, 'PSA.16.5', 'The LORD is my chosen portion and my cup; You have made my lot secure.'),
('PSA', 16, 6, 'PSA.16.6', 'The lines of my boundary have fallen in pleasant places; surely my inheritance is delightful.'),
('PSA', 16, 7, 'PSA.16.7', 'I will bless the LORD who counsels me; even at night my conscience instructs me.'),
('PSA', 16, 8, 'PSA.16.8', 'I have set the LORD always before me. Because He is at my right hand, I will not be shaken.'),
('PSA', 16, 9, 'PSA.16.9', 'Therefore my heart is glad and my tongue rejoices; my body also will dwell securely.'),
('PSA', 16, 10, 'PSA.16.10', 'For You will not abandon my soul to Sheol, nor will You let Your Holy One see decay.'),
('PSA', 16, 11, 'PSA.16.11', 'You have made known to me the path of life; You will fill me with joy in Your presence, with eternal pleasures at Your right hand.'),
('PSA', 17, 1, 'PSA.17.1', 'A prayer of David. Hear, O LORD, my righteous plea; listen to my cry. Give ear to my prayer—it comes from lips free of deceit.'),
('PSA', 17, 2, 'PSA.17.2', 'May my vindication come from Your presence; may Your eyes see what is right.'),
('PSA', 17, 3, 'PSA.17.3', 'You have tried my heart; You have visited me in the night. You have tested me and found no evil; I have resolved not to sin with my mouth.'),
('PSA', 17, 4, 'PSA.17.4', 'As for the deeds of men—by the word of Your lips I have avoided the ways of the violent.'),
('PSA', 17, 5, 'PSA.17.5', 'My steps have held to Your paths; my feet have not slipped.'),
('PSA', 17, 6, 'PSA.17.6', 'I call on You, O God, for You will answer me. Incline Your ear to me; hear my words.'),
('PSA', 17, 7, 'PSA.17.7', 'Show the wonders of Your loving devotion, You who save by Your right hand those who seek refuge from their foes.'),
('PSA', 17, 8, 'PSA.17.8', 'Keep me as the apple of Your eye; hide me in the shadow of Your wings'),
('PSA', 17, 9, 'PSA.17.9', 'from the wicked who assail me, from my mortal enemies who surround me.'),
('PSA', 17, 10, 'PSA.17.10', 'They have closed their callous hearts; their mouths speak with arrogance.'),
('PSA', 17, 11, 'PSA.17.11', 'They have tracked us down, and now surround us; their eyes are set to cast us to the ground,'),
('PSA', 17, 12, 'PSA.17.12', 'like a lion greedy for prey, like a young lion lurking in ambush.'),
('PSA', 17, 13, 'PSA.17.13', 'Arise, O LORD, confront them! Bring them to their knees; deliver me from the wicked by Your sword,'),
('PSA', 17, 14, 'PSA.17.14', 'from such men, O LORD, by Your hand—from men of the world whose portion is in this life. May You fill the bellies of Your treasured ones and satisfy their sons, so they leave their abundance to their children.'),
('PSA', 17, 15, 'PSA.17.15', 'As for me, I will behold Your face in righteousness; when I awake, I will be satisfied in Your presence.'),
('PSA', 18, 1, 'PSA.18.1', 'For the choirmaster. Of David the servant of the LORD, who sang this song to the LORD on the day the LORD had delivered him from the hand of all his enemies and from the hand of Saul. He said: I love You, O LORD, my strength.'),
('PSA', 18, 2, 'PSA.18.2', 'The LORD is my rock, my fortress, and my deliverer. My God is my rock, in whom I take refuge, my shield, and the horn of my salvation, my stronghold.'),
('PSA', 18, 3, 'PSA.18.3', 'I will call upon the LORD, who is worthy to be praised; so shall I be saved from my enemies.'),
('PSA', 18, 4, 'PSA.18.4', 'The cords of death encompassed me; the torrents of chaos overwhelmed me.'),
('PSA', 18, 5, 'PSA.18.5', 'The cords of Sheol entangled me; the snares of death confronted me.'),
('PSA', 18, 6, 'PSA.18.6', 'In my distress I called upon the LORD; I cried to my God for help. From His temple He heard my voice, and my cry for His help reached His ears.'),
('PSA', 18, 7, 'PSA.18.7', 'Then the earth shook and quaked, and the foundations of the mountains trembled; they were shaken because He burned with anger.'),
('PSA', 18, 8, 'PSA.18.8', 'Smoke rose from His nostrils, and consuming fire came from His mouth; glowing coals blazed forth.'),
('PSA', 18, 9, 'PSA.18.9', 'He parted the heavens and came down with dark clouds beneath His feet.'),
('PSA', 18, 10, 'PSA.18.10', 'He mounted a cherub and flew; He soared on the wings of the wind.'),
('PSA', 18, 11, 'PSA.18.11', 'He made darkness His hiding place, and storm clouds a canopy around Him.'),
('PSA', 18, 12, 'PSA.18.12', 'From the brightness of His presence His clouds advanced—hailstones and coals of fire.'),
('PSA', 18, 13, 'PSA.18.13', 'The LORD thundered from heaven; the voice of the Most High resounded—hailstones and coals of fire.'),
('PSA', 18, 14, 'PSA.18.14', 'He shot His arrows and scattered the foes; He hurled lightning and routed them.'),
('PSA', 18, 15, 'PSA.18.15', 'The channels of the sea appeared, and the foundations of the world were exposed, at Your rebuke, O LORD, at the blast of the breath of Your nostrils.'),
('PSA', 18, 16, 'PSA.18.16', 'He reached down from on high and took hold of me; He drew me out of deep waters.'),
('PSA', 18, 17, 'PSA.18.17', 'He rescued me from my powerful enemy, from foes too mighty for me.'),
('PSA', 18, 18, 'PSA.18.18', 'They confronted me in my day of calamity, but the LORD was my support.'),
('PSA', 18, 19, 'PSA.18.19', 'He brought me out into the open; He rescued me because He delighted in me.'),
('PSA', 18, 20, 'PSA.18.20', 'The LORD has rewarded me according to my righteousness; He has repaid me according to the cleanness of my hands.'),
('PSA', 18, 21, 'PSA.18.21', 'For I have kept the ways of the LORD and have not wickedly departed from my God.'),
('PSA', 18, 22, 'PSA.18.22', 'For all His ordinances are before me; I have not disregarded His statutes.'),
('PSA', 18, 23, 'PSA.18.23', 'And I have been blameless before Him and kept myself from iniquity.'),
('PSA', 18, 24, 'PSA.18.24', 'So the LORD has repaid me according to my righteousness, according to the cleanness of my hands in His sight.'),
('PSA', 18, 25, 'PSA.18.25', 'To the faithful You show Yourself faithful, to the blameless You show Yourself blameless;'),
('PSA', 18, 26, 'PSA.18.26', 'to the pure You show Yourself pure, but to the crooked You show Yourself shrewd.'),
('PSA', 18, 27, 'PSA.18.27', 'For You save an afflicted people, but You humble those with haughty eyes.'),
('PSA', 18, 28, 'PSA.18.28', 'For You, O LORD, light my lamp; my God lights up my darkness.'),
('PSA', 18, 29, 'PSA.18.29', 'For in You I can charge an army, and with my God I can scale a wall.'),
('PSA', 18, 30, 'PSA.18.30', 'As for God, His way is perfect; the word of the LORD is flawless. He is a shield to all who take refuge in Him.'),
('PSA', 18, 31, 'PSA.18.31', 'For who is God besides the LORD? And who is the Rock except our God?'),
('PSA', 18, 32, 'PSA.18.32', 'It is God who arms me with strength and makes my way clear.'),
('PSA', 18, 33, 'PSA.18.33', 'He makes my feet like those of a deer and stations me upon the heights.'),
('PSA', 18, 34, 'PSA.18.34', 'He trains my hands for battle; my arms can bend a bow of bronze.'),
('PSA', 18, 35, 'PSA.18.35', 'You have given me Your shield of salvation; Your right hand upholds me, and Your gentleness exalts me.'),
('PSA', 18, 36, 'PSA.18.36', 'You broaden the path beneath me so that my ankles do not give way.'),
('PSA', 18, 37, 'PSA.18.37', 'I pursued my enemies and overtook them; I did not turn back until they were consumed.'),
('PSA', 18, 38, 'PSA.18.38', 'I crushed them so they could not rise; they have fallen under my feet.'),
('PSA', 18, 39, 'PSA.18.39', 'You have armed me with strength for battle; You have subdued my foes beneath me.'),
('PSA', 18, 40, 'PSA.18.40', 'You have made my enemies retreat before me; I destroyed those who hated me.'),
('PSA', 18, 41, 'PSA.18.41', 'They cried for help, but there was no one to save them—to the LORD, but He did not answer.'),
('PSA', 18, 42, 'PSA.18.42', 'I ground them as dust in the face of the wind; I trampled them like mud in the streets.'),
('PSA', 18, 43, 'PSA.18.43', 'You have delivered me from the strife of the people; You have made me the head of nations; a people I had not known shall serve me.'),
('PSA', 18, 44, 'PSA.18.44', 'When they hear me, they obey me; foreigners cower before me.'),
('PSA', 18, 45, 'PSA.18.45', 'Foreigners lose heart and come trembling from their strongholds.'),
('PSA', 18, 46, 'PSA.18.46', 'The LORD lives, and blessed be my Rock! And may the God of my salvation be exalted—'),
('PSA', 18, 47, 'PSA.18.47', 'the God who avenges me and subdues nations beneath me,'),
('PSA', 18, 48, 'PSA.18.48', 'who delivers me from my enemies. You exalt me above my foes; You rescue me from violent men.'),
('PSA', 18, 49, 'PSA.18.49', 'Therefore I will praise You, O LORD, among the nations; I will sing praises to Your name.'),
('PSA', 18, 50, 'PSA.18.50', 'Great salvation He brings to His king. He shows loving devotion to His anointed, to David and his descendants forever.'),
('PSA', 19, 1, 'PSA.19.1', 'For the choirmaster. A Psalm of David. The heavens declare the glory of God; the skies proclaim the work of His hands.'),
('PSA', 19, 2, 'PSA.19.2', 'Day after day they pour forth speech; night after night they reveal knowledge.'),
('PSA', 19, 3, 'PSA.19.3', 'Without speech or language, without a sound to be heard,'),
('PSA', 19, 4, 'PSA.19.4', 'their voice has gone out into all the earth, their words to the ends of the world. In the heavens He has pitched a tent for the sun.'),
('PSA', 19, 5, 'PSA.19.5', 'Like a bridegroom emerging from his chamber, like a champion rejoicing to run his course,'),
('PSA', 19, 6, 'PSA.19.6', 'it rises at one end of the heavens and runs its circuit to the other; nothing is deprived of its warmth.'),
('PSA', 19, 7, 'PSA.19.7', 'The Law of the LORD is perfect, reviving the soul; the testimony of the LORD is trustworthy, making wise the simple.'),
('PSA', 19, 8, 'PSA.19.8', 'The precepts of the LORD are right, bringing joy to the heart; the commandments of the LORD are radiant, giving light to the eyes.'),
('PSA', 19, 9, 'PSA.19.9', 'The fear of the LORD is pure, enduring forever; the judgments of the LORD are true, being altogether righteous.'),
('PSA', 19, 10, 'PSA.19.10', 'They are more precious than gold, than much pure gold; they are sweeter than honey, than honey from the comb.'),
('PSA', 19, 11, 'PSA.19.11', 'By them indeed Your servant is warned; in keeping them is great reward.'),
('PSA', 19, 12, 'PSA.19.12', 'Who can discern his own errors? Cleanse me from my hidden faults.'),
('PSA', 19, 13, 'PSA.19.13', 'Keep Your servant also from willful sins; may they not rule over me. Then I will be blameless and cleansed of great transgression.'),
('PSA', 19, 14, 'PSA.19.14', 'May the words of my mouth and the meditation of my heart be pleasing in Your sight, O LORD, my Rock and my Redeemer.'),
('PSA', 20, 1, 'PSA.20.1', 'For the choirmaster. A Psalm of David. May the LORD answer you in the day of trouble; may the name of the God of Jacob protect you.'),
('PSA', 20, 2, 'PSA.20.2', 'May He send you help from the sanctuary and sustain you from Zion.'),
('PSA', 20, 3, 'PSA.20.3', 'May He remember all your gifts and look favorably on your burnt offerings. Selah'),
('PSA', 20, 4, 'PSA.20.4', 'May He give you the desires of your heart and make all your plans succeed.'),
('PSA', 20, 5, 'PSA.20.5', 'May we shout for joy at your victory and raise a banner in the name of our God. May the LORD grant all your petitions.'),
('PSA', 20, 6, 'PSA.20.6', 'Now I know that the LORD saves His anointed; He answers him from His holy heaven with the saving power of His right hand.'),
('PSA', 20, 7, 'PSA.20.7', 'Some trust in chariots and others in horses, but we trust in the name of the LORD our God.'),
('PSA', 20, 8, 'PSA.20.8', 'They collapse and fall, but we rise up and stand firm.'),
('PSA', 20, 9, 'PSA.20.9', 'O LORD, save the king. Answer us on the day we call.'),
('PSA', 21, 1, 'PSA.21.1', 'For the choirmaster. A Psalm of David. O LORD, the king rejoices in Your strength. How greatly he exults in Your salvation!'),
('PSA', 21, 2, 'PSA.21.2', 'You have granted his heart’s desire and have not withheld the request of his lips. Selah'),
('PSA', 21, 3, 'PSA.21.3', 'For You welcomed him with rich blessings; You placed on his head a crown of pure gold.'),
('PSA', 21, 4, 'PSA.21.4', 'He asked You for life, and You granted it—length of days, forever and ever.'),
('PSA', 21, 5, 'PSA.21.5', 'Great is his glory in Your salvation; You bestow on him splendor and majesty.'),
('PSA', 21, 6, 'PSA.21.6', 'For You grant him blessings forever; You cheer him with joy in Your presence.'),
('PSA', 21, 7, 'PSA.21.7', 'For the king trusts in the LORD; through the loving devotion of the Most High, he will not be shaken.'),
('PSA', 21, 8, 'PSA.21.8', 'Your hand will apprehend all Your enemies; Your right hand will seize those who hate You.'),
('PSA', 21, 9, 'PSA.21.9', 'You will place them in a fiery furnace at the time of Your appearing. In His wrath the LORD will engulf them, and the fire will consume them.'),
('PSA', 21, 10, 'PSA.21.10', 'You will wipe their descendants from the earth, and their offspring from the sons of men.'),
('PSA', 21, 11, 'PSA.21.11', 'Though they intend You harm, the schemes they devise will not prevail.'),
('PSA', 21, 12, 'PSA.21.12', 'For You will put them to flight when Your bow is trained upon them.'),
('PSA', 21, 13, 'PSA.21.13', 'Be exalted, O LORD, in Your strength; we will sing and praise Your power.'),
('PSA', 22, 1, 'PSA.22.1', 'For the choirmaster. To the tune of “The Doe of the Dawn.” A Psalm of David. My God, my God, why have You forsaken me? Why are You so far from saving me, so far from my words of groaning?'),
('PSA', 22, 2, 'PSA.22.2', 'I cry out by day, O my God, but You do not answer, and by night, but I have no rest.'),
('PSA', 22, 3, 'PSA.22.3', 'Yet You are holy, enthroned on the praises of Israel.'),
('PSA', 22, 4, 'PSA.22.4', 'In You our fathers trusted; they trusted and You delivered them.'),
('PSA', 22, 5, 'PSA.22.5', 'They cried out to You and were set free; they trusted in You and were not disappointed.'),
('PSA', 22, 6, 'PSA.22.6', 'But I am a worm and not a man, scorned by men and despised by the people.'),
('PSA', 22, 7, 'PSA.22.7', 'All who see me mock me; they sneer and shake their heads:'),
('PSA', 22, 8, 'PSA.22.8', '“He trusts in the LORD, let the LORD deliver him; let the LORD rescue him, since He delights in him.”'),
('PSA', 22, 9, 'PSA.22.9', 'Yet You brought me forth from the womb; You made me secure at my mother’s breast.'),
('PSA', 22, 10, 'PSA.22.10', 'From birth I was cast upon You; from my mother’s womb You have been my God.'),
('PSA', 22, 11, 'PSA.22.11', 'Be not far from me, for trouble is near and there is no one to help.'),
('PSA', 22, 12, 'PSA.22.12', 'Many bulls surround me; strong bulls of Bashan encircle me.'),
('PSA', 22, 13, 'PSA.22.13', 'They open their jaws against me like lions that roar and maul.'),
('PSA', 22, 14, 'PSA.22.14', 'I am poured out like water, and all my bones are disjointed. My heart is like wax; it melts away within me.'),
('PSA', 22, 15, 'PSA.22.15', 'My strength is dried up like a potsherd, and my tongue sticks to the roof of my mouth. You lay me in the dust of death.'),
('PSA', 22, 16, 'PSA.22.16', 'For dogs surround me; a band of evil men encircles me; they have pierced my hands and feet.'),
('PSA', 22, 17, 'PSA.22.17', 'I can count all my bones; they stare and gloat over me.'),
('PSA', 22, 18, 'PSA.22.18', 'They divide my garments among them and cast lots for my clothing.'),
('PSA', 22, 19, 'PSA.22.19', 'But You, O LORD, be not far off; O my Strength, come quickly to help me.'),
('PSA', 22, 20, 'PSA.22.20', 'Deliver my soul from the sword, my precious life from the power of wild dogs.'),
('PSA', 22, 21, 'PSA.22.21', 'Save me from the mouth of the lion; at the horns of the wild oxen You have answered me!'),
('PSA', 22, 22, 'PSA.22.22', 'I will proclaim Your name to my brothers; I will praise You in the assembly.'),
('PSA', 22, 23, 'PSA.22.23', 'You who fear the LORD, praise Him! All descendants of Jacob, honor Him! All offspring of Israel, revere Him!'),
('PSA', 22, 24, 'PSA.22.24', 'For He has not despised or detested the torment of the afflicted. He has not hidden His face from him, but has attended to his cry for help.'),
('PSA', 22, 25, 'PSA.22.25', 'My praise for You resounds in the great assembly; I will fulfill my vows before those who fear You.'),
('PSA', 22, 26, 'PSA.22.26', 'The poor will eat and be satisfied; those who seek the LORD will praise Him. May your hearts live forever!'),
('PSA', 22, 27, 'PSA.22.27', 'All the ends of the earth will remember and turn to the LORD. All the families of the nations will bow down before Him.'),
('PSA', 22, 28, 'PSA.22.28', 'For dominion belongs to the LORD and He rules over the nations.'),
('PSA', 22, 29, 'PSA.22.29', 'All the rich of the earth will feast and worship; all who go down to the dust will kneel before Him—even those unable to preserve their lives.'),
('PSA', 22, 30, 'PSA.22.30', 'Posterity will serve Him; they will declare the Lord to a new generation.'),
('PSA', 22, 31, 'PSA.22.31', 'They will come and proclaim His righteousness to a people yet unborn—all that He has done.'),
('PSA', 23, 1, 'PSA.23.1', 'A Psalm of David. The LORD is my shepherd; I shall not want.'),
('PSA', 23, 2, 'PSA.23.2', 'He makes me lie down in green pastures; He leads me beside quiet waters.'),
('PSA', 23, 3, 'PSA.23.3', 'He restores my soul; He guides me in the paths of righteousness for the sake of His name.'),
('PSA', 23, 4, 'PSA.23.4', 'Even though I walk through the valley of the shadow of death, I will fear no evil, for You are with me; Your rod and Your staff, they comfort me.'),
('PSA', 23, 5, 'PSA.23.5', 'You prepare a table before me in the presence of my enemies. You anoint my head with oil; my cup overflows.'),
('PSA', 23, 6, 'PSA.23.6', 'Surely goodness and mercy will follow me all the days of my life, and I will dwell in the house of the LORD forever.'),
('PSA', 24, 1, 'PSA.24.1', 'A Psalm of David. The earth is the LORD’s, and the fullness thereof, the world and all who dwell therein.'),
('PSA', 24, 2, 'PSA.24.2', 'For He has founded it upon the seas and established it upon the waters.'),
('PSA', 24, 3, 'PSA.24.3', 'Who may ascend the hill of the LORD? Who may stand in His holy place?'),
('PSA', 24, 4, 'PSA.24.4', 'He who has clean hands and a pure heart, who does not lift up his soul to an idol or swear deceitfully.'),
('PSA', 24, 5, 'PSA.24.5', 'He will receive blessing from the LORD and vindication from the God of his salvation.'),
('PSA', 24, 6, 'PSA.24.6', 'Such is the generation of those who seek Him, who seek Your face, O God of Jacob. Selah'),
('PSA', 24, 7, 'PSA.24.7', 'Lift up your heads, O gates! Be lifted up, O ancient doors, that the King of Glory may enter!'),
('PSA', 24, 8, 'PSA.24.8', 'Who is this King of Glory? The LORD strong and mighty, the LORD mighty in battle.'),
('PSA', 24, 9, 'PSA.24.9', 'Lift up your heads, O gates! Be lifted up, O ancient doors, that the King of Glory may enter!'),
('PSA', 24, 10, 'PSA.24.10', 'Who is He, this King of Glory? The LORD of Hosts—He is the King of Glory. Selah'),
('PSA', 25, 1, 'PSA.25.1', 'Of David. To You, O LORD, I lift up my soul;'),
('PSA', 25, 2, 'PSA.25.2', 'in You, my God, I trust. Do not let me be put to shame; do not let my enemies exult over me.'),
('PSA', 25, 3, 'PSA.25.3', 'Surely none who wait for You will be put to shame; but those who engage in treachery without cause will be disgraced.'),
('PSA', 25, 4, 'PSA.25.4', 'Show me Your ways, O LORD; teach me Your paths.'),
('PSA', 25, 5, 'PSA.25.5', 'Guide me in Your truth and teach me, for You are the God of my salvation; all day long I wait for You.'),
('PSA', 25, 6, 'PSA.25.6', 'Remember, O LORD, Your compassion and loving devotion, for they are from age to age.'),
('PSA', 25, 7, 'PSA.25.7', 'Remember not the sins of my youth, nor my rebellious acts; remember me according to Your loving devotion, because of Your goodness, O LORD.'),
('PSA', 25, 8, 'PSA.25.8', 'Good and upright is the LORD; therefore He shows sinners the way.'),
('PSA', 25, 9, 'PSA.25.9', 'He guides the humble in what is right and teaches them His way.'),
('PSA', 25, 10, 'PSA.25.10', 'All the LORD’s ways are loving and faithful to those who keep His covenant and His decrees.'),
('PSA', 25, 11, 'PSA.25.11', 'For the sake of Your name, O LORD, forgive my iniquity, for it is great.'),
('PSA', 25, 12, 'PSA.25.12', 'Who is the man who fears the LORD? He will instruct him in the path chosen for him.'),
('PSA', 25, 13, 'PSA.25.13', 'His soul will dwell in prosperity, and his descendants will inherit the land.'),
('PSA', 25, 14, 'PSA.25.14', 'The LORD confides in those who fear Him, and reveals His covenant to them.'),
('PSA', 25, 15, 'PSA.25.15', 'My eyes are always on the LORD, for He will free my feet from the mesh.'),
('PSA', 25, 16, 'PSA.25.16', 'Turn to me and be gracious, for I am lonely and afflicted.'),
('PSA', 25, 17, 'PSA.25.17', 'The troubles of my heart increase; free me from my distress.'),
('PSA', 25, 18, 'PSA.25.18', 'Consider my affliction and trouble, and take away all my sins.'),
('PSA', 25, 19, 'PSA.25.19', 'Consider my enemies, for they are many, and they hate me with vicious hatred.'),
('PSA', 25, 20, 'PSA.25.20', 'Guard my soul and deliver me; let me not be put to shame, for I take refuge in You.'),
('PSA', 25, 21, 'PSA.25.21', 'May integrity and uprightness preserve me, because I wait for You.'),
('PSA', 25, 22, 'PSA.25.22', 'Redeem Israel, O God, from all its distress.'),
('PSA', 26, 1, 'PSA.26.1', 'Of David. Vindicate me, O LORD! For I have walked with integrity; I have trusted in the LORD without wavering.'),
('PSA', 26, 2, 'PSA.26.2', 'Test me, O LORD, and try me; examine my heart and mind.'),
('PSA', 26, 3, 'PSA.26.3', 'For Your loving devotion is before my eyes, and I have walked in Your truth.'),
('PSA', 26, 4, 'PSA.26.4', 'I do not sit with deceitful men, nor keep company with hypocrites.'),
('PSA', 26, 5, 'PSA.26.5', 'I hate the mob of evildoers, and refuse to sit with the wicked.'),
('PSA', 26, 6, 'PSA.26.6', 'I wash my hands in innocence that I may go about Your altar, O LORD,'),
('PSA', 26, 7, 'PSA.26.7', 'to raise my voice in thanksgiving and declare all Your wonderful works.'),
('PSA', 26, 8, 'PSA.26.8', 'O LORD, I love the house where You dwell, the place where Your glory resides.'),
('PSA', 26, 9, 'PSA.26.9', 'Do not take my soul away with sinners, or my life with men of bloodshed,'),
('PSA', 26, 10, 'PSA.26.10', 'in whose hands are wicked schemes, whose right hands are full of bribes.'),
('PSA', 26, 11, 'PSA.26.11', 'But I will walk with integrity; redeem me and be merciful to me.'),
('PSA', 26, 12, 'PSA.26.12', 'My feet stand on level ground; in the congregations I will bless the LORD.'),
('PSA', 27, 1, 'PSA.27.1', 'Of David. The LORD is my light and my salvation—whom shall I fear? The LORD is the stronghold of my life—whom shall I dread?'),
('PSA', 27, 2, 'PSA.27.2', 'When the wicked came upon me to devour my flesh, my enemies and foes stumbled and fell.'),
('PSA', 27, 3, 'PSA.27.3', 'Though an army encamps around me, my heart will not fear; though a war breaks out against me, I will keep my trust.'),
('PSA', 27, 4, 'PSA.27.4', 'One thing I have asked of the LORD; this is what I desire: to dwell in the house of the LORD all the days of my life, to gaze on the beauty of the LORD and seek Him in His temple.'),
('PSA', 27, 5, 'PSA.27.5', 'For in the day of trouble He will hide me in His shelter; He will conceal me under the cover of His tent; He will set me high upon a rock.'),
('PSA', 27, 6, 'PSA.27.6', 'Then my head will be held high above my enemies around me. At His tabernacle I will offer sacrifices with shouts of joy; I will sing and make music to the LORD.'),
('PSA', 27, 7, 'PSA.27.7', 'Hear, O LORD, my voice when I call; be merciful and answer me.'),
('PSA', 27, 8, 'PSA.27.8', 'My heart said, “Seek His face.” Your face, O LORD, I will seek.'),
('PSA', 27, 9, 'PSA.27.9', 'Hide not Your face from me, nor turn away Your servant in anger. You have been my helper; do not leave me or forsake me, O God of my salvation.'),
('PSA', 27, 10, 'PSA.27.10', 'Though my father and mother forsake me, the LORD will receive me.'),
('PSA', 27, 11, 'PSA.27.11', 'Teach me Your way, O LORD, and lead me on a level path, because of my oppressors.'),
('PSA', 27, 12, 'PSA.27.12', 'Do not hand me over to the will of my foes, for false witnesses rise up against me, breathing out violence.'),
('PSA', 27, 13, 'PSA.27.13', 'Still I am certain to see the goodness of the LORD in the land of the living.'),
('PSA', 27, 14, 'PSA.27.14', 'Wait patiently for the LORD; be strong and courageous. Wait patiently for the LORD!'),
('PSA', 28, 1, 'PSA.28.1', 'Of David. To You, O LORD, I call; be not deaf to me, O my Rock. For if You remain silent, I will be like those descending to the Pit.'),
('PSA', 28, 2, 'PSA.28.2', 'Hear my cry for mercy when I call to You for help, when I lift up my hands toward Your holy sanctuary.'),
('PSA', 28, 3, 'PSA.28.3', 'Do not drag me away with the wicked, and with the workers of iniquity, who speak peace to their neighbors while malice is in their hearts.'),
('PSA', 28, 4, 'PSA.28.4', 'Repay them according to their deeds and for their works of evil. Repay them for what their hands have done; bring back on them what they deserve.'),
('PSA', 28, 5, 'PSA.28.5', 'Since they show no regard for the works of the LORD or what His hands have done, He will tear them down and never rebuild them.'),
('PSA', 28, 6, 'PSA.28.6', 'Blessed be the LORD, for He has heard my cry for mercy.'),
('PSA', 28, 7, 'PSA.28.7', 'The LORD is my strength and my shield; my heart trusts in Him, and I am helped. Therefore my heart rejoices, and I give thanks to Him with my song.'),
('PSA', 28, 8, 'PSA.28.8', 'The LORD is the strength of His people, a stronghold of salvation for His anointed.'),
('PSA', 28, 9, 'PSA.28.9', 'Save Your people and bless Your inheritance; shepherd them and carry them forever.'),
('PSA', 29, 1, 'PSA.29.1', 'A Psalm of David. Ascribe to the LORD, O heavenly beings, ascribe to the LORD glory and strength.'),
('PSA', 29, 2, 'PSA.29.2', 'Ascribe to the LORD the glory due His name; worship the LORD in the splendor of His holiness.'),
('PSA', 29, 3, 'PSA.29.3', 'The voice of the LORD is over the waters; the God of glory thunders; the LORD is heard over many waters.'),
('PSA', 29, 4, 'PSA.29.4', 'The voice of the LORD is powerful; the voice of the LORD is majestic.'),
('PSA', 29, 5, 'PSA.29.5', 'The voice of the LORD breaks the cedars; the LORD shatters the cedars of Lebanon.'),
('PSA', 29, 6, 'PSA.29.6', 'He makes Lebanon skip like a calf, and Sirion like a young wild ox.'),
('PSA', 29, 7, 'PSA.29.7', 'The voice of the LORD strikes with flames of fire.'),
('PSA', 29, 8, 'PSA.29.8', 'The voice of the LORD shakes the wilderness; the LORD shakes the Wilderness of Kadesh.'),
('PSA', 29, 9, 'PSA.29.9', 'The voice of the LORD twists the oaks and strips the forests bare. And in His temple all cry, “Glory!”'),
('PSA', 29, 10, 'PSA.29.10', 'The LORD sits enthroned over the flood; the LORD is enthroned as King forever.'),
('PSA', 29, 11, 'PSA.29.11', 'The LORD gives His people strength; the LORD blesses His people with peace.'),
('PSA', 30, 1, 'PSA.30.1', 'A Psalm. A song for the dedication of the temple. Of David. I will exalt You, O LORD, for You have lifted me up and have not allowed my foes to rejoice over me.'),
('PSA', 30, 2, 'PSA.30.2', 'O LORD my God, I cried to You for help, and You healed me.'),
('PSA', 30, 3, 'PSA.30.3', 'O LORD, You pulled me up from Sheol; You spared me from descending into the Pit.'),
('PSA', 30, 4, 'PSA.30.4', 'Sing to the LORD, O you His saints, and praise His holy name.'),
('PSA', 30, 5, 'PSA.30.5', 'For His anger is fleeting, but His favor lasts a lifetime. Weeping may stay the night, but joy comes in the morning.'),
('PSA', 30, 6, 'PSA.30.6', 'In prosperity I said, “I will never be shaken.”'),
('PSA', 30, 7, 'PSA.30.7', 'O LORD, You favored me; You made my mountain stand strong. When You hid Your face, I was dismayed.'),
('PSA', 30, 8, 'PSA.30.8', 'To You, O LORD, I called, and I begged my Lord for mercy:'),
('PSA', 30, 9, 'PSA.30.9', '“What gain is there in my bloodshed, in my descent to the Pit? Will the dust praise You? Will it proclaim Your faithfulness?'),
('PSA', 30, 10, 'PSA.30.10', 'Hear me, O LORD, and have mercy; O LORD, be my helper.”'),
('PSA', 30, 11, 'PSA.30.11', 'You turned my mourning into dancing; You peeled off my sackcloth and clothed me with joy,'),
('PSA', 30, 12, 'PSA.30.12', 'that my heart may sing Your praises and not be silent. O LORD my God, I will give thanks forever.'),
('PSA', 31, 1, 'PSA.31.1', 'For the choirmaster. A Psalm of David. In You, O LORD, I have taken refuge; let me never be put to shame; save me by Your righteousness.'),
('PSA', 31, 2, 'PSA.31.2', 'Incline Your ear to me; come quickly to my rescue. Be my rock of refuge, the stronghold of my deliverance.'),
('PSA', 31, 3, 'PSA.31.3', 'For You are my rock and my fortress; lead me and guide me for the sake of Your name.'),
('PSA', 31, 4, 'PSA.31.4', 'You free me from the net laid out for me, for You are my refuge.'),
('PSA', 31, 5, 'PSA.31.5', 'Into Your hands I commit my spirit; You have redeemed me, O LORD, God of truth.'),
('PSA', 31, 6, 'PSA.31.6', 'I hate those who cling to worthless idols, but in the LORD I trust.'),
('PSA', 31, 7, 'PSA.31.7', 'I will be glad and rejoice in Your loving devotion, for You have seen my affliction; You have known the anguish of my soul.'),
('PSA', 31, 8, 'PSA.31.8', 'You have not delivered me to the enemy; You have set my feet in the open.'),
('PSA', 31, 9, 'PSA.31.9', 'Be merciful to me, O LORD, for I am in distress; my eyes fail from sorrow, my soul and body as well.'),
('PSA', 31, 10, 'PSA.31.10', 'For my life is consumed with grief and my years with groaning; my iniquity has drained my strength, and my bones are wasting away.'),
('PSA', 31, 11, 'PSA.31.11', 'Among all my enemies I am a disgrace, and among my neighbors even more. I am dreaded by my friends—they flee when they see me on the street.'),
('PSA', 31, 12, 'PSA.31.12', 'I am forgotten like a dead man, out of mind. I am like a broken vessel.'),
('PSA', 31, 13, 'PSA.31.13', 'For I hear the slander of many; there is terror on every side. They conspire against me and plot to take my life.'),
('PSA', 31, 14, 'PSA.31.14', 'But I trust in You, O LORD; I say, “You are my God.”'),
('PSA', 31, 15, 'PSA.31.15', 'My times are in Your hands; deliver me from my enemies and from those who pursue me.'),
('PSA', 31, 16, 'PSA.31.16', 'Make Your face shine on Your servant; save me by Your loving devotion.'),
('PSA', 31, 17, 'PSA.31.17', 'O LORD, let me not be ashamed, for I have called on You. Let the wicked be put to shame; let them lie silent in Sheol.'),
('PSA', 31, 18, 'PSA.31.18', 'May lying lips be silenced—lips that speak with arrogance against the righteous, full of pride and contempt.'),
('PSA', 31, 19, 'PSA.31.19', 'How great is Your goodness which You have laid up for those who fear You, which You have bestowed before the sons of men on those who take refuge in You!'),
('PSA', 31, 20, 'PSA.31.20', 'You hide them in the secret place of Your presence from the schemes of men. You conceal them in Your shelter from accusing tongues.'),
('PSA', 31, 21, 'PSA.31.21', 'Blessed be the LORD, for He has shown me His loving devotion in a city under siege.'),
('PSA', 31, 22, 'PSA.31.22', 'In my alarm I said, “I am cut off from Your sight!” But You heard my plea for mercy when I called to You for help.'),
('PSA', 31, 23, 'PSA.31.23', 'Love the LORD, all His saints. The LORD preserves the faithful, but fully repays the arrogant.'),
('PSA', 31, 24, 'PSA.31.24', 'Be strong and courageous, all you who hope in the LORD.'),
('PSA', 32, 1, 'PSA.32.1', 'Of David. A Maskil. Blessed is he whose transgressions are forgiven, whose sins are covered.'),
('PSA', 32, 2, 'PSA.32.2', 'Blessed is the man whose iniquity the LORD does not count against him, in whose spirit there is no deceit.'),
('PSA', 32, 3, 'PSA.32.3', 'When I kept silent, my bones became brittle from my groaning all day long.'),
('PSA', 32, 4, 'PSA.32.4', 'For day and night Your hand was heavy upon me; my strength was drained as in the summer heat. Selah'),
('PSA', 32, 5, 'PSA.32.5', 'Then I acknowledged my sin to You and did not hide my iniquity. I said, “I will confess my transgressions to the LORD,” and You forgave the guilt of my sin. Selah'),
('PSA', 32, 6, 'PSA.32.6', 'Therefore let all the godly pray to You while You may be found. Surely when great waters rise, they will not come near.'),
('PSA', 32, 7, 'PSA.32.7', 'You are my hiding place. You protect me from trouble; You surround me with songs of deliverance. Selah'),
('PSA', 32, 8, 'PSA.32.8', 'I will instruct you and teach you the way you should go; I will give you counsel and watch over you.'),
('PSA', 32, 9, 'PSA.32.9', 'Do not be like the horse or mule, which have no understanding; they must be controlled with bit and bridle to make them come to you.'),
('PSA', 32, 10, 'PSA.32.10', 'Many are the sorrows of the wicked, but loving devotion surrounds him who trusts in the LORD.'),
('PSA', 32, 11, 'PSA.32.11', 'Be glad in the LORD and rejoice, O righteous ones; shout for joy, all you upright in heart.'),
('PSA', 33, 1, 'PSA.33.1', 'Rejoice in the LORD, O righteous ones; it is fitting for the upright to praise Him.'),
('PSA', 33, 2, 'PSA.33.2', 'Praise the LORD with the harp; make music to Him with ten strings.'),
('PSA', 33, 3, 'PSA.33.3', 'Sing to Him a new song; play skillfully with a shout of joy.'),
('PSA', 33, 4, 'PSA.33.4', 'For the word of the LORD is upright, and all His work is trustworthy.'),
('PSA', 33, 5, 'PSA.33.5', 'The LORD loves righteousness and justice; the earth is full of His loving devotion.'),
('PSA', 33, 6, 'PSA.33.6', 'By the word of the LORD the heavens were made, and all the stars by the breath of His mouth.'),
('PSA', 33, 7, 'PSA.33.7', 'He piles up the waters of the sea; He puts the depths into storehouses.'),
('PSA', 33, 8, 'PSA.33.8', 'Let all the earth fear the LORD; let all the people of the world revere Him.'),
('PSA', 33, 9, 'PSA.33.9', 'For He spoke, and it came to be; He commanded, and it stood firm.'),
('PSA', 33, 10, 'PSA.33.10', 'The LORD frustrates the plans of the nations; He thwarts the devices of the peoples.'),
('PSA', 33, 11, 'PSA.33.11', 'The counsel of the LORD stands forever, the purposes of His heart to all generations.'),
('PSA', 33, 12, 'PSA.33.12', 'Blessed is the nation whose God is the LORD, the people He has chosen as His inheritance!'),
('PSA', 33, 13, 'PSA.33.13', 'The LORD looks down from heaven; He sees all the sons of men.'),
('PSA', 33, 14, 'PSA.33.14', 'From His dwelling place He gazes on all who inhabit the earth.'),
('PSA', 33, 15, 'PSA.33.15', 'He shapes the hearts of each; He considers all their works.'),
('PSA', 33, 16, 'PSA.33.16', 'No king is saved by his vast army; no warrior is delivered by his great strength.'),
('PSA', 33, 17, 'PSA.33.17', 'A horse is a vain hope for salvation; even its great strength cannot save.'),
('PSA', 33, 18, 'PSA.33.18', 'Surely the eyes of the LORD are on those who fear Him, on those whose hope is in His loving devotion'),
('PSA', 33, 19, 'PSA.33.19', 'to deliver them from death and keep them alive in famine.'),
('PSA', 33, 20, 'PSA.33.20', 'Our soul waits for the LORD; He is our help and our shield.'),
('PSA', 33, 21, 'PSA.33.21', 'For our hearts rejoice in Him, since we trust in His holy name.'),
('PSA', 33, 22, 'PSA.33.22', 'May Your loving devotion rest on us, O LORD, as we put our hope in You.'),
('PSA', 34, 1, 'PSA.34.1', 'Of David, when he pretended to be insane before Abimelech, so that the king drove him away. I will bless the LORD at all times; His praise will always be on my lips.'),
('PSA', 34, 2, 'PSA.34.2', 'My soul boasts in the LORD; let the oppressed hear and rejoice.'),
('PSA', 34, 3, 'PSA.34.3', 'Magnify the LORD with me; let us exalt His name together.'),
('PSA', 34, 4, 'PSA.34.4', 'I sought the LORD, and He answered me; He delivered me from all my fears.'),
('PSA', 34, 5, 'PSA.34.5', 'Those who look to Him are radiant with joy; their faces shall never be ashamed.'),
('PSA', 34, 6, 'PSA.34.6', 'This poor man called out, and the LORD heard him; He saved him from all his troubles.'),
('PSA', 34, 7, 'PSA.34.7', 'The angel of the LORD encamps around those who fear Him, and he delivers them.'),
('PSA', 34, 8, 'PSA.34.8', 'Taste and see that the LORD is good; blessed is the man who takes refuge in Him!'),
('PSA', 34, 9, 'PSA.34.9', 'Fear the LORD, you His saints, for those who fear Him lack nothing.'),
('PSA', 34, 10, 'PSA.34.10', 'Young lions go lacking and hungry, but those who seek the LORD lack no good thing.'),
('PSA', 34, 11, 'PSA.34.11', 'Come, children, listen to me; I will teach you the fear of the LORD.'),
('PSA', 34, 12, 'PSA.34.12', 'Who is the man who delights in life, who desires to see good days?'),
('PSA', 34, 13, 'PSA.34.13', 'Keep your tongue from evil and your lips from deceitful speech.'),
('PSA', 34, 14, 'PSA.34.14', 'Turn away from evil and do good; seek peace and pursue it.'),
('PSA', 34, 15, 'PSA.34.15', 'The eyes of the LORD are on the righteous, and His ears are inclined to their cry.'),
('PSA', 34, 16, 'PSA.34.16', 'But the face of the LORD is against those who do evil, to wipe out all memory of them from the earth.'),
('PSA', 34, 17, 'PSA.34.17', 'The righteous cry out, and the LORD hears; He delivers them from all their troubles.'),
('PSA', 34, 18, 'PSA.34.18', 'The LORD is near to the brokenhearted; He saves the contrite in spirit.'),
('PSA', 34, 19, 'PSA.34.19', 'Many are the afflictions of the righteous, but the LORD delivers him from them all.'),
('PSA', 34, 20, 'PSA.34.20', 'He protects all his bones; not one of them will be broken.'),
('PSA', 34, 21, 'PSA.34.21', 'Evil will slay the wicked, and the haters of the righteous will be condemned.'),
('PSA', 34, 22, 'PSA.34.22', 'The LORD redeems His servants, and none who take refuge in Him will be condemned.'),
('PSA', 35, 1, 'PSA.35.1', 'Of David. Contend with my opponents, O LORD; fight against those who fight against me.'),
('PSA', 35, 2, 'PSA.35.2', 'Take up Your shield and buckler; arise and come to my aid.'),
('PSA', 35, 3, 'PSA.35.3', 'Draw the spear and javelin against my pursuers; say to my soul: “I am your salvation.”'),
('PSA', 35, 4, 'PSA.35.4', 'May those who seek my life be disgraced and put to shame; may those who plan to harm me be driven back and confounded.'),
('PSA', 35, 5, 'PSA.35.5', 'May they be like chaff in the wind, as the angel of the LORD drives them away.'),
('PSA', 35, 6, 'PSA.35.6', 'May their path be dark and slick, as the angel of the LORD pursues.'),
('PSA', 35, 7, 'PSA.35.7', 'For without cause they laid their net for me; without reason they dug a pit for my soul.'),
('PSA', 35, 8, 'PSA.35.8', 'May ruin befall them by surprise; may the net they hid ensnare them; may they fall into the hazard they created.'),
('PSA', 35, 9, 'PSA.35.9', 'Then my soul will rejoice in the LORD and exult in His salvation.'),
('PSA', 35, 10, 'PSA.35.10', 'All my bones will exclaim, “Who is like You, O LORD, who delivers the afflicted from the aggressor, the poor and needy from the robber?”'),
('PSA', 35, 11, 'PSA.35.11', 'Hostile witnesses come forward; they make charges I know nothing about.'),
('PSA', 35, 12, 'PSA.35.12', 'They repay me evil for good, to the bereavement of my soul.'),
('PSA', 35, 13, 'PSA.35.13', 'Yet when they were ill, I put on sackcloth; I humbled myself with fasting, but my prayers returned unanswered.'),
('PSA', 35, 14, 'PSA.35.14', 'I paced about as for my friend or brother; I was bowed down with grief, like one mourning for his mother.'),
('PSA', 35, 15, 'PSA.35.15', 'But when I stumbled, they assembled in glee; they gathered together against me. Assailants I did not know slandered me without ceasing.'),
('PSA', 35, 16, 'PSA.35.16', 'Like godless jesters at a feast, they gnashed their teeth at me.'),
('PSA', 35, 17, 'PSA.35.17', 'How long, O Lord, will You look on? Rescue my soul from their ravages, my precious life from these lions.'),
('PSA', 35, 18, 'PSA.35.18', 'Then I will give You thanks in the great assembly; I will praise You among many people.'),
('PSA', 35, 19, 'PSA.35.19', 'Let not my enemies gloat over me without cause, nor those who hate me without reason wink in malice.'),
('PSA', 35, 20, 'PSA.35.20', 'For they do not speak peace, but they devise deceitful schemes against those who live quietly in the land.'),
('PSA', 35, 21, 'PSA.35.21', 'They gape at me and say, “Aha, aha! Our eyes have seen!”'),
('PSA', 35, 22, 'PSA.35.22', 'O LORD, You have seen it; be not silent. O Lord, be not far from me.'),
('PSA', 35, 23, 'PSA.35.23', 'Awake and rise to my defense, to my cause, my God and my Lord!'),
('PSA', 35, 24, 'PSA.35.24', 'Vindicate me by Your righteousness, O LORD my God, and do not let them gloat over me.'),
('PSA', 35, 25, 'PSA.35.25', 'Let them not say in their hearts, “Aha, just what we wanted!” Let them not say, “We have swallowed him up!”'),
('PSA', 35, 26, 'PSA.35.26', 'May those who gloat in my distress be ashamed and confounded; may those who exalt themselves over me be clothed in shame and reproach.'),
('PSA', 35, 27, 'PSA.35.27', 'May those who favor my vindication shout for joy and gladness; may they always say, “Exalted be the LORD who delights in His servant’s well-being.”'),
('PSA', 35, 28, 'PSA.35.28', 'Then my tongue will proclaim Your righteousness and Your praises all day long.'),
('PSA', 36, 1, 'PSA.36.1', 'For the choirmaster. A Psalm of David, the servant of the LORD. An oracle is in my heart regarding the transgression of the wicked man: There is no fear of God before his eyes.'),
('PSA', 36, 2, 'PSA.36.2', 'For his eyes are too full of conceit to detect or hate his own sin.'),
('PSA', 36, 3, 'PSA.36.3', 'The words of his mouth are wicked and deceitful; he has ceased to be wise and well-doing.'),
('PSA', 36, 4, 'PSA.36.4', 'Even on his bed he plots wickedness; he sets himself on a path that is not good; he fails to reject evil.'),
('PSA', 36, 5, 'PSA.36.5', 'Your loving devotion, O LORD, reaches to the heavens, Your faithfulness to the clouds.'),
('PSA', 36, 6, 'PSA.36.6', 'Your righteousness is like the highest mountains; Your judgments are like the deepest sea. O LORD, You preserve man and beast.'),
('PSA', 36, 7, 'PSA.36.7', 'How precious is Your loving devotion, O God, that the children of men take refuge in the shadow of Your wings!'),
('PSA', 36, 8, 'PSA.36.8', 'They feast on the abundance of Your house, and You give them drink from Your river of delights.'),
('PSA', 36, 9, 'PSA.36.9', 'For with You is the fountain of life; in Your light we see light.'),
('PSA', 36, 10, 'PSA.36.10', 'Extend Your loving devotion to those who know You, and Your righteousness to the upright in heart.'),
('PSA', 36, 11, 'PSA.36.11', 'Let not the foot of the proud come against me, nor the hand of the wicked drive me away.'),
('PSA', 36, 12, 'PSA.36.12', 'There the evildoers lie fallen, thrown down and unable to rise.'),
('PSA', 37, 1, 'PSA.37.1', 'Of David. Do not fret over those who do evil; do not envy those who do wrong.'),
('PSA', 37, 2, 'PSA.37.2', 'For they wither quickly like grass and wilt like tender plants.'),
('PSA', 37, 3, 'PSA.37.3', 'Trust in the LORD and do good; dwell in the land and cultivate faithfulness.'),
('PSA', 37, 4, 'PSA.37.4', 'Delight yourself in the LORD, and He will give you the desires of your heart.'),
('PSA', 37, 5, 'PSA.37.5', 'Commit your way to the LORD; trust in Him, and He will do it.'),
('PSA', 37, 6, 'PSA.37.6', 'He will bring forth your righteousness like the dawn, your justice like the noonday sun.'),
('PSA', 37, 7, 'PSA.37.7', 'Be still before the LORD and wait patiently for Him; do not fret when men prosper in their ways, when they carry out wicked schemes.'),
('PSA', 37, 8, 'PSA.37.8', 'Refrain from anger and abandon wrath; do not fret—it can only bring harm.'),
('PSA', 37, 9, 'PSA.37.9', 'For the evildoers will be cut off, but those who hope in the LORD will inherit the land.'),
('PSA', 37, 10, 'PSA.37.10', 'Yet a little while, and the wicked will be no more; though you look for them, they will not be found.'),
('PSA', 37, 11, 'PSA.37.11', 'But the meek will inherit the land and delight in abundant prosperity.'),
('PSA', 37, 12, 'PSA.37.12', 'The wicked scheme against the righteous and gnash their teeth at them,'),
('PSA', 37, 13, 'PSA.37.13', 'but the Lord laughs, seeing that their day is coming.'),
('PSA', 37, 14, 'PSA.37.14', 'The wicked have drawn the sword and bent the bow to bring down the poor and needy, to slay those whose ways are upright.'),
('PSA', 37, 15, 'PSA.37.15', 'But their swords will pierce their own hearts, and their bows will be broken.'),
('PSA', 37, 16, 'PSA.37.16', 'Better is the little of the righteous than the abundance of many who are wicked.'),
('PSA', 37, 17, 'PSA.37.17', 'For the arms of the wicked will be broken, but the LORD upholds the righteous.'),
('PSA', 37, 18, 'PSA.37.18', 'The LORD knows the days of the blameless, and their inheritance will last forever.'),
('PSA', 37, 19, 'PSA.37.19', 'In the time of evil they will not be ashamed, and in the days of famine they will be satisfied.'),
('PSA', 37, 20, 'PSA.37.20', 'But the wicked and enemies of the LORD will perish like the glory of the fields. They will vanish; like smoke they will fade away.'),
('PSA', 37, 21, 'PSA.37.21', 'The wicked borrow and do not repay, but the righteous are gracious and giving.'),
('PSA', 37, 22, 'PSA.37.22', 'Surely those He blesses will inherit the land, but the cursed will be destroyed.'),
('PSA', 37, 23, 'PSA.37.23', 'The steps of a man are ordered by the LORD who takes delight in his journey.'),
('PSA', 37, 24, 'PSA.37.24', 'Though he falls, he will not be overwhelmed, for the LORD is holding his hand.'),
('PSA', 37, 25, 'PSA.37.25', 'I once was young and now am old, yet never have I seen the righteous abandoned or their children begging for bread.'),
('PSA', 37, 26, 'PSA.37.26', 'They are ever generous and quick to lend, and their children are a blessing.'),
('PSA', 37, 27, 'PSA.37.27', 'Turn away from evil and do good, so that you will abide forever.'),
('PSA', 37, 28, 'PSA.37.28', 'For the LORD loves justice and will not forsake His saints. They are preserved forever, but the offspring of the wicked will be cut off.'),
('PSA', 37, 29, 'PSA.37.29', 'The righteous will inherit the land and dwell in it forever.'),
('PSA', 37, 30, 'PSA.37.30', 'The mouth of the righteous man utters wisdom, and his tongue speaks justice.'),
('PSA', 37, 31, 'PSA.37.31', 'The law of his God is in his heart; his steps do not falter.'),
('PSA', 37, 32, 'PSA.37.32', 'Though the wicked lie in wait for the righteous, and seek to slay them,'),
('PSA', 37, 33, 'PSA.37.33', 'the LORD will not leave them in their power or let them be condemned under judgment.'),
('PSA', 37, 34, 'PSA.37.34', 'Wait for the LORD and keep His way, and He will raise you up to inherit the land. When the wicked are cut off, you will see it.'),
('PSA', 37, 35, 'PSA.37.35', 'I have seen a wicked, ruthless man flourishing like a well-rooted native tree,'),
('PSA', 37, 36, 'PSA.37.36', 'yet he passed away and was no more; though I searched, he could not be found.'),
('PSA', 37, 37, 'PSA.37.37', 'Consider the blameless and observe the upright, for posterity awaits the man of peace.'),
('PSA', 37, 38, 'PSA.37.38', 'But the transgressors will all be destroyed; the future of the wicked will be cut off.'),
('PSA', 37, 39, 'PSA.37.39', 'The salvation of the righteous is from the LORD; He is their stronghold in time of trouble.'),
('PSA', 37, 40, 'PSA.37.40', 'The LORD helps and delivers them; He rescues and saves them from the wicked, because they take refuge in Him.'),
('PSA', 38, 1, 'PSA.38.1', 'A Psalm of David, for remembrance. O LORD, do not rebuke me in Your anger or discipline me in Your wrath.'),
('PSA', 38, 2, 'PSA.38.2', 'For Your arrows have pierced me deeply, and Your hand has pressed down on me.'),
('PSA', 38, 3, 'PSA.38.3', 'There is no soundness in my body because of Your anger; there is no rest in my bones because of my sin.'),
('PSA', 38, 4, 'PSA.38.4', 'For my iniquities have overwhelmed me; they are a burden too heavy to bear.'),
('PSA', 38, 5, 'PSA.38.5', 'My wounds are foul and festering because of my sinful folly.'),
('PSA', 38, 6, 'PSA.38.6', 'I am bent and brought low; all day long I go about mourning.'),
('PSA', 38, 7, 'PSA.38.7', 'For my loins are full of burning pain, and no soundness remains in my body.'),
('PSA', 38, 8, 'PSA.38.8', 'I am numb and badly crushed; I groan in anguish of heart.'),
('PSA', 38, 9, 'PSA.38.9', 'O Lord, my every desire is before You; my groaning is not hidden from You.'),
('PSA', 38, 10, 'PSA.38.10', 'My heart pounds, my strength fails, and even the light of my eyes has faded.'),
('PSA', 38, 11, 'PSA.38.11', 'My beloved and friends shun my disease, and my kinsmen stand at a distance.'),
('PSA', 38, 12, 'PSA.38.12', 'Those who seek my life lay snares; those who wish me harm speak destruction, plotting deceit all day long.'),
('PSA', 38, 13, 'PSA.38.13', 'But like a deaf man, I do not hear; and like a mute man, I do not open my mouth.'),
('PSA', 38, 14, 'PSA.38.14', 'I am like a man who cannot hear, whose mouth offers no reply.'),
('PSA', 38, 15, 'PSA.38.15', 'I wait for You, O LORD; You will answer, O Lord my God.'),
('PSA', 38, 16, 'PSA.38.16', 'For I said, “Let them not gloat over me—those who taunt me when my foot slips.”'),
('PSA', 38, 17, 'PSA.38.17', 'For I am ready to fall, and my pain is ever with me.'),
('PSA', 38, 18, 'PSA.38.18', 'Yes, I confess my iniquity; I am troubled by my sin.'),
('PSA', 38, 19, 'PSA.38.19', 'Many are my enemies without cause, and many hate me without reason.'),
('PSA', 38, 20, 'PSA.38.20', 'Those who repay my good with evil attack me for pursuing the good.'),
('PSA', 38, 21, 'PSA.38.21', 'Do not forsake me, O LORD; be not far from me, O my God.'),
('PSA', 38, 22, 'PSA.38.22', 'Come quickly to help me, O Lord my Savior.'),
('PSA', 39, 1, 'PSA.39.1', 'For the choirmaster. For Jeduthun. A Psalm of David. I said, “I will watch my ways so that I will not sin with my tongue; I will guard my mouth with a muzzle as long as the wicked are present.”'),
('PSA', 39, 2, 'PSA.39.2', 'I was speechless and still; I remained silent, even from speaking good, and my sorrow was stirred.'),
('PSA', 39, 3, 'PSA.39.3', 'My heart grew hot within me; as I mused, the fire burned. Then I spoke with my tongue:'),
('PSA', 39, 4, 'PSA.39.4', '“Show me, O LORD, my end and the measure of my days. Let me know how fleeting my life is.'),
('PSA', 39, 5, 'PSA.39.5', 'You, indeed, have made my days as handbreadths, and my lifetime as nothing before You. Truly each man at his best exists as but a breath. Selah'),
('PSA', 39, 6, 'PSA.39.6', 'Surely every man goes about like a phantom; surely he bustles in vain; he heaps up riches not knowing who will haul them away.'),
('PSA', 39, 7, 'PSA.39.7', 'And now, O Lord, for what do I wait? My hope is in You.'),
('PSA', 39, 8, 'PSA.39.8', 'Deliver me from all my transgressions; do not make me the reproach of fools.'),
('PSA', 39, 9, 'PSA.39.9', 'I have become mute; I do not open my mouth because of what You have done.'),
('PSA', 39, 10, 'PSA.39.10', 'Remove Your scourge from me; I am perishing by the force of Your hand.'),
('PSA', 39, 11, 'PSA.39.11', 'You discipline and correct a man for his iniquity, consuming like a moth what he holds dear; surely each man is but a vapor. Selah'),
('PSA', 39, 12, 'PSA.39.12', 'Hear my prayer, O LORD, and give ear to my cry for help; do not be deaf to my weeping. For I am a foreigner dwelling with You, a stranger like all my fathers.'),
('PSA', 39, 13, 'PSA.39.13', 'Turn Your gaze away from me, that I may again be cheered before I depart and am no more.”'),
('PSA', 40, 1, 'PSA.40.1', 'For the choirmaster. A Psalm of David. I waited patiently for the LORD; He inclined to me and heard my cry.'),
('PSA', 40, 2, 'PSA.40.2', 'He lifted me up from the pit of despair, out of the miry clay; He set my feet upon a rock, and made my footsteps firm.'),
('PSA', 40, 3, 'PSA.40.3', 'He put a new song in my mouth, a hymn of praise to our God. Many will see and fear and put their trust in the LORD.'),
('PSA', 40, 4, 'PSA.40.4', 'Blessed is the man who has made the LORD his trust, who has not turned to the proud, nor to those who lapse into falsehood.'),
('PSA', 40, 5, 'PSA.40.5', 'Many, O LORD my God, are the wonders You have done, and the plans You have for us—none can compare to You—if I proclaim and declare them, they are more than I can count.'),
('PSA', 40, 6, 'PSA.40.6', 'Sacrifice and offering You did not desire, but my ears You have opened. Burnt offerings and sin offerings You did not require.'),
('PSA', 40, 7, 'PSA.40.7', 'Then I said, “Here I am, I have come—it is written about me in the scroll:'),
('PSA', 40, 8, 'PSA.40.8', 'I delight to do Your will, O my God; Your law is within my heart.”'),
('PSA', 40, 9, 'PSA.40.9', 'I proclaim righteousness in the great assembly; behold, I do not seal my lips, as You, O LORD, do know.'),
('PSA', 40, 10, 'PSA.40.10', 'I have not covered up Your righteousness in my heart; I have declared Your faithfulness and salvation; I have not concealed Your loving devotion and faithfulness from the great assembly.'),
('PSA', 40, 11, 'PSA.40.11', 'O LORD, do not withhold Your mercy from me; Your loving devotion and faithfulness will always guard me.'),
('PSA', 40, 12, 'PSA.40.12', 'For evils without number surround me; my sins have overtaken me, so that I cannot see. They are more than the hairs of my head, and my heart has failed within me.'),
('PSA', 40, 13, 'PSA.40.13', 'Be pleased, O LORD, to deliver me; hurry, O LORD, to help me.'),
('PSA', 40, 14, 'PSA.40.14', 'May those who seek my life be ashamed and confounded; may those who wish me harm be repelled and humiliated.'),
('PSA', 40, 15, 'PSA.40.15', 'May those who say to me, “Aha, aha!” be appalled at their own shame.'),
('PSA', 40, 16, 'PSA.40.16', 'May all who seek You rejoice and be glad in You; may those who love Your salvation always say, “The LORD be magnified!”'),
('PSA', 40, 17, 'PSA.40.17', 'But I am poor and needy; may the Lord think of me. You are my helper and deliverer; O my God, do not delay.'),
('PSA', 41, 1, 'PSA.41.1', 'For the choirmaster. A Psalm of David. Blessed is the one who cares for the poor; the LORD will deliver him in the day of trouble.'),
('PSA', 41, 2, 'PSA.41.2', 'The LORD will protect and preserve him; He will bless him in the land and refuse to give him over to the will of his foes.'),
('PSA', 41, 3, 'PSA.41.3', 'The LORD will sustain him on his bed of illness and restore him from his bed of sickness.'),
('PSA', 41, 4, 'PSA.41.4', 'I said, “O LORD, be gracious to me; heal me, for I have sinned against You.”'),
('PSA', 41, 5, 'PSA.41.5', 'My enemies say with malice: “When will he die and be forgotten?”'),
('PSA', 41, 6, 'PSA.41.6', 'My visitor speaks falsehood; he gathers slander in his heart; he goes out and spreads it abroad.'),
('PSA', 41, 7, 'PSA.41.7', 'All who hate me whisper against me; they imagine the worst for me:'),
('PSA', 41, 8, 'PSA.41.8', '“A vile disease has been poured into him; he will never get up from where he lies!”'),
('PSA', 41, 9, 'PSA.41.9', 'Even my close friend whom I trusted, the one who shared my bread, has lifted up his heel against me.'),
('PSA', 41, 10, 'PSA.41.10', 'But You, O LORD, be gracious to me and raise me up, that I may repay them.'),
('PSA', 41, 11, 'PSA.41.11', 'By this I know that You delight in me, for my enemy does not triumph over me.'),
('PSA', 41, 12, 'PSA.41.12', 'In my integrity You uphold me and set me in Your presence forever.'),
('PSA', 41, 13, 'PSA.41.13', 'Blessed be the LORD, the God of Israel, from everlasting to everlasting. Amen and Amen.'),
('PSA', 42, 1, 'PSA.42.1', 'For the choirmaster. A Maskil of the sons of Korah. As the deer pants for streams of water, so my soul longs after You, O God.'),
('PSA', 42, 2, 'PSA.42.2', 'My soul thirsts for God, the living God. When shall I come and appear in God’s presence?'),
('PSA', 42, 3, 'PSA.42.3', 'My tears have been my food both day and night, while men ask me all day long, “Where is your God?”'),
('PSA', 42, 4, 'PSA.42.4', 'These things come to mind as I pour out my soul: how I walked with the multitude, leading the festive procession to the house of God with shouts of joy and praise.'),
('PSA', 42, 5, 'PSA.42.5', 'Why are you downcast, O my soul? Why the unease within me? Put your hope in God, for I will yet praise Him for the salvation of His presence.'),
('PSA', 42, 6, 'PSA.42.6', 'O my God, my soul despairs within me. Therefore I remember You from the land of Jordan and the peaks of Hermon—even from Mount Mizar.'),
('PSA', 42, 7, 'PSA.42.7', 'Deep calls to deep in the roar of Your waterfalls; all Your breakers and waves have rolled over me.'),
('PSA', 42, 8, 'PSA.42.8', 'The LORD decrees His loving devotion by day, and at night His song is with me as a prayer to the God of my life.'),
('PSA', 42, 9, 'PSA.42.9', 'I say to God my Rock, “Why have You forgotten me? Why must I walk in sorrow because of the enemy’s oppression?”'),
('PSA', 42, 10, 'PSA.42.10', 'Like the crushing of my bones, my enemies taunt me, while they say to me all day long, “Where is your God?”'),
('PSA', 42, 11, 'PSA.42.11', 'Why are you downcast, O my soul? Why the unease within me? Put your hope in God, for I will yet praise Him, my Savior and my God.'),
('PSA', 43, 1, 'PSA.43.1', 'Vindicate me, O God, and plead my case against an ungodly nation; deliver me from deceitful and unjust men.'),
('PSA', 43, 2, 'PSA.43.2', 'For You are the God of my refuge. Why have You rejected me? Why must I walk in sorrow because of the enemy’s oppression?'),
('PSA', 43, 3, 'PSA.43.3', 'Send out Your light and Your truth; let them lead me. Let them bring me to Your holy mountain and to the place where You dwell.'),
('PSA', 43, 4, 'PSA.43.4', 'Then I will go to the altar of God, to God, my greatest joy. I will praise You with the harp, O God, my God.'),
('PSA', 43, 5, 'PSA.43.5', 'Why are you downcast, O my soul? Why the unease within me? Put your hope in God, for I will yet praise Him, my Savior and my God.'),
('PSA', 44, 1, 'PSA.44.1', 'For the choirmaster. A Maskil of the sons of Korah. We have heard with our ears, O God; our fathers have told us the work You did in their days, in the days of old.'),
('PSA', 44, 2, 'PSA.44.2', 'With Your hand You drove out the nations and planted our fathers there; You crushed the peoples and cast them out.'),
('PSA', 44, 3, 'PSA.44.3', 'For it was not by their sword that they took the land; their arm did not bring them victory. It was by Your right hand, Your arm, and the light of Your face, because You favored them.'),
('PSA', 44, 4, 'PSA.44.4', 'You are my King, O God, who ordains victories for Jacob.'),
('PSA', 44, 5, 'PSA.44.5', 'Through You we repel our foes; through Your name we trample our enemies.'),
('PSA', 44, 6, 'PSA.44.6', 'For I do not trust in my bow, nor does my sword save me.'),
('PSA', 44, 7, 'PSA.44.7', 'For You save us from our enemies; You put those who hate us to shame.'),
('PSA', 44, 8, 'PSA.44.8', 'In God we have boasted all day long, and Your name we will praise forever. Selah'),
('PSA', 44, 9, 'PSA.44.9', 'But You have rejected and humbled us; You no longer go forth with our armies.'),
('PSA', 44, 10, 'PSA.44.10', 'You have made us retreat from the foe, and those who hate us have plundered us.'),
('PSA', 44, 11, 'PSA.44.11', 'You have given us up as sheep to be devoured; You have scattered us among the nations.'),
('PSA', 44, 12, 'PSA.44.12', 'You sell Your people for nothing; no profit do You gain from their sale.'),
('PSA', 44, 13, 'PSA.44.13', 'You have made us a reproach to our neighbors, a mockery and derision to those around us.'),
('PSA', 44, 14, 'PSA.44.14', 'You have made us a byword among the nations, a laughingstock among the peoples.'),
('PSA', 44, 15, 'PSA.44.15', 'All day long my disgrace is before me, and shame has covered my face,'),
('PSA', 44, 16, 'PSA.44.16', 'at the voice of the scorner and reviler, because of the enemy, bent on revenge.'),
('PSA', 44, 17, 'PSA.44.17', 'All this has come upon us, though we have not forgotten You or betrayed Your covenant.'),
('PSA', 44, 18, 'PSA.44.18', 'Our hearts have not turned back; our steps have not strayed from Your path.'),
('PSA', 44, 19, 'PSA.44.19', 'But You have crushed us in the lair of jackals; You have covered us with deepest darkness.'),
('PSA', 44, 20, 'PSA.44.20', 'If we had forgotten the name of our God or spread out our hands to a foreign god,'),
('PSA', 44, 21, 'PSA.44.21', 'would not God have discovered, since He knows the secrets of the heart?'),
('PSA', 44, 22, 'PSA.44.22', 'Yet for Your sake we face death all day long; we are considered as sheep to be slaughtered.'),
('PSA', 44, 23, 'PSA.44.23', 'Wake up, O Lord! Why are You sleeping? Arise! Do not reject us forever.'),
('PSA', 44, 24, 'PSA.44.24', 'Why do You hide Your face and forget our affliction and oppression?'),
('PSA', 44, 25, 'PSA.44.25', 'For our soul has sunk to the dust; our bodies cling to the earth.'),
('PSA', 44, 26, 'PSA.44.26', 'Rise up; be our help! Redeem us on account of Your loving devotion.'),
('PSA', 45, 1, 'PSA.45.1', 'For the choirmaster. To the tune of “The Lilies.” A Maskil of the sons of Korah. A love song. My heart is stirred by a noble theme as I recite my verses to the king; my tongue is the pen of a skillful writer.'),
('PSA', 45, 2, 'PSA.45.2', 'You are the most handsome of men; grace has anointed your lips; therefore God has blessed you forever.'),
('PSA', 45, 3, 'PSA.45.3', 'Strap your sword at your side, O mighty warrior; appear in your majesty and splendor.'),
('PSA', 45, 4, 'PSA.45.4', 'In your splendor ride forth in victory on behalf of truth and humility and justice; may your right hand show your awesome deeds.'),
('PSA', 45, 5, 'PSA.45.5', 'Your arrows pierce the hearts of the king’s foes; the nations fall beneath your feet.'),
('PSA', 45, 6, 'PSA.45.6', 'Your throne, O God, endures forever and ever, and justice is the scepter of Your kingdom.'),
('PSA', 45, 7, 'PSA.45.7', 'You have loved righteousness and hated wickedness; therefore God, your God, has anointed you above your companions with the oil of joy.'),
('PSA', 45, 8, 'PSA.45.8', 'All your garments are fragrant with myrrh and aloes and cassia; from palaces of ivory the harps make you glad.'),
('PSA', 45, 9, 'PSA.45.9', 'The daughters of kings are among your honored women; the queen stands at your right hand, adorned with the gold of Ophir.'),
('PSA', 45, 10, 'PSA.45.10', 'Listen, O daughter! Consider and incline your ear: Forget your people and your father’s house,'),
('PSA', 45, 11, 'PSA.45.11', 'and the king will desire your beauty; bow to him, for he is your lord.'),
('PSA', 45, 12, 'PSA.45.12', 'The Daughter of Tyre will come with a gift; men of wealth will seek your favor.'),
('PSA', 45, 13, 'PSA.45.13', 'All glorious is the princess in her chamber; her gown is embroidered with gold.'),
('PSA', 45, 14, 'PSA.45.14', 'In colorful garments she is led to the king; her virgin companions are brought before you.'),
('PSA', 45, 15, 'PSA.45.15', 'They are led in with joy and gladness; they enter the palace of the king.'),
('PSA', 45, 16, 'PSA.45.16', 'Your sons will succeed your fathers; you will make them princes throughout the land.'),
('PSA', 45, 17, 'PSA.45.17', 'I will commemorate your name through all generations; therefore the nations will praise you forever and ever.'),
('PSA', 46, 1, 'PSA.46.1', 'For the choirmaster. Of the sons of Korah. According to Alamoth. A song. God is our refuge and strength, an ever-present help in times of trouble.'),
('PSA', 46, 2, 'PSA.46.2', 'Therefore we will not fear, though the earth is transformed and the mountains are toppled into the depths of the seas,'),
('PSA', 46, 3, 'PSA.46.3', 'though their waters roar and foam and the mountains quake in the surge. Selah'),
('PSA', 46, 4, 'PSA.46.4', 'There is a river whose streams delight the city of God, the holy place where the Most High dwells.'),
('PSA', 46, 5, 'PSA.46.5', 'God is within her; she will not be moved. God will help her when morning dawns.'),
('PSA', 46, 6, 'PSA.46.6', 'Nations rage, kingdoms crumble; the earth melts when He lifts His voice.'),
('PSA', 46, 7, 'PSA.46.7', 'The LORD of Hosts is with us; the God of Jacob is our fortress. Selah'),
('PSA', 46, 8, 'PSA.46.8', 'Come, see the works of the LORD, who brings devastation upon the earth.'),
('PSA', 46, 9, 'PSA.46.9', 'He makes wars to cease throughout the earth; He breaks the bow and shatters the spear; He burns the shields in the fire.'),
('PSA', 46, 10, 'PSA.46.10', '“Be still and know that I am God; I will be exalted among the nations, I will be exalted over the earth.”'),
('PSA', 46, 11, 'PSA.46.11', 'The LORD of Hosts is with us; the God of Jacob is our fortress. Selah'),
('PSA', 47, 1, 'PSA.47.1', 'For the choirmaster. A Psalm of the sons of Korah. Clap your hands, all you peoples; shout unto God with a voice of triumph.'),
('PSA', 47, 2, 'PSA.47.2', 'How awesome is the LORD Most High, the great King over all the earth!'),
('PSA', 47, 3, 'PSA.47.3', 'He subdues nations beneath us, and peoples under our feet.'),
('PSA', 47, 4, 'PSA.47.4', 'He chooses our inheritance for us, the pride of Jacob, whom He loves. Selah'),
('PSA', 47, 5, 'PSA.47.5', 'God has ascended amid shouts of joy, the LORD with the sound of the horn.'),
('PSA', 47, 6, 'PSA.47.6', 'Sing praises to God, sing praises; sing praises to our King, sing praises!'),
('PSA', 47, 7, 'PSA.47.7', 'For God is King of all the earth; sing to Him a psalm of praise.'),
('PSA', 47, 8, 'PSA.47.8', 'God reigns over the nations; God is seated on His holy throne.'),
('PSA', 47, 9, 'PSA.47.9', 'The nobles of the nations have assembled as the people of the God of Abraham; for the shields of the earth belong to God; He is highly exalted.'),
('PSA', 48, 1, 'PSA.48.1', 'A song. A Psalm of the sons of Korah. Great is the LORD, and greatly to be praised in the city of our God, His holy mountain.'),
('PSA', 48, 2, 'PSA.48.2', 'Beautiful in loftiness, the joy of all the earth, like the peaks of Zaphon is Mount Zion, the city of the great King.'),
('PSA', 48, 3, 'PSA.48.3', 'God is in her citadels; He has shown Himself to be a fortress.'),
('PSA', 48, 4, 'PSA.48.4', 'For behold, the kings assembled; they all advanced together.'),
('PSA', 48, 5, 'PSA.48.5', 'They saw and were astounded; they fled in terror.'),
('PSA', 48, 6, 'PSA.48.6', 'Trembling seized them there, anguish like a woman in labor.'),
('PSA', 48, 7, 'PSA.48.7', 'With a wind from the east You wrecked the ships of Tarshish.'),
('PSA', 48, 8, 'PSA.48.8', 'As we have heard, so we have seen in the city of the LORD of Hosts, in the city of our God: God will establish her forever. Selah'),
('PSA', 48, 9, 'PSA.48.9', 'Within Your temple, O God, we contemplate Your loving devotion.'),
('PSA', 48, 10, 'PSA.48.10', 'Your name, O God, like Your praise, reaches to the ends of the earth; Your right hand is full of righteousness.'),
('PSA', 48, 11, 'PSA.48.11', 'Mount Zion is glad, the daughters of Judah rejoice, on account of Your judgments.'),
('PSA', 48, 12, 'PSA.48.12', 'March around Zion, encircle her, count her towers,'),
('PSA', 48, 13, 'PSA.48.13', 'consider her ramparts, tour her citadels, that you may tell the next generation.'),
('PSA', 48, 14, 'PSA.48.14', 'For this God is our God forever and ever; He will be our guide even till death.'),
('PSA', 49, 1, 'PSA.49.1', 'For the choirmaster. A Psalm of the sons of Korah. Hear this, all you peoples; listen, all inhabitants of the world,'),
('PSA', 49, 2, 'PSA.49.2', 'both low and high, rich and poor alike.'),
('PSA', 49, 3, 'PSA.49.3', 'My mouth will impart wisdom, and the meditation of my heart will bring understanding.'),
('PSA', 49, 4, 'PSA.49.4', 'I will incline my ear to a proverb; I will express my riddle with the harp:'),
('PSA', 49, 5, 'PSA.49.5', 'Why should I fear in times of trouble, when wicked usurpers surround me?'),
('PSA', 49, 6, 'PSA.49.6', 'They trust in their wealth and boast in their great riches.'),
('PSA', 49, 7, 'PSA.49.7', 'No man can possibly redeem his brother or pay his ransom to God.'),
('PSA', 49, 8, 'PSA.49.8', 'For the redemption of his soul is costly, and never can payment suffice,'),
('PSA', 49, 9, 'PSA.49.9', 'that he should live on forever and not see decay.'),
('PSA', 49, 10, 'PSA.49.10', 'For it is clear that wise men die, and the foolish and the senseless both perish and leave their wealth to others.'),
('PSA', 49, 11, 'PSA.49.11', 'Their graves are their eternal homes—their dwellings for endless generations—even though their lands were their namesakes.'),
('PSA', 49, 12, 'PSA.49.12', 'But a man, despite his wealth, cannot endure; he is like the beasts that perish.'),
('PSA', 49, 13, 'PSA.49.13', 'This is the fate of the foolish and their followers who endorse their sayings. Selah'),
('PSA', 49, 14, 'PSA.49.14', 'Like sheep they are destined for Sheol. Death will be their shepherd. The upright will rule them in the morning, and their form will decay in Sheol, far from their lofty abode.'),
('PSA', 49, 15, 'PSA.49.15', 'But God will redeem my life from Sheol, for He will surely take me to Himself. Selah'),
('PSA', 49, 16, 'PSA.49.16', 'Do not be afraid when a man grows rich, when the splendor of his house increases.'),
('PSA', 49, 17, 'PSA.49.17', 'For when he dies, he will carry nothing away; his abundance will not follow him down.'),
('PSA', 49, 18, 'PSA.49.18', 'Though in his lifetime he blesses his soul—and men praise you when you prosper—'),
('PSA', 49, 19, 'PSA.49.19', 'he will join the generation of his fathers, who will never see the light of day.'),
('PSA', 49, 20, 'PSA.49.20', 'A man who has riches without understanding is like the beasts that perish.'),
('PSA', 50, 1, 'PSA.50.1', 'A Psalm of Asaph. The Mighty One, God the LORD, speaks and summons the earth from where the sun rises to where it sets.'),
('PSA', 50, 2, 'PSA.50.2', 'From Zion, perfect in beauty, God shines forth.'),
('PSA', 50, 3, 'PSA.50.3', 'Our God approaches and will not be silent! Consuming fire precedes Him, and a tempest rages around Him.'),
('PSA', 50, 4, 'PSA.50.4', 'He summons the heavens above, and the earth, that He may judge His people:'),
('PSA', 50, 5, 'PSA.50.5', '“Gather to Me My saints, who made a covenant with Me by sacrifice.”'),
('PSA', 50, 6, 'PSA.50.6', 'And the heavens proclaim His righteousness, for God Himself is Judge. Selah'),
('PSA', 50, 7, 'PSA.50.7', '“Hear, O My people, and I will speak, O Israel, and I will testify against you: I am God, your God.'),
('PSA', 50, 8, 'PSA.50.8', 'I do not rebuke you for your sacrifices, and your burnt offerings are ever before Me.'),
('PSA', 50, 9, 'PSA.50.9', 'I have no need for a bull from your stall or goats from your pens,'),
('PSA', 50, 10, 'PSA.50.10', 'for every beast of the forest is Mine—the cattle on a thousand hills.'),
('PSA', 50, 11, 'PSA.50.11', 'I know every bird in the mountains, and the creatures of the field are Mine.'),
('PSA', 50, 12, 'PSA.50.12', 'If I were hungry, I would not tell you, for the world is Mine, and the fullness thereof.'),
('PSA', 50, 13, 'PSA.50.13', 'Do I eat the flesh of bulls, or drink the blood of goats?'),
('PSA', 50, 14, 'PSA.50.14', 'Sacrifice a thank offering to God, and fulfill your vows to the Most High.'),
('PSA', 50, 15, 'PSA.50.15', 'Call upon Me in the day of trouble; I will deliver you, and you will honor Me.”'),
('PSA', 50, 16, 'PSA.50.16', 'To the wicked, however, God says, “What right have you to recite My statutes and to bear My covenant on your lips?'),
('PSA', 50, 17, 'PSA.50.17', 'For you hate My instruction and cast My words behind you.'),
('PSA', 50, 18, 'PSA.50.18', 'When you see a thief, you befriend him, and throw in your lot with adulterers.'),
('PSA', 50, 19, 'PSA.50.19', 'You unleash your mouth for evil and harness your tongue to deceit.'),
('PSA', 50, 20, 'PSA.50.20', 'You sit and malign your brother; you slander your own mother’s son.'),
('PSA', 50, 21, 'PSA.50.21', 'You have done these things, and I kept silent; you thought I was just like you. But now I rebuke you and accuse you to your face.'),
('PSA', 50, 22, 'PSA.50.22', 'Now consider this, you who forget God, lest I tear you to pieces, with no one to rescue you:'),
('PSA', 50, 23, 'PSA.50.23', 'He who sacrifices a thank offering honors Me, and to him who rightly orders his way, I will show the salvation of God.”'),
('PSA', 51, 1, 'PSA.51.1', 'For the choirmaster. A Psalm of David. When Nathan the prophet came to him after his adultery with Bathsheba. Have mercy on me, O God, according to Your loving devotion; according to Your great compassion, blot out my transgressions.'),
('PSA', 51, 2, 'PSA.51.2', 'Wash me clean of my iniquity and cleanse me from my sin.'),
('PSA', 51, 3, 'PSA.51.3', 'For I know my transgressions, and my sin is always before me.'),
('PSA', 51, 4, 'PSA.51.4', 'Against You, You only, have I sinned and done what is evil in Your sight, so that You may be proved right when You speak and blameless when You judge.'),
('PSA', 51, 5, 'PSA.51.5', 'Surely I was brought forth in iniquity; I was sinful when my mother conceived me.'),
('PSA', 51, 6, 'PSA.51.6', 'Surely You desire truth in the inmost being; You teach me wisdom in the inmost place.'),
('PSA', 51, 7, 'PSA.51.7', 'Purify me with hyssop, and I will be clean; wash me, and I will be whiter than snow.'),
('PSA', 51, 8, 'PSA.51.8', 'Let me hear joy and gladness; let the bones You have crushed rejoice.'),
('PSA', 51, 9, 'PSA.51.9', 'Hide Your face from my sins and blot out all my iniquities.'),
('PSA', 51, 10, 'PSA.51.10', 'Create in me a clean heart, O God, and renew a right spirit within me.'),
('PSA', 51, 11, 'PSA.51.11', 'Cast me not away from Your presence; take not Your Holy Spirit from me.'),
('PSA', 51, 12, 'PSA.51.12', 'Restore to me the joy of Your salvation, and sustain me with a willing spirit.'),
('PSA', 51, 13, 'PSA.51.13', 'Then I will teach transgressors Your ways, and sinners will return to You.'),
('PSA', 51, 14, 'PSA.51.14', 'Deliver me from bloodguilt, O God, the God of my salvation, and my tongue will sing of Your righteousness.'),
('PSA', 51, 15, 'PSA.51.15', 'O Lord, open my lips, and my mouth will declare Your praise.'),
('PSA', 51, 16, 'PSA.51.16', 'For You do not delight in sacrifice, or I would bring it; You take no pleasure in burnt offerings.'),
('PSA', 51, 17, 'PSA.51.17', 'The sacrifices of God are a broken spirit; a broken and a contrite heart, O God, You will not despise.'),
('PSA', 51, 18, 'PSA.51.18', 'In Your good pleasure, cause Zion to prosper; build up the walls of Jerusalem.'),
('PSA', 51, 19, 'PSA.51.19', 'Then You will delight in righteous sacrifices, in whole burnt offerings; then bulls will be offered on Your altar.'),
('PSA', 52, 1, 'PSA.52.1', 'For the choirmaster. A Maskil of David. After Doeg the Edomite went to Saul and told him, “David has gone to the house of Ahimelech.” Why do you boast of evil, O mighty man? The loving devotion of God endures all day long.'),
('PSA', 52, 2, 'PSA.52.2', 'Your tongue devises destruction like a sharpened razor, O worker of deceit.'),
('PSA', 52, 3, 'PSA.52.3', 'You love evil more than good, falsehood more than speaking truth. Selah'),
('PSA', 52, 4, 'PSA.52.4', 'You love every word that devours, O deceitful tongue.'),
('PSA', 52, 5, 'PSA.52.5', 'Surely God will bring you down to everlasting ruin; He will snatch you up and tear you away from your tent; He will uproot you from the land of the living. Selah'),
('PSA', 52, 6, 'PSA.52.6', 'The righteous will see and fear; they will mock the evildoer, saying,'),
('PSA', 52, 7, 'PSA.52.7', '“Look at the man who did not make God his refuge, but trusted in the abundance of his wealth and strengthened himself by destruction.”'),
('PSA', 52, 8, 'PSA.52.8', 'But I am like an olive tree flourishing in the house of God; I trust in the loving devotion of God forever and ever.'),
('PSA', 52, 9, 'PSA.52.9', 'I will praise You forever, because You have done it. I will wait on Your name—for it is good—in the presence of Your saints.'),
('PSA', 53, 1, 'PSA.53.1', 'For the choirmaster. According to Mahalath. A Maskil of David. The fool says in his heart, “There is no God.” They are corrupt; their ways are vile. There is no one who does good.'),
('PSA', 53, 2, 'PSA.53.2', 'God looks down from heaven upon the sons of men to see if any understand, if any seek God.'),
('PSA', 53, 3, 'PSA.53.3', 'All have turned away, they have together become corrupt; there is no one who does good, not even one.'),
('PSA', 53, 4, 'PSA.53.4', 'Will the workers of iniquity never learn? They devour my people like bread; they refuse to call upon God.'),
('PSA', 53, 5, 'PSA.53.5', 'There they are, overwhelmed with dread, where there was nothing to fear. For God has scattered the bones of those who besieged you. You put them to shame, for God has despised them.'),
('PSA', 53, 6, 'PSA.53.6', 'Oh, that the salvation of Israel would come from Zion! When God restores His captive people, let Jacob rejoice, let Israel be glad!'),
('PSA', 54, 1, 'PSA.54.1', 'For the choirmaster. With stringed instruments. A Maskil of David. When the Ziphites went to Saul and said, “Is David not hiding among us?” Save me, O God, by Your name, and vindicate me by Your might!'),
('PSA', 54, 2, 'PSA.54.2', 'Hear my prayer, O God; listen to the words of my mouth.'),
('PSA', 54, 3, 'PSA.54.3', 'For strangers rise up against me, and ruthless men seek my life—men with no regard for God. Selah'),
('PSA', 54, 4, 'PSA.54.4', 'Surely God is my helper; the Lord is the sustainer of my soul.'),
('PSA', 54, 5, 'PSA.54.5', 'He will reward my enemies with evil. In Your faithfulness, destroy them.'),
('PSA', 54, 6, 'PSA.54.6', 'Freely I will sacrifice to You; I will praise Your name, O LORD, for it is good.'),
('PSA', 54, 7, 'PSA.54.7', 'For He has delivered me from every trouble, and my eyes have looked in triumph on my foes.'),
('PSA', 55, 1, 'PSA.55.1', 'For the choirmaster. With stringed instruments. A Maskil of David. Listen to my prayer, O God, and do not ignore my plea.'),
('PSA', 55, 2, 'PSA.55.2', 'Attend to me and answer me. I am restless in my complaint, and distraught'),
('PSA', 55, 3, 'PSA.55.3', 'at the voice of the enemy, at the pressure of the wicked. For they bring down disaster upon me and resent me in their anger.'),
('PSA', 55, 4, 'PSA.55.4', 'My heart pounds within me, and the terrors of death assail me.'),
('PSA', 55, 5, 'PSA.55.5', 'Fear and trembling grip me, and horror has overwhelmed me.'),
('PSA', 55, 6, 'PSA.55.6', 'I said, “Oh, that I had wings like a dove! I would fly away and find rest.'),
('PSA', 55, 7, 'PSA.55.7', 'How far away I would flee! In the wilderness I would remain. Selah'),
('PSA', 55, 8, 'PSA.55.8', 'I would hurry to my shelter, far from this raging tempest.”'),
('PSA', 55, 9, 'PSA.55.9', 'O Lord, confuse and confound their speech, for I see violence and strife in the city.'),
('PSA', 55, 10, 'PSA.55.10', 'Day and night they encircle the walls, while malice and trouble lie within.'),
('PSA', 55, 11, 'PSA.55.11', 'Destruction is within; oppression and deceit never leave the streets.'),
('PSA', 55, 12, 'PSA.55.12', 'For it is not an enemy who insults me; that I could endure. It is not a foe who rises against me; from him I could hide.'),
('PSA', 55, 13, 'PSA.55.13', 'But it is you, a man like myself, my companion and close friend.'),
('PSA', 55, 14, 'PSA.55.14', 'We shared sweet fellowship together; we walked with the crowd into the house of God.'),
('PSA', 55, 15, 'PSA.55.15', 'Let death seize them by surprise; let them go down to Sheol alive, for evil is with them in their homes.'),
('PSA', 55, 16, 'PSA.55.16', 'But I call to God, and the LORD saves me.'),
('PSA', 55, 17, 'PSA.55.17', 'Morning, noon, and night, I cry out in distress, and He hears my voice.'),
('PSA', 55, 18, 'PSA.55.18', 'He redeems my soul in peace from the battle waged against me, even though many oppose me.'),
('PSA', 55, 19, 'PSA.55.19', 'God will hear and humiliate them—the One enthroned for the ages—Selah because they do not change and they have no fear of God.'),
('PSA', 55, 20, 'PSA.55.20', 'My companion attacks his friends; he violates his covenant.'),
('PSA', 55, 21, 'PSA.55.21', 'His speech is smooth as butter, but war is in his heart. His words are softer than oil, yet they are swords unsheathed.'),
('PSA', 55, 22, 'PSA.55.22', 'Cast your burden upon the LORD and He will sustain you; He will never let the righteous be shaken.'),
('PSA', 55, 23, 'PSA.55.23', 'But You, O God, will bring them down to the Pit of destruction; men of bloodshed and deceit will not live out half their days. But I will trust in You.'),
('PSA', 56, 1, 'PSA.56.1', 'For the choirmaster. To the tune of “A Dove on Distant Oaks.” A Miktam of David, when the Philistines seized him in Gath. Be merciful to me, O God, for men are hounding me; all day they press their attack.'),
('PSA', 56, 2, 'PSA.56.2', 'My enemies pursue me all day long, for many proudly assail me.'),
('PSA', 56, 3, 'PSA.56.3', 'When I am afraid, I put my trust in You.'),
('PSA', 56, 4, 'PSA.56.4', 'In God, whose word I praise—in God I trust. I will not be afraid. What can man do to me?'),
('PSA', 56, 5, 'PSA.56.5', 'All day long they twist my words; all their thoughts are on my demise.'),
('PSA', 56, 6, 'PSA.56.6', 'They conspire, they lurk, they watch my steps while they wait to take my life.'),
('PSA', 56, 7, 'PSA.56.7', 'In spite of such sin, will they escape? In Your anger, O God, cast down the nations.'),
('PSA', 56, 8, 'PSA.56.8', 'You have taken account of my wanderings. Put my tears in Your bottle—are they not in Your book?'),
('PSA', 56, 9, 'PSA.56.9', 'Then my enemies will retreat on the day I cry for help. By this I will know that God is on my side.'),
('PSA', 56, 10, 'PSA.56.10', 'In God, whose word I praise, in the LORD, whose word I praise,'),
('PSA', 56, 11, 'PSA.56.11', 'in God I trust; I will not be afraid. What can man do to me?'),
('PSA', 56, 12, 'PSA.56.12', 'Your vows are upon me, O God; I will render thank offerings to You.'),
('PSA', 56, 13, 'PSA.56.13', 'For You have delivered my soul from death, and my feet from stumbling, that I may walk before God in the light of life.'),
('PSA', 57, 1, 'PSA.57.1', 'For the choirmaster. To the tune of “Do Not Destroy.” A Miktam of David, when he fled from Saul into the cave. Have mercy on me, O God, have mercy, for in You my soul takes refuge. In the shadow of Your wings I will take shelter until the danger has passed.'),
('PSA', 57, 2, 'PSA.57.2', 'I cry out to God Most High, to God who fulfills His purpose for me.'),
('PSA', 57, 3, 'PSA.57.3', 'He reaches down from heaven and saves me; He rebukes those who trample me. Selah God sends forth His loving devotion and His truth.'),
('PSA', 57, 4, 'PSA.57.4', 'My soul is among the lions; I lie down with ravenous beasts—with men whose teeth are spears and arrows, whose tongues are sharp swords.'),
('PSA', 57, 5, 'PSA.57.5', 'Be exalted, O God, above the heavens; may Your glory cover all the earth.'),
('PSA', 57, 6, 'PSA.57.6', 'They spread a net for my feet; my soul was despondent. They dug a pit before me, but they themselves have fallen into it! Selah'),
('PSA', 57, 7, 'PSA.57.7', 'My heart is steadfast, O God, my heart is steadfast. I will sing and make music.'),
('PSA', 57, 8, 'PSA.57.8', 'Awake, my glory! Awake, O harp and lyre! I will awaken the dawn.'),
('PSA', 57, 9, 'PSA.57.9', 'I will praise You, O Lord, among the nations; I will sing Your praises among the peoples.'),
('PSA', 57, 10, 'PSA.57.10', 'For Your loving devotion reaches to the heavens, and Your faithfulness to the clouds.'),
('PSA', 57, 11, 'PSA.57.11', 'Be exalted, O God, above the heavens; may Your glory cover all the earth.'),
('PSA', 58, 1, 'PSA.58.1', 'For the choirmaster. To the tune of “Do Not Destroy.” A Miktam of David. Do you indeed speak justly, O rulers? Do you judge uprightly, O sons of men?'),
('PSA', 58, 2, 'PSA.58.2', 'No, in your hearts you devise injustice; with your hands you mete out violence on the earth.'),
('PSA', 58, 3, 'PSA.58.3', 'The wicked are estranged from the womb; the liars go astray from birth.'),
('PSA', 58, 4, 'PSA.58.4', 'Their venom is like the venom of a snake, like a cobra that shuts its ears,'),
('PSA', 58, 5, 'PSA.58.5', 'refusing to hear the tune of the charmer who skillfully weaves his spell.'),
('PSA', 58, 6, 'PSA.58.6', 'O God, shatter their teeth in their mouths; O LORD, tear out the fangs of the lions.'),
('PSA', 58, 7, 'PSA.58.7', 'May they vanish like water that runs off; when they draw the bow, may their arrows be blunted.'),
('PSA', 58, 8, 'PSA.58.8', 'Like a slug that dissolves in its slime, like a woman’s stillborn child, may they never see the sun.'),
('PSA', 58, 9, 'PSA.58.9', 'Before your pots can feel the burning thorns—whether green or dry—He will sweep them away.'),
('PSA', 58, 10, 'PSA.58.10', 'The righteous will rejoice when they see they are avenged; they will wash their feet in the blood of the wicked.'),
('PSA', 58, 11, 'PSA.58.11', 'Then men will say, “There is surely a reward for the righteous! There is surely a God who judges the earth!”'),
('PSA', 59, 1, 'PSA.59.1', 'For the choirmaster. To the tune of “Do Not Destroy.” A Miktam of David, when Saul sent men to watch David’s house in order to kill him. Deliver me from my enemies, O my God; protect me from those who rise against me.'),
('PSA', 59, 2, 'PSA.59.2', 'Deliver me from workers of iniquity, and save me from men of bloodshed.'),
('PSA', 59, 3, 'PSA.59.3', 'See how they lie in wait for me. Fierce men conspire against me for no transgression or sin of my own, O LORD.'),
('PSA', 59, 4, 'PSA.59.4', 'For no fault of my own, they move swiftly to attack me. Arise to help me, and take notice.'),
('PSA', 59, 5, 'PSA.59.5', 'O LORD God of Hosts, the God of Israel, rouse Yourself to punish all the nations; show no mercy to the wicked traitors. Selah'),
('PSA', 59, 6, 'PSA.59.6', 'They return in the evening, snarling like dogs and prowling around the city.'),
('PSA', 59, 7, 'PSA.59.7', 'See what they spew from their mouths—sharp words from their lips: “For who can hear us?”'),
('PSA', 59, 8, 'PSA.59.8', 'But You, O LORD, laugh at them; You scoff at all the nations.'),
('PSA', 59, 9, 'PSA.59.9', 'I will keep watch for You, O my strength, because You, O God, are my fortress.'),
('PSA', 59, 10, 'PSA.59.10', 'My God of loving devotion will come to meet me; God will let me stare down my foes.'),
('PSA', 59, 11, 'PSA.59.11', 'Do not kill them, or my people will forget. Scatter them by Your power, and bring them down, O Lord, our shield.'),
('PSA', 59, 12, 'PSA.59.12', 'By the sins of their mouths and the words of their lips, let them be trapped in their pride, in the curses and lies they utter.'),
('PSA', 59, 13, 'PSA.59.13', 'Consume them in wrath; consume them till they are no more, so it may be known to the ends of the earth that God rules over Jacob. Selah'),
('PSA', 59, 14, 'PSA.59.14', 'They return in the evening, snarling like dogs and prowling around the city.'),
('PSA', 59, 15, 'PSA.59.15', 'They scavenge for food, and growl if they are not satisfied.'),
('PSA', 59, 16, 'PSA.59.16', 'But I will sing of Your strength and proclaim Your loving devotion in the morning. For You are my fortress, my refuge in times of trouble.'),
('PSA', 59, 17, 'PSA.59.17', 'To You, O my strength, I sing praises, for You, O God, are my fortress, my God of loving devotion.'),
('PSA', 60, 1, 'PSA.60.1', 'For the choirmaster. To the tune of “The Lily of the Covenant.” A Miktam of David for instruction. When he fought Aram-naharaim and Aram-zobah, and Joab returned and struck down 12,000 Edomites in the Valley of Salt. You have rejected us, O God; You have broken us; You have been angry; restore us!'),
('PSA', 60, 2, 'PSA.60.2', 'You have shaken the land and torn it open. Heal its fractures, for it is quaking.'),
('PSA', 60, 3, 'PSA.60.3', 'You have shown Your people hardship; we are staggered from the wine You made us drink.'),
('PSA', 60, 4, 'PSA.60.4', 'You have raised a banner for those who fear You, that they may flee the bow. Selah'),
('PSA', 60, 5, 'PSA.60.5', 'Respond and save us with Your right hand, that Your beloved may be delivered.'),
('PSA', 60, 6, 'PSA.60.6', 'God has spoken from His sanctuary: “I will triumph! I will parcel out Shechem and apportion the Valley of Succoth.'),
('PSA', 60, 7, 'PSA.60.7', 'Gilead is Mine, and Manasseh is Mine; Ephraim is My helmet, Judah is My scepter.'),
('PSA', 60, 8, 'PSA.60.8', 'Moab is My washbasin; upon Edom I toss My sandal; over Philistia I shout in triumph.”'),
('PSA', 60, 9, 'PSA.60.9', 'Who will bring me to the fortified city? Who will lead me to Edom?'),
('PSA', 60, 10, 'PSA.60.10', 'Have You not rejected us, O God? Will You no longer march out, O God, with our armies?'),
('PSA', 60, 11, 'PSA.60.11', 'Give us aid against the enemy, for the help of man is worthless.'),
('PSA', 60, 12, 'PSA.60.12', 'With God we will perform with valor, and He will trample our enemies.'),
('PSA', 61, 1, 'PSA.61.1', 'For the choirmaster. With stringed instruments. Of David. Hear my cry, O God; attend to my prayer.'),
('PSA', 61, 2, 'PSA.61.2', 'From the ends of the earth I call out to You whenever my heart is faint. Lead me to the rock that is higher than I.'),
('PSA', 61, 3, 'PSA.61.3', 'For You have been my refuge, a tower of strength against the enemy.'),
('PSA', 61, 4, 'PSA.61.4', 'Let me dwell in Your tent forever and take refuge in the shelter of Your wings. Selah'),
('PSA', 61, 5, 'PSA.61.5', 'For You have heard my vows, O God; You have given me the inheritance reserved for those who fear Your name.'),
('PSA', 61, 6, 'PSA.61.6', 'Increase the days of the king’s life; may his years span many generations.'),
('PSA', 61, 7, 'PSA.61.7', 'May he sit enthroned in God’s presence forever; appoint Your loving devotion and Your faithfulness to guard him.'),
('PSA', 61, 8, 'PSA.61.8', 'Then I will ever sing praise to Your name and fulfill my vows day by day.'),
('PSA', 62, 1, 'PSA.62.1', 'For the choirmaster. According to Jeduthun. A Psalm of David. In God alone my soul finds rest; my salvation comes from Him.'),
('PSA', 62, 2, 'PSA.62.2', 'He alone is my rock and my salvation. He is my fortress; I will never be shaken.'),
('PSA', 62, 3, 'PSA.62.3', 'How long will you threaten a man? Will all of you throw him down like a leaning wall or a tottering fence?'),
('PSA', 62, 4, 'PSA.62.4', 'They fully intend to cast him down from his lofty perch; they delight in lies; with their mouths they bless, but inwardly they curse. Selah'),
('PSA', 62, 5, 'PSA.62.5', 'Rest in God alone, O my soul, for my hope comes from Him.'),
('PSA', 62, 6, 'PSA.62.6', 'He alone is my rock and my salvation; He is my fortress; I will not be shaken.'),
('PSA', 62, 7, 'PSA.62.7', 'My salvation and my honor rest on God, my strong rock; my refuge is in God.'),
('PSA', 62, 8, 'PSA.62.8', 'Trust in Him at all times, O people; pour out your hearts before Him. God is our refuge. Selah'),
('PSA', 62, 9, 'PSA.62.9', 'Lowborn men are but a vapor; the exalted are but a lie. Weighed on the scale, they go up; together they are but a vapor.'),
('PSA', 62, 10, 'PSA.62.10', 'Place no trust in extortion or false hope in stolen goods. If your riches increase, do not set your heart upon them.'),
('PSA', 62, 11, 'PSA.62.11', 'God has spoken once; I have heard this twice: that power belongs to God,'),
('PSA', 62, 12, 'PSA.62.12', 'and loving devotion to You, O Lord. For You will repay each man according to his deeds.'),
('PSA', 63, 1, 'PSA.63.1', 'A Psalm of David, when he was in the Wilderness of Judah. O God, You are my God. Earnestly I seek You; my soul thirsts for You. My body yearns for You in a dry and weary land without water.'),
('PSA', 63, 2, 'PSA.63.2', 'So I have seen You in the sanctuary and beheld Your power and glory.'),
('PSA', 63, 3, 'PSA.63.3', 'Because Your loving devotion is better than life, my lips will glorify You.'),
('PSA', 63, 4, 'PSA.63.4', 'So I will bless You as long as I live; in Your name I will lift my hands.'),
('PSA', 63, 5, 'PSA.63.5', 'My soul is satisfied as with the richest of foods; with joyful lips my mouth will praise You.'),
('PSA', 63, 6, 'PSA.63.6', 'When I remember You on my bed, I think of You through the watches of the night.'),
('PSA', 63, 7, 'PSA.63.7', 'For You are my help; I will sing for joy in the shadow of Your wings.'),
('PSA', 63, 8, 'PSA.63.8', 'My soul clings to You; Your right hand upholds me.'),
('PSA', 63, 9, 'PSA.63.9', 'But those who seek my life to destroy it will go into the depths of the earth.'),
('PSA', 63, 10, 'PSA.63.10', 'They will fall to the power of the sword; they will become a portion for foxes.'),
('PSA', 63, 11, 'PSA.63.11', 'But the king will rejoice in God; all who swear by Him will exult, for the mouths of liars will be shut.'),
('PSA', 64, 1, 'PSA.64.1', 'For the choirmaster. A Psalm of David. Hear, O God, my voice of complaint; preserve my life from dread of the enemy.'),
('PSA', 64, 2, 'PSA.64.2', 'Hide me from the scheming of the wicked, from the mob of workers of iniquity,'),
('PSA', 64, 3, 'PSA.64.3', 'who sharpen their tongues like swords and aim their bitter words like arrows,'),
('PSA', 64, 4, 'PSA.64.4', 'ambushing the innocent in seclusion, shooting suddenly, without fear.'),
('PSA', 64, 5, 'PSA.64.5', 'They hold fast to their evil purpose; they speak of hiding their snares. “Who will see them?” they say.'),
('PSA', 64, 6, 'PSA.64.6', 'They devise injustice and say, “We have perfected a secret plan.” For the inner man and the heart are mysterious.'),
('PSA', 64, 7, 'PSA.64.7', 'But God will shoot them with arrows; suddenly they will be wounded.'),
('PSA', 64, 8, 'PSA.64.8', 'They will be made to stumble, their own tongues turned against them. All who see will shake their heads.'),
('PSA', 64, 9, 'PSA.64.9', 'Then all mankind will fear and proclaim the work of God; so they will ponder what He has done.'),
('PSA', 64, 10, 'PSA.64.10', 'Let the righteous rejoice in the LORD and take refuge in Him; let all the upright in heart exult.'),
('PSA', 65, 1, 'PSA.65.1', 'For the choirmaster. A Psalm of David. A song. Praise awaits You, O God, in Zion; to You our vows will be fulfilled.'),
('PSA', 65, 2, 'PSA.65.2', 'O You who listen to prayer, all people will come to You.'),
('PSA', 65, 3, 'PSA.65.3', 'When iniquities prevail against me, You atone for our transgressions.'),
('PSA', 65, 4, 'PSA.65.4', 'Blessed is the one You choose and bring near to dwell in Your courts! We are filled with the goodness of Your house, the holiness of Your temple.'),
('PSA', 65, 5, 'PSA.65.5', 'With awesome deeds of righteousness You answer us, O God of our salvation, the hope of all the ends of the earth and of the farthest seas.'),
('PSA', 65, 6, 'PSA.65.6', 'You formed the mountains by Your power, having girded Yourself with might.'),
('PSA', 65, 7, 'PSA.65.7', 'You stilled the roaring of the seas, the pounding of their waves, and the tumult of the nations.'),
('PSA', 65, 8, 'PSA.65.8', 'Those who live far away fear Your wonders; You make the dawn and sunset shout for joy.'),
('PSA', 65, 9, 'PSA.65.9', 'You attend to the earth and water it; with abundance You enrich it. The streams of God are full of water, for You prepare our grain by providing for the earth.'),
('PSA', 65, 10, 'PSA.65.10', 'You soak its furrows and level its ridges; You soften it with showers and bless its growth.'),
('PSA', 65, 11, 'PSA.65.11', 'You crown the year with Your bounty, and Your paths overflow with plenty.'),
('PSA', 65, 12, 'PSA.65.12', 'The pastures of the wilderness overflow; the hills are robed with joy.'),
('PSA', 65, 13, 'PSA.65.13', 'The pastures are clothed with flocks, and the valleys are decked with grain. They shout in triumph; indeed, they sing.'),
('PSA', 66, 1, 'PSA.66.1', 'For the choirmaster. A song. A Psalm. Make a joyful noise to God, all the earth!'),
('PSA', 66, 2, 'PSA.66.2', 'Sing the glory of His name; make His praise glorious.'),
('PSA', 66, 3, 'PSA.66.3', 'Say to God, “How awesome are Your deeds! So great is Your power that Your enemies cower before You.'),
('PSA', 66, 4, 'PSA.66.4', 'All the earth bows down to You; they sing praise to You; they sing praise to Your name.” Selah'),
('PSA', 66, 5, 'PSA.66.5', 'Come and see the works of God; how awesome are His deeds toward mankind.'),
('PSA', 66, 6, 'PSA.66.6', 'He turned the sea into dry land; they passed through the waters on foot; there we rejoiced in Him.'),
('PSA', 66, 7, 'PSA.66.7', 'He rules forever by His power; His eyes watch the nations. Do not let the rebellious exalt themselves. Selah'),
('PSA', 66, 8, 'PSA.66.8', 'Bless our God, O peoples; let the sound of His praise be heard.'),
('PSA', 66, 9, 'PSA.66.9', 'He preserves our lives and keeps our feet from slipping.'),
('PSA', 66, 10, 'PSA.66.10', 'For You, O God, have tested us; You have refined us like silver.'),
('PSA', 66, 11, 'PSA.66.11', 'You led us into the net; You laid burdens on our backs.'),
('PSA', 66, 12, 'PSA.66.12', 'You let men ride over our heads; we went through fire and water, but You brought us into abundance.'),
('PSA', 66, 13, 'PSA.66.13', 'I will enter Your house with burnt offerings; I will fulfill my vows to You—'),
('PSA', 66, 14, 'PSA.66.14', 'the vows that my lips promised and my mouth spoke in my distress.'),
('PSA', 66, 15, 'PSA.66.15', 'I will offer You fatlings as burnt offerings, with the fragrant smoke of rams; I will offer bulls and goats. Selah'),
('PSA', 66, 16, 'PSA.66.16', 'Come and listen, all you who fear God, and I will declare what He has done for me.'),
('PSA', 66, 17, 'PSA.66.17', 'I cried out to Him with my mouth and praised Him with my tongue.'),
('PSA', 66, 18, 'PSA.66.18', 'If I had cherished iniquity in my heart, the Lord would not have listened.'),
('PSA', 66, 19, 'PSA.66.19', 'But God has surely heard; He has attended to the sound of my prayer.'),
('PSA', 66, 20, 'PSA.66.20', 'Blessed be God, who has not rejected my prayer or withheld from me His loving devotion!'),
('PSA', 67, 1, 'PSA.67.1', 'For the choirmaster. With stringed instruments. A Psalm. A song. May God be gracious to us and bless us, and cause His face to shine upon us, Selah'),
('PSA', 67, 2, 'PSA.67.2', 'that Your ways may be known on earth, Your salvation among all nations.'),
('PSA', 67, 3, 'PSA.67.3', 'Let the peoples praise You, O God; let all the peoples praise You.'),
('PSA', 67, 4, 'PSA.67.4', 'Let the nations be glad and sing for joy, for You judge the peoples justly and lead the nations of the earth. Selah'),
('PSA', 67, 5, 'PSA.67.5', 'Let the peoples praise You, O God; let all the peoples praise You.'),
('PSA', 67, 6, 'PSA.67.6', 'The earth has yielded its harvest; God, our God, blesses us.'),
('PSA', 67, 7, 'PSA.67.7', 'God blesses us, that all the ends of the earth shall fear Him.'),
('PSA', 68, 1, 'PSA.68.1', 'For the choirmaster. A Psalm of David. A song. God arises. His enemies are scattered, and those who hate Him flee His presence.'),
('PSA', 68, 2, 'PSA.68.2', 'As smoke is blown away, You will drive them out; as wax melts before the fire, the wicked will perish in the presence of God.'),
('PSA', 68, 3, 'PSA.68.3', 'But the righteous will be glad and rejoice before God; they will celebrate with joy.'),
('PSA', 68, 4, 'PSA.68.4', 'Sing to God! Sing praises to His name. Exalt Him who rides on the clouds—His name is the LORD—and rejoice before Him.'),
('PSA', 68, 5, 'PSA.68.5', 'A father of the fatherless and a defender of widows is God in His holy habitation.'),
('PSA', 68, 6, 'PSA.68.6', 'God settles the lonely in families; He leads the prisoners out to prosperity, but the rebellious dwell in a sun-scorched land.'),
('PSA', 68, 7, 'PSA.68.7', 'O God, when You went out before Your people, when You marched through the wasteland, Selah'),
('PSA', 68, 8, 'PSA.68.8', 'the earth shook and the heavens poured down rain before God, the One on Sinai, before God, the God of Israel.'),
('PSA', 68, 9, 'PSA.68.9', 'You sent abundant rain, O God; You refreshed Your weary inheritance.'),
('PSA', 68, 10, 'PSA.68.10', 'Your flock settled therein; O God, from Your bounty You provided for the poor.'),
('PSA', 68, 11, 'PSA.68.11', 'The Lord gives the command; a great company of women proclaim it:'),
('PSA', 68, 12, 'PSA.68.12', '“Kings and their armies flee in haste; she who waits at home divides the plunder.'),
('PSA', 68, 13, 'PSA.68.13', 'Though you lie down among the sheepfolds, the wings of the dove are covered with silver, and her feathers with shimmering gold.”'),
('PSA', 68, 14, 'PSA.68.14', 'When the Almighty scattered the kings in the land, it was like the snow falling on Zalmon.'),
('PSA', 68, 15, 'PSA.68.15', 'A mountain of God is Mount Bashan; a mountain of many peaks is Mount Bashan.'),
('PSA', 68, 16, 'PSA.68.16', 'Why do you gaze in envy, O mountains of many peaks? This is the mountain God chose for His dwelling, where the LORD will surely dwell forever.'),
('PSA', 68, 17, 'PSA.68.17', 'The chariots of God are tens of thousands—thousands of thousands are they; the Lord is in His sanctuary as He was at Sinai.'),
('PSA', 68, 18, 'PSA.68.18', 'You have ascended on high; You have led captives away. You have received gifts from men, even from the rebellious, that the LORD God may dwell there.'),
('PSA', 68, 19, 'PSA.68.19', 'Blessed be the Lord, who daily bears our burden, the God of our salvation. Selah'),
('PSA', 68, 20, 'PSA.68.20', 'Our God is a God of deliverance; the Lord GOD is our rescuer from death.'),
('PSA', 68, 21, 'PSA.68.21', 'Surely God will crush the heads of His enemies, the hairy crowns of those who persist in guilty ways.'),
('PSA', 68, 22, 'PSA.68.22', 'The Lord said, “I will retrieve them from Bashan, I will bring them up from the depths of the sea,'),
('PSA', 68, 23, 'PSA.68.23', 'that your foot may be dipped in the blood of your foes—the tongues of your dogs in the same.”'),
('PSA', 68, 24, 'PSA.68.24', 'They have seen Your procession, O God—the march of my God and King into the sanctuary.'),
('PSA', 68, 25, 'PSA.68.25', 'The singers lead the way, the musicians follow after, among the maidens playing tambourines.'),
('PSA', 68, 26, 'PSA.68.26', 'Bless God in the great congregation; bless the LORD from the fountain of Israel.'),
('PSA', 68, 27, 'PSA.68.27', 'There is Benjamin, the youngest, ruling them, the princes of Judah in their company, the princes of Zebulun and of Naphtali.'),
('PSA', 68, 28, 'PSA.68.28', 'Summon Your power, O God; show Your strength, O God, which You have exerted on our behalf.'),
('PSA', 68, 29, 'PSA.68.29', 'Because of Your temple at Jerusalem kings will bring You gifts.'),
('PSA', 68, 30, 'PSA.68.30', 'Rebuke the beast in the reeds, the herd of bulls among the calves of the nations, until it submits, bringing bars of silver. Scatter the nations who delight in war.'),
('PSA', 68, 31, 'PSA.68.31', 'Envoys will arrive from Egypt; Cush will stretch out her hands to God.'),
('PSA', 68, 32, 'PSA.68.32', 'Sing to God, O kingdoms of the earth; sing praises to the Lord—Selah'),
('PSA', 68, 33, 'PSA.68.33', 'to Him who rides upon the highest heavens of old; behold, His mighty voice resounds.'),
('PSA', 68, 34, 'PSA.68.34', 'Ascribe the power to God, whose majesty is over Israel, whose strength is in the skies.'),
('PSA', 68, 35, 'PSA.68.35', 'O God, You are awesome in Your sanctuary; the God of Israel Himself gives strength and power to His people. Blessed be God!'),
('PSA', 69, 1, 'PSA.69.1', 'For the choirmaster. To the tune of “Lilies.” Of David. Save me, O God, for the waters are up to my neck.'),
('PSA', 69, 2, 'PSA.69.2', 'I have sunk into the miry depths, where there is no footing; I have drifted into deep waters, where the flood engulfs me.'),
('PSA', 69, 3, 'PSA.69.3', 'I am weary from my crying; my throat is parched. My eyes fail, looking for my God.'),
('PSA', 69, 4, 'PSA.69.4', 'Those who hate me without cause outnumber the hairs of my head; many are those who would destroy me—my enemies for no reason. Though I did not steal, I must repay.'),
('PSA', 69, 5, 'PSA.69.5', 'You know my folly, O God, and my guilt is not hidden from You.'),
('PSA', 69, 6, 'PSA.69.6', 'May those who hope in You not be ashamed through me, O Lord GOD of Hosts; may those who seek You not be dishonored through me, O God of Israel.'),
('PSA', 69, 7, 'PSA.69.7', 'For I have endured scorn for Your sake, and shame has covered my face.'),
('PSA', 69, 8, 'PSA.69.8', 'I have become a stranger to my brothers and a foreigner to my mother’s sons,'),
('PSA', 69, 9, 'PSA.69.9', 'because zeal for Your house has consumed me, and the insults of those who insult You have fallen on me.'),
('PSA', 69, 10, 'PSA.69.10', 'I wept and fasted, but it brought me reproach.'),
('PSA', 69, 11, 'PSA.69.11', 'I made sackcloth my clothing, and I was sport to them.'),
('PSA', 69, 12, 'PSA.69.12', 'Those who sit at the gate mock me, and I am the song of drunkards.'),
('PSA', 69, 13, 'PSA.69.13', 'But my prayer to You, O LORD, is for a time of favor. In Your abundant loving devotion, O God, answer me with Your sure salvation.'),
('PSA', 69, 14, 'PSA.69.14', 'Rescue me from the mire and do not let me sink; deliver me from my foes and out of the deep waters.'),
('PSA', 69, 15, 'PSA.69.15', 'Do not let the floods engulf me or the depths swallow me up; let not the Pit close its mouth over me.'),
('PSA', 69, 16, 'PSA.69.16', 'Answer me, O LORD, for Your loving devotion is good; turn to me in keeping with Your great compassion.'),
('PSA', 69, 17, 'PSA.69.17', 'Hide not Your face from Your servant, for I am in distress. Answer me quickly!'),
('PSA', 69, 18, 'PSA.69.18', 'Draw near to my soul and redeem me; ransom me because of my foes.'),
('PSA', 69, 19, 'PSA.69.19', 'You know my reproach, my shame and disgrace. All my adversaries are before You.'),
('PSA', 69, 20, 'PSA.69.20', 'Insults have broken my heart, and I am in despair. I looked for sympathy, but there was none, for comforters, but I found no one.'),
('PSA', 69, 21, 'PSA.69.21', 'They poisoned my food with gall and gave me vinegar to quench my thirst.'),
('PSA', 69, 22, 'PSA.69.22', 'May their table become a snare; may it be a retribution and a trap.'),
('PSA', 69, 23, 'PSA.69.23', 'May their eyes be darkened so they cannot see, and their backs be bent forever.'),
('PSA', 69, 24, 'PSA.69.24', 'Pour out Your wrath upon them, and let Your burning anger overtake them.'),
('PSA', 69, 25, 'PSA.69.25', 'May their place be deserted; let there be no one to dwell in their tents.'),
('PSA', 69, 26, 'PSA.69.26', 'For they persecute the one You struck and recount the pain of those You wounded.'),
('PSA', 69, 27, 'PSA.69.27', 'Add iniquity to their iniquity; let them not share in Your righteousness.'),
('PSA', 69, 28, 'PSA.69.28', 'May they be blotted out of the Book of Life and not listed with the righteous.'),
('PSA', 69, 29, 'PSA.69.29', 'But I am in pain and distress; let Your salvation protect me, O God.'),
('PSA', 69, 30, 'PSA.69.30', 'I will praise God’s name in song and exalt Him with thanksgiving.'),
('PSA', 69, 31, 'PSA.69.31', 'And this will please the LORD more than an ox, more than a bull with horns and hooves.'),
('PSA', 69, 32, 'PSA.69.32', 'The humble will see and rejoice. You who seek God, let your hearts be revived!'),
('PSA', 69, 33, 'PSA.69.33', 'For the LORD listens to the needy and does not despise His captive people.'),
('PSA', 69, 34, 'PSA.69.34', 'Let heaven and earth praise Him, the seas and everything that moves in them.'),
('PSA', 69, 35, 'PSA.69.35', 'For God will save Zion and rebuild the cities of Judah, that they may dwell there and possess it.'),
('PSA', 69, 36, 'PSA.69.36', 'The descendants of His servants will inherit it, and those who love His name will settle in it.'),
('PSA', 70, 1, 'PSA.70.1', 'For the choirmaster. Of David. To bring remembrance. Make haste, O God, to deliver me! Hurry, O LORD, to help me!'),
('PSA', 70, 2, 'PSA.70.2', 'May those who seek my life be ashamed and confounded; may those who wish me harm be repelled and humiliated.'),
('PSA', 70, 3, 'PSA.70.3', 'May those who say, “Aha, aha!” retreat because of their shame.'),
('PSA', 70, 4, 'PSA.70.4', 'May all who seek You rejoice and be glad in You; may those who love Your salvation always say, “Let God be magnified!”'),
('PSA', 70, 5, 'PSA.70.5', 'But I am poor and needy; hurry to me, O God. You are my help and my deliverer; O LORD, do not delay.'),
('PSA', 71, 1, 'PSA.71.1', 'In You, O LORD, I have taken refuge; let me never be put to shame.'),
('PSA', 71, 2, 'PSA.71.2', 'In Your justice, rescue and deliver me; incline Your ear and save me.'),
('PSA', 71, 3, 'PSA.71.3', 'Be my rock of refuge, where I can always go. Give the command to save me, for You are my rock and my fortress.'),
('PSA', 71, 4, 'PSA.71.4', 'Deliver me, O my God, from the hand of the wicked, from the grasp of the unjust and ruthless.'),
('PSA', 71, 5, 'PSA.71.5', 'For You are my hope, O Lord GOD, my confidence from my youth.'),
('PSA', 71, 6, 'PSA.71.6', 'I have leaned on You since birth; You pulled me from my mother’s womb. My praise is always for You.'),
('PSA', 71, 7, 'PSA.71.7', 'I have become a portent to many, but You are my strong refuge.'),
('PSA', 71, 8, 'PSA.71.8', 'My mouth is filled with Your praise and with Your splendor all day long.'),
('PSA', 71, 9, 'PSA.71.9', 'Do not discard me in my old age; do not forsake me when my strength fails.'),
('PSA', 71, 10, 'PSA.71.10', 'For my enemies speak against me, and those who lie in wait for my life conspire,'),
('PSA', 71, 11, 'PSA.71.11', 'saying, “God has forsaken him; pursue him and seize him, for there is no one to rescue him.”'),
('PSA', 71, 12, 'PSA.71.12', 'Be not far from me, O God. Hurry, O my God, to help me.'),
('PSA', 71, 13, 'PSA.71.13', 'May the accusers of my soul be ashamed and consumed; may those who seek my harm be covered with scorn and disgrace.'),
('PSA', 71, 14, 'PSA.71.14', 'But I will always hope and will praise You more and more.'),
('PSA', 71, 15, 'PSA.71.15', 'My mouth will declare Your righteousness and Your salvation all day long, though I cannot know their full measure.'),
('PSA', 71, 16, 'PSA.71.16', 'I will come in the strength of the Lord GOD; I will proclaim Your righteousness—Yours alone.'),
('PSA', 71, 17, 'PSA.71.17', 'O God, You have taught me from my youth, and to this day I proclaim Your marvelous deeds.'),
('PSA', 71, 18, 'PSA.71.18', 'Even when I am old and gray, do not forsake me, O God, until I proclaim Your power to the next generation, Your might to all who are to come.'),
('PSA', 71, 19, 'PSA.71.19', 'Your righteousness reaches to the heavens, O God, You who have done great things. Who, O God, is like You?'),
('PSA', 71, 20, 'PSA.71.20', 'Though You have shown me many troubles and misfortunes, You will revive me once again. Even from the depths of the earth You will bring me back up.'),
('PSA', 71, 21, 'PSA.71.21', 'You will increase my honor and comfort me once again.'),
('PSA', 71, 22, 'PSA.71.22', 'So I will praise You with the harp for Your faithfulness, O my God; I will sing praise to You with the lyre, O Holy One of Israel.'),
('PSA', 71, 23, 'PSA.71.23', 'When I sing praise to You my lips will shout for joy, along with my soul, which You have redeemed.'),
('PSA', 71, 24, 'PSA.71.24', 'My tongue will indeed proclaim Your righteousness all day long, for those who seek my harm are disgraced and confounded.'),
('PSA', 72, 1, 'PSA.72.1', 'Of Solomon. Endow the king with Your justice, O God, and the son of the king with Your righteousness.'),
('PSA', 72, 2, 'PSA.72.2', 'May he judge Your people with righteousness and Your afflicted with justice.'),
('PSA', 72, 3, 'PSA.72.3', 'May the mountains bring peace to the people, and the hills bring righteousness.'),
('PSA', 72, 4, 'PSA.72.4', 'May he vindicate the afflicted among the people; may he save the children of the needy and crush the oppressor.'),
('PSA', 72, 5, 'PSA.72.5', 'May they fear him as long as the sun shines, as long as the moon remains, through all generations.'),
('PSA', 72, 6, 'PSA.72.6', 'May he be like rain that falls on freshly cut grass, like spring showers that water the earth.'),
('PSA', 72, 7, 'PSA.72.7', 'May the righteous flourish in his days and prosperity abound until the moon is no more.'),
('PSA', 72, 8, 'PSA.72.8', 'May he rule from sea to sea, and from the Euphrates to the ends of the earth.'),
('PSA', 72, 9, 'PSA.72.9', 'May the nomads bow before him, and his enemies lick the dust.'),
('PSA', 72, 10, 'PSA.72.10', 'May the kings of Tarshish and distant shores bring tribute; may the kings of Sheba and Seba offer gifts.'),
('PSA', 72, 11, 'PSA.72.11', 'May all kings bow down to him and all nations serve him.'),
('PSA', 72, 12, 'PSA.72.12', 'For he will deliver the needy who cry out and the afflicted who have no helper.'),
('PSA', 72, 13, 'PSA.72.13', 'He will take pity on the poor and needy and save the lives of the oppressed.'),
('PSA', 72, 14, 'PSA.72.14', 'He will redeem them from oppression and violence, for their blood is precious in his sight.'),
('PSA', 72, 15, 'PSA.72.15', 'Long may he live! May gold from Sheba be given him. May people ever pray for him; may they bless him all day long.'),
('PSA', 72, 16, 'PSA.72.16', 'May there be an abundance of grain in the land; may it sway atop the hills. May its fruit trees flourish like the forests of Lebanon, the people of its cities like the grass of the field.'),
('PSA', 72, 17, 'PSA.72.17', 'May his name endure forever; may his name continue as long as the sun shines. In him may all nations be blessed; may they call him blessed.'),
('PSA', 72, 18, 'PSA.72.18', 'Blessed be the LORD God, the God of Israel, who alone does marvelous deeds.'),
('PSA', 72, 19, 'PSA.72.19', 'And blessed be His glorious name forever; may all the earth be filled with His glory. Amen and amen.'),
('PSA', 72, 20, 'PSA.72.20', 'Thus conclude the prayers of David son of Jesse.'),
('PSA', 73, 1, 'PSA.73.1', 'A Psalm of Asaph. Surely God is good to Israel, to those who are pure in heart.'),
('PSA', 73, 2, 'PSA.73.2', 'But as for me, my feet had almost stumbled; my steps had nearly slipped.'),
('PSA', 73, 3, 'PSA.73.3', 'For I envied the arrogant when I saw the prosperity of the wicked.'),
('PSA', 73, 4, 'PSA.73.4', 'They have no struggle in their death; their bodies are well-fed.'),
('PSA', 73, 5, 'PSA.73.5', 'They are free of the burdens others carry; they are not afflicted like other men.'),
('PSA', 73, 6, 'PSA.73.6', 'Therefore pride is their necklace; a garment of violence covers them.'),
('PSA', 73, 7, 'PSA.73.7', 'From their prosperity proceeds iniquity; the imaginations of their hearts run wild.'),
('PSA', 73, 8, 'PSA.73.8', 'They mock and speak with malice; with arrogance they threaten oppression.'),
('PSA', 73, 9, 'PSA.73.9', 'They set their mouths against the heavens, and their tongues strut across the earth.'),
('PSA', 73, 10, 'PSA.73.10', 'So their people return to this place and drink up waters in abundance.'),
('PSA', 73, 11, 'PSA.73.11', 'The wicked say, “How can God know? Does the Most High have knowledge?”'),
('PSA', 73, 12, 'PSA.73.12', 'Behold, these are the wicked—always carefree as they increase their wealth.'),
('PSA', 73, 13, 'PSA.73.13', 'Surely in vain I have kept my heart pure; in innocence I have washed my hands.'),
('PSA', 73, 14, 'PSA.73.14', 'For I am afflicted all day long and punished every morning.'),
('PSA', 73, 15, 'PSA.73.15', 'If I had said, “I will speak this way,” then I would have betrayed Your children.'),
('PSA', 73, 16, 'PSA.73.16', 'When I tried to understand all this, it was troublesome in my sight'),
('PSA', 73, 17, 'PSA.73.17', 'until I entered God’s sanctuary; then I discerned their end.'),
('PSA', 73, 18, 'PSA.73.18', 'Surely You set them on slick ground; You cast them down into ruin.'),
('PSA', 73, 19, 'PSA.73.19', 'How suddenly they are laid waste, completely swept away by terrors!'),
('PSA', 73, 20, 'PSA.73.20', 'Like one waking from a dream, so You, O Lord, awaken and despise their form.'),
('PSA', 73, 21, 'PSA.73.21', 'When my heart was grieved and I was pierced within,'),
('PSA', 73, 22, 'PSA.73.22', 'I was senseless and ignorant; I was a brute beast before You.'),
('PSA', 73, 23, 'PSA.73.23', 'Yet I am always with You; You hold my right hand.'),
('PSA', 73, 24, 'PSA.73.24', 'You guide me with Your counsel, and later receive me in glory.'),
('PSA', 73, 25, 'PSA.73.25', 'Whom have I in heaven but You? And on earth I desire no one besides You.'),
('PSA', 73, 26, 'PSA.73.26', 'My flesh and my heart may fail, but God is the strength of my heart and my portion forever.'),
('PSA', 73, 27, 'PSA.73.27', 'Those far from You will surely perish; You destroy all who are unfaithful to You.'),
('PSA', 73, 28, 'PSA.73.28', 'But as for me, it is good to draw near to God. I have made the Lord GOD my refuge, that I may proclaim all Your works.'),
('PSA', 74, 1, 'PSA.74.1', 'A Maskil of Asaph. Why have You rejected us forever, O God? Why does Your anger smolder against the sheep of Your pasture?'),
('PSA', 74, 2, 'PSA.74.2', 'Remember Your congregation, which You purchased long ago and redeemed as the tribe of Your inheritance—Mount Zion, where You dwell.'),
('PSA', 74, 3, 'PSA.74.3', 'Turn Your steps to the everlasting ruins, to everything in the sanctuary the enemy has destroyed.'),
('PSA', 74, 4, 'PSA.74.4', 'Your foes have roared within Your meeting place; they have unfurled their banners as signs,'),
('PSA', 74, 5, 'PSA.74.5', 'like men wielding axes in a thicket of trees'),
('PSA', 74, 6, 'PSA.74.6', 'and smashing all the carvings with hatchets and picks.'),
('PSA', 74, 7, 'PSA.74.7', 'They have burned Your sanctuary to the ground; they have defiled the dwelling place of Your Name.'),
('PSA', 74, 8, 'PSA.74.8', 'They said in their hearts, “We will crush them completely.” They burned down every place where God met us in the land.'),
('PSA', 74, 9, 'PSA.74.9', 'There are no signs for us to see. There is no longer any prophet. And none of us knows how long this will last.'),
('PSA', 74, 10, 'PSA.74.10', 'How long, O God, will the enemy taunt You? Will the foe revile Your name forever?'),
('PSA', 74, 11, 'PSA.74.11', 'Why do You withdraw Your strong right hand? Stretch it out to destroy them!'),
('PSA', 74, 12, 'PSA.74.12', 'Yet God is my King from ancient times, working salvation on the earth.'),
('PSA', 74, 13, 'PSA.74.13', 'You divided the sea by Your strength; You smashed the heads of the dragons of the sea;'),
('PSA', 74, 14, 'PSA.74.14', 'You crushed the heads of Leviathan; You fed him to the creatures of the desert.'),
('PSA', 74, 15, 'PSA.74.15', 'You broke open the fountain and the flood; You dried up the ever-flowing rivers.'),
('PSA', 74, 16, 'PSA.74.16', 'The day is Yours, and also the night; You established the moon and the sun.'),
('PSA', 74, 17, 'PSA.74.17', 'You set all the boundaries of the earth; You made the summer and winter.'),
('PSA', 74, 18, 'PSA.74.18', 'Remember how the enemy has mocked You, O LORD, how a foolish people has spurned Your name.'),
('PSA', 74, 19, 'PSA.74.19', 'Do not deliver the soul of Your dove to beasts; do not forget the lives of Your afflicted forever.'),
('PSA', 74, 20, 'PSA.74.20', 'Consider Your covenant, for haunts of violence fill the dark places of the land.'),
('PSA', 74, 21, 'PSA.74.21', 'Do not let the oppressed retreat in shame; may the poor and needy praise Your name.'),
('PSA', 74, 22, 'PSA.74.22', 'Rise up, O God; defend Your cause! Remember how the fool mocks You all day long.'),
('PSA', 74, 23, 'PSA.74.23', 'Do not disregard the clamor of Your adversaries, the uproar of Your enemies that ascends continually.'),
('PSA', 75, 1, 'PSA.75.1', 'For the choirmaster: To the tune of “Do Not Destroy.” A Psalm of Asaph. A song. We give thanks to You, O God; we give thanks, for Your Name is near. The people declare Your wondrous works.'),
('PSA', 75, 2, 'PSA.75.2', '“When I choose a time, I will judge fairly.'),
('PSA', 75, 3, 'PSA.75.3', 'When the earth and all its dwellers quake, it is I who bear up its pillars. Selah'),
('PSA', 75, 4, 'PSA.75.4', 'I say to the proud, ‘Do not boast,’ and to the wicked, ‘Do not lift up your horn.'),
('PSA', 75, 5, 'PSA.75.5', 'Do not lift up your horn against heaven or speak with an outstretched neck.’”'),
('PSA', 75, 6, 'PSA.75.6', 'For exaltation comes neither from east nor west, nor out of the desert,'),
('PSA', 75, 7, 'PSA.75.7', 'but it is God who judges; He brings down one and exalts another.'),
('PSA', 75, 8, 'PSA.75.8', 'For a cup is in the hand of the LORD, full of foaming wine mixed with spices. He pours from His cup, and all the wicked of the earth drink it down to the dregs.'),
('PSA', 75, 9, 'PSA.75.9', 'But I will proclaim Him forever; I will sing praise to the God of Jacob.'),
('PSA', 75, 10, 'PSA.75.10', '“All the horns of the wicked I will cut off, but the horns of the righteous will be exalted.”'),
('PSA', 76, 1, 'PSA.76.1', 'For the choirmaster. With stringed instruments. A Psalm of Asaph. A song. God is known in Judah; His name is great in Israel.'),
('PSA', 76, 2, 'PSA.76.2', 'His tent is in Salem, His dwelling place in Zion.'),
('PSA', 76, 3, 'PSA.76.3', 'There He shattered the flaming arrows, the shield and sword and weapons of war. Selah'),
('PSA', 76, 4, 'PSA.76.4', 'You are resplendent with light, more majestic than mountains filled with game.'),
('PSA', 76, 5, 'PSA.76.5', 'The valiant lie plundered; they sleep their last sleep. No men of might could lift a hand.'),
('PSA', 76, 6, 'PSA.76.6', 'At Your rebuke, O God of Jacob, both horse and rider lie stunned.'),
('PSA', 76, 7, 'PSA.76.7', 'You alone are to be feared. When You are angry, who can stand before You?'),
('PSA', 76, 8, 'PSA.76.8', 'From heaven You pronounced judgment, and the earth feared and was still'),
('PSA', 76, 9, 'PSA.76.9', 'when God rose up to judge, to save all the lowly of the earth. Selah'),
('PSA', 76, 10, 'PSA.76.10', 'Even the wrath of man shall praise You; with the survivors of wrath You will clothe Yourself.'),
('PSA', 76, 11, 'PSA.76.11', 'Make and fulfill your vows to the LORD your God; let all the neighboring lands bring tribute to Him who is to be feared.'),
('PSA', 76, 12, 'PSA.76.12', 'He breaks the spirits of princes; He is feared by the kings of the earth.'),
('PSA', 77, 1, 'PSA.77.1', 'For the choirmaster. According to Jeduthun. A Psalm of Asaph. I cried out to God; I cried aloud to God to hear me.'),
('PSA', 77, 2, 'PSA.77.2', 'In the day of trouble I sought the Lord; through the night my outstretched hands did not grow weary; my soul refused to be comforted.'),
('PSA', 77, 3, 'PSA.77.3', 'I remembered You, O God, and I groaned; I mused and my spirit grew faint. Selah'),
('PSA', 77, 4, 'PSA.77.4', 'You have kept my eyes from closing; I am too troubled to speak.'),
('PSA', 77, 5, 'PSA.77.5', 'I considered the days of old, the years long in the past.'),
('PSA', 77, 6, 'PSA.77.6', 'At night I remembered my song; in my heart I mused, and my spirit pondered:'),
('PSA', 77, 7, 'PSA.77.7', '“Will the Lord spurn us forever and never show His favor again?'),
('PSA', 77, 8, 'PSA.77.8', 'Is His loving devotion gone forever? Has His promise failed for all time?'),
('PSA', 77, 9, 'PSA.77.9', 'Has God forgotten to be gracious? Has His anger shut off His compassion?” Selah'),
('PSA', 77, 10, 'PSA.77.10', 'So I said, “I am grieved that the right hand of the Most High has changed.”'),
('PSA', 77, 11, 'PSA.77.11', 'I will remember the works of the LORD; yes, I will remember Your wonders of old.'),
('PSA', 77, 12, 'PSA.77.12', 'I will reflect on all You have done and ponder Your mighty deeds.'),
('PSA', 77, 13, 'PSA.77.13', 'Your way, O God, is holy. What god is so great as our God?'),
('PSA', 77, 14, 'PSA.77.14', 'You are the God who works wonders; You display Your strength among the peoples.'),
('PSA', 77, 15, 'PSA.77.15', 'With power You redeemed Your people, the sons of Jacob and Joseph. Selah'),
('PSA', 77, 16, 'PSA.77.16', 'The waters saw You, O God; the waters saw You and swirled; even the depths were shaken.'),
('PSA', 77, 17, 'PSA.77.17', 'The clouds poured down water; the skies resounded with thunder; Your arrows flashed back and forth.'),
('PSA', 77, 18, 'PSA.77.18', 'Your thunder resounded in the whirlwind; the lightning lit up the world; the earth trembled and quaked.'),
('PSA', 77, 19, 'PSA.77.19', 'Your path led through the sea, Your way through the mighty waters, but Your footprints were not to be found.'),
('PSA', 77, 20, 'PSA.77.20', 'You led Your people like a flock by the hand of Moses and Aaron.'),
('PSA', 78, 1, 'PSA.78.1', 'A Maskil of Asaph. Give ear, O my people, to my instruction; listen to the words of my mouth.'),
('PSA', 78, 2, 'PSA.78.2', 'I will open my mouth in parables; I will utter things hidden from the beginning,'),
('PSA', 78, 3, 'PSA.78.3', 'that we have heard and known and our fathers have relayed to us.'),
('PSA', 78, 4, 'PSA.78.4', 'We will not hide them from their children but will declare to the next generation the praises of the LORD and His might and the wonders He has performed.'),
('PSA', 78, 5, 'PSA.78.5', 'For He established a testimony in Jacob and appointed a law in Israel, which He commanded our fathers to teach to their children,'),
('PSA', 78, 6, 'PSA.78.6', 'that the coming generation would know them—even children yet to be born—to arise and tell their own children'),
('PSA', 78, 7, 'PSA.78.7', 'that they should put their confidence in God, not forgetting His works, but keeping His commandments.'),
('PSA', 78, 8, 'PSA.78.8', 'Then they will not be like their fathers, a stubborn and rebellious generation, whose heart was not loyal, whose spirit was not faithful to God.'),
('PSA', 78, 9, 'PSA.78.9', 'The archers of Ephraim turned back on the day of battle.'),
('PSA', 78, 10, 'PSA.78.10', 'They failed to keep God’s covenant and refused to live by His law.'),
('PSA', 78, 11, 'PSA.78.11', 'They forgot what He had done, the wonders He had shown them.'),
('PSA', 78, 12, 'PSA.78.12', 'He worked wonders before their fathers in the land of Egypt, in the region of Zoan.'),
('PSA', 78, 13, 'PSA.78.13', 'He split the sea and brought them through; He set the waters upright like a wall.'),
('PSA', 78, 14, 'PSA.78.14', 'He led them with a cloud by day and with a light of fire all night.'),
('PSA', 78, 15, 'PSA.78.15', 'He split the rocks in the wilderness and gave them drink as abundant as the seas.'),
('PSA', 78, 16, 'PSA.78.16', 'He brought streams from the stone and made water flow down like rivers.'),
('PSA', 78, 17, 'PSA.78.17', 'But they continued to sin against Him, rebelling in the desert against the Most High.'),
('PSA', 78, 18, 'PSA.78.18', 'They willfully tested God by demanding the food they craved.'),
('PSA', 78, 19, 'PSA.78.19', 'They spoke against God, saying, “Can God really prepare a table in the wilderness?'),
('PSA', 78, 20, 'PSA.78.20', 'When He struck the rock, water gushed out and torrents raged. But can He also give bread or supply His people with meat?”'),
('PSA', 78, 21, 'PSA.78.21', 'Therefore the LORD heard and was filled with wrath; so a fire was kindled against Jacob, and His anger flared against Israel,'),
('PSA', 78, 22, 'PSA.78.22', 'because they did not believe God or rely on His salvation.'),
('PSA', 78, 23, 'PSA.78.23', 'Yet He commanded the clouds above and opened the doors of the heavens.'),
('PSA', 78, 24, 'PSA.78.24', 'He rained down manna for them to eat; He gave them grain from heaven.'),
('PSA', 78, 25, 'PSA.78.25', 'Man ate the bread of angels; He sent them food in abundance.'),
('PSA', 78, 26, 'PSA.78.26', 'He stirred the east wind from the heavens and drove the south wind by His might.'),
('PSA', 78, 27, 'PSA.78.27', 'He rained meat on them like dust, and winged birds like the sand of the sea.'),
('PSA', 78, 28, 'PSA.78.28', 'He felled them in the midst of their camp, all around their dwellings.'),
('PSA', 78, 29, 'PSA.78.29', 'So they ate and were well filled, for He gave them what they craved.'),
('PSA', 78, 30, 'PSA.78.30', 'Yet before they had filled their desire, with the food still in their mouths,'),
('PSA', 78, 31, 'PSA.78.31', 'God’s anger flared against them, and He put to death their strongest and subdued the young men of Israel.'),
('PSA', 78, 32, 'PSA.78.32', 'In spite of all this, they kept on sinning; despite His wonderful works, they did not believe.'),
('PSA', 78, 33, 'PSA.78.33', 'So He ended their days in futility, and their years in sudden terror.'),
('PSA', 78, 34, 'PSA.78.34', 'When He slew them, they would seek Him; they repented and searched for God.'),
('PSA', 78, 35, 'PSA.78.35', 'And they remembered that God was their Rock, that God Most High was their Redeemer.'),
('PSA', 78, 36, 'PSA.78.36', 'But they deceived Him with their mouths, and lied to Him with their tongues.'),
('PSA', 78, 37, 'PSA.78.37', 'Their hearts were disloyal to Him, and they were unfaithful to His covenant.'),
('PSA', 78, 38, 'PSA.78.38', 'And yet He was compassionate; He forgave their iniquity and did not destroy them. He often restrained His anger and did not unleash His full wrath.'),
('PSA', 78, 39, 'PSA.78.39', 'He remembered that they were but flesh, a passing breeze that does not return.'),
('PSA', 78, 40, 'PSA.78.40', 'How often they disobeyed Him in the wilderness and grieved Him in the desert!'),
('PSA', 78, 41, 'PSA.78.41', 'Again and again they tested God and provoked the Holy One of Israel.'),
('PSA', 78, 42, 'PSA.78.42', 'They did not remember His power—the day He redeemed them from the adversary,'),
('PSA', 78, 43, 'PSA.78.43', 'when He performed His signs in Egypt and His wonders in the fields of Zoan.'),
('PSA', 78, 44, 'PSA.78.44', 'He turned their rivers to blood, and from their streams they could not drink.'),
('PSA', 78, 45, 'PSA.78.45', 'He sent swarms of flies that devoured them, and frogs that devastated them.'),
('PSA', 78, 46, 'PSA.78.46', 'He gave their crops to the grasshopper, the fruit of their labor to the locust.'),
('PSA', 78, 47, 'PSA.78.47', 'He killed their vines with hailstones and their sycamore-figs with sleet.'),
('PSA', 78, 48, 'PSA.78.48', 'He abandoned their cattle to the hail and their livestock to bolts of lightning.'),
('PSA', 78, 49, 'PSA.78.49', 'He unleashed His fury against them, wrath, indignation, and calamity—a band of destroying angels.'),
('PSA', 78, 50, 'PSA.78.50', 'He cleared a path for His anger; He did not spare them from death but delivered their lives to the plague.'),
('PSA', 78, 51, 'PSA.78.51', 'He struck all the firstborn of Egypt, the virility in the tents of Ham.'),
('PSA', 78, 52, 'PSA.78.52', 'He led out His people like sheep and guided them like a flock in the wilderness.'),
('PSA', 78, 53, 'PSA.78.53', 'He led them safely, so they did not fear, but the sea engulfed their enemies.'),
('PSA', 78, 54, 'PSA.78.54', 'He brought them to His holy land, to the mountain His right hand had acquired.'),
('PSA', 78, 55, 'PSA.78.55', 'He drove out nations before them and apportioned their inheritance; He settled the tribes of Israel in their tents.'),
('PSA', 78, 56, 'PSA.78.56', 'But they tested and disobeyed God Most High, for they did not keep His decrees.'),
('PSA', 78, 57, 'PSA.78.57', 'They turned back and were faithless like their fathers, twisted like a faulty bow.'),
('PSA', 78, 58, 'PSA.78.58', 'They enraged Him with their high places and provoked His jealousy with their idols.'),
('PSA', 78, 59, 'PSA.78.59', 'On hearing it, God was furious and rejected Israel completely.'),
('PSA', 78, 60, 'PSA.78.60', 'He abandoned the tabernacle of Shiloh, the tent He had pitched among men.'),
('PSA', 78, 61, 'PSA.78.61', 'He delivered His strength to captivity, and His splendor to the hand of the adversary.'),
('PSA', 78, 62, 'PSA.78.62', 'He surrendered His people to the sword because He was enraged by His heritage.'),
('PSA', 78, 63, 'PSA.78.63', 'Fire consumed His young men, and their maidens were left without wedding songs.'),
('PSA', 78, 64, 'PSA.78.64', 'His priests fell by the sword, but their widows could not lament.'),
('PSA', 78, 65, 'PSA.78.65', 'Then the Lord awoke as from sleep, like a mighty warrior overcome by wine.'),
('PSA', 78, 66, 'PSA.78.66', 'He beat back His foes; He put them to everlasting shame.'),
('PSA', 78, 67, 'PSA.78.67', 'He rejected the tent of Joseph and refused the tribe of Ephraim.'),
('PSA', 78, 68, 'PSA.78.68', 'But He chose the tribe of Judah, Mount Zion, which He loved.'),
('PSA', 78, 69, 'PSA.78.69', 'He built His sanctuary like the heights, like the earth He has established forever.'),
('PSA', 78, 70, 'PSA.78.70', 'He chose David His servant and took him from the sheepfolds;'),
('PSA', 78, 71, 'PSA.78.71', 'from tending the ewes He brought him to be shepherd of His people Jacob, of Israel His inheritance.'),
('PSA', 78, 72, 'PSA.78.72', 'So David shepherded them with integrity of heart and guided them with skillful hands.'),
('PSA', 79, 1, 'PSA.79.1', 'A Psalm of Asaph. The nations, O God, have invaded Your inheritance; they have defiled Your holy temple and reduced Jerusalem to rubble.'),
('PSA', 79, 2, 'PSA.79.2', 'They have given the corpses of Your servants as food to the birds of the air, the flesh of Your saints to the beasts of the earth.'),
('PSA', 79, 3, 'PSA.79.3', 'They have poured out their blood like water all around Jerusalem, and there is no one to bury the dead.'),
('PSA', 79, 4, 'PSA.79.4', 'We have become a reproach to our neighbors, a scorn and derision to those around us.'),
('PSA', 79, 5, 'PSA.79.5', 'How long, O LORD? Will You be angry forever? Will Your jealousy burn like fire?'),
('PSA', 79, 6, 'PSA.79.6', 'Pour out Your wrath on the nations that do not acknowledge You, on the kingdoms that refuse to call on Your name,'),
('PSA', 79, 7, 'PSA.79.7', 'for they have devoured Jacob and devastated his homeland.'),
('PSA', 79, 8, 'PSA.79.8', 'Do not hold past sins against us; let Your compassion come quickly, for we are brought low.'),
('PSA', 79, 9, 'PSA.79.9', 'Help us, O God of our salvation, for the glory of Your name; deliver us and atone for our sins, for the sake of Your name.'),
('PSA', 79, 10, 'PSA.79.10', 'Why should the nations ask, “Where is their God?” Before our eyes, make known among the nations Your vengeance for the bloodshed of Your servants.'),
('PSA', 79, 11, 'PSA.79.11', 'May the groans of the captives reach You; by the strength of Your arm preserve those condemned to death.'),
('PSA', 79, 12, 'PSA.79.12', 'Pay back into the laps of our neighbors sevenfold the reproach they hurled at You, O Lord.'),
('PSA', 79, 13, 'PSA.79.13', 'Then we Your people, the sheep of Your pasture, will thank You forever; from generation to generation we will declare Your praise.'),
('PSA', 80, 1, 'PSA.80.1', 'For the choirmaster. To the tune of “The Lilies of the Covenant.” A Psalm of Asaph. Hear us, O Shepherd of Israel, who leads Joseph like a flock; You who sit enthroned between the cherubim, shine forth'),
('PSA', 80, 2, 'PSA.80.2', 'before Ephraim, Benjamin, and Manasseh. Rally Your mighty power and come to save us.'),
('PSA', 80, 3, 'PSA.80.3', 'Restore us, O God, and cause Your face to shine upon us, that we may be saved.'),
('PSA', 80, 4, 'PSA.80.4', 'O LORD God of Hosts, how long will Your anger smolder against the prayers of Your people?'),
('PSA', 80, 5, 'PSA.80.5', 'You fed them with the bread of tears and made them drink the full measure of their tears.'),
('PSA', 80, 6, 'PSA.80.6', 'You make us contend with our neighbors; our enemies mock us.'),
('PSA', 80, 7, 'PSA.80.7', 'Restore us, O God of Hosts, and cause Your face to shine upon us, that we may be saved.'),
('PSA', 80, 8, 'PSA.80.8', 'You uprooted a vine from Egypt; You drove out the nations and transplanted it.'),
('PSA', 80, 9, 'PSA.80.9', 'You cleared the ground for it, and it took root and filled the land.'),
('PSA', 80, 10, 'PSA.80.10', 'The mountains were covered by its shade, and the mighty cedars with its branches.'),
('PSA', 80, 11, 'PSA.80.11', 'It sent out its branches to the Sea, and its shoots toward the River.'),
('PSA', 80, 12, 'PSA.80.12', 'Why have You broken down its walls, so that all who pass by pick its fruit?'),
('PSA', 80, 13, 'PSA.80.13', 'The boar from the forest ravages it, and the creatures of the field feed upon it.'),
('PSA', 80, 14, 'PSA.80.14', 'Return, O God of Hosts, we pray! Look down from heaven and see! Attend to this vine—'),
('PSA', 80, 15, 'PSA.80.15', 'the root Your right hand has planted, the son You have raised up for Yourself.'),
('PSA', 80, 16, 'PSA.80.16', 'Your vine has been cut down and burned; they perish at the rebuke of Your countenance.'),
('PSA', 80, 17, 'PSA.80.17', 'Let Your hand be upon the man at Your right hand, on the son of man You have raised up for Yourself.'),
('PSA', 80, 18, 'PSA.80.18', 'Then we will not turn away from You; revive us, and we will call on Your name.'),
('PSA', 80, 19, 'PSA.80.19', 'Restore us, O LORD God of Hosts; cause Your face to shine upon us, that we may be saved.'),
('PSA', 81, 1, 'PSA.81.1', 'For the choirmaster. According to Gittith. Of Asaph. Sing for joy to God our strength; make a joyful noise to the God of Jacob.'),
('PSA', 81, 2, 'PSA.81.2', 'Lift up a song, strike the tambourine, play the sweet-sounding harp and lyre.'),
('PSA', 81, 3, 'PSA.81.3', 'Sound the ram’s horn at the New Moon, and at the full moon on the day of our Feast.'),
('PSA', 81, 4, 'PSA.81.4', 'For this is a statute for Israel, an ordinance of the God of Jacob.'),
('PSA', 81, 5, 'PSA.81.5', 'He ordained it as a testimony for Joseph when he went out over the land of Egypt, where I heard an unfamiliar language:'),
('PSA', 81, 6, 'PSA.81.6', '“I relieved his shoulder of the burden; his hands were freed from the basket.'),
('PSA', 81, 7, 'PSA.81.7', 'You called out in distress, and I rescued you; I answered you from the cloud of thunder; I tested you at the waters of Meribah. Selah'),
('PSA', 81, 8, 'PSA.81.8', 'Hear, O My people, and I will warn you: O Israel, if only you would listen to Me!'),
('PSA', 81, 9, 'PSA.81.9', 'There must be no strange god among you, nor shall you bow to a foreign god.'),
('PSA', 81, 10, 'PSA.81.10', 'I am the LORD your God, who brought you up out of Egypt. Open wide your mouth, and I will fill it.'),
('PSA', 81, 11, 'PSA.81.11', 'But My people would not listen to Me, and Israel would not obey Me.'),
('PSA', 81, 12, 'PSA.81.12', 'So I gave them up to their stubborn hearts to follow their own devices.'),
('PSA', 81, 13, 'PSA.81.13', 'If only My people would listen to Me, if Israel would follow My ways,'),
('PSA', 81, 14, 'PSA.81.14', 'how soon I would subdue their enemies and turn My hand against their foes!'),
('PSA', 81, 15, 'PSA.81.15', 'Those who hate the LORD would feign obedience, and their doom would last forever.'),
('PSA', 81, 16, 'PSA.81.16', 'But I would feed you the finest wheat; with honey from the rock I would satisfy you.”'),
('PSA', 82, 1, 'PSA.82.1', 'A Psalm of Asaph. God presides in the divine assembly; He renders judgment among the gods:'),
('PSA', 82, 2, 'PSA.82.2', '“How long will you judge unjustly and show partiality to the wicked? Selah'),
('PSA', 82, 3, 'PSA.82.3', 'Defend the cause of the weak and fatherless; uphold the rights of the afflicted and oppressed.'),
('PSA', 82, 4, 'PSA.82.4', 'Rescue the weak and needy; save them from the hand of the wicked.'),
('PSA', 82, 5, 'PSA.82.5', 'They do not know or understand; they wander in the darkness; all the foundations of the earth are shaken.'),
('PSA', 82, 6, 'PSA.82.6', 'I have said, ‘You are gods; you are all sons of the Most High.’'),
('PSA', 82, 7, 'PSA.82.7', 'But like mortals you will die, and like rulers you will fall.”'),
('PSA', 82, 8, 'PSA.82.8', 'Arise, O God, judge the earth, for all the nations are Your inheritance.'),
('PSA', 83, 1, 'PSA.83.1', 'A song. A Psalm of Asaph. O God, be not silent; be not speechless; be not still, O God.'),
('PSA', 83, 2, 'PSA.83.2', 'See how Your enemies rage, how Your foes have reared their heads.'),
('PSA', 83, 3, 'PSA.83.3', 'With cunning they scheme against Your people and conspire against those You cherish,'),
('PSA', 83, 4, 'PSA.83.4', 'saying, “Come, let us erase them as a nation; may the name of Israel be remembered no more.”'),
('PSA', 83, 5, 'PSA.83.5', 'For with one mind they plot together; they form an alliance against You—'),
('PSA', 83, 6, 'PSA.83.6', 'the tents of Edom and the Ishmaelites, of Moab and the Hagrites,'),
('PSA', 83, 7, 'PSA.83.7', 'of Gebal, Ammon, and Amalek, of Philistia with the people of Tyre.'),
('PSA', 83, 8, 'PSA.83.8', 'Even Assyria has joined them, lending strength to the sons of Lot. Selah'),
('PSA', 83, 9, 'PSA.83.9', 'Do to them as You did to Midian, as to Sisera and Jabin at the River Kishon,'),
('PSA', 83, 10, 'PSA.83.10', 'who perished at Endor and became like dung on the ground.'),
('PSA', 83, 11, 'PSA.83.11', 'Make their nobles like Oreb and Zeeb, and all their princes like Zebah and Zalmunna,'),
('PSA', 83, 12, 'PSA.83.12', 'who said, “Let us possess for ourselves the pastures of God.”'),
('PSA', 83, 13, 'PSA.83.13', 'Make them like tumbleweed, O my God, like chaff before the wind.'),
('PSA', 83, 14, 'PSA.83.14', 'As fire consumes a forest, as a flame sets the mountains ablaze,'),
('PSA', 83, 15, 'PSA.83.15', 'so pursue them with Your tempest, and terrify them with Your storm.'),
('PSA', 83, 16, 'PSA.83.16', 'Cover their faces with shame, that they may seek Your name, O LORD.'),
('PSA', 83, 17, 'PSA.83.17', 'May they be ever ashamed and terrified; may they perish in disgrace.'),
('PSA', 83, 18, 'PSA.83.18', 'May they know that You alone, whose name is the LORD, are Most High over all the earth.'),
('PSA', 84, 1, 'PSA.84.1', 'For the choirmaster. According to Gittith. A Psalm of the sons of Korah. How lovely is Your dwelling place, O LORD of Hosts!'),
('PSA', 84, 2, 'PSA.84.2', 'My soul longs, even faints, for the courts of the LORD; my heart and my flesh cry out for the living God.'),
('PSA', 84, 3, 'PSA.84.3', 'Even the sparrow has found a home, and the swallow a nest for herself, where she places her young near Your altars, O LORD of Hosts, my King and my God.'),
('PSA', 84, 4, 'PSA.84.4', 'How blessed are those who dwell in Your house! They are ever praising You. Selah'),
('PSA', 84, 5, 'PSA.84.5', 'Blessed are those whose strength is in You, whose hearts are set on pilgrimage.'),
('PSA', 84, 6, 'PSA.84.6', 'As they pass through the Valley of Baca, they make it a place of springs; even the autumn rain covers it with pools.'),
('PSA', 84, 7, 'PSA.84.7', 'They go from strength to strength, until each appears before God in Zion.'),
('PSA', 84, 8, 'PSA.84.8', 'O LORD God of Hosts, hear my prayer; give ear, O God of Jacob. Selah'),
('PSA', 84, 9, 'PSA.84.9', 'Take notice of our shield, O God, and look with favor on the face of Your anointed.'),
('PSA', 84, 10, 'PSA.84.10', 'For better is one day in Your courts than a thousand elsewhere. I would rather be a doorkeeper in the house of my God than dwell in the tents of the wicked.'),
('PSA', 84, 11, 'PSA.84.11', 'For the LORD God is a sun and a shield; the LORD gives grace and glory; He withholds no good thing from those who walk with integrity.'),
('PSA', 84, 12, 'PSA.84.12', 'O LORD of Hosts, how blessed is the man who trusts in You!'),
('PSA', 85, 1, 'PSA.85.1', 'For the choirmaster. A Psalm of the sons of Korah. You showed favor to Your land, O LORD; You restored Jacob from captivity.'),
('PSA', 85, 2, 'PSA.85.2', 'You forgave the iniquity of Your people; You covered all their sin. Selah'),
('PSA', 85, 3, 'PSA.85.3', 'You withheld all Your fury; You turned from Your burning anger.'),
('PSA', 85, 4, 'PSA.85.4', 'Restore us, O God of our salvation, and put away Your displeasure toward us.'),
('PSA', 85, 5, 'PSA.85.5', 'Will You be angry with us forever? Will You draw out Your anger to all generations?'),
('PSA', 85, 6, 'PSA.85.6', 'Will You not revive us again, that Your people may rejoice in You?'),
('PSA', 85, 7, 'PSA.85.7', 'Show us Your loving devotion, O LORD, and grant us Your salvation.'),
('PSA', 85, 8, 'PSA.85.8', 'I will listen to what God the LORD will say; for He will surely speak peace to His people and His saints; He will not let them return to folly.'),
('PSA', 85, 9, 'PSA.85.9', 'Surely His salvation is near to those who fear Him, that His glory may dwell in our land.'),
('PSA', 85, 10, 'PSA.85.10', 'Loving devotion and faithfulness have joined together; righteousness and peace have kissed.'),
('PSA', 85, 11, 'PSA.85.11', 'Faithfulness sprouts from the earth, and righteousness looks down from heaven.'),
('PSA', 85, 12, 'PSA.85.12', 'The LORD will indeed provide what is good, and our land will yield its increase.'),
('PSA', 85, 13, 'PSA.85.13', 'Righteousness will go before Him to prepare the way for His steps.'),
('PSA', 86, 1, 'PSA.86.1', 'A prayer of David. Incline Your ear, O LORD, and answer me, for I am poor and needy.'),
('PSA', 86, 2, 'PSA.86.2', 'Preserve my soul, for I am godly. You are my God; save Your servant who trusts in You.'),
('PSA', 86, 3, 'PSA.86.3', 'Be merciful to me, O Lord, for I call to You all day long.'),
('PSA', 86, 4, 'PSA.86.4', 'Bring joy to Your servant, for to You, O Lord, I lift up my soul.'),
('PSA', 86, 5, 'PSA.86.5', 'For You, O Lord, are kind and forgiving, rich in loving devotion to all who call on You.'),
('PSA', 86, 6, 'PSA.86.6', 'Hear my prayer, O LORD, and attend to my plea for mercy.'),
('PSA', 86, 7, 'PSA.86.7', 'In the day of my distress I call on You, because You answer me.'),
('PSA', 86, 8, 'PSA.86.8', 'O Lord, there is none like You among the gods, nor any works like Yours.'),
('PSA', 86, 9, 'PSA.86.9', 'All the nations You have made will come and bow before You, O Lord, and they will glorify Your name.'),
('PSA', 86, 10, 'PSA.86.10', 'For You are great and perform wonders; You alone are God.'),
('PSA', 86, 11, 'PSA.86.11', 'Teach me Your way, O LORD, that I may walk in Your truth. Give me an undivided heart, that I may fear Your name.'),
('PSA', 86, 12, 'PSA.86.12', 'I will praise You, O Lord my God, with all my heart; I will glorify Your name forever.'),
('PSA', 86, 13, 'PSA.86.13', 'For great is Your loving devotion to me; You have delivered me from the depths of Sheol.'),
('PSA', 86, 14, 'PSA.86.14', 'The arrogant rise against me, O God; a band of ruthless men seeks my life; they have no regard for You.'),
('PSA', 86, 15, 'PSA.86.15', 'But You, O Lord, are a compassionate and gracious God, slow to anger, abounding in loving devotion and faithfulness.'),
('PSA', 86, 16, 'PSA.86.16', 'Turn to me and have mercy; grant Your strength to Your servant; save the son of Your maidservant.'),
('PSA', 86, 17, 'PSA.86.17', 'Show me a sign of Your goodness, that my enemies may see and be ashamed; for You, O LORD, have helped me and comforted me.'),
('PSA', 87, 1, 'PSA.87.1', 'A Psalm of the sons of Korah. A song. He has founded His city on the holy mountains.'),
('PSA', 87, 2, 'PSA.87.2', 'The LORD loves the gates of Zion more than all the dwellings of Jacob.'),
('PSA', 87, 3, 'PSA.87.3', 'Glorious things are ascribed to you, O city of God. Selah'),
('PSA', 87, 4, 'PSA.87.4', '“I will mention Rahab and Babylon among those who know Me—along with Philistia, Tyre, and Cush—when I say, ‘This one was born in Zion.’”'),
('PSA', 87, 5, 'PSA.87.5', 'And it will be said of Zion: “This one and that one were born in her, and the Most High Himself will establish her.”'),
('PSA', 87, 6, 'PSA.87.6', 'The LORD will record in the register of the peoples: “This one was born in Zion.” Selah'),
('PSA', 87, 7, 'PSA.87.7', 'Singers and pipers will proclaim, “All my springs of joy are in You.”'),
('PSA', 88, 1, 'PSA.88.1', 'A song. A Psalm of the sons of Korah. For the choirmaster. According to Mahalath Leannoth. A Maskil of Heman the Ezrahite. O LORD, the God of my salvation, day and night I cry out before You.'),
('PSA', 88, 2, 'PSA.88.2', 'May my prayer come before You; incline Your ear to my cry.'),
('PSA', 88, 3, 'PSA.88.3', 'For my soul is full of troubles, and my life draws near to Sheol.'),
('PSA', 88, 4, 'PSA.88.4', 'I am counted among those descending to the Pit. I am like a man without strength.'),
('PSA', 88, 5, 'PSA.88.5', 'I am forsaken among the dead, like the slain who lie in the grave, whom You remember no more, who are cut off from Your care.'),
('PSA', 88, 6, 'PSA.88.6', 'You have laid me in the lowest Pit, in the darkest of the depths.'),
('PSA', 88, 7, 'PSA.88.7', 'Your wrath weighs heavily upon me; all Your waves have submerged me. Selah'),
('PSA', 88, 8, 'PSA.88.8', 'You have removed my friends from me; You have made me repulsive to them; I am confined and cannot escape.'),
('PSA', 88, 9, 'PSA.88.9', 'My eyes grow dim with grief. I call to You daily, O LORD; I spread out my hands to You.'),
('PSA', 88, 10, 'PSA.88.10', 'Do You work wonders for the dead? Do departed spirits rise up to praise You? Selah'),
('PSA', 88, 11, 'PSA.88.11', 'Can Your loving devotion be proclaimed in the grave, Your faithfulness in Abaddon?'),
('PSA', 88, 12, 'PSA.88.12', 'Will Your wonders be known in the darkness, or Your righteousness in the land of oblivion?'),
('PSA', 88, 13, 'PSA.88.13', 'But to You, O LORD, I cry for help; in the morning my prayer comes before You.'),
('PSA', 88, 14, 'PSA.88.14', 'Why, O LORD, do You reject me? Why do You hide Your face from me?'),
('PSA', 88, 15, 'PSA.88.15', 'From my youth I was afflicted and near death. I have borne Your terrors; I am in despair.'),
('PSA', 88, 16, 'PSA.88.16', 'Your wrath has swept over me; Your terrors have destroyed me.'),
('PSA', 88, 17, 'PSA.88.17', 'All day long they engulf me like water; they enclose me on every side.'),
('PSA', 88, 18, 'PSA.88.18', 'You have removed my beloved and my friend; darkness is my closest companion.'),
('PSA', 89, 1, 'PSA.89.1', 'A Maskil of Ethan the Ezrahite. I will sing of the loving devotion of the LORD forever; with my mouth I will proclaim Your faithfulness to all generations.'),
('PSA', 89, 2, 'PSA.89.2', 'For I have said, “Loving devotion is built up forever; in the heavens You establish Your faithfulness.”'),
('PSA', 89, 3, 'PSA.89.3', 'You said, “I have made a covenant with My chosen one, I have sworn to David My servant:'),
('PSA', 89, 4, 'PSA.89.4', '‘I will establish your offspring forever and build up your throne for all generations.’” Selah'),
('PSA', 89, 5, 'PSA.89.5', 'The heavens praise Your wonders, O LORD—Your faithfulness as well—in the assembly of the holy ones.'),
('PSA', 89, 6, 'PSA.89.6', 'For who in the skies can compare with the LORD? Who among the heavenly beings is like the LORD?'),
('PSA', 89, 7, 'PSA.89.7', 'In the council of the holy ones, God is greatly feared, and awesome above all who surround Him.'),
('PSA', 89, 8, 'PSA.89.8', 'O LORD God of Hosts, who is like You? O mighty LORD, Your faithfulness surrounds You.'),
('PSA', 89, 9, 'PSA.89.9', 'You rule the raging sea; when its waves mount up, You still them.'),
('PSA', 89, 10, 'PSA.89.10', 'You crushed Rahab like a carcass; You scattered Your enemies with Your mighty arm.'),
('PSA', 89, 11, 'PSA.89.11', 'The heavens are Yours, and also the earth. The earth and its fullness You founded.'),
('PSA', 89, 12, 'PSA.89.12', 'North and south You created; Tabor and Hermon shout for joy at Your name.'),
('PSA', 89, 13, 'PSA.89.13', 'Mighty is Your arm; strong is Your hand. Your right hand is exalted.'),
('PSA', 89, 14, 'PSA.89.14', 'Righteousness and justice are the foundation of Your throne; loving devotion and faithfulness go before You.'),
('PSA', 89, 15, 'PSA.89.15', 'Blessed are those who know the joyful sound, who walk, O LORD, in the light of Your presence.'),
('PSA', 89, 16, 'PSA.89.16', 'They rejoice in Your name all day long, and in Your righteousness they exult.'),
('PSA', 89, 17, 'PSA.89.17', 'For You are the glory of their strength, and by Your favor our horn is exalted.'),
('PSA', 89, 18, 'PSA.89.18', 'Surely our shield belongs to the LORD, and our king to the Holy One of Israel.'),
('PSA', 89, 19, 'PSA.89.19', 'You once spoke in a vision; to Your godly ones You said, “I have bestowed help on a warrior; I have exalted one chosen from the people.'),
('PSA', 89, 20, 'PSA.89.20', 'I have found My servant David; with My sacred oil I have anointed him.'),
('PSA', 89, 21, 'PSA.89.21', 'My hand will sustain him; surely My arm will strengthen him.'),
('PSA', 89, 22, 'PSA.89.22', 'No enemy will exact tribute; no wicked man will oppress him.'),
('PSA', 89, 23, 'PSA.89.23', 'I will crush his foes before him and strike down those who hate him.'),
('PSA', 89, 24, 'PSA.89.24', 'My faithfulness and loving devotion will be with him, and through My name his horn will be exalted.'),
('PSA', 89, 25, 'PSA.89.25', 'I will set his hand over the sea, and his right hand upon the rivers.'),
('PSA', 89, 26, 'PSA.89.26', 'He will call to Me, ‘You are my Father, my God, the Rock of my salvation.’'),
('PSA', 89, 27, 'PSA.89.27', 'I will indeed appoint him as My firstborn, the highest of the kings of the earth.'),
('PSA', 89, 28, 'PSA.89.28', 'I will forever preserve My loving devotion for him, and My covenant with him will stand fast.'),
('PSA', 89, 29, 'PSA.89.29', 'I will establish his line forever, his throne as long as the heavens endure.'),
('PSA', 89, 30, 'PSA.89.30', 'If his sons forsake My law and do not walk in My judgments,'),
('PSA', 89, 31, 'PSA.89.31', 'if they violate My statutes and fail to keep My commandments,'),
('PSA', 89, 32, 'PSA.89.32', 'I will attend to their transgression with the rod, and to their iniquity with stripes.'),
('PSA', 89, 33, 'PSA.89.33', 'But I will not withdraw My loving devotion from him, nor ever betray My faithfulness.'),
('PSA', 89, 34, 'PSA.89.34', 'I will not violate My covenant or alter the utterance of My lips.'),
('PSA', 89, 35, 'PSA.89.35', 'Once and for all I have sworn by My holiness—I will not lie to David—'),
('PSA', 89, 36, 'PSA.89.36', 'his offspring shall endure forever, and his throne before Me like the sun,'),
('PSA', 89, 37, 'PSA.89.37', 'like the moon, established forever, a faithful witness in the sky.” Selah'),
('PSA', 89, 38, 'PSA.89.38', 'Now, however, You have spurned and rejected him; You are enraged by Your anointed one.'),
('PSA', 89, 39, 'PSA.89.39', 'You have renounced the covenant with Your servant and sullied his crown in the dust.'),
('PSA', 89, 40, 'PSA.89.40', 'You have broken down all his walls; You have reduced his strongholds to rubble.'),
('PSA', 89, 41, 'PSA.89.41', 'All who pass by plunder him; he has become a reproach to his neighbors.'),
('PSA', 89, 42, 'PSA.89.42', 'You have exalted the right hand of his foes; You have made all his enemies rejoice.'),
('PSA', 89, 43, 'PSA.89.43', 'You have bent the edge of his sword and have not sustained him in battle.'),
('PSA', 89, 44, 'PSA.89.44', 'You have ended his splendor and cast his throne to the ground.'),
('PSA', 89, 45, 'PSA.89.45', 'You have cut short the days of his youth; You have covered him with shame. Selah'),
('PSA', 89, 46, 'PSA.89.46', 'How long, O LORD? Will You hide Yourself forever? Will Your wrath keep burning like fire?'),
('PSA', 89, 47, 'PSA.89.47', 'Remember the briefness of my lifespan! For what futility You have created all men!'),
('PSA', 89, 48, 'PSA.89.48', 'What man can live and never see death? Can he deliver his soul from the power of Sheol? Selah'),
('PSA', 89, 49, 'PSA.89.49', 'Where, O Lord, is Your loving devotion of old, which You faithfully swore to David?'),
('PSA', 89, 50, 'PSA.89.50', 'Remember, O Lord, the reproach of Your servants, which I bear in my heart from so many people—'),
('PSA', 89, 51, 'PSA.89.51', 'how Your enemies have taunted, O LORD, and have mocked every step of Your anointed one!'),
('PSA', 89, 52, 'PSA.89.52', 'Blessed be the LORD forever! Amen and amen.'),
('PSA', 90, 1, 'PSA.90.1', 'A prayer of Moses the man of God. Lord, You have been our dwelling place through all generations.'),
('PSA', 90, 2, 'PSA.90.2', 'Before the mountains were born or You brought forth the earth and the world, from everlasting to everlasting You are God.'),
('PSA', 90, 3, 'PSA.90.3', 'You return man to dust, saying, “Return, O sons of mortals.”'),
('PSA', 90, 4, 'PSA.90.4', 'For in Your sight a thousand years are but a day that passes, or a watch of the night.'),
('PSA', 90, 5, 'PSA.90.5', 'You sweep them away in their sleep; they are like the new grass of the morning—'),
('PSA', 90, 6, 'PSA.90.6', 'in the morning it springs up new, but by evening it fades and withers.'),
('PSA', 90, 7, 'PSA.90.7', 'For we are consumed by Your anger and terrified by Your wrath.'),
('PSA', 90, 8, 'PSA.90.8', 'You have set our iniquities before You, our secret sins in the light of Your presence.'),
('PSA', 90, 9, 'PSA.90.9', 'For all our days decline in Your fury; we finish our years with a sigh.'),
('PSA', 90, 10, 'PSA.90.10', 'The length of our days is seventy years—or eighty if we are strong—yet their pride is but labor and sorrow, for they quickly pass, and we fly away.'),
('PSA', 90, 11, 'PSA.90.11', 'Who knows the power of Your anger? Your wrath matches the fear You are due.'),
('PSA', 90, 12, 'PSA.90.12', 'So teach us to number our days, that we may present a heart of wisdom.'),
('PSA', 90, 13, 'PSA.90.13', 'Return, O LORD! How long will it be? Have compassion on Your servants.'),
('PSA', 90, 14, 'PSA.90.14', 'Satisfy us in the morning with Your loving devotion, that we may sing for joy and be glad all our days.'),
('PSA', 90, 15, 'PSA.90.15', 'Make us glad for as many days as You have afflicted us, for as many years as we have seen evil.'),
('PSA', 90, 16, 'PSA.90.16', 'May Your work be shown to Your servants, and Your splendor to their children.'),
('PSA', 90, 17, 'PSA.90.17', 'May the favor of the Lord our God rest upon us; establish for us the work of our hands—yes, establish the work of our hands!'),
('PSA', 91, 1, 'PSA.91.1', 'He who dwells in the shelter of the Most High will abide in the shadow of the Almighty.'),
('PSA', 91, 2, 'PSA.91.2', 'I will say to the LORD, “You are my refuge and my fortress, my God, in whom I trust.”'),
('PSA', 91, 3, 'PSA.91.3', 'Surely He will deliver you from the snare of the fowler, and from the deadly plague.'),
('PSA', 91, 4, 'PSA.91.4', 'He will cover you with His feathers; under His wings you will find refuge; His faithfulness is a shield and rampart.'),
('PSA', 91, 5, 'PSA.91.5', 'You will not fear the terror of the night, nor the arrow that flies by day,'),
('PSA', 91, 6, 'PSA.91.6', 'nor the pestilence that stalks in the darkness, nor the calamity that destroys at noon.'),
('PSA', 91, 7, 'PSA.91.7', 'Though a thousand may fall at your side, and ten thousand at your right hand, no harm will come near you.'),
('PSA', 91, 8, 'PSA.91.8', 'You will only see it with your eyes and witness the punishment of the wicked.'),
('PSA', 91, 9, 'PSA.91.9', 'Because you have made the LORD your dwelling—my refuge, the Most High—'),
('PSA', 91, 10, 'PSA.91.10', 'no evil will befall you, no plague will approach your tent.'),
('PSA', 91, 11, 'PSA.91.11', 'For He will command His angels concerning you to guard you in all your ways.'),
('PSA', 91, 12, 'PSA.91.12', 'They will lift you up in their hands, so that you will not strike your foot against a stone.'),
('PSA', 91, 13, 'PSA.91.13', 'You will tread on the lion and cobra; you will trample the young lion and serpent.'),
('PSA', 91, 14, 'PSA.91.14', '“Because he loves Me, I will deliver him; because he knows My name, I will protect him.'),
('PSA', 91, 15, 'PSA.91.15', 'When he calls out to Me, I will answer him; I will be with him in trouble. I will deliver him and honor him.'),
('PSA', 91, 16, 'PSA.91.16', 'With long life I will satisfy him and show him My salvation.”'),
('PSA', 92, 1, 'PSA.92.1', 'A Psalm. A song for the Sabbath day. It is good to praise the LORD, and to sing praises to Your name, O Most High,'),
('PSA', 92, 2, 'PSA.92.2', 'to proclaim Your loving devotion in the morning and Your faithfulness at night'),
('PSA', 92, 3, 'PSA.92.3', 'with the ten-stringed harp and the melody of the lyre.'),
('PSA', 92, 4, 'PSA.92.4', 'For You, O LORD, have made me glad by Your deeds; I sing for joy at the works of Your hands.'),
('PSA', 92, 5, 'PSA.92.5', 'How great are Your works, O LORD, how deep are Your thoughts!'),
('PSA', 92, 6, 'PSA.92.6', 'A senseless man does not know, and a fool does not understand,'),
('PSA', 92, 7, 'PSA.92.7', 'that though the wicked sprout like grass, and all evildoers flourish, they will be forever destroyed.'),
('PSA', 92, 8, 'PSA.92.8', 'But You, O LORD, are exalted forever!'),
('PSA', 92, 9, 'PSA.92.9', 'For surely Your enemies, O LORD, surely Your enemies will perish; all evildoers will be scattered.'),
('PSA', 92, 10, 'PSA.92.10', 'But You have exalted my horn like that of a wild ox; with fine oil I have been anointed.'),
('PSA', 92, 11, 'PSA.92.11', 'My eyes see the downfall of my enemies; my ears hear the wailing of my wicked foes.'),
('PSA', 92, 12, 'PSA.92.12', 'The righteous will flourish like a palm tree, and grow like a cedar in Lebanon.'),
('PSA', 92, 13, 'PSA.92.13', 'Planted in the house of the LORD, they will flourish in the courts of our God.'),
('PSA', 92, 14, 'PSA.92.14', 'In old age they will still bear fruit; healthy and green they will remain,'),
('PSA', 92, 15, 'PSA.92.15', 'to proclaim, “The LORD is upright; He is my Rock, and in Him there is no unrighteousness.”'),
('PSA', 93, 1, 'PSA.93.1', 'The LORD reigns! He is robed in majesty; the LORD has clothed and armed Himself with strength. The world indeed is firmly established; it cannot be moved.'),
('PSA', 93, 2, 'PSA.93.2', 'Your throne was established long ago; You are from all eternity.'),
('PSA', 93, 3, 'PSA.93.3', 'The floodwaters have risen, O LORD; the rivers have raised their voice; the seas lift up their pounding waves.'),
('PSA', 93, 4, 'PSA.93.4', 'Above the roar of many waters—the mighty breakers of the sea—the LORD on high is majestic.'),
('PSA', 93, 5, 'PSA.93.5', 'Your testimonies are fully confirmed; holiness adorns Your house, O LORD, for all the days to come.'),
('PSA', 94, 1, 'PSA.94.1', 'O LORD, God of vengeance, O God of vengeance, shine forth.'),
('PSA', 94, 2, 'PSA.94.2', 'Rise up, O Judge of the earth; render a reward to the proud.'),
('PSA', 94, 3, 'PSA.94.3', 'How long will the wicked, O LORD, how long will the wicked exult?'),
('PSA', 94, 4, 'PSA.94.4', 'They pour out arrogant words; all workers of iniquity boast.'),
('PSA', 94, 5, 'PSA.94.5', 'They crush Your people, O LORD; they oppress Your heritage.'),
('PSA', 94, 6, 'PSA.94.6', 'They kill the widow and the foreigner; they murder the fatherless.'),
('PSA', 94, 7, 'PSA.94.7', 'They say, “The LORD does not see; the God of Jacob pays no heed.”'),
('PSA', 94, 8, 'PSA.94.8', 'Take notice, O senseless among the people! O fools, when will you be wise?'),
('PSA', 94, 9, 'PSA.94.9', 'He who affixed the ear, can He not hear? He who formed the eye, can He not see?'),
('PSA', 94, 10, 'PSA.94.10', 'He who admonishes the nations, does He not discipline? He who teaches man, does He lack knowledge?'),
('PSA', 94, 11, 'PSA.94.11', 'The LORD knows the thoughts of man, that they are futile.'),
('PSA', 94, 12, 'PSA.94.12', 'Blessed is the man You discipline, O LORD, and teach from Your law,'),
('PSA', 94, 13, 'PSA.94.13', 'to grant him relief from days of trouble, until a pit is dug for the wicked.'),
('PSA', 94, 14, 'PSA.94.14', 'For the LORD will not forsake His people; He will never abandon His heritage.'),
('PSA', 94, 15, 'PSA.94.15', 'Surely judgment will again be righteous, and all the upright in heart will follow it.'),
('PSA', 94, 16, 'PSA.94.16', 'Who will rise up for me against the wicked? Who will stand for me against the workers of iniquity?'),
('PSA', 94, 17, 'PSA.94.17', 'Unless the LORD had been my helper, I would soon have dwelt in the abode of silence.'),
('PSA', 94, 18, 'PSA.94.18', 'If I say, “My foot is slipping,” Your loving devotion, O LORD, supports me.'),
('PSA', 94, 19, 'PSA.94.19', 'When anxiety overwhelms me, Your consolation delights my soul.'),
('PSA', 94, 20, 'PSA.94.20', 'Can a corrupt throne be Your ally—one devising mischief by decree?'),
('PSA', 94, 21, 'PSA.94.21', 'They band together against the righteous and condemn the innocent to death.'),
('PSA', 94, 22, 'PSA.94.22', 'But the LORD has been my stronghold, and my God is my rock of refuge.'),
('PSA', 94, 23, 'PSA.94.23', 'He will bring upon them their own iniquity and destroy them for their wickedness. The LORD our God will destroy them.'),
('PSA', 95, 1, 'PSA.95.1', 'Come, let us sing for joy to the LORD; let us shout to the Rock of our salvation!'),
('PSA', 95, 2, 'PSA.95.2', 'Let us enter His presence with thanksgiving; let us make a joyful noise to Him in song.'),
('PSA', 95, 3, 'PSA.95.3', 'For the LORD is a great God, a great King above all gods.'),
('PSA', 95, 4, 'PSA.95.4', 'In His hand are the depths of the earth, and the mountain peaks belong to Him.'),
('PSA', 95, 5, 'PSA.95.5', 'The sea is His, for He made it, and His hands formed the dry land.'),
('PSA', 95, 6, 'PSA.95.6', 'O come, let us worship and bow down; let us kneel before the LORD our Maker.'),
('PSA', 95, 7, 'PSA.95.7', 'For He is our God, and we are the people of His pasture, the sheep under His care. Today, if you hear His voice,'),
('PSA', 95, 8, 'PSA.95.8', 'do not harden your hearts as you did at Meribah, in the day at Massah in the wilderness,'),
('PSA', 95, 9, 'PSA.95.9', 'where your fathers tested and tried Me, though they had seen My work.'),
('PSA', 95, 10, 'PSA.95.10', 'For forty years I was angry with that generation, and I said, “They are a people whose hearts go astray, and they have not known My ways.”'),
('PSA', 95, 11, 'PSA.95.11', 'So I swore on oath in My anger, “They shall never enter My rest.”'),
('PSA', 96, 1, 'PSA.96.1', 'Sing to the LORD a new song; sing to the LORD, all the earth.'),
('PSA', 96, 2, 'PSA.96.2', 'Sing to the LORD, bless His name; proclaim His salvation day after day.'),
('PSA', 96, 3, 'PSA.96.3', 'Declare His glory among the nations, His wonders among all peoples.'),
('PSA', 96, 4, 'PSA.96.4', 'For great is the LORD, and greatly to be praised; He is to be feared above all gods.'),
('PSA', 96, 5, 'PSA.96.5', 'For all the gods of the nations are idols, but it is the LORD who made the heavens.'),
('PSA', 96, 6, 'PSA.96.6', 'Splendor and majesty are before Him; strength and beauty fill His sanctuary.'),
('PSA', 96, 7, 'PSA.96.7', 'Ascribe to the LORD, O families of the nations, ascribe to the LORD glory and strength.'),
('PSA', 96, 8, 'PSA.96.8', 'Ascribe to the LORD the glory due His name; bring an offering and enter His courts.'),
('PSA', 96, 9, 'PSA.96.9', 'Worship the LORD in the splendor of His holiness; tremble before Him, all the earth.'),
('PSA', 96, 10, 'PSA.96.10', 'Declare among the nations: “The LORD reigns!” The world is firmly established; it cannot be moved; He will judge the peoples with equity.'),
('PSA', 96, 11, 'PSA.96.11', 'Let the heavens be glad and the earth rejoice; let the sea resound, and all that fills it.'),
('PSA', 96, 12, 'PSA.96.12', 'Let the fields exult, and all that is in them. Then all the trees of the forest will sing for joy'),
('PSA', 96, 13, 'PSA.96.13', 'before the LORD, for He is coming—He is coming to judge the earth. He will judge the world in righteousness and the peoples in His faithfulness.'),
('PSA', 97, 1, 'PSA.97.1', 'The LORD reigns, let the earth rejoice; let the distant shores be glad.'),
('PSA', 97, 2, 'PSA.97.2', 'Clouds and darkness surround Him; righteousness and justice are His throne’s foundation.'),
('PSA', 97, 3, 'PSA.97.3', 'Fire goes before Him and consumes His foes on every side.'),
('PSA', 97, 4, 'PSA.97.4', 'His lightning illuminates the world; the earth sees and trembles.'),
('PSA', 97, 5, 'PSA.97.5', 'The mountains melt like wax at the presence of the LORD, before the Lord of all the earth.'),
('PSA', 97, 6, 'PSA.97.6', 'The heavens proclaim His righteousness; all the peoples see His glory.'),
('PSA', 97, 7, 'PSA.97.7', 'All worshipers of images are put to shame—those who boast in idols. Worship Him, all you gods!'),
('PSA', 97, 8, 'PSA.97.8', 'Zion hears and rejoices, and the towns of Judah exult because of Your judgments, O LORD.'),
('PSA', 97, 9, 'PSA.97.9', 'For You, O LORD, are Most High over all the earth; You are exalted far above all gods.'),
('PSA', 97, 10, 'PSA.97.10', 'Hate evil, O you who love the LORD! He preserves the souls of His saints; He delivers them from the hand of the wicked.'),
('PSA', 97, 11, 'PSA.97.11', 'Light shines on the righteous, gladness on the upright in heart.'),
('PSA', 97, 12, 'PSA.97.12', 'Rejoice in the LORD, you righteous ones, and praise His holy name.'),
('PSA', 98, 1, 'PSA.98.1', 'A Psalm. Sing to the LORD a new song, for He has done wonders; His right hand and holy arm have gained Him the victory.'),
('PSA', 98, 2, 'PSA.98.2', 'The LORD has proclaimed His salvation and revealed His righteousness to the nations.'),
('PSA', 98, 3, 'PSA.98.3', 'He has remembered His love and faithfulness to the house of Israel; all the ends of the earth have seen the salvation of our God.'),
('PSA', 98, 4, 'PSA.98.4', 'Make a joyful noise to the LORD, all the earth; break forth—let your cry ring out, and sing praises!'),
('PSA', 98, 5, 'PSA.98.5', 'Sing praises to the LORD with the lyre, in melodious song with the harp.'),
('PSA', 98, 6, 'PSA.98.6', 'With trumpets and the blast of the ram’s horn shout for joy before the LORD, the King.'),
('PSA', 98, 7, 'PSA.98.7', 'Let the sea resound, and all that fills it, the world, and all who dwell in it.'),
('PSA', 98, 8, 'PSA.98.8', 'Let the rivers clap their hands, let the mountains sing together for joy'),
('PSA', 98, 9, 'PSA.98.9', 'before the LORD, for He comes to judge the earth. He will judge the world with righteousness and the peoples with equity.'),
('PSA', 99, 1, 'PSA.99.1', 'The LORD reigns; let the nations tremble! He is enthroned above the cherubim; let the earth quake!'),
('PSA', 99, 2, 'PSA.99.2', 'Great is the LORD in Zion; He is exalted above all the peoples.'),
('PSA', 99, 3, 'PSA.99.3', 'Let them praise Your great and awesome name—He is holy!'),
('PSA', 99, 4, 'PSA.99.4', 'The mighty King loves justice. You have established equity; You have exercised justice and righteousness in Jacob.'),
('PSA', 99, 5, 'PSA.99.5', 'Exalt the LORD our God, and worship at His footstool; He is holy!'),
('PSA', 99, 6, 'PSA.99.6', 'Moses and Aaron were among His priests; Samuel was among those who called on His name. They called to the LORD and He answered.'),
('PSA', 99, 7, 'PSA.99.7', 'He spoke to them from the pillar of cloud; they kept His decrees and the statutes He gave them.'),
('PSA', 99, 8, 'PSA.99.8', 'O LORD our God, You answered them. You were a forgiving God to them, yet an avenger of their misdeeds.'),
('PSA', 99, 9, 'PSA.99.9', 'Exalt the LORD our God and worship at His holy mountain, for the LORD our God is holy.'),
('PSA', 100, 1, 'PSA.100.1', 'A Psalm of thanksgiving. Make a joyful noise to the LORD, all the earth.'),
('PSA', 100, 2, 'PSA.100.2', 'Serve the LORD with gladness; come into His presence with joyful songs.'),
('PSA', 100, 3, 'PSA.100.3', 'Know that the LORD is God. It is He who made us, and we are His; we are His people, and the sheep of His pasture.'),
('PSA', 100, 4, 'PSA.100.4', 'Enter His gates with thanksgiving and His courts with praise; give thanks to Him and bless His name.'),
('PSA', 100, 5, 'PSA.100.5', 'For the LORD is good, and His loving devotion endures forever; His faithfulness continues to all generations.'),
('PSA', 101, 1, 'PSA.101.1', 'A Psalm of David. I will sing of Your loving devotion and justice; to You, O LORD, I will sing praises.'),
('PSA', 101, 2, 'PSA.101.2', 'I will ponder the way that is blameless—when will You come to me? I will walk in my house with integrity of heart.'),
('PSA', 101, 3, 'PSA.101.3', 'I will set no worthless thing before my eyes. I hate the work of those who fall away; it shall not cling to me.'),
('PSA', 101, 4, 'PSA.101.4', 'A perverse heart shall depart from me; I will know nothing of evil.'),
('PSA', 101, 5, 'PSA.101.5', 'Whoever slanders his neighbor in secret, I will put to silence; the one with haughty eyes and a proud heart, I will not endure.'),
('PSA', 101, 6, 'PSA.101.6', 'My eyes favor the faithful of the land, that they may dwell with me; he who walks in the way of integrity shall minister to me.'),
('PSA', 101, 7, 'PSA.101.7', 'No one who practices deceit shall dwell in my house; no one who tells lies shall stand in my presence.'),
('PSA', 101, 8, 'PSA.101.8', 'Every morning I will remove all the wicked of the land, that I may cut off every evildoer from the city of the LORD.'),
('PSA', 102, 1, 'PSA.102.1', 'A prayer of one who is afflicted, when he grows faint and pours out his lament before the LORD. Hear my prayer, O LORD; let my cry for help come before You.'),
('PSA', 102, 2, 'PSA.102.2', 'Do not hide Your face from me in my day of distress. Incline Your ear to me; answer me quickly when I call.'),
('PSA', 102, 3, 'PSA.102.3', 'For my days vanish like smoke, and my bones burn like glowing embers.'),
('PSA', 102, 4, 'PSA.102.4', 'My heart is afflicted, and withered like grass; I even forget to eat my bread.'),
('PSA', 102, 5, 'PSA.102.5', 'Through my loud groaning my skin hangs on my bones.'),
('PSA', 102, 6, 'PSA.102.6', 'I am like a desert owl, like an owl among the ruins.'),
('PSA', 102, 7, 'PSA.102.7', 'I lie awake; I am like a lone bird on a housetop.'),
('PSA', 102, 8, 'PSA.102.8', 'All day long my enemies taunt me; they ridicule me and curse me.'),
('PSA', 102, 9, 'PSA.102.9', 'For I have eaten ashes like bread and mixed my drink with tears'),
('PSA', 102, 10, 'PSA.102.10', 'because of Your indignation and wrath, for You have picked me up and cast me aside.'),
('PSA', 102, 11, 'PSA.102.11', 'My days are like lengthening shadows, and I wither away like grass.'),
('PSA', 102, 12, 'PSA.102.12', 'But You, O LORD, sit enthroned forever; Your renown endures to all generations.'),
('PSA', 102, 13, 'PSA.102.13', 'You will rise up and have compassion on Zion, for it is time to show her favor—the appointed time has come.'),
('PSA', 102, 14, 'PSA.102.14', 'For Your servants delight in her stones and take pity on her dust.'),
('PSA', 102, 15, 'PSA.102.15', 'So the nations will fear the name of the LORD, and all the kings of the earth will fear Your glory.'),
('PSA', 102, 16, 'PSA.102.16', 'For the LORD will rebuild Zion; He has appeared in His glory.'),
('PSA', 102, 17, 'PSA.102.17', 'He will turn toward the prayer of the destitute; He will not despise their prayer.'),
('PSA', 102, 18, 'PSA.102.18', 'Let this be written for the generation to come, so that a people not yet created may praise the LORD.'),
('PSA', 102, 19, 'PSA.102.19', 'For He looked down from the heights of His sanctuary; the LORD gazed out from heaven to earth'),
('PSA', 102, 20, 'PSA.102.20', 'to hear a prisoner’s groaning, to release those condemned to death,'),
('PSA', 102, 21, 'PSA.102.21', 'that they may proclaim the name of the LORD in Zion and praise Him in Jerusalem,'),
('PSA', 102, 22, 'PSA.102.22', 'when peoples and kingdoms assemble to serve the LORD.'),
('PSA', 102, 23, 'PSA.102.23', 'He has broken my strength on the way; He has cut short my days.'),
('PSA', 102, 24, 'PSA.102.24', 'I say: “O my God, do not take me in the midst of my days! Your years go on through all generations.'),
('PSA', 102, 25, 'PSA.102.25', 'In the beginning You laid the foundations of the earth, and the heavens are the work of Your hands.'),
('PSA', 102, 26, 'PSA.102.26', 'They will perish, but You remain; they will all wear out like a garment. Like clothing You will change them, and they will be passed on.'),
('PSA', 102, 27, 'PSA.102.27', 'But You remain the same, and Your years will never end.'),
('PSA', 102, 28, 'PSA.102.28', 'The children of Your servants will dwell securely, and their descendants will be established before You.”'),
('PSA', 103, 1, 'PSA.103.1', 'Of David. Bless the LORD, O my soul; all that is within me, bless His holy name.'),
('PSA', 103, 2, 'PSA.103.2', 'Bless the LORD, O my soul, and do not forget all His kind deeds—'),
('PSA', 103, 3, 'PSA.103.3', 'He who forgives all your iniquities and heals all your diseases,'),
('PSA', 103, 4, 'PSA.103.4', 'who redeems your life from the Pit and crowns you with loving devotion and compassion,'),
('PSA', 103, 5, 'PSA.103.5', 'who satisfies you with good things, so that your youth is renewed like the eagle’s.'),
('PSA', 103, 6, 'PSA.103.6', 'The LORD executes righteousness and justice for all the oppressed.'),
('PSA', 103, 7, 'PSA.103.7', 'He made known His ways to Moses, His deeds to the people of Israel.'),
('PSA', 103, 8, 'PSA.103.8', 'The LORD is compassionate and gracious, slow to anger, abounding in loving devotion.'),
('PSA', 103, 9, 'PSA.103.9', 'He will not always accuse us, nor harbor His anger forever.'),
('PSA', 103, 10, 'PSA.103.10', 'He has not dealt with us according to our sins or repaid us according to our iniquities.'),
('PSA', 103, 11, 'PSA.103.11', 'For as high as the heavens are above the earth, so great is His loving devotion for those who fear Him.'),
('PSA', 103, 12, 'PSA.103.12', 'As far as the east is from the west, so far has He removed our transgressions from us.'),
('PSA', 103, 13, 'PSA.103.13', 'As a father has compassion on his children, so the LORD has compassion on those who fear Him.'),
('PSA', 103, 14, 'PSA.103.14', 'For He knows our frame; He is mindful that we are dust.'),
('PSA', 103, 15, 'PSA.103.15', 'As for man, his days are like grass—he blooms like a flower of the field;'),
('PSA', 103, 16, 'PSA.103.16', 'when the wind passes over, it vanishes, and its place remembers it no more.'),
('PSA', 103, 17, 'PSA.103.17', 'But from everlasting to everlasting the loving devotion of the LORD extends to those who fear Him, and His righteousness to their children’s children—'),
('PSA', 103, 18, 'PSA.103.18', 'to those who keep His covenant and remember to obey His precepts.'),
('PSA', 103, 19, 'PSA.103.19', 'The LORD has established His throne in heaven, and His kingdom rules over all.'),
('PSA', 103, 20, 'PSA.103.20', 'Bless the LORD, all His angels mighty in strength who carry out His word, who hearken to the voice of His command.'),
('PSA', 103, 21, 'PSA.103.21', 'Bless the LORD, all His hosts, you servants who do His will.'),
('PSA', 103, 22, 'PSA.103.22', 'Bless the LORD, all His works in all places of His dominion. Bless the LORD, O my soul!'),
('PSA', 104, 1, 'PSA.104.1', 'Bless the LORD, O my soul! O LORD my God, You are very great; You are clothed with splendor and majesty.'),
('PSA', 104, 2, 'PSA.104.2', 'He wraps Himself in light as with a garment; He stretches out the heavens like a tent,'),
('PSA', 104, 3, 'PSA.104.3', 'laying the beams of His chambers in the waters above, making the clouds His chariot, walking on the wings of the wind.'),
('PSA', 104, 4, 'PSA.104.4', 'He makes the winds His messengers, flames of fire His servants.'),
('PSA', 104, 5, 'PSA.104.5', 'He set the earth on its foundations, never to be moved.'),
('PSA', 104, 6, 'PSA.104.6', 'You covered it with the deep like a garment; the waters stood above the mountains.'),
('PSA', 104, 7, 'PSA.104.7', 'At Your rebuke the waters fled; at the sound of Your thunder they hurried away—'),
('PSA', 104, 8, 'PSA.104.8', 'the mountains rose and the valleys sank to the place You assigned for them—'),
('PSA', 104, 9, 'PSA.104.9', 'You set a boundary they cannot cross, that they may never again cover the earth.'),
('PSA', 104, 10, 'PSA.104.10', 'He sends forth springs in the valleys; they flow between the mountains.'),
('PSA', 104, 11, 'PSA.104.11', 'They give drink to every beast of the field; the wild donkeys quench their thirst.'),
('PSA', 104, 12, 'PSA.104.12', 'The birds of the air nest beside the springs; they sing among the branches.'),
('PSA', 104, 13, 'PSA.104.13', 'He waters the mountains from His chambers; the earth is satisfied by the fruit of His works.'),
('PSA', 104, 14, 'PSA.104.14', 'He makes the grass grow for the livestock and provides crops for man to cultivate, bringing forth food from the earth:'),
('PSA', 104, 15, 'PSA.104.15', 'wine that gladdens the heart of man, oil that makes his face to shine, and bread that sustains his heart.'),
('PSA', 104, 16, 'PSA.104.16', 'The trees of the LORD have their fill, the cedars of Lebanon that He planted,'),
('PSA', 104, 17, 'PSA.104.17', 'where the birds build their nests; the stork makes her home in the cypresses.'),
('PSA', 104, 18, 'PSA.104.18', 'The high mountains are for the wild goats, the cliffs a refuge for the rock badgers.'),
('PSA', 104, 19, 'PSA.104.19', 'He made the moon to mark the seasons; the sun knows when to set.'),
('PSA', 104, 20, 'PSA.104.20', 'You bring darkness, and it becomes night, when all the beasts of the forest prowl.'),
('PSA', 104, 21, 'PSA.104.21', 'The young lions roar for their prey and seek their food from God.'),
('PSA', 104, 22, 'PSA.104.22', 'The sun rises, and they withdraw; they lie down in their dens.'),
('PSA', 104, 23, 'PSA.104.23', 'Man goes forth to his work and to his labor until evening.'),
('PSA', 104, 24, 'PSA.104.24', 'How many are Your works, O LORD! In wisdom You have made them all; the earth is full of Your creatures.'),
('PSA', 104, 25, 'PSA.104.25', 'Here is the sea, vast and wide, teeming with creatures beyond number, living things both great and small.'),
('PSA', 104, 26, 'PSA.104.26', 'There the ships pass, and Leviathan, which You formed to frolic there.'),
('PSA', 104, 27, 'PSA.104.27', 'All creatures look to You to give them their food in due season.'),
('PSA', 104, 28, 'PSA.104.28', 'When You give it to them, they gather it up; when You open Your hand, they are satisfied with good things.'),
('PSA', 104, 29, 'PSA.104.29', 'When You hide Your face, they are terrified; when You take away their breath, they die and return to dust.'),
('PSA', 104, 30, 'PSA.104.30', 'When You send Your Spirit, they are created, and You renew the face of the earth.'),
('PSA', 104, 31, 'PSA.104.31', 'May the glory of the LORD endure forever; may the LORD rejoice in His works.'),
('PSA', 104, 32, 'PSA.104.32', 'He looks on the earth, and it trembles; He touches the mountains, and they smolder.'),
('PSA', 104, 33, 'PSA.104.33', 'I will sing to the LORD all my life; I will sing praise to my God while I have my being.'),
('PSA', 104, 34, 'PSA.104.34', 'May my meditation be pleasing to Him, for I rejoice in the LORD.'),
('PSA', 104, 35, 'PSA.104.35', 'May sinners vanish from the earth and the wicked be no more. Bless the LORD, O my soul. Hallelujah!'),
('PSA', 105, 1, 'PSA.105.1', 'Give thanks to the LORD, call upon His name; make known His deeds among the nations.'),
('PSA', 105, 2, 'PSA.105.2', 'Sing to Him, sing praises to Him; tell of all His wonders.'),
('PSA', 105, 3, 'PSA.105.3', 'Glory in His holy name; let the hearts of those who seek the LORD rejoice.'),
('PSA', 105, 4, 'PSA.105.4', 'Seek out the LORD and His strength; seek His face always.'),
('PSA', 105, 5, 'PSA.105.5', 'Remember the wonders He has done, His marvels, and the judgments He has pronounced,'),
('PSA', 105, 6, 'PSA.105.6', 'O offspring of His servant Abraham, O sons of Jacob, His chosen ones.'),
('PSA', 105, 7, 'PSA.105.7', 'He is the LORD our God; His judgments carry throughout the earth.'),
('PSA', 105, 8, 'PSA.105.8', 'He remembers His covenant forever, the word He ordained for a thousand generations—'),
('PSA', 105, 9, 'PSA.105.9', 'the covenant He made with Abraham, and the oath He swore to Isaac.'),
('PSA', 105, 10, 'PSA.105.10', 'He confirmed it to Jacob as a decree, to Israel as an everlasting covenant:'),
('PSA', 105, 11, 'PSA.105.11', '“I will give you the land of Canaan as the portion of your inheritance.”'),
('PSA', 105, 12, 'PSA.105.12', 'When they were few in number, few indeed, and strangers in the land,'),
('PSA', 105, 13, 'PSA.105.13', 'they wandered from nation to nation, from one kingdom to another.'),
('PSA', 105, 14, 'PSA.105.14', 'He let no man oppress them; He rebuked kings on their behalf:'),
('PSA', 105, 15, 'PSA.105.15', '“Do not touch My anointed ones! Do no harm to My prophets!”'),
('PSA', 105, 16, 'PSA.105.16', 'He called down famine on the land and cut off all their supplies of food.'),
('PSA', 105, 17, 'PSA.105.17', 'He sent a man before them—Joseph, sold as a slave.'),
('PSA', 105, 18, 'PSA.105.18', 'They bruised his feet with shackles and placed his neck in irons,'),
('PSA', 105, 19, 'PSA.105.19', 'until his prediction came true and the word of the LORD proved him right.'),
('PSA', 105, 20, 'PSA.105.20', 'The king sent and released him; the ruler of peoples set him free.'),
('PSA', 105, 21, 'PSA.105.21', 'He made him master of his household, ruler over all his substance,'),
('PSA', 105, 22, 'PSA.105.22', 'to instruct his princes as he pleased and teach his elders wisdom.'),
('PSA', 105, 23, 'PSA.105.23', 'Then Israel entered Egypt; Jacob dwelt in the land of Ham.'),
('PSA', 105, 24, 'PSA.105.24', 'And the LORD made His people very fruitful, more numerous than their foes,'),
('PSA', 105, 25, 'PSA.105.25', 'whose hearts He turned to hate His people, to conspire against His servants.'),
('PSA', 105, 26, 'PSA.105.26', 'He sent Moses His servant, and Aaron, whom He had chosen.'),
('PSA', 105, 27, 'PSA.105.27', 'They performed His miraculous signs among them, and wonders in the land of Ham.'),
('PSA', 105, 28, 'PSA.105.28', 'He sent darkness, and it became dark—yet they defied His words.'),
('PSA', 105, 29, 'PSA.105.29', 'He turned their waters to blood and caused their fish to die.'),
('PSA', 105, 30, 'PSA.105.30', 'Their land teemed with frogs, even in their royal chambers.'),
('PSA', 105, 31, 'PSA.105.31', 'He spoke, and insects swarmed—gnats throughout their country.'),
('PSA', 105, 32, 'PSA.105.32', 'He gave them hail for rain, with lightning throughout their land.'),
('PSA', 105, 33, 'PSA.105.33', 'He struck their vines and fig trees and shattered the trees of their country.'),
('PSA', 105, 34, 'PSA.105.34', 'He spoke, and the locusts came—young locusts without number.'),
('PSA', 105, 35, 'PSA.105.35', 'They devoured every plant in their land and consumed the produce of their soil.'),
('PSA', 105, 36, 'PSA.105.36', 'Then He struck all the firstborn in their land, the firstfruits of all their vigor.'),
('PSA', 105, 37, 'PSA.105.37', 'He brought Israel out with silver and gold, and none among His tribes stumbled.'),
('PSA', 105, 38, 'PSA.105.38', 'Egypt was glad when they departed, for the dread of Israel had fallen on them.'),
('PSA', 105, 39, 'PSA.105.39', 'He spread a cloud as a covering and a fire to light up the night.'),
('PSA', 105, 40, 'PSA.105.40', 'They asked, and He brought quail and satisfied them with the bread of heaven.'),
('PSA', 105, 41, 'PSA.105.41', 'He opened a rock, and water gushed out; it flowed like a river in the desert.'),
('PSA', 105, 42, 'PSA.105.42', 'For He remembered His holy promise to Abraham His servant.'),
('PSA', 105, 43, 'PSA.105.43', 'He brought forth His people with rejoicing, His chosen with shouts of joy.'),
('PSA', 105, 44, 'PSA.105.44', 'He gave them the lands of the nations, that they might inherit the fruit of others’ labor,'),
('PSA', 105, 45, 'PSA.105.45', 'that they might keep His statutes and obey His laws. Hallelujah!'),
('PSA', 106, 1, 'PSA.106.1', 'Hallelujah! Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
('PSA', 106, 2, 'PSA.106.2', 'Who can describe the mighty acts of the LORD or fully proclaim His praise?'),
('PSA', 106, 3, 'PSA.106.3', 'Blessed are those who uphold justice, who practice righteousness at all times.'),
('PSA', 106, 4, 'PSA.106.4', 'Remember me, O LORD, in Your favor to Your people; visit me with Your salvation,'),
('PSA', 106, 5, 'PSA.106.5', 'that I may see the prosperity of Your chosen ones, and rejoice in the gladness of Your nation, and give glory with Your inheritance.'),
('PSA', 106, 6, 'PSA.106.6', 'We have sinned like our fathers; we have done wrong and acted wickedly.'),
('PSA', 106, 7, 'PSA.106.7', 'Our fathers in Egypt did not grasp Your wonders or remember Your abundant kindness; but they rebelled by the sea, there at the Red Sea.'),
('PSA', 106, 8, 'PSA.106.8', 'Yet He saved them for the sake of His name, to make His power known.'),
('PSA', 106, 9, 'PSA.106.9', 'He rebuked the Red Sea, and it dried up; He led them through the depths as through a desert.'),
('PSA', 106, 10, 'PSA.106.10', 'He saved them from the hand that hated them; He redeemed them from the hand of the enemy.'),
('PSA', 106, 11, 'PSA.106.11', 'The waters covered their foes; not one of them remained.'),
('PSA', 106, 12, 'PSA.106.12', 'Then they believed His promises and sang His praise.'),
('PSA', 106, 13, 'PSA.106.13', 'Yet they soon forgot His works and failed to wait for His counsel.'),
('PSA', 106, 14, 'PSA.106.14', 'They craved intensely in the wilderness and tested God in the desert.'),
('PSA', 106, 15, 'PSA.106.15', 'So He granted their request, but sent a wasting disease upon them.'),
('PSA', 106, 16, 'PSA.106.16', 'In the camp they envied Moses, as well as Aaron, the holy one of the LORD.'),
('PSA', 106, 17, 'PSA.106.17', 'The earth opened up and swallowed Dathan; it covered the assembly of Abiram.'),
('PSA', 106, 18, 'PSA.106.18', 'Then fire blazed through their company; flames consumed the wicked.'),
('PSA', 106, 19, 'PSA.106.19', 'At Horeb they made a calf and worshiped a molten image.'),
('PSA', 106, 20, 'PSA.106.20', 'They exchanged their Glory for the image of a grass-eating ox.'),
('PSA', 106, 21, 'PSA.106.21', 'They forgot God their Savior, who did great things in Egypt,'),
('PSA', 106, 22, 'PSA.106.22', 'wondrous works in the land of Ham, and awesome deeds by the Red Sea.'),
('PSA', 106, 23, 'PSA.106.23', 'So He said He would destroy them—had not Moses His chosen one stood before Him in the breach to divert His wrath from destroying them.'),
('PSA', 106, 24, 'PSA.106.24', 'They despised the pleasant land; they did not believe His promise.'),
('PSA', 106, 25, 'PSA.106.25', 'They grumbled in their tents and did not listen to the voice of the LORD.'),
('PSA', 106, 26, 'PSA.106.26', 'So He raised His hand and swore to cast them down in the wilderness,'),
('PSA', 106, 27, 'PSA.106.27', 'to disperse their offspring among the nations and scatter them throughout the lands.'),
('PSA', 106, 28, 'PSA.106.28', 'They yoked themselves to Baal of Peor and ate sacrifices offered to lifeless gods.'),
('PSA', 106, 29, 'PSA.106.29', 'So they provoked the LORD to anger with their deeds, and a plague broke out among them.'),
('PSA', 106, 30, 'PSA.106.30', 'But Phinehas stood and intervened, and the plague was restrained.'),
('PSA', 106, 31, 'PSA.106.31', 'It was credited to him as righteousness for endless generations to come.'),
('PSA', 106, 32, 'PSA.106.32', 'At the waters of Meribah they angered the LORD, and trouble came to Moses because of them.'),
('PSA', 106, 33, 'PSA.106.33', 'For they rebelled against His Spirit, and Moses spoke rashly with his lips.'),
('PSA', 106, 34, 'PSA.106.34', 'They did not destroy the peoples as the LORD had commanded them,'),
('PSA', 106, 35, 'PSA.106.35', 'but they mingled with the nations and adopted their customs.'),
('PSA', 106, 36, 'PSA.106.36', 'They worshiped their idols, which became a snare to them.'),
('PSA', 106, 37, 'PSA.106.37', 'They sacrificed their sons and their daughters to demons.'),
('PSA', 106, 38, 'PSA.106.38', 'They shed innocent blood—the blood of their sons and daughters, whom they sacrificed to the idols of Canaan, and the land was polluted with blood.'),
('PSA', 106, 39, 'PSA.106.39', 'They defiled themselves by their actions and prostituted themselves by their deeds.'),
('PSA', 106, 40, 'PSA.106.40', 'So the anger of the LORD burned against His people, and He abhorred His own inheritance.'),
('PSA', 106, 41, 'PSA.106.41', 'He delivered them into the hand of the nations, and those who hated them ruled over them.'),
('PSA', 106, 42, 'PSA.106.42', 'Their enemies oppressed them and subdued them under their hand.'),
('PSA', 106, 43, 'PSA.106.43', 'Many times He rescued them, but they were bent on rebellion and sank down in their iniquity.'),
('PSA', 106, 44, 'PSA.106.44', 'Nevertheless He heard their cry; He took note of their distress.'),
('PSA', 106, 45, 'PSA.106.45', 'And He remembered His covenant with them, and relented by the abundance of His loving devotion.'),
('PSA', 106, 46, 'PSA.106.46', 'He made them objects of compassion to all who held them captive.'),
('PSA', 106, 47, 'PSA.106.47', 'Save us, O LORD our God, and gather us from the nations, that we may give thanks to Your holy name, that we may glory in Your praise.'),
('PSA', 106, 48, 'PSA.106.48', 'Blessed be the LORD, the God of Israel, from everlasting to everlasting. Let all the people say, “Amen!” Hallelujah!'),
('PSA', 107, 1, 'PSA.107.1', 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
('PSA', 107, 2, 'PSA.107.2', 'Let the redeemed of the LORD say so, whom He has redeemed from the hand of the enemy'),
('PSA', 107, 3, 'PSA.107.3', 'and gathered from the lands, from east and west, from north and south.'),
('PSA', 107, 4, 'PSA.107.4', 'Some wandered in desert wastelands, finding no path to a city in which to dwell.'),
('PSA', 107, 5, 'PSA.107.5', 'They were hungry and thirsty; their soul fainted within them.'),
('PSA', 107, 6, 'PSA.107.6', 'Then they cried out to the LORD in their trouble, and He delivered them from their distress.'),
('PSA', 107, 7, 'PSA.107.7', 'He led them on a straight path to reach a city where they could live.'),
('PSA', 107, 8, 'PSA.107.8', 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
('PSA', 107, 9, 'PSA.107.9', 'For He satisfies the thirsty and fills the hungry with good things.'),
('PSA', 107, 10, 'PSA.107.10', 'Some sat in darkness and in the shadow of death, prisoners in affliction and chains,'),
('PSA', 107, 11, 'PSA.107.11', 'because they rebelled against the words of God and despised the counsel of the Most High.'),
('PSA', 107, 12, 'PSA.107.12', 'He humbled their hearts with hard labor; they stumbled, and there was no one to help.'),
('PSA', 107, 13, 'PSA.107.13', 'Then they cried out to the LORD in their trouble, and He saved them from their distress.'),
('PSA', 107, 14, 'PSA.107.14', 'He brought them out of darkness and the shadow of death and broke away their chains.'),
('PSA', 107, 15, 'PSA.107.15', 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
('PSA', 107, 16, 'PSA.107.16', 'For He has broken down the gates of bronze and cut through the bars of iron.'),
('PSA', 107, 17, 'PSA.107.17', 'Fools, in their rebellious ways, and through their iniquities, suffered affliction.'),
('PSA', 107, 18, 'PSA.107.18', 'They loathed all food and drew near to the gates of death.'),
('PSA', 107, 19, 'PSA.107.19', 'Then they cried out to the LORD in their trouble, and He saved them from their distress.'),
('PSA', 107, 20, 'PSA.107.20', 'He sent forth His word and healed them; He rescued them from the Pit.'),
('PSA', 107, 21, 'PSA.107.21', 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
('PSA', 107, 22, 'PSA.107.22', 'Let them offer sacrifices of thanksgiving and declare His works with rejoicing.'),
('PSA', 107, 23, 'PSA.107.23', 'Others went out to sea in ships, conducting trade on the mighty waters.'),
('PSA', 107, 24, 'PSA.107.24', 'They saw the works of the LORD, and His wonders in the deep.'),
('PSA', 107, 25, 'PSA.107.25', 'For He spoke and raised a tempest that lifted the waves of the sea.'),
('PSA', 107, 26, 'PSA.107.26', 'They mounted up to the heavens, then sunk to the depths; their courage melted in their anguish.'),
('PSA', 107, 27, 'PSA.107.27', 'They reeled and staggered like drunkards, and all their skill was useless.'),
('PSA', 107, 28, 'PSA.107.28', 'Then they cried out to the LORD in their trouble, and He brought them out of their distress.'),
('PSA', 107, 29, 'PSA.107.29', 'He calmed the storm to a whisper, and the waves of the sea were hushed.'),
('PSA', 107, 30, 'PSA.107.30', 'They rejoiced in the silence, and He guided them to the harbor they desired.'),
('PSA', 107, 31, 'PSA.107.31', 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
('PSA', 107, 32, 'PSA.107.32', 'Let them exalt Him in the assembly of the people and praise Him in the council of the elders.'),
('PSA', 107, 33, 'PSA.107.33', 'He turns rivers into deserts, springs of water into thirsty ground,'),
('PSA', 107, 34, 'PSA.107.34', 'and fruitful land into fields of salt, because of the wickedness of its dwellers.'),
('PSA', 107, 35, 'PSA.107.35', 'He turns a desert into pools of water and a dry land into flowing springs.'),
('PSA', 107, 36, 'PSA.107.36', 'He causes the hungry to settle there, that they may establish a city in which to dwell.'),
('PSA', 107, 37, 'PSA.107.37', 'They sow fields and plant vineyards that yield a fruitful harvest.'),
('PSA', 107, 38, 'PSA.107.38', 'He blesses them, and they multiply greatly; He does not let their herds diminish.'),
('PSA', 107, 39, 'PSA.107.39', 'When they are decreased and humbled by oppression, evil, and sorrow,'),
('PSA', 107, 40, 'PSA.107.40', 'He pours out contempt on the nobles and makes them wander in a trackless wasteland.'),
('PSA', 107, 41, 'PSA.107.41', 'But He lifts the needy from affliction and increases their families like flocks.'),
('PSA', 107, 42, 'PSA.107.42', 'The upright see and rejoice, and all iniquity shuts its mouth.'),
('PSA', 107, 43, 'PSA.107.43', 'Let him who is wise pay heed to these things and consider the loving devotion of the LORD.'),
('PSA', 108, 1, 'PSA.108.1', 'A song. A Psalm of David. My heart is steadfast, O God; I will sing and make music with all my being.'),
('PSA', 108, 2, 'PSA.108.2', 'Awake, O harp and lyre! I will awaken the dawn.'),
('PSA', 108, 3, 'PSA.108.3', 'I will praise You, O LORD, among the nations; I will sing Your praises among the peoples.'),
('PSA', 108, 4, 'PSA.108.4', 'For Your loving devotion extends beyond the heavens, and Your faithfulness reaches to the clouds.'),
('PSA', 108, 5, 'PSA.108.5', 'Be exalted, O God, above the heavens; may Your glory cover all the earth.'),
('PSA', 108, 6, 'PSA.108.6', 'Respond and save us with Your right hand, that Your beloved may be delivered.'),
('PSA', 108, 7, 'PSA.108.7', 'God has spoken from His sanctuary: “I will triumph! I will parcel out Shechem and apportion the Valley of Succoth.'),
('PSA', 108, 8, 'PSA.108.8', 'Gilead is Mine, and Manasseh is Mine; Ephraim is My helmet, Judah is My scepter.'),
('PSA', 108, 9, 'PSA.108.9', 'Moab is My washbasin; upon Edom I toss My sandal; over Philistia I shout in triumph.”'),
('PSA', 108, 10, 'PSA.108.10', 'Who will bring me to the fortified city? Who will lead me to Edom?'),
('PSA', 108, 11, 'PSA.108.11', 'Have You not rejected us, O God? Will You no longer march out, O God, with our armies?'),
('PSA', 108, 12, 'PSA.108.12', 'Give us aid against the enemy, for the help of man is worthless.'),
('PSA', 108, 13, 'PSA.108.13', 'With God we will perform with valor, and He will trample our enemies.'),
('PSA', 109, 1, 'PSA.109.1', 'For the choirmaster. A Psalm of David. O God of my praise, be not silent.'),
('PSA', 109, 2, 'PSA.109.2', 'For wicked and deceitful mouths open against me; they speak against me with lying tongues.'),
('PSA', 109, 3, 'PSA.109.3', 'They surround me with hateful words and attack me without cause.'),
('PSA', 109, 4, 'PSA.109.4', 'In return for my love they accuse me, but I am a man of prayer.'),
('PSA', 109, 5, 'PSA.109.5', 'They repay me evil for good, and hatred for my love.'),
('PSA', 109, 6, 'PSA.109.6', 'Set over him a wicked man; let an accuser stand at his right hand.'),
('PSA', 109, 7, 'PSA.109.7', 'When he is tried, let him be found guilty, and may his prayer be regarded as sin.'),
('PSA', 109, 8, 'PSA.109.8', 'May his days be few; may another take his position.'),
('PSA', 109, 9, 'PSA.109.9', 'May his children be fatherless and his wife a widow.'),
('PSA', 109, 10, 'PSA.109.10', 'May his children wander as beggars, seeking sustenance far from their ruined homes.'),
('PSA', 109, 11, 'PSA.109.11', 'May the creditor seize all he owns, and strangers plunder the fruits of his labor.'),
('PSA', 109, 12, 'PSA.109.12', 'May there be no one to extend kindness to him, and no one to favor his fatherless children.'),
('PSA', 109, 13, 'PSA.109.13', 'May his descendants be cut off; may their name be blotted out from the next generation.'),
('PSA', 109, 14, 'PSA.109.14', 'May the iniquity of his fathers be remembered before the LORD, and the sin of his mother never be blotted out.'),
('PSA', 109, 15, 'PSA.109.15', 'May their sins always remain before the LORD, that He may cut off their memory from the earth.'),
('PSA', 109, 16, 'PSA.109.16', 'For he never thought to show kindness, but pursued the poor and needy and brokenhearted, even to their death.'),
('PSA', 109, 17, 'PSA.109.17', 'The cursing that he loved, may it fall on him; the blessing in which he refused to delight, may it be far from him.'),
('PSA', 109, 18, 'PSA.109.18', 'The cursing that he wore like a coat, may it soak into his body like water, and into his bones like oil.'),
('PSA', 109, 19, 'PSA.109.19', 'May it be like a robe wrapped about him, like a belt tied forever around him.'),
('PSA', 109, 20, 'PSA.109.20', 'May this be the LORD’s reward to my accusers, to those who speak evil against me.'),
('PSA', 109, 21, 'PSA.109.21', 'But You, O GOD, the Lord, deal kindly with me for the sake of Your name; deliver me by the goodness of Your loving devotion.'),
('PSA', 109, 22, 'PSA.109.22', 'For I am poor and needy; my heart is wounded within me.'),
('PSA', 109, 23, 'PSA.109.23', 'I am fading away like a lengthening shadow; I am shaken off like a locust.'),
('PSA', 109, 24, 'PSA.109.24', 'My knees are weak from fasting, and my body grows lean and gaunt.'),
('PSA', 109, 25, 'PSA.109.25', 'I am an object of scorn to my accusers; when they see me, they shake their heads.'),
('PSA', 109, 26, 'PSA.109.26', 'Help me, O LORD my God; save me according to Your loving devotion.'),
('PSA', 109, 27, 'PSA.109.27', 'Let them know that this is Your hand, that You, O LORD, have done it.'),
('PSA', 109, 28, 'PSA.109.28', 'Though they curse, You will bless. When they rise up, they will be put to shame, but Your servant will rejoice.'),
('PSA', 109, 29, 'PSA.109.29', 'May my accusers be clothed with disgrace; may they wear their shame like a robe.'),
('PSA', 109, 30, 'PSA.109.30', 'With my mouth I will thank the LORD profusely; I will praise Him in the presence of many.'),
('PSA', 109, 31, 'PSA.109.31', 'For He stands at the right hand of the needy one, to save him from the condemners of his soul.'),
('PSA', 110, 1, 'PSA.110.1', 'A Psalm of David. The LORD said to my Lord: “Sit at My right hand until I make Your enemies a footstool for Your feet.”'),
('PSA', 110, 2, 'PSA.110.2', 'The LORD extends Your mighty scepter from Zion: “Rule in the midst of Your enemies.”'),
('PSA', 110, 3, 'PSA.110.3', 'Your people shall be willing on Your day of battle. Arrayed in holy splendor, from the womb of the dawn, to You belongs the dew of Your youth.'),
('PSA', 110, 4, 'PSA.110.4', 'The LORD has sworn and will not change His mind: “You are a priest forever in the order of Melchizedek.”'),
('PSA', 110, 5, 'PSA.110.5', 'The Lord is at Your right hand; He will crush kings in the day of His wrath.'),
('PSA', 110, 6, 'PSA.110.6', 'He will judge the nations, heaping up the dead; He will crush the leaders far and wide.'),
('PSA', 110, 7, 'PSA.110.7', 'He will drink from the brook by the road; therefore He will lift up His head.'),
('PSA', 111, 1, 'PSA.111.1', 'Hallelujah! I will give thanks to the LORD with all my heart in the council of the upright and in the assembly.'),
('PSA', 111, 2, 'PSA.111.2', 'Great are the works of the LORD; they are pondered by all who delight in them.'),
('PSA', 111, 3, 'PSA.111.3', 'Splendid and majestic is His work; His righteousness endures forever.'),
('PSA', 111, 4, 'PSA.111.4', 'He has caused His wonders to be remembered; the LORD is gracious and compassionate.'),
('PSA', 111, 5, 'PSA.111.5', 'He provides food for those who fear Him; He remembers His covenant forever.'),
('PSA', 111, 6, 'PSA.111.6', 'He has shown His people the power of His works by giving them the inheritance of the nations.'),
('PSA', 111, 7, 'PSA.111.7', 'The works of His hands are truth and justice; all His precepts are trustworthy.'),
('PSA', 111, 8, 'PSA.111.8', 'They are upheld forever and ever, enacted in truth and uprightness.'),
('PSA', 111, 9, 'PSA.111.9', 'He has sent redemption to His people; He has ordained His covenant forever; holy and awesome is His name.'),
('PSA', 111, 10, 'PSA.111.10', 'The fear of the LORD is the beginning of wisdom; all who follow His precepts gain rich understanding. His praise endures forever!'),
('PSA', 112, 1, 'PSA.112.1', 'Hallelujah! Blessed is the man who fears the LORD, who greatly delights in His commandments.'),
('PSA', 112, 2, 'PSA.112.2', 'His descendants will be mighty in the land; the generation of the upright will be blessed.'),
('PSA', 112, 3, 'PSA.112.3', 'Wealth and riches are in his house, and his righteousness endures forever.'),
('PSA', 112, 4, 'PSA.112.4', 'Light dawns in the darkness for the upright—for the gracious, compassionate, and righteous.'),
('PSA', 112, 5, 'PSA.112.5', 'It is well with the man who is generous and lends freely, whose affairs are guided by justice.'),
('PSA', 112, 6, 'PSA.112.6', 'Surely he will never be shaken; the righteous man will be remembered forever.'),
('PSA', 112, 7, 'PSA.112.7', 'He does not fear bad news; his heart is steadfast, trusting in the LORD.'),
('PSA', 112, 8, 'PSA.112.8', 'His heart is assured; he does not fear, until he looks in triumph on his foes.'),
('PSA', 112, 9, 'PSA.112.9', 'He has scattered abroad his gifts to the poor; his righteousness endures forever; his horn will be lifted high in honor.'),
('PSA', 112, 10, 'PSA.112.10', 'The wicked man will see and be grieved; he will gnash his teeth and waste away; the desires of the wicked will perish.'),
('PSA', 113, 1, 'PSA.113.1', 'Hallelujah! Give praise, O servants of the LORD; praise the name of the LORD.'),
('PSA', 113, 2, 'PSA.113.2', 'Blessed be the name of the LORD both now and forevermore.'),
('PSA', 113, 3, 'PSA.113.3', 'From where the sun rises to where it sets, the name of the LORD is praised.'),
('PSA', 113, 4, 'PSA.113.4', 'The LORD is exalted over all the nations, His glory above the heavens.'),
('PSA', 113, 5, 'PSA.113.5', 'Who is like the LORD our God, the One enthroned on high?'),
('PSA', 113, 6, 'PSA.113.6', 'He humbles Himself to behold the heavens and the earth.'),
('PSA', 113, 7, 'PSA.113.7', 'He raises the poor from the dust and lifts the needy from the dump'),
('PSA', 113, 8, 'PSA.113.8', 'to seat them with nobles, with the princes of His people.'),
('PSA', 113, 9, 'PSA.113.9', 'He settles the barren woman in her home as a joyful mother to her children. Hallelujah!'),
('PSA', 114, 1, 'PSA.114.1', 'When Israel departed from Egypt, the house of Jacob from a people of foreign tongue,'),
('PSA', 114, 2, 'PSA.114.2', 'Judah became God’s sanctuary, Israel His dominion.'),
('PSA', 114, 3, 'PSA.114.3', 'The sea observed and fled; the Jordan turned back;'),
('PSA', 114, 4, 'PSA.114.4', 'the mountains skipped like rams, the hills like lambs.'),
('PSA', 114, 5, 'PSA.114.5', 'Why was it, O sea, that you fled, O Jordan, that you turned back,'),
('PSA', 114, 6, 'PSA.114.6', 'O mountains, that you skipped like rams, O hills, like lambs?'),
('PSA', 114, 7, 'PSA.114.7', 'Tremble, O earth, at the presence of the Lord, at the presence of the God of Jacob,'),
('PSA', 114, 8, 'PSA.114.8', 'who turned the rock into a pool, the flint into a fountain of water!'),
('PSA', 115, 1, 'PSA.115.1', 'Not to us, O LORD, not to us, but to Your name be the glory, because of Your loving devotion, because of Your faithfulness.'),
('PSA', 115, 2, 'PSA.115.2', 'Why should the nations say, “Where is their God?”'),
('PSA', 115, 3, 'PSA.115.3', 'Our God is in heaven; He does as He pleases.'),
('PSA', 115, 4, 'PSA.115.4', 'Their idols are silver and gold, made by the hands of men.'),
('PSA', 115, 5, 'PSA.115.5', 'They have mouths, but cannot speak; they have eyes, but cannot see;'),
('PSA', 115, 6, 'PSA.115.6', 'they have ears, but cannot hear; they have noses, but cannot smell;'),
('PSA', 115, 7, 'PSA.115.7', 'they have hands, but cannot feel; they have feet, but cannot walk; they cannot even clear their throats.'),
('PSA', 115, 8, 'PSA.115.8', 'Those who make them become like them, as do all who trust in them.'),
('PSA', 115, 9, 'PSA.115.9', 'O Israel, trust in the LORD! He is their help and shield.'),
('PSA', 115, 10, 'PSA.115.10', 'O house of Aaron, trust in the LORD! He is their help and shield.'),
('PSA', 115, 11, 'PSA.115.11', 'You who fear the LORD, trust in the LORD! He is their help and shield.'),
('PSA', 115, 12, 'PSA.115.12', 'The LORD is mindful of us; He will bless us. He will bless the house of Israel; He will bless the house of Aaron;'),
('PSA', 115, 13, 'PSA.115.13', 'He will bless those who fear the LORD—small and great alike.'),
('PSA', 115, 14, 'PSA.115.14', 'May the LORD give you increase, both you and your children.'),
('PSA', 115, 15, 'PSA.115.15', 'May you be blessed by the LORD, the Maker of heaven and earth.'),
('PSA', 115, 16, 'PSA.115.16', 'The highest heavens belong to the LORD, but the earth He has given to mankind.'),
('PSA', 115, 17, 'PSA.115.17', 'It is not the dead who praise the LORD, nor any who descend into silence.'),
('PSA', 115, 18, 'PSA.115.18', 'But it is we who will bless the LORD, both now and forevermore. Hallelujah!'),
('PSA', 116, 1, 'PSA.116.1', 'I love the LORD, for He has heard my voice—my appeal for mercy.'),
('PSA', 116, 2, 'PSA.116.2', 'Because He has inclined His ear to me, I will call on Him as long as I live.'),
('PSA', 116, 3, 'PSA.116.3', 'The ropes of death entangled me; the anguish of Sheol overcame me; I was confronted by trouble and sorrow.'),
('PSA', 116, 4, 'PSA.116.4', 'Then I called on the name of the LORD: “O LORD, deliver my soul!”'),
('PSA', 116, 5, 'PSA.116.5', 'The LORD is gracious and righteous; our God is full of compassion.'),
('PSA', 116, 6, 'PSA.116.6', 'The LORD preserves the simplehearted; I was helpless, and He saved me.'),
('PSA', 116, 7, 'PSA.116.7', 'Return to your rest, O my soul, for the LORD has been good to you.'),
('PSA', 116, 8, 'PSA.116.8', 'For You have delivered my soul from death, my eyes from tears, my feet from stumbling.'),
('PSA', 116, 9, 'PSA.116.9', 'I will walk before the LORD in the land of the living.'),
('PSA', 116, 10, 'PSA.116.10', 'I believed, therefore I said, “I am greatly afflicted.”'),
('PSA', 116, 11, 'PSA.116.11', 'In my alarm I said, “All men are liars!”'),
('PSA', 116, 12, 'PSA.116.12', 'How can I repay the LORD for all His goodness to me?'),
('PSA', 116, 13, 'PSA.116.13', 'I will lift the cup of salvation and call on the name of the LORD.'),
('PSA', 116, 14, 'PSA.116.14', 'I will fulfill my vows to the LORD in the presence of all His people.'),
('PSA', 116, 15, 'PSA.116.15', 'Precious in the sight of the LORD is the death of His saints.'),
('PSA', 116, 16, 'PSA.116.16', 'Truly, O LORD, I am Your servant; I am Your servant, the son of Your maidservant; You have broken my bonds.'),
('PSA', 116, 17, 'PSA.116.17', 'I will offer to You a sacrifice of thanksgiving and call on the name of the LORD.'),
('PSA', 116, 18, 'PSA.116.18', 'I will fulfill my vows to the LORD in the presence of all His people,'),
('PSA', 116, 19, 'PSA.116.19', 'in the courts of the LORD’s house, in your midst, O Jerusalem. Hallelujah!'),
('PSA', 117, 1, 'PSA.117.1', 'Praise the LORD, all you nations! Extol Him, all you peoples!'),
('PSA', 117, 2, 'PSA.117.2', 'For great is His loving devotion toward us, and the faithfulness of the LORD endures forever. Hallelujah!'),
('PSA', 118, 1, 'PSA.118.1', 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
('PSA', 118, 2, 'PSA.118.2', 'Let Israel say, “His loving devotion endures forever.”'),
('PSA', 118, 3, 'PSA.118.3', 'Let the house of Aaron say, “His loving devotion endures forever.”'),
('PSA', 118, 4, 'PSA.118.4', 'Let those who fear the LORD say, “His loving devotion endures forever.”'),
('PSA', 118, 5, 'PSA.118.5', 'In my distress I called to the LORD, and He answered and set me free.'),
('PSA', 118, 6, 'PSA.118.6', 'The LORD is on my side; I will not be afraid. What can man do to me?'),
('PSA', 118, 7, 'PSA.118.7', 'The LORD is on my side; He is my helper. Therefore I will look in triumph on those who hate me.'),
('PSA', 118, 8, 'PSA.118.8', 'It is better to take refuge in the LORD than to trust in man.'),
('PSA', 118, 9, 'PSA.118.9', 'It is better to take refuge in the LORD than to trust in princes.'),
('PSA', 118, 10, 'PSA.118.10', 'All the nations surrounded me, but in the name of the LORD I cut them off.'),
('PSA', 118, 11, 'PSA.118.11', 'They surrounded me on every side, but in the name of the LORD I cut them off.'),
('PSA', 118, 12, 'PSA.118.12', 'They swarmed around me like bees, but they were extinguished like burning thorns; in the name of the LORD I cut them off.'),
('PSA', 118, 13, 'PSA.118.13', 'I was pushed so hard I was falling, but the LORD helped me.'),
('PSA', 118, 14, 'PSA.118.14', 'The LORD is my strength and my song, and He has become my salvation.'),
('PSA', 118, 15, 'PSA.118.15', 'Shouts of joy and salvation resound in the tents of the righteous: “The right hand of the LORD performs with valor!'),
('PSA', 118, 16, 'PSA.118.16', 'The right hand of the LORD is exalted! The right hand of the LORD performs with valor!”'),
('PSA', 118, 17, 'PSA.118.17', 'I will not die, but I will live and proclaim what the LORD has done.'),
('PSA', 118, 18, 'PSA.118.18', 'The LORD disciplined me severely, but He has not given me over to death.'),
('PSA', 118, 19, 'PSA.118.19', 'Open to me the gates of righteousness, that I may enter and give thanks to the LORD.'),
('PSA', 118, 20, 'PSA.118.20', 'This is the gate of the LORD; the righteous shall enter through it.'),
('PSA', 118, 21, 'PSA.118.21', 'I will give You thanks, for You have answered me, and You have become my salvation.'),
('PSA', 118, 22, 'PSA.118.22', 'The stone the builders rejected has become the cornerstone.'),
('PSA', 118, 23, 'PSA.118.23', 'This is from the LORD, and it is marvelous in our eyes.'),
('PSA', 118, 24, 'PSA.118.24', 'This is the day that the LORD has made; we will rejoice and be glad in it.'),
('PSA', 118, 25, 'PSA.118.25', 'O LORD, save us, we pray. We beseech You, O LORD, cause us to prosper!'),
('PSA', 118, 26, 'PSA.118.26', 'Blessed is he who comes in the name of the LORD. From the house of the LORD we bless you.'),
('PSA', 118, 27, 'PSA.118.27', 'The LORD is God; He has made His light to shine upon us. Bind the festal sacrifice with cords to the horns of the altar.'),
('PSA', 118, 28, 'PSA.118.28', 'You are my God, and I will give You thanks. You are my God, and I will exalt You.'),
('PSA', 118, 29, 'PSA.118.29', 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
('PSA', 119, 1, 'PSA.119.1', 'Blessed are those whose way is blameless, who walk in the Law of the LORD.'),
('PSA', 119, 2, 'PSA.119.2', 'Blessed are those who keep His testimonies and seek Him with all their heart.'),
('PSA', 119, 3, 'PSA.119.3', 'They do no iniquity; they walk in His ways.'),
('PSA', 119, 4, 'PSA.119.4', 'You have ordained Your precepts, that we should keep them diligently.'),
('PSA', 119, 5, 'PSA.119.5', 'Oh, that my ways were committed to keeping Your statutes!'),
('PSA', 119, 6, 'PSA.119.6', 'Then I would not be ashamed when I consider all Your commandments.'),
('PSA', 119, 7, 'PSA.119.7', 'I will praise You with an upright heart when I learn Your righteous judgments.'),
('PSA', 119, 8, 'PSA.119.8', 'I will keep Your statutes; do not utterly forsake me.'),
('PSA', 119, 9, 'PSA.119.9', 'How can a young man keep his way pure? By guarding it according to Your word.'),
('PSA', 119, 10, 'PSA.119.10', 'With all my heart I have sought You; do not let me stray from Your commandments.'),
('PSA', 119, 11, 'PSA.119.11', 'I have hidden Your word in my heart that I might not sin against You.'),
('PSA', 119, 12, 'PSA.119.12', 'Blessed are You, O LORD; teach me Your statutes.'),
('PSA', 119, 13, 'PSA.119.13', 'With my lips I proclaim all the judgments of Your mouth.'),
('PSA', 119, 14, 'PSA.119.14', 'I rejoice in the way of Your testimonies as much as in all riches.'),
('PSA', 119, 15, 'PSA.119.15', 'I will meditate on Your precepts and regard Your ways.'),
('PSA', 119, 16, 'PSA.119.16', 'I will delight in Your statutes; I will not forget Your word.'),
('PSA', 119, 17, 'PSA.119.17', 'Deal bountifully with Your servant, that I may live and keep Your word.'),
('PSA', 119, 18, 'PSA.119.18', 'Open my eyes that I may see wondrous things from Your law.'),
('PSA', 119, 19, 'PSA.119.19', 'I am a stranger on the earth; do not hide Your commandments from me.'),
('PSA', 119, 20, 'PSA.119.20', 'My soul is consumed with longing for Your judgments at all times.'),
('PSA', 119, 21, 'PSA.119.21', 'You rebuke the arrogant—the cursed who stray from Your commandments.'),
('PSA', 119, 22, 'PSA.119.22', 'Remove my scorn and contempt, for I have kept Your testimonies.'),
('PSA', 119, 23, 'PSA.119.23', 'Though rulers sit and slander me, Your servant meditates on Your statutes.'),
('PSA', 119, 24, 'PSA.119.24', 'Your testimonies are indeed my delight; they are my counselors.'),
('PSA', 119, 25, 'PSA.119.25', 'My soul cleaves to the dust; revive me according to Your word.'),
('PSA', 119, 26, 'PSA.119.26', 'I recounted my ways, and You answered me; teach me Your statutes.'),
('PSA', 119, 27, 'PSA.119.27', 'Make clear to me the way of Your precepts; then I will meditate on Your wonders.'),
('PSA', 119, 28, 'PSA.119.28', 'My soul melts with sorrow; strengthen me according to Your word.'),
('PSA', 119, 29, 'PSA.119.29', 'Remove me from the path of deceit and graciously grant me Your law.'),
('PSA', 119, 30, 'PSA.119.30', 'I have chosen the way of truth; I have set Your ordinances before me.'),
('PSA', 119, 31, 'PSA.119.31', 'I cling to Your testimonies, O LORD; let me not be put to shame.'),
('PSA', 119, 32, 'PSA.119.32', 'I run in the path of Your commandments, for You will enlarge my heart.'),
('PSA', 119, 33, 'PSA.119.33', 'Teach me, O LORD, the way of Your statutes, and I will keep them to the end.'),
('PSA', 119, 34, 'PSA.119.34', 'Give me understanding that I may obey Your law, and follow it with all my heart.'),
('PSA', 119, 35, 'PSA.119.35', 'Direct me in the path of Your commandments, for there I find delight.'),
('PSA', 119, 36, 'PSA.119.36', 'Turn my heart to Your testimonies and not to covetous gain.'),
('PSA', 119, 37, 'PSA.119.37', 'Turn my eyes away from worthless things; revive me with Your word.'),
('PSA', 119, 38, 'PSA.119.38', 'Establish Your word to Your servant, to produce reverence for You.'),
('PSA', 119, 39, 'PSA.119.39', 'Turn away the disgrace I dread, for Your judgments are good.'),
('PSA', 119, 40, 'PSA.119.40', 'How I long for Your precepts! Revive me in Your righteousness.'),
('PSA', 119, 41, 'PSA.119.41', 'May Your loving devotion come to me, O LORD, Your salvation, according to Your promise.'),
('PSA', 119, 42, 'PSA.119.42', 'Then I can answer him who taunts, for I trust in Your word.'),
('PSA', 119, 43, 'PSA.119.43', 'Never take Your word of truth from my mouth, for I hope in Your judgments.'),
('PSA', 119, 44, 'PSA.119.44', 'I will always obey Your law, forever and ever.'),
('PSA', 119, 45, 'PSA.119.45', 'And I will walk in freedom, for I have sought Your precepts.'),
('PSA', 119, 46, 'PSA.119.46', 'I will speak of Your testimonies before kings, and I will not be ashamed.'),
('PSA', 119, 47, 'PSA.119.47', 'I delight in Your commandments because I love them.'),
('PSA', 119, 48, 'PSA.119.48', 'I lift up my hands to Your commandments, which I love, and I meditate on Your statutes.'),
('PSA', 119, 49, 'PSA.119.49', 'Remember Your word to Your servant, upon which You have given me hope.'),
('PSA', 119, 50, 'PSA.119.50', 'This is my comfort in affliction, that Your promise has given me life.'),
('PSA', 119, 51, 'PSA.119.51', 'The arrogant utterly deride me, but I do not turn from Your law.'),
('PSA', 119, 52, 'PSA.119.52', 'I remember Your judgments of old, O LORD, and in them I find comfort.'),
('PSA', 119, 53, 'PSA.119.53', 'Rage has taken hold of me because of the wicked who reject Your law.'),
('PSA', 119, 54, 'PSA.119.54', 'Your statutes are songs to me in the house of my pilgrimage.'),
('PSA', 119, 55, 'PSA.119.55', 'In the night, O LORD, I remember Your name, that I may keep Your law.'),
('PSA', 119, 56, 'PSA.119.56', 'This is my practice, for I obey Your precepts.'),
('PSA', 119, 57, 'PSA.119.57', 'The LORD is my portion; I have promised to keep Your words.'),
('PSA', 119, 58, 'PSA.119.58', 'I have sought Your face with all my heart; be gracious to me according to Your promise.'),
('PSA', 119, 59, 'PSA.119.59', 'I considered my ways and turned my steps to Your testimonies.'),
('PSA', 119, 60, 'PSA.119.60', 'I hurried without hesitating to keep Your commandments.'),
('PSA', 119, 61, 'PSA.119.61', 'Though the ropes of the wicked bind me, I do not forget Your law.'),
('PSA', 119, 62, 'PSA.119.62', 'At midnight I rise to give You thanks for Your righteous judgments.'),
('PSA', 119, 63, 'PSA.119.63', 'I am a friend to all who fear You, and to those who keep Your precepts.'),
('PSA', 119, 64, 'PSA.119.64', 'The earth is filled with Your loving devotion, O LORD; teach me Your statutes.'),
('PSA', 119, 65, 'PSA.119.65', 'You are good to Your servant, O LORD, according to Your word.'),
('PSA', 119, 66, 'PSA.119.66', 'Teach me good judgment and knowledge, for I believe in Your commandments.'),
('PSA', 119, 67, 'PSA.119.67', 'Before I was afflicted, I went astray; but now I keep Your word.'),
('PSA', 119, 68, 'PSA.119.68', 'You are good, and You do what is good; teach me Your statutes.'),
('PSA', 119, 69, 'PSA.119.69', 'Though the arrogant have smeared me with lies, I keep Your precepts with all my heart.'),
('PSA', 119, 70, 'PSA.119.70', 'Their hearts are callous and insensitive, but I delight in Your law.'),
('PSA', 119, 71, 'PSA.119.71', 'It was good for me to be afflicted, that I might learn Your statutes.'),
('PSA', 119, 72, 'PSA.119.72', 'The law from Your mouth is more precious to me than thousands of pieces of gold and silver.'),
('PSA', 119, 73, 'PSA.119.73', 'Your hands have made me and fashioned me; give me understanding to learn Your commandments.'),
('PSA', 119, 74, 'PSA.119.74', 'May those who fear You see me and rejoice, for I have hoped in Your word.'),
('PSA', 119, 75, 'PSA.119.75', 'I know, O LORD, that Your judgments are righteous, and that in faithfulness You have afflicted me.'),
('PSA', 119, 76, 'PSA.119.76', 'May Your loving devotion comfort me, I pray, according to Your promise to Your servant.'),
('PSA', 119, 77, 'PSA.119.77', 'May Your compassion come to me, that I may live, for Your law is my delight.'),
('PSA', 119, 78, 'PSA.119.78', 'May the arrogant be put to shame for subverting me with a lie; I will meditate on Your precepts.'),
('PSA', 119, 79, 'PSA.119.79', 'May those who fear You turn to me, those who know Your testimonies.'),
('PSA', 119, 80, 'PSA.119.80', 'May my heart be blameless in Your statutes, that I may not be put to shame.'),
('PSA', 119, 81, 'PSA.119.81', 'My soul faints for Your salvation; I wait for Your word.'),
('PSA', 119, 82, 'PSA.119.82', 'My eyes fail, looking for Your promise; I ask, “When will You comfort me?”'),
('PSA', 119, 83, 'PSA.119.83', 'Though I am like a wineskin dried up by smoke, I do not forget Your statutes.'),
('PSA', 119, 84, 'PSA.119.84', 'How many days must Your servant wait? When will You execute judgment on my persecutors?'),
('PSA', 119, 85, 'PSA.119.85', 'The arrogant have dug pits for me in violation of Your law.'),
('PSA', 119, 86, 'PSA.119.86', 'All Your commandments are faithful; I am persecuted without cause—help me!'),
('PSA', 119, 87, 'PSA.119.87', 'They almost wiped me from the earth, but I have not forsaken Your precepts.'),
('PSA', 119, 88, 'PSA.119.88', 'Revive me according to Your loving devotion, that I may obey the testimony of Your mouth.'),
('PSA', 119, 89, 'PSA.119.89', 'Your word, O LORD, is everlasting; it is firmly fixed in the heavens.'),
('PSA', 119, 90, 'PSA.119.90', 'Your faithfulness continues through all generations; You established the earth, and it endures.'),
('PSA', 119, 91, 'PSA.119.91', 'Your ordinances stand to this day, for all things are servants to You.'),
('PSA', 119, 92, 'PSA.119.92', 'If Your law had not been my delight, then I would have perished in my affliction.'),
('PSA', 119, 93, 'PSA.119.93', 'I will never forget Your precepts, for by them You have revived me.'),
('PSA', 119, 94, 'PSA.119.94', 'I am Yours; save me, for I have sought Your precepts.'),
('PSA', 119, 95, 'PSA.119.95', 'The wicked wait to destroy me, but I will ponder Your testimonies.'),
('PSA', 119, 96, 'PSA.119.96', 'I have seen a limit to all perfection, but Your commandment is without limit.'),
('PSA', 119, 97, 'PSA.119.97', 'Oh, how I love Your law! All day long it is my meditation.'),
('PSA', 119, 98, 'PSA.119.98', 'Your commandments make me wiser than my enemies, for they are always with me.'),
('PSA', 119, 99, 'PSA.119.99', 'I have more insight than all my teachers, for Your testimonies are my meditation.'),
('PSA', 119, 100, 'PSA.119.100', 'I discern more than the elders, for I obey Your precepts.'),
('PSA', 119, 101, 'PSA.119.101', 'I have kept my feet from every evil path, that I may keep Your word.'),
('PSA', 119, 102, 'PSA.119.102', 'I have not departed from Your ordinances, for You Yourself have taught me.'),
('PSA', 119, 103, 'PSA.119.103', 'How sweet are Your words to my taste—sweeter than honey in my mouth!'),
('PSA', 119, 104, 'PSA.119.104', 'I gain understanding from Your precepts; therefore I hate every false way.'),
('PSA', 119, 105, 'PSA.119.105', 'Your word is a lamp to my feet and a light to my path.'),
('PSA', 119, 106, 'PSA.119.106', 'I have sworn and confirmed that I will keep Your righteous judgments.'),
('PSA', 119, 107, 'PSA.119.107', 'I am severely afflicted, O LORD; revive me through Your word.'),
('PSA', 119, 108, 'PSA.119.108', 'Accept the freewill offerings of my mouth, O LORD, and teach me Your judgments.'),
('PSA', 119, 109, 'PSA.119.109', 'I constantly take my life in my hands, yet I do not forget Your law.'),
('PSA', 119, 110, 'PSA.119.110', 'The wicked have set a snare for me, but I have not strayed from Your precepts.'),
('PSA', 119, 111, 'PSA.119.111', 'Your testimonies are my heritage forever, for they are the joy of my heart.'),
('PSA', 119, 112, 'PSA.119.112', 'I have inclined my heart to perform Your statutes, even to the very end.'),
('PSA', 119, 113, 'PSA.119.113', 'The double-minded I despise, but Your law I love.'),
('PSA', 119, 114, 'PSA.119.114', 'You are my hiding place and my shield; I put my hope in Your word.'),
('PSA', 119, 115, 'PSA.119.115', 'Depart from me, you evildoers, that I may obey the commandments of my God.'),
('PSA', 119, 116, 'PSA.119.116', 'Sustain me as You promised, that I may live; let me not be ashamed of my hope.'),
('PSA', 119, 117, 'PSA.119.117', 'Uphold me, and I will be saved, that I may always regard Your statutes.'),
('PSA', 119, 118, 'PSA.119.118', 'You reject all who stray from Your statutes, for their deceitfulness is in vain.'),
('PSA', 119, 119, 'PSA.119.119', 'All the wicked on earth You discard like dross; therefore I love Your testimonies.'),
('PSA', 119, 120, 'PSA.119.120', 'My flesh trembles in awe of You; I stand in fear of Your judgments.'),
('PSA', 119, 121, 'PSA.119.121', 'I have done what is just and right; do not leave me to my oppressors.'),
('PSA', 119, 122, 'PSA.119.122', 'Ensure Your servant’s well-being; do not let the arrogant oppress me.'),
('PSA', 119, 123, 'PSA.119.123', 'My eyes fail, looking for Your salvation, and for Your righteous promise.'),
('PSA', 119, 124, 'PSA.119.124', 'Deal with Your servant according to Your loving devotion, and teach me Your statutes.'),
('PSA', 119, 125, 'PSA.119.125', 'I am Your servant; give me understanding, that I may know Your testimonies.'),
('PSA', 119, 126, 'PSA.119.126', 'It is time for the LORD to act, for they have broken Your law.'),
('PSA', 119, 127, 'PSA.119.127', 'Therefore I love Your commandments more than gold, even the purest gold.'),
('PSA', 119, 128, 'PSA.119.128', 'Therefore I admire all Your precepts and hate every false way.'),
('PSA', 119, 129, 'PSA.119.129', 'Wonderful are Your testimonies; therefore I obey them.'),
('PSA', 119, 130, 'PSA.119.130', 'The unfolding of Your words gives light; it informs the simple.'),
('PSA', 119, 131, 'PSA.119.131', 'I open my mouth and pant, longing for Your commandments.'),
('PSA', 119, 132, 'PSA.119.132', 'Turn to me and show me mercy, as You do to those who love Your name.'),
('PSA', 119, 133, 'PSA.119.133', 'Order my steps in Your word; let no sin rule over me.'),
('PSA', 119, 134, 'PSA.119.134', 'Redeem me from the oppression of man, that I may keep Your precepts.'),
('PSA', 119, 135, 'PSA.119.135', 'Make Your face shine upon Your servant, and teach me Your statutes.'),
('PSA', 119, 136, 'PSA.119.136', 'My eyes shed streams of tears because Your law is not obeyed.'),
('PSA', 119, 137, 'PSA.119.137', 'Righteous are You, O LORD, and upright are Your judgments.'),
('PSA', 119, 138, 'PSA.119.138', 'The testimonies You have laid down are righteous and altogether faithful.'),
('PSA', 119, 139, 'PSA.119.139', 'My zeal has consumed me because my foes forget Your words.'),
('PSA', 119, 140, 'PSA.119.140', 'Your promise is completely pure; therefore Your servant loves it.'),
('PSA', 119, 141, 'PSA.119.141', 'I am lowly and despised, but I do not forget Your precepts.'),
('PSA', 119, 142, 'PSA.119.142', 'Your righteousness is everlasting and Your law is true.'),
('PSA', 119, 143, 'PSA.119.143', 'Trouble and distress have found me, but Your commandments are my delight.'),
('PSA', 119, 144, 'PSA.119.144', 'Your testimonies are righteous forever. Give me understanding, that I may live.'),
('PSA', 119, 145, 'PSA.119.145', 'I call with all my heart; answer me, O LORD! I will obey Your statutes.'),
('PSA', 119, 146, 'PSA.119.146', 'I call to You; save me, that I may keep Your testimonies.'),
('PSA', 119, 147, 'PSA.119.147', 'I rise before dawn and cry for help; in Your word I have put my hope.'),
('PSA', 119, 148, 'PSA.119.148', 'My eyes anticipate the watches of night, that I may meditate on Your word.'),
('PSA', 119, 149, 'PSA.119.149', 'Hear my voice, O LORD, according to Your loving devotion; give me life according to Your justice.'),
('PSA', 119, 150, 'PSA.119.150', 'Those who follow after wickedness draw near; they are far from Your law.'),
('PSA', 119, 151, 'PSA.119.151', 'You are near, O LORD, and all Your commandments are true.'),
('PSA', 119, 152, 'PSA.119.152', 'Long ago I learned from Your testimonies that You have established them forever.'),
('PSA', 119, 153, 'PSA.119.153', 'Look upon my affliction and rescue me, for I have not forgotten Your law.'),
('PSA', 119, 154, 'PSA.119.154', 'Defend my cause and redeem me; revive me according to Your word.'),
('PSA', 119, 155, 'PSA.119.155', 'Salvation is far from the wicked because they do not seek Your statutes.'),
('PSA', 119, 156, 'PSA.119.156', 'Great are Your mercies, O LORD; revive me according to Your ordinances.'),
('PSA', 119, 157, 'PSA.119.157', 'Though my persecutors and foes are many, I have not turned from Your testimonies.'),
('PSA', 119, 158, 'PSA.119.158', 'I look on the faithless with loathing because they do not keep Your word.'),
('PSA', 119, 159, 'PSA.119.159', 'Consider how I love Your precepts, O LORD; give me life according to Your loving devotion.'),
('PSA', 119, 160, 'PSA.119.160', 'The entirety of Your word is truth, and all Your righteous judgments endure forever.'),
('PSA', 119, 161, 'PSA.119.161', 'Rulers persecute me without cause, but my heart fears only Your word.'),
('PSA', 119, 162, 'PSA.119.162', 'I rejoice in Your promise like one who finds great spoil.'),
('PSA', 119, 163, 'PSA.119.163', 'I hate and abhor falsehood, but Your law I love.'),
('PSA', 119, 164, 'PSA.119.164', 'Seven times a day I praise You for Your righteous judgments.'),
('PSA', 119, 165, 'PSA.119.165', 'Abundant peace belongs to those who love Your law; nothing can make them stumble.'),
('PSA', 119, 166, 'PSA.119.166', 'I wait for Your salvation, O LORD, and I carry out Your commandments.'),
('PSA', 119, 167, 'PSA.119.167', 'I obey Your testimonies and love them greatly.'),
('PSA', 119, 168, 'PSA.119.168', 'I obey Your precepts and Your testimonies, for all my ways are before You.'),
('PSA', 119, 169, 'PSA.119.169', 'May my cry come before You, O LORD; give me understanding according to Your word.'),
('PSA', 119, 170, 'PSA.119.170', 'May my plea come before You; rescue me according to Your promise.'),
('PSA', 119, 171, 'PSA.119.171', 'My lips pour forth praise, for You teach me Your statutes.'),
('PSA', 119, 172, 'PSA.119.172', 'My tongue sings of Your word, for all Your commandments are righteous.'),
('PSA', 119, 173, 'PSA.119.173', 'May Your hand be ready to help me, for I have chosen Your precepts.'),
('PSA', 119, 174, 'PSA.119.174', 'I long for Your salvation, O LORD, and Your law is my delight.'),
('PSA', 119, 175, 'PSA.119.175', 'Let me live to praise You; may Your judgments sustain me.'),
('PSA', 119, 176, 'PSA.119.176', 'I have strayed like a lost sheep; seek Your servant, for I have not forgotten Your commandments.'),
('PSA', 120, 1, 'PSA.120.1', 'A song of ascents. In my distress I cried to the LORD, and He answered me.'),
('PSA', 120, 2, 'PSA.120.2', 'Deliver my soul, O LORD, from lying lips and a deceitful tongue.'),
('PSA', 120, 3, 'PSA.120.3', 'What will He do to you, and what will be added to you, O deceitful tongue?'),
('PSA', 120, 4, 'PSA.120.4', 'Sharp arrows will come from the warrior, with burning coals of the broom tree!'),
('PSA', 120, 5, 'PSA.120.5', 'Woe to me that I dwell in Meshech, that I live among the tents of Kedar!'),
('PSA', 120, 6, 'PSA.120.6', 'Too long have I dwelt among those who hate peace.'),
('PSA', 120, 7, 'PSA.120.7', 'I am in favor of peace; but when I speak, they want war.'),
('PSA', 121, 1, 'PSA.121.1', 'A song of ascents. I lift up my eyes to the hills. From where does my help come?'),
('PSA', 121, 2, 'PSA.121.2', 'My help comes from the LORD, the Maker of heaven and earth.'),
('PSA', 121, 3, 'PSA.121.3', 'He will not allow your foot to slip; your Protector will not slumber.'),
('PSA', 121, 4, 'PSA.121.4', 'Behold, the Protector of Israel will neither slumber nor sleep.'),
('PSA', 121, 5, 'PSA.121.5', 'The LORD is your keeper; the LORD is the shade on your right hand.'),
('PSA', 121, 6, 'PSA.121.6', 'The sun will not strike you by day, nor the moon by night.'),
('PSA', 121, 7, 'PSA.121.7', 'The LORD will guard you from all evil; He will preserve your soul.'),
('PSA', 121, 8, 'PSA.121.8', 'The LORD will watch over your coming and going, both now and forevermore.'),
('PSA', 122, 1, 'PSA.122.1', 'A song of ascents. Of David. I was glad when they said to me, “Let us go to the house of the LORD.”'),
('PSA', 122, 2, 'PSA.122.2', 'Our feet are standing in your gates, O Jerusalem.'),
('PSA', 122, 3, 'PSA.122.3', 'Jerusalem is built up as a city united together,'),
('PSA', 122, 4, 'PSA.122.4', 'where the tribes go up, the tribes of the LORD, as a testimony for Israel, to give thanks to the name of the LORD.'),
('PSA', 122, 5, 'PSA.122.5', 'For there the thrones of judgment stand, the thrones of the house of David.'),
('PSA', 122, 6, 'PSA.122.6', 'Pray for the peace of Jerusalem: “May those who love you prosper.'),
('PSA', 122, 7, 'PSA.122.7', 'May there be peace within your walls, and prosperity inside your fortresses.”'),
('PSA', 122, 8, 'PSA.122.8', 'For the sake of my brothers and friends, I will say, “Peace be within you.”'),
('PSA', 122, 9, 'PSA.122.9', 'For the sake of the house of the LORD our God, I will seek your prosperity.'),
('PSA', 123, 1, 'PSA.123.1', 'A song of ascents. I lift up my eyes to You, the One enthroned in heaven.'),
('PSA', 123, 2, 'PSA.123.2', 'As the eyes of servants look to the hand of their master, as the eyes of a maidservant look to the hand of her mistress, so our eyes are on the LORD our God until He shows us mercy.'),
('PSA', 123, 3, 'PSA.123.3', 'Have mercy on us, O LORD, have mercy, for we have endured much contempt.'),
('PSA', 123, 4, 'PSA.123.4', 'We have endured much scorn from the arrogant, much contempt from the proud.'),
('PSA', 124, 1, 'PSA.124.1', 'A song of ascents. Of David. If the LORD had not been on our side—let Israel now declare—'),
('PSA', 124, 2, 'PSA.124.2', 'if the LORD had not been on our side when men attacked us,'),
('PSA', 124, 3, 'PSA.124.3', 'when their anger flared against us, then they would have swallowed us alive,'),
('PSA', 124, 4, 'PSA.124.4', 'then the floods would have engulfed us, then the torrent would have overwhelmed us,'),
('PSA', 124, 5, 'PSA.124.5', 'then the raging waters would have swept us away.'),
('PSA', 124, 6, 'PSA.124.6', 'Blessed be the LORD, who has not given us as prey to their teeth.'),
('PSA', 124, 7, 'PSA.124.7', 'We have escaped like a bird from the snare of the fowler; the net is torn, and we have slipped away.'),
('PSA', 124, 8, 'PSA.124.8', 'Our help is in the name of the LORD, the Maker of heaven and earth.'),
('PSA', 125, 1, 'PSA.125.1', 'A song of ascents. Those who trust in the LORD are like Mount Zion. It cannot be moved; it abides forever.'),
('PSA', 125, 2, 'PSA.125.2', 'As the mountains surround Jerusalem, so the LORD surrounds His people, both now and forevermore.'),
('PSA', 125, 3, 'PSA.125.3', 'For the scepter of the wicked will not rest upon the land allotted to the righteous, so that the righteous will not put forth their hands to injustice.'),
('PSA', 125, 4, 'PSA.125.4', 'Do good, O LORD, to those who are good, and to the upright in heart.'),
('PSA', 125, 5, 'PSA.125.5', 'But those who turn to crooked ways the LORD will banish with the evildoers. Peace be upon Israel.'),
('PSA', 126, 1, 'PSA.126.1', 'A song of ascents. When the LORD restored the captives of Zion, we were like dreamers.'),
('PSA', 126, 2, 'PSA.126.2', 'Then our mouths were filled with laughter, our tongues with shouts of joy. Then it was said among the nations, “The LORD has done great things for them.”'),
('PSA', 126, 3, 'PSA.126.3', 'The LORD has done great things for us; we are filled with joy.'),
('PSA', 126, 4, 'PSA.126.4', 'Restore our captives, O LORD, like streams in the Negev.'),
('PSA', 126, 5, 'PSA.126.5', 'Those who sow in tears will reap with shouts of joy.'),
('PSA', 126, 6, 'PSA.126.6', 'He who goes out weeping, bearing a trail of seed, will surely return with shouts of joy, carrying sheaves of grain.'),
('PSA', 127, 1, 'PSA.127.1', 'A song of ascents. Of Solomon. Unless the LORD builds the house, its builders labor in vain; unless the LORD protects the city, its watchmen stand guard in vain.'),
('PSA', 127, 2, 'PSA.127.2', 'In vain you rise early and stay up late, toiling for bread to eat—for He gives sleep to His beloved.'),
('PSA', 127, 3, 'PSA.127.3', 'Children are indeed a heritage from the LORD, and the fruit of the womb is His reward.'),
('PSA', 127, 4, 'PSA.127.4', 'Like arrows in the hand of a warrior, so are children born in one’s youth.'),
('PSA', 127, 5, 'PSA.127.5', 'Blessed is the man whose quiver is full of them. He will not be put to shame when he confronts the enemies at the gate.'),
('PSA', 128, 1, 'PSA.128.1', 'A song of ascents. Blessed are all who fear the LORD, who walk in His ways!'),
('PSA', 128, 2, 'PSA.128.2', 'For when you eat the fruit of your labor, blessings and prosperity will be yours.'),
('PSA', 128, 3, 'PSA.128.3', 'Your wife will be like a fruitful vine flourishing within your house, your sons like olive shoots sitting around your table.'),
('PSA', 128, 4, 'PSA.128.4', 'In this way indeed shall blessing come to the man who fears the LORD.'),
('PSA', 128, 5, 'PSA.128.5', 'May the LORD bless you from Zion, that you may see the prosperity of Jerusalem all the days of your life,'),
('PSA', 128, 6, 'PSA.128.6', 'that you may see your children’s children. Peace be upon Israel!'),
('PSA', 129, 1, 'PSA.129.1', 'A song of ascents. Many a time they have persecuted me from my youth—let Israel now declare—'),
('PSA', 129, 2, 'PSA.129.2', 'many a time they have persecuted me from my youth, but they have not prevailed against me.'),
('PSA', 129, 3, 'PSA.129.3', 'The plowmen plowed over my back; they made their furrows long.'),
('PSA', 129, 4, 'PSA.129.4', 'The LORD is righteous; He has cut me from the cords of the wicked.'),
('PSA', 129, 5, 'PSA.129.5', 'May all who hate Zion be turned back in shame.'),
('PSA', 129, 6, 'PSA.129.6', 'May they be like grass on the rooftops, which withers before it can grow,'),
('PSA', 129, 7, 'PSA.129.7', 'unable to fill the hands of the reaper, or the arms of the binder of sheaves.'),
('PSA', 129, 8, 'PSA.129.8', 'May none who pass by say to them, “The blessing of the LORD be on you; we bless you in the name of the LORD.”'),
('PSA', 130, 1, 'PSA.130.1', 'A song of ascents. Out of the depths I cry to You, O LORD!'),
('PSA', 130, 2, 'PSA.130.2', 'O Lord, hear my voice; let Your ears be attentive to my plea for mercy.'),
('PSA', 130, 3, 'PSA.130.3', 'If You, O LORD, kept track of iniquities, then who, O Lord, could stand?'),
('PSA', 130, 4, 'PSA.130.4', 'But with You there is forgiveness, so that You may be feared.'),
('PSA', 130, 5, 'PSA.130.5', 'I wait for the LORD; my soul does wait, and in His word I put my hope.'),
('PSA', 130, 6, 'PSA.130.6', 'My soul waits for the Lord more than watchmen wait for the morning—more than watchmen wait for the morning.'),
('PSA', 130, 7, 'PSA.130.7', 'O Israel, put your hope in the LORD, for with the LORD is loving devotion, and with Him is redemption in abundance.'),
('PSA', 130, 8, 'PSA.130.8', 'And He will redeem Israel from all iniquity.'),
('PSA', 131, 1, 'PSA.131.1', 'A song of ascents. Of David. My heart is not proud, O LORD, my eyes are not haughty. I do not aspire to great things or matters too lofty for me.'),
('PSA', 131, 2, 'PSA.131.2', 'Surely I have stilled and quieted my soul; like a weaned child with his mother, like a weaned child is my soul within me.'),
('PSA', 131, 3, 'PSA.131.3', 'O Israel, put your hope in the LORD, both now and forevermore.'),
('PSA', 132, 1, 'PSA.132.1', 'A song of ascents. O LORD, remember on behalf of David all the hardships he endured,'),
('PSA', 132, 2, 'PSA.132.2', 'how he swore an oath to the LORD, and vowed to the Mighty One of Jacob:'),
('PSA', 132, 3, 'PSA.132.3', '“I will not enter my house or get into my bed,'),
('PSA', 132, 4, 'PSA.132.4', 'I will not give sleep to my eyes or slumber to my eyelids,'),
('PSA', 132, 5, 'PSA.132.5', 'until I find a place for the LORD, a dwelling for the Mighty One of Jacob.”'),
('PSA', 132, 6, 'PSA.132.6', 'We heard that the ark was in Ephrathah; we found it in the fields of Jaar.'),
('PSA', 132, 7, 'PSA.132.7', 'Let us go to His dwelling place; let us worship at His footstool.'),
('PSA', 132, 8, 'PSA.132.8', 'Arise, O LORD, to Your resting place, You and the ark of Your strength.'),
('PSA', 132, 9, 'PSA.132.9', 'May Your priests be clothed with righteousness, and Your saints shout for joy.'),
('PSA', 132, 10, 'PSA.132.10', 'For the sake of Your servant David, do not reject Your anointed one.'),
('PSA', 132, 11, 'PSA.132.11', 'The LORD swore an oath to David, a promise He will not revoke: “One of your descendants I will place on your throne.'),
('PSA', 132, 12, 'PSA.132.12', 'If your sons keep My covenant and the testimony I will teach them, then their sons will also sit on your throne forever and ever.”'),
('PSA', 132, 13, 'PSA.132.13', 'For the LORD has chosen Zion; He has desired it for His home:'),
('PSA', 132, 14, 'PSA.132.14', '“This is My resting place forever and ever; here I will dwell, for I have desired this home.'),
('PSA', 132, 15, 'PSA.132.15', 'I will bless her with abundant provisions; I will satisfy her poor with bread.'),
('PSA', 132, 16, 'PSA.132.16', 'I will clothe her priests with salvation, and her saints will sing out in joy.'),
('PSA', 132, 17, 'PSA.132.17', 'There I will make a horn grow for David; I have prepared a lamp for My anointed one.'),
('PSA', 132, 18, 'PSA.132.18', 'I will clothe his enemies with shame, but the crown upon him will gleam.”'),
('PSA', 133, 1, 'PSA.133.1', 'A song of ascents. Of David. Behold, how good and pleasant it is when brothers live together in harmony!'),
('PSA', 133, 2, 'PSA.133.2', 'It is like fine oil on the head, running down on the beard, running down Aaron’s beard over the collar of his robes.'),
('PSA', 133, 3, 'PSA.133.3', 'It is like the dew of Hermon falling on the mountains of Zion. For there the LORD has bestowed the blessing of life forevermore.'),
('PSA', 134, 1, 'PSA.134.1', 'A song of ascents. Come, bless the LORD, all you servants of the LORD who serve by night in the house of the LORD!'),
('PSA', 134, 2, 'PSA.134.2', 'Lift up your hands to the sanctuary and bless the LORD!'),
('PSA', 134, 3, 'PSA.134.3', 'May the LORD, the Maker of heaven and earth, bless you from Zion.'),
('PSA', 135, 1, 'PSA.135.1', 'Hallelujah! Praise the name of the LORD. Give praise, O servants of the LORD,'),
('PSA', 135, 2, 'PSA.135.2', 'who stand in the house of the LORD, in the courts of the house of our God.'),
('PSA', 135, 3, 'PSA.135.3', 'Hallelujah, for the LORD is good; sing praises to His name, for it is lovely.'),
('PSA', 135, 4, 'PSA.135.4', 'For the LORD has chosen Jacob as His own, Israel as His treasured possession.'),
('PSA', 135, 5, 'PSA.135.5', 'For I know that the LORD is great; our Lord is above all gods.'),
('PSA', 135, 6, 'PSA.135.6', 'The LORD does all that pleases Him in the heavens and on the earth, in the seas and in all their depths.'),
('PSA', 135, 7, 'PSA.135.7', 'He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
('PSA', 135, 8, 'PSA.135.8', 'He struck down the firstborn of Egypt, of both man and beast.'),
('PSA', 135, 9, 'PSA.135.9', 'He sent signs and wonders into your midst, O Egypt, against Pharaoh and all his servants.'),
('PSA', 135, 10, 'PSA.135.10', 'He struck down many nations and slaughtered mighty kings:'),
('PSA', 135, 11, 'PSA.135.11', 'Sihon king of the Amorites, Og king of Bashan, and all the kings of Canaan.'),
('PSA', 135, 12, 'PSA.135.12', 'He gave their land as an inheritance, as a heritage to His people Israel.'),
('PSA', 135, 13, 'PSA.135.13', 'Your name, O LORD, endures forever, Your renown, O LORD, through all generations.'),
('PSA', 135, 14, 'PSA.135.14', 'For the LORD will vindicate His people and will have compassion on His servants.'),
('PSA', 135, 15, 'PSA.135.15', 'The idols of the nations are silver and gold, made by the hands of men.'),
('PSA', 135, 16, 'PSA.135.16', 'They have mouths, but cannot speak; they have eyes, but cannot see;'),
('PSA', 135, 17, 'PSA.135.17', 'they have ears, but cannot hear; nor is there breath in their mouths.'),
('PSA', 135, 18, 'PSA.135.18', 'Those who make them become like them, as do all who trust in them.'),
('PSA', 135, 19, 'PSA.135.19', 'O house of Israel, bless the LORD; O house of Aaron, bless the LORD;'),
('PSA', 135, 20, 'PSA.135.20', 'O house of Levi, bless the LORD; you who fear the LORD, bless the LORD!'),
('PSA', 135, 21, 'PSA.135.21', 'Blessed be the LORD from Zion—He who dwells in Jerusalem. Hallelujah!'),
('PSA', 136, 1, 'PSA.136.1', 'Give thanks to the LORD, for He is good. His loving devotion endures forever.'),
('PSA', 136, 2, 'PSA.136.2', 'Give thanks to the God of gods. His loving devotion endures forever.'),
('PSA', 136, 3, 'PSA.136.3', 'Give thanks to the Lord of lords. His loving devotion endures forever.'),
('PSA', 136, 4, 'PSA.136.4', 'He alone does great wonders. His loving devotion endures forever.'),
('PSA', 136, 5, 'PSA.136.5', 'By His insight He made the heavens. His loving devotion endures forever.'),
('PSA', 136, 6, 'PSA.136.6', 'He spread out the earth upon the waters. His loving devotion endures forever.'),
('PSA', 136, 7, 'PSA.136.7', 'He made the great lights—His loving devotion endures forever.'),
('PSA', 136, 8, 'PSA.136.8', 'the sun to rule the day, His loving devotion endures forever.'),
('PSA', 136, 9, 'PSA.136.9', 'the moon and stars to govern the night. His loving devotion endures forever.'),
('PSA', 136, 10, 'PSA.136.10', 'He struck down the firstborn of Egypt His loving devotion endures forever.'),
('PSA', 136, 11, 'PSA.136.11', 'and brought Israel out from among them His loving devotion endures forever.'),
('PSA', 136, 12, 'PSA.136.12', 'with a mighty hand and an outstretched arm. His loving devotion endures forever.'),
('PSA', 136, 13, 'PSA.136.13', 'He divided the Red Sea in two His loving devotion endures forever.'),
('PSA', 136, 14, 'PSA.136.14', 'and led Israel through the midst, His loving devotion endures forever.'),
('PSA', 136, 15, 'PSA.136.15', 'but swept Pharaoh and his army into the Red Sea. His loving devotion endures forever.'),
('PSA', 136, 16, 'PSA.136.16', 'He led His people through the wilderness. His loving devotion endures forever.'),
('PSA', 136, 17, 'PSA.136.17', 'He struck down great kings His loving devotion endures forever.'),
('PSA', 136, 18, 'PSA.136.18', 'and slaughtered mighty kings—His loving devotion endures forever.'),
('PSA', 136, 19, 'PSA.136.19', 'Sihon king of the Amorites His loving devotion endures forever.'),
('PSA', 136, 20, 'PSA.136.20', 'and Og king of Bashan—His loving devotion endures forever.'),
('PSA', 136, 21, 'PSA.136.21', 'and He gave their land as an inheritance, His loving devotion endures forever.'),
('PSA', 136, 22, 'PSA.136.22', 'a heritage to His servant Israel. His loving devotion endures forever.'),
('PSA', 136, 23, 'PSA.136.23', 'He remembered us in our low estate His loving devotion endures forever.'),
('PSA', 136, 24, 'PSA.136.24', 'and freed us from our enemies. His loving devotion endures forever.'),
('PSA', 136, 25, 'PSA.136.25', 'He gives food to every creature. His loving devotion endures forever.'),
('PSA', 136, 26, 'PSA.136.26', 'Give thanks to the God of heaven! His loving devotion endures forever.'),
('PSA', 137, 1, 'PSA.137.1', 'By the rivers of Babylon we sat and wept when we remembered Zion.'),
('PSA', 137, 2, 'PSA.137.2', 'There on the willows we hung our harps,'),
('PSA', 137, 3, 'PSA.137.3', 'for there our captors requested a song; our tormentors demanded songs of joy: “Sing us a song of Zion.”'),
('PSA', 137, 4, 'PSA.137.4', 'How can we sing a song of the LORD in a foreign land?'),
('PSA', 137, 5, 'PSA.137.5', 'If I forget you, O Jerusalem, may my right hand cease to function.'),
('PSA', 137, 6, 'PSA.137.6', 'May my tongue cling to the roof of my mouth if I do not remember you, if I do not exalt Jerusalem as my greatest joy!'),
('PSA', 137, 7, 'PSA.137.7', 'Remember, O LORD, the sons of Edom on the day Jerusalem fell: “Destroy it,” they said, “tear it down to its foundations!”'),
('PSA', 137, 8, 'PSA.137.8', 'O Daughter of Babylon, doomed to destruction, blessed is he who repays you as you have done to us.'),
('PSA', 137, 9, 'PSA.137.9', 'Blessed is he who seizes your infants and dashes them against the rocks.'),
('PSA', 138, 1, 'PSA.138.1', 'Of David. I give You thanks with all my heart; before the gods I sing Your praises.'),
('PSA', 138, 2, 'PSA.138.2', 'I bow down toward Your holy temple and give thanks to Your name for Your loving devotion and Your faithfulness; You have exalted Your name and Your word above all else.'),
('PSA', 138, 3, 'PSA.138.3', 'On the day I called, You answered me; You emboldened me and strengthened my soul.'),
('PSA', 138, 4, 'PSA.138.4', 'All the kings of the earth will give You thanks, O LORD, when they hear the words of Your mouth.'),
('PSA', 138, 5, 'PSA.138.5', 'They will sing of the ways of the LORD, for the glory of the LORD is great.'),
('PSA', 138, 6, 'PSA.138.6', 'Though the LORD is on high, He attends to the lowly; but the proud He knows from afar.'),
('PSA', 138, 7, 'PSA.138.7', 'If I walk in the midst of trouble, You preserve me from the anger of my foes; You extend Your hand, and Your right hand saves me.'),
('PSA', 138, 8, 'PSA.138.8', 'The LORD will fulfill His purpose for me. O LORD, Your loving devotion endures forever—do not abandon the works of Your hands.'),
('PSA', 139, 1, 'PSA.139.1', 'For the choirmaster. A Psalm of David. O LORD, You have searched me and known me.'),
('PSA', 139, 2, 'PSA.139.2', 'You know when I sit and when I rise; You understand my thoughts from afar.'),
('PSA', 139, 3, 'PSA.139.3', 'You search out my path and my lying down; You are aware of all my ways.'),
('PSA', 139, 4, 'PSA.139.4', 'Even before a word is on my tongue, You know all about it, O LORD.'),
('PSA', 139, 5, 'PSA.139.5', 'You hem me in behind and before; You have laid Your hand upon me.'),
('PSA', 139, 6, 'PSA.139.6', 'Such knowledge is too wonderful for me, too lofty for me to attain.'),
('PSA', 139, 7, 'PSA.139.7', 'Where can I go to escape Your Spirit? Where can I flee from Your presence?'),
('PSA', 139, 8, 'PSA.139.8', 'If I ascend to the heavens, You are there; if I make my bed in Sheol, You are there.'),
('PSA', 139, 9, 'PSA.139.9', 'If I rise on the wings of the dawn, if I settle by the farthest sea,'),
('PSA', 139, 10, 'PSA.139.10', 'even there Your hand will guide me; Your right hand will hold me fast.'),
('PSA', 139, 11, 'PSA.139.11', 'If I say, “Surely the darkness will hide me, and the light become night around me”—'),
('PSA', 139, 12, 'PSA.139.12', 'even the darkness is not dark to You, but the night shines like the day, for darkness is as light to You.'),
('PSA', 139, 13, 'PSA.139.13', 'For You formed my inmost being; You knit me together in my mother’s womb.'),
('PSA', 139, 14, 'PSA.139.14', 'I praise You, for I am fearfully and wonderfully made. Marvelous are Your works, and I know this very well.'),
('PSA', 139, 15, 'PSA.139.15', 'My frame was not hidden from You when I was made in secret, when I was woven together in the depths of the earth.'),
('PSA', 139, 16, 'PSA.139.16', 'Your eyes saw my unformed body; all my days were written in Your book and ordained for me before one of them came to be.'),
('PSA', 139, 17, 'PSA.139.17', 'How precious to me are Your thoughts, O God, how vast is their sum!'),
('PSA', 139, 18, 'PSA.139.18', 'If I were to count them, they would outnumber the grains of sand; and when I awake, I am still with You.'),
('PSA', 139, 19, 'PSA.139.19', 'O God, that You would slay the wicked—away from me, you bloodthirsty men—'),
('PSA', 139, 20, 'PSA.139.20', 'who speak of You deceitfully; Your enemies take Your name in vain.'),
('PSA', 139, 21, 'PSA.139.21', 'Do I not hate those who hate You, O LORD, and detest those who rise against You?'),
('PSA', 139, 22, 'PSA.139.22', 'I hate them with perfect hatred; I count them as my enemies.'),
('PSA', 139, 23, 'PSA.139.23', 'Search me, O God, and know my heart; test me and know my concerns.'),
('PSA', 139, 24, 'PSA.139.24', 'See if there is any offensive way in me; lead me in the way everlasting.'),
('PSA', 140, 1, 'PSA.140.1', 'For the choirmaster. A Psalm of David. Rescue me, O LORD, from evil men. Protect me from men of violence,'),
('PSA', 140, 2, 'PSA.140.2', 'who devise evil in their hearts and stir up war all day long.'),
('PSA', 140, 3, 'PSA.140.3', 'They sharpen their tongues like snakes; the venom of vipers is on their lips. Selah'),
('PSA', 140, 4, 'PSA.140.4', 'Guard me, O LORD, from the hands of the wicked. Keep me safe from men of violence who scheme to make me stumble.'),
('PSA', 140, 5, 'PSA.140.5', 'The proud hide a snare for me; the cords of their net are spread along the path, and lures are set out for me. Selah'),
('PSA', 140, 6, 'PSA.140.6', 'I say to the LORD, “You are my God.” Hear, O LORD, my cry for help.'),
('PSA', 140, 7, 'PSA.140.7', 'O GOD the Lord, the strength of my salvation, You shield my head in the day of battle.'),
('PSA', 140, 8, 'PSA.140.8', 'Grant not, O LORD, the desires of the wicked; do not promote their evil plans, lest they be exalted. Selah'),
('PSA', 140, 9, 'PSA.140.9', 'May the heads of those who surround me be covered in the trouble their lips have caused.'),
('PSA', 140, 10, 'PSA.140.10', 'May burning coals fall on them; may they be thrown into the fire, into the miry pits, never to rise again.'),
('PSA', 140, 11, 'PSA.140.11', 'May no slanderer be established in the land; may calamity hunt down the man of violence.'),
('PSA', 140, 12, 'PSA.140.12', 'I know that the LORD upholds justice for the poor and defends the cause of the needy.'),
('PSA', 140, 13, 'PSA.140.13', 'Surely the righteous will praise Your name; the upright will dwell in Your presence.'),
('PSA', 141, 1, 'PSA.141.1', 'A Psalm of David. I call upon You, O LORD; come quickly to me. Hear my voice when I call to You.'),
('PSA', 141, 2, 'PSA.141.2', 'May my prayer be set before You like incense; my uplifted hands, like the evening offering.'),
('PSA', 141, 3, 'PSA.141.3', 'Set a guard, O LORD, over my mouth; keep watch at the door of my lips.'),
('PSA', 141, 4, 'PSA.141.4', 'Do not let my heart be drawn to any evil thing or take part in works of wickedness with men who do iniquity; let me not feast on their delicacies.'),
('PSA', 141, 5, 'PSA.141.5', 'Let the righteous man strike me; let his rebuke be an act of loving devotion. It is oil for my head; let me not refuse it. For my prayer is ever against the deeds of the wicked.'),
('PSA', 141, 6, 'PSA.141.6', 'When their rulers are thrown down from the cliffs, the people will listen to my words, for they are pleasant.'),
('PSA', 141, 7, 'PSA.141.7', 'As when one plows and breaks up the soil, so our bones have been scattered at the mouth of Sheol.'),
('PSA', 141, 8, 'PSA.141.8', 'But my eyes are fixed on You, O GOD the Lord. In You I seek refuge; do not leave my soul defenseless.'),
('PSA', 141, 9, 'PSA.141.9', 'Keep me from the snares they have laid for me, and from the lures of evildoers.'),
('PSA', 141, 10, 'PSA.141.10', 'Let the wicked fall into their own nets, while I pass by in safety.'),
('PSA', 142, 1, 'PSA.142.1', 'A Maskil of David, when he was in the cave. A prayer. I cry aloud to the LORD; I lift my voice to the LORD for mercy.'),
('PSA', 142, 2, 'PSA.142.2', 'I pour out my complaint before Him; I reveal my trouble to Him.'),
('PSA', 142, 3, 'PSA.142.3', 'Although my spirit grows faint within me, You know my way. Along the path I travel they have hidden a snare for me.'),
('PSA', 142, 4, 'PSA.142.4', 'Look to my right and see; no one attends to me. There is no refuge for me; no one cares for my soul.'),
('PSA', 142, 5, 'PSA.142.5', 'I cry to You, O LORD: “You are my refuge, my portion in the land of the living.”'),
('PSA', 142, 6, 'PSA.142.6', 'Listen to my cry, for I am brought quite low. Rescue me from my pursuers, for they are too strong for me.'),
('PSA', 142, 7, 'PSA.142.7', 'Free my soul from prison, that I may praise Your name. The righteous will gather around me because of Your goodness to me.'),
('PSA', 143, 1, 'PSA.143.1', 'A Psalm of David. O LORD, hear my prayer. In Your faithfulness, give ear to my plea; in Your righteousness, answer me.'),
('PSA', 143, 2, 'PSA.143.2', 'Do not bring Your servant into judgment, for no one alive is righteous before You.'),
('PSA', 143, 3, 'PSA.143.3', 'For the enemy has pursued my soul, crushing my life to the ground, making me dwell in darkness like those long since dead.'),
('PSA', 143, 4, 'PSA.143.4', 'My spirit grows faint within me; my heart is dismayed inside me.'),
('PSA', 143, 5, 'PSA.143.5', 'I remember the days of old; I meditate on all Your works; I consider the work of Your hands.'),
('PSA', 143, 6, 'PSA.143.6', 'I stretch out my hands to You; my soul thirsts for You like a parched land. Selah'),
('PSA', 143, 7, 'PSA.143.7', 'Answer me quickly, O LORD; my spirit fails. Do not hide Your face from me, or I will be like those who descend to the Pit.'),
('PSA', 143, 8, 'PSA.143.8', 'Let me hear Your loving devotion in the morning, for I have put my trust in You. Teach me the way I should walk, for to You I lift up my soul.'),
('PSA', 143, 9, 'PSA.143.9', 'Deliver me from my enemies, O LORD; I flee to You for refuge.'),
('PSA', 143, 10, 'PSA.143.10', 'Teach me to do Your will, for You are my God. May Your good Spirit lead me on level ground.'),
('PSA', 143, 11, 'PSA.143.11', 'For the sake of Your name, O LORD, revive me. In Your righteousness, bring my soul out of trouble.'),
('PSA', 143, 12, 'PSA.143.12', 'And in Your loving devotion, cut off my enemies. Destroy all who afflict me, for I am Your servant.'),
('PSA', 144, 1, 'PSA.144.1', 'Of David. Blessed be the LORD, my Rock, who trains my hands for war, my fingers for battle.'),
('PSA', 144, 2, 'PSA.144.2', 'He is my steadfast love and my fortress, my stronghold and my deliverer. He is my shield, in whom I take refuge, who subdues peoples under me.'),
('PSA', 144, 3, 'PSA.144.3', 'O LORD, what is man, that You regard him, the son of man that You think of him?'),
('PSA', 144, 4, 'PSA.144.4', 'Man is like a breath; his days are like a passing shadow.'),
('PSA', 144, 5, 'PSA.144.5', 'Part Your heavens, O LORD, and come down; touch the mountains, that they may smoke.'),
('PSA', 144, 6, 'PSA.144.6', 'Flash forth Your lightning and scatter them; shoot Your arrows and rout them.'),
('PSA', 144, 7, 'PSA.144.7', 'Reach down from on high; set me free and rescue me from the deep waters, from the grasp of foreigners,'),
('PSA', 144, 8, 'PSA.144.8', 'whose mouths speak falsehood, whose right hands are deceitful.'),
('PSA', 144, 9, 'PSA.144.9', 'I will sing to You a new song, O God; on a harp of ten strings I will make music to You—'),
('PSA', 144, 10, 'PSA.144.10', 'to Him who gives victory to kings, who frees His servant David from the deadly sword.'),
('PSA', 144, 11, 'PSA.144.11', 'Set me free and rescue me from the grasp of foreigners, whose mouths speak falsehood, whose right hands are deceitful.'),
('PSA', 144, 12, 'PSA.144.12', 'Then our sons will be like plants nurtured in their youth, our daughters like corner pillars carved to adorn a palace.'),
('PSA', 144, 13, 'PSA.144.13', 'Our storehouses will be full, supplying all manner of produce; our flocks will bring forth thousands, tens of thousands in our fields.'),
('PSA', 144, 14, 'PSA.144.14', 'Our oxen will bear great loads. There will be no breach in the walls, no going into captivity, and no cry of lament in our streets.'),
('PSA', 144, 15, 'PSA.144.15', 'Blessed are the people of whom this is so; blessed are the people whose God is the LORD.'),
('PSA', 145, 1, 'PSA.145.1', 'A Psalm of praise. Of David. I will exalt You, my God and King; I will bless Your name forever and ever.'),
('PSA', 145, 2, 'PSA.145.2', 'Every day I will bless You, and I will praise Your name forever and ever.'),
('PSA', 145, 3, 'PSA.145.3', 'Great is the LORD and greatly to be praised; His greatness is unsearchable.'),
('PSA', 145, 4, 'PSA.145.4', 'One generation will commend Your works to the next, and will proclaim Your mighty acts—'),
('PSA', 145, 5, 'PSA.145.5', 'the glorious splendor of Your majesty. And I will meditate on Your wondrous works.'),
('PSA', 145, 6, 'PSA.145.6', 'They will proclaim the power of Your awesome deeds, and I will declare Your greatness.'),
('PSA', 145, 7, 'PSA.145.7', 'They will extol the fame of Your abundant goodness and sing joyfully of Your righteousness.'),
('PSA', 145, 8, 'PSA.145.8', 'The LORD is gracious and compassionate, slow to anger and abounding in loving devotion.'),
('PSA', 145, 9, 'PSA.145.9', 'The LORD is good to all; His compassion rests on all He has made.'),
('PSA', 145, 10, 'PSA.145.10', 'All You have made will give You thanks, O LORD, and Your saints will bless You.'),
('PSA', 145, 11, 'PSA.145.11', 'They will tell of the glory of Your kingdom and speak of Your might,'),
('PSA', 145, 12, 'PSA.145.12', 'to make known to men Your mighty acts and the glorious splendor of Your kingdom.'),
('PSA', 145, 13, 'PSA.145.13', 'Your kingdom is an everlasting kingdom, and Your dominion endures through all generations. The LORD is faithful in all His words and kind in all His actions.'),
('PSA', 145, 14, 'PSA.145.14', 'The LORD upholds all who fall and lifts up all who are bowed down.'),
('PSA', 145, 15, 'PSA.145.15', 'The eyes of all look to You, and You give them their food in season.'),
('PSA', 145, 16, 'PSA.145.16', 'You open Your hand and satisfy the desire of every living thing.'),
('PSA', 145, 17, 'PSA.145.17', 'The LORD is righteous in all His ways and kind in all His deeds.'),
('PSA', 145, 18, 'PSA.145.18', 'The LORD is near to all who call on Him, to all who call out to Him in truth.'),
('PSA', 145, 19, 'PSA.145.19', 'He fulfills the desires of those who fear Him; He hears their cry and saves them.'),
('PSA', 145, 20, 'PSA.145.20', 'The LORD preserves all who love Him, but all the wicked He will destroy.'),
('PSA', 145, 21, 'PSA.145.21', 'My mouth will declare the praise of the LORD; let every creature bless His holy name forever and ever.'),
('PSA', 146, 1, 'PSA.146.1', 'Hallelujah! Praise the LORD, O my soul.'),
('PSA', 146, 2, 'PSA.146.2', 'I will praise the LORD all my life; I will sing praises to my God while I have my being.'),
('PSA', 146, 3, 'PSA.146.3', 'Put not your trust in princes, in mortal man, who cannot save.'),
('PSA', 146, 4, 'PSA.146.4', 'When his spirit departs, he returns to the ground; on that very day his plans perish.'),
('PSA', 146, 5, 'PSA.146.5', 'Blessed is he whose help is the God of Jacob, whose hope is in the LORD his God,'),
('PSA', 146, 6, 'PSA.146.6', 'the Maker of heaven and earth, the sea, and everything in them. He remains faithful forever.'),
('PSA', 146, 7, 'PSA.146.7', 'He executes justice for the oppressed and gives food to the hungry. The LORD sets the prisoners free,'),
('PSA', 146, 8, 'PSA.146.8', 'the LORD opens the eyes of the blind, the LORD lifts those who are weighed down, the LORD loves the righteous.'),
('PSA', 146, 9, 'PSA.146.9', 'The LORD protects foreigners; He sustains the fatherless and the widow, but the ways of the wicked He frustrates.'),
('PSA', 146, 10, 'PSA.146.10', 'The LORD reigns forever, your God, O Zion, for all generations. Hallelujah!'),
('PSA', 147, 1, 'PSA.147.1', 'Hallelujah! How good it is to sing praises to our God, how pleasant and lovely to praise Him!'),
('PSA', 147, 2, 'PSA.147.2', 'The LORD builds up Jerusalem; He gathers the exiles of Israel.'),
('PSA', 147, 3, 'PSA.147.3', 'He heals the brokenhearted and binds up their wounds.'),
('PSA', 147, 4, 'PSA.147.4', 'He determines the number of the stars; He calls them each by name.'),
('PSA', 147, 5, 'PSA.147.5', 'Great is our Lord, and mighty in power; His understanding has no limit.'),
('PSA', 147, 6, 'PSA.147.6', 'The LORD sustains the humble, but casts the wicked to the ground.'),
('PSA', 147, 7, 'PSA.147.7', 'Sing to the LORD with thanksgiving; make music on the harp to our God,'),
('PSA', 147, 8, 'PSA.147.8', 'who covers the sky with clouds, who prepares rain for the earth, who makes grass to grow on the hills.'),
('PSA', 147, 9, 'PSA.147.9', 'He provides food for the animals, and for the young ravens when they call.'),
('PSA', 147, 10, 'PSA.147.10', 'He does not delight in the strength of the horse; He takes no pleasure in the legs of a man.'),
('PSA', 147, 11, 'PSA.147.11', 'The LORD is pleased with those who fear Him, who hope in His loving devotion.'),
('PSA', 147, 12, 'PSA.147.12', 'Exalt the LORD, O Jerusalem; praise your God, O Zion!'),
('PSA', 147, 13, 'PSA.147.13', 'For He strengthens the bars of your gates and blesses the children within you.'),
('PSA', 147, 14, 'PSA.147.14', 'He makes peace at your borders; He fills you with the finest wheat.'),
('PSA', 147, 15, 'PSA.147.15', 'He sends forth His command to the earth; His word runs swiftly.'),
('PSA', 147, 16, 'PSA.147.16', 'He spreads the snow like wool; He scatters the frost like ashes;'),
('PSA', 147, 17, 'PSA.147.17', 'He casts forth His hail like pebbles. Who can withstand His icy blast?'),
('PSA', 147, 18, 'PSA.147.18', 'He sends forth His word and melts them; He unleashes His winds, and the waters flow.'),
('PSA', 147, 19, 'PSA.147.19', 'He declares His word to Jacob, His statutes and judgments to Israel.'),
('PSA', 147, 20, 'PSA.147.20', 'He has done this for no other nation; they do not know His judgments. Hallelujah!'),
('PSA', 148, 1, 'PSA.148.1', 'Hallelujah! Praise the LORD from the heavens; praise Him in the highest places.'),
('PSA', 148, 2, 'PSA.148.2', 'Praise Him, all His angels; praise Him, all His heavenly hosts.'),
('PSA', 148, 3, 'PSA.148.3', 'Praise Him, O sun and moon; praise Him, all you shining stars.'),
('PSA', 148, 4, 'PSA.148.4', 'Praise Him, O highest heavens, and you waters above the skies.'),
('PSA', 148, 5, 'PSA.148.5', 'Let them praise the name of the LORD, for He gave the command and they were created.'),
('PSA', 148, 6, 'PSA.148.6', 'He established them forever and ever; He issued a decree that will never pass away.'),
('PSA', 148, 7, 'PSA.148.7', 'Praise the LORD from the earth, all great sea creatures and ocean depths,'),
('PSA', 148, 8, 'PSA.148.8', 'lightning and hail, snow and clouds, powerful wind fulfilling His word,'),
('PSA', 148, 9, 'PSA.148.9', 'mountains and all hills, fruit trees and all cedars,'),
('PSA', 148, 10, 'PSA.148.10', 'wild animals and all cattle, crawling creatures and flying birds,'),
('PSA', 148, 11, 'PSA.148.11', 'kings of the earth and all peoples, princes and all rulers of the earth,'),
('PSA', 148, 12, 'PSA.148.12', 'young men and maidens, old and young together.'),
('PSA', 148, 13, 'PSA.148.13', 'Let them praise the name of the LORD, for His name alone is exalted; His splendor is above the earth and the heavens.'),
('PSA', 148, 14, 'PSA.148.14', 'He has raised up a horn for His people, the praise of all His saints, of Israel, a people near to Him. Hallelujah!'),
('PSA', 149, 1, 'PSA.149.1', 'Hallelujah! Sing to the LORD a new song—His praise in the assembly of the godly.'),
('PSA', 149, 2, 'PSA.149.2', 'Let Israel rejoice in their Maker; let the children of Zion rejoice in their King.'),
('PSA', 149, 3, 'PSA.149.3', 'Let them praise His name with dancing, and make music to Him with tambourine and harp.'),
('PSA', 149, 4, 'PSA.149.4', 'For the LORD takes pleasure in His people; He adorns the afflicted with salvation.'),
('PSA', 149, 5, 'PSA.149.5', 'Let the saints exult in glory; let them shout for joy upon their beds.'),
('PSA', 149, 6, 'PSA.149.6', 'May the high praises of God be in their mouths, and a double-edged sword in their hands,'),
('PSA', 149, 7, 'PSA.149.7', 'to inflict vengeance on the nations and punishment on the peoples,'),
('PSA', 149, 8, 'PSA.149.8', 'to bind their kings with chains and their nobles with shackles of iron,'),
('PSA', 149, 9, 'PSA.149.9', 'to execute the judgment written against them. This honor is for all His saints. Hallelujah!'),
('PSA', 150, 1, 'PSA.150.1', 'Hallelujah! Praise God in His sanctuary. Praise Him in His mighty heavens.'),
('PSA', 150, 2, 'PSA.150.2', 'Praise Him for His mighty acts; praise Him for His excellent greatness.'),
('PSA', 150, 3, 'PSA.150.3', 'Praise Him with the sound of the horn; praise Him with the harp and lyre.'),
('PSA', 150, 4, 'PSA.150.4', 'Praise Him with tambourine and dancing; praise Him with strings and flute.'),
('PSA', 150, 5, 'PSA.150.5', 'Praise Him with clashing cymbals; praise Him with resounding cymbals.'),
('PSA', 150, 6, 'PSA.150.6', 'Let everything that has breath praise the LORD! Hallelujah!'),
('PRO', 1, 1, 'PRO.1.1', 'These are the proverbs of Solomon son of David, king of Israel,'),
('PRO', 1, 2, 'PRO.1.2', 'for gaining wisdom and discipline, for comprehending words of insight,'),
('PRO', 1, 3, 'PRO.1.3', 'and for receiving instruction in wise living and in righteousness, justice, and equity.'),
('PRO', 1, 4, 'PRO.1.4', 'To impart prudence to the simple and knowledge and discretion to the young,'),
('PRO', 1, 5, 'PRO.1.5', 'let the wise listen and gain instruction, and the discerning acquire wise counsel'),
('PRO', 1, 6, 'PRO.1.6', 'by understanding the proverbs and parables, the sayings and riddles of the wise.'),
('PRO', 1, 7, 'PRO.1.7', 'The fear of the LORD is the beginning of knowledge, but fools despise wisdom and discipline.'),
('PRO', 1, 8, 'PRO.1.8', 'Listen, my son, to your father’s instruction, and do not forsake the teaching of your mother.'),
('PRO', 1, 9, 'PRO.1.9', 'For they are a garland of grace on your head and a pendant around your neck.'),
('PRO', 1, 10, 'PRO.1.10', 'My son, if sinners entice you, do not yield to them.'),
('PRO', 1, 11, 'PRO.1.11', 'If they say, “Come along, let us lie in wait for blood, let us ambush the innocent without cause,'),
('PRO', 1, 12, 'PRO.1.12', 'let us swallow them alive like Sheol, and whole like those descending into the Pit.'),
('PRO', 1, 13, 'PRO.1.13', 'We will find all manner of precious goods; we will fill our houses with plunder.'),
('PRO', 1, 14, 'PRO.1.14', 'Throw in your lot with us; let us all share one purse”—'),
('PRO', 1, 15, 'PRO.1.15', 'my son, do not walk the road with them or set foot upon their path.'),
('PRO', 1, 16, 'PRO.1.16', 'For their feet run to evil, and they are swift to shed blood.'),
('PRO', 1, 17, 'PRO.1.17', 'How futile it is to spread the net where any bird can see it!'),
('PRO', 1, 18, 'PRO.1.18', 'But they lie in wait for their own blood; they ambush their own lives.'),
('PRO', 1, 19, 'PRO.1.19', 'Such is the fate of all who are greedy, whose unjust gain takes the lives of its possessors.'),
('PRO', 1, 20, 'PRO.1.20', 'Wisdom calls out in the street, she lifts her voice in the square;'),
('PRO', 1, 21, 'PRO.1.21', 'in the main concourse she cries aloud, at the city gates she makes her speech:'),
('PRO', 1, 22, 'PRO.1.22', '“How long, O simple ones, will you love your simple ways? How long will scoffers delight in their scorn and fools hate knowledge?'),
('PRO', 1, 23, 'PRO.1.23', 'If you had repented at my rebuke, then surely I would have poured out my spirit on you; I would have made my words known to you.'),
('PRO', 1, 24, 'PRO.1.24', 'Because you refused my call, and no one took my outstretched hand,'),
('PRO', 1, 25, 'PRO.1.25', 'because you neglected all my counsel, and wanted none of my correction,'),
('PRO', 1, 26, 'PRO.1.26', 'in turn I will mock your calamity; I will sneer when terror strikes you,'),
('PRO', 1, 27, 'PRO.1.27', 'when your dread comes like a storm, and your destruction like a whirlwind, when distress and anguish overwhelm you.'),
('PRO', 1, 28, 'PRO.1.28', 'Then they will call on me, but I will not answer; they will earnestly seek me, but will not find me.'),
('PRO', 1, 29, 'PRO.1.29', 'For they hated knowledge and chose not to fear the LORD.'),
('PRO', 1, 30, 'PRO.1.30', 'They accepted none of my counsel; they despised all my reproof.'),
('PRO', 1, 31, 'PRO.1.31', 'So they will eat the fruit of their own way, and be filled with their own devices.'),
('PRO', 1, 32, 'PRO.1.32', 'For the waywardness of the simple will slay them, and the complacency of fools will destroy them.'),
('PRO', 1, 33, 'PRO.1.33', 'But whoever listens to me will dwell in safety, secure from the fear of evil.”'),
('PRO', 2, 1, 'PRO.2.1', 'My son, if you accept my words and hide my commandments within you,'),
('PRO', 2, 2, 'PRO.2.2', 'if you incline your ear to wisdom and direct your heart to understanding,'),
('PRO', 2, 3, 'PRO.2.3', 'if you truly call out to insight and lift your voice to understanding,'),
('PRO', 2, 4, 'PRO.2.4', 'if you seek it like silver and search it out like hidden treasure,'),
('PRO', 2, 5, 'PRO.2.5', 'then you will discern the fear of the LORD and discover the knowledge of God.'),
('PRO', 2, 6, 'PRO.2.6', 'For the LORD gives wisdom; from His mouth come knowledge and understanding.'),
('PRO', 2, 7, 'PRO.2.7', 'He stores up sound wisdom for the upright; He is a shield to those who walk with integrity,'),
('PRO', 2, 8, 'PRO.2.8', 'to guard the paths of justice and protect the way of His saints.'),
('PRO', 2, 9, 'PRO.2.9', 'Then you will discern righteousness and justice and equity—every good path.'),
('PRO', 2, 10, 'PRO.2.10', 'For wisdom will enter your heart, and knowledge will delight your soul.'),
('PRO', 2, 11, 'PRO.2.11', 'Discretion will watch over you, and understanding will guard you,'),
('PRO', 2, 12, 'PRO.2.12', 'to deliver you from the way of evil, from the man who speaks perversity,'),
('PRO', 2, 13, 'PRO.2.13', 'from those who leave the straight paths to walk in the ways of darkness,'),
('PRO', 2, 14, 'PRO.2.14', 'from those who enjoy doing evil and rejoice in the twistedness of evil,'),
('PRO', 2, 15, 'PRO.2.15', 'whose paths are crooked and whose ways are devious.'),
('PRO', 2, 16, 'PRO.2.16', 'It will rescue you from the forbidden woman, from the stranger with seductive words'),
('PRO', 2, 17, 'PRO.2.17', 'who abandons the partner of her youth and forgets the covenant of her God.'),
('PRO', 2, 18, 'PRO.2.18', 'For her house sinks down to death, and her tracks to the departed spirits.'),
('PRO', 2, 19, 'PRO.2.19', 'None who go to her return or negotiate the paths of life.'),
('PRO', 2, 20, 'PRO.2.20', 'So you will follow in the ways of the good, and keep to the paths of the righteous.'),
('PRO', 2, 21, 'PRO.2.21', 'For the upright will inhabit the land, and the blameless will remain in it;'),
('PRO', 2, 22, 'PRO.2.22', 'but the wicked will be cut off from the land, and the unfaithful will be uprooted.'),
('PRO', 3, 1, 'PRO.3.1', 'My son, do not forget my teaching, but let your heart keep my commandments;'),
('PRO', 3, 2, 'PRO.3.2', 'for they will add length to your days, years and peace to your life.'),
('PRO', 3, 3, 'PRO.3.3', 'Never let loving devotion or faithfulness leave you; bind them around your neck, write them on the tablet of your heart.'),
('PRO', 3, 4, 'PRO.3.4', 'Then you will find favor and high regard in the sight of God and man.'),
('PRO', 3, 5, 'PRO.3.5', 'Trust in the LORD with all your heart, and lean not on your own understanding;'),
('PRO', 3, 6, 'PRO.3.6', 'in all your ways acknowledge Him, and He will make your paths straight.'),
('PRO', 3, 7, 'PRO.3.7', 'Be not wise in your own eyes; fear the LORD and turn away from evil.'),
('PRO', 3, 8, 'PRO.3.8', 'This will bring healing to your body and refreshment to your bones.'),
('PRO', 3, 9, 'PRO.3.9', 'Honor the LORD with your wealth and with the firstfruits of all your crops;'),
('PRO', 3, 10, 'PRO.3.10', 'then your barns will be filled with plenty, and your vats will overflow with new wine.'),
('PRO', 3, 11, 'PRO.3.11', 'My son, do not reject the discipline of the LORD, and do not loathe His rebuke;'),
('PRO', 3, 12, 'PRO.3.12', 'for the LORD disciplines the one He loves, as does a father the son in whom he delights.'),
('PRO', 3, 13, 'PRO.3.13', 'Blessed is the man who finds wisdom, the man who acquires understanding,'),
('PRO', 3, 14, 'PRO.3.14', 'for she is more profitable than silver, and her gain is better than fine gold.'),
('PRO', 3, 15, 'PRO.3.15', 'She is more precious than rubies; nothing you desire compares with her.'),
('PRO', 3, 16, 'PRO.3.16', 'Long life is in her right hand; in her left hand are riches and honor.'),
('PRO', 3, 17, 'PRO.3.17', 'All her ways are pleasant, and all her paths are peaceful.'),
('PRO', 3, 18, 'PRO.3.18', 'She is a tree of life to those who embrace her, and those who lay hold of her are blessed.'),
('PRO', 3, 19, 'PRO.3.19', 'The LORD founded the earth by wisdom and established the heavens by understanding.'),
('PRO', 3, 20, 'PRO.3.20', 'By His knowledge the watery depths were broken open, and the clouds dripped with dew.'),
('PRO', 3, 21, 'PRO.3.21', 'My son, do not lose sight of this: Preserve sound judgment and discernment.'),
('PRO', 3, 22, 'PRO.3.22', 'They will be life to your soul and adornment to your neck.'),
('PRO', 3, 23, 'PRO.3.23', 'Then you will go on your way in safety, and your foot will not stumble.'),
('PRO', 3, 24, 'PRO.3.24', 'When you lie down, you will not be afraid; when you rest, your sleep will be sweet.'),
('PRO', 3, 25, 'PRO.3.25', 'Do not fear sudden danger or the ruin that overtakes the wicked,'),
('PRO', 3, 26, 'PRO.3.26', 'for the LORD will be your confidence and will keep your foot from the snare.'),
('PRO', 3, 27, 'PRO.3.27', 'Do not withhold good from the deserving when it is within your power to act.'),
('PRO', 3, 28, 'PRO.3.28', 'Do not tell your neighbor, “Come back tomorrow and I will provide”—when you already have the means.'),
('PRO', 3, 29, 'PRO.3.29', 'Do not devise evil against your neighbor, for he trustfully dwells beside you.'),
('PRO', 3, 30, 'PRO.3.30', 'Do not accuse a man without cause, when he has done you no harm.'),
('PRO', 3, 31, 'PRO.3.31', 'Do not envy a violent man or choose any of his ways;'),
('PRO', 3, 32, 'PRO.3.32', 'for the LORD detests the perverse, but He is a friend to the upright.'),
('PRO', 3, 33, 'PRO.3.33', 'The curse of the LORD is on the house of the wicked, but He blesses the home of the righteous.'),
('PRO', 3, 34, 'PRO.3.34', 'He mocks the mockers, but gives grace to the humble.'),
('PRO', 3, 35, 'PRO.3.35', 'The wise will inherit honor, but fools are held up to shame.'),
('PRO', 4, 1, 'PRO.4.1', 'Listen, my sons, to a father’s instruction; pay attention and gain understanding.'),
('PRO', 4, 2, 'PRO.4.2', 'For I give you sound teaching; do not abandon my directive.'),
('PRO', 4, 3, 'PRO.4.3', 'When I was a son to my father, tender and the only child of my mother,'),
('PRO', 4, 4, 'PRO.4.4', 'he taught me and said, “Let your heart lay hold of my words; keep my commands and you will live.'),
('PRO', 4, 5, 'PRO.4.5', 'Get wisdom, get understanding; do not forget my words or turn from them.'),
('PRO', 4, 6, 'PRO.4.6', 'Do not forsake wisdom, and she will preserve you; love her, and she will guard you.'),
('PRO', 4, 7, 'PRO.4.7', 'Wisdom is supreme; so acquire wisdom. And whatever you may acquire, gain understanding.'),
('PRO', 4, 8, 'PRO.4.8', 'Prize her, and she will exalt you; if you embrace her, she will honor you.'),
('PRO', 4, 9, 'PRO.4.9', 'She will set a garland of grace on your head; she will present you with a crown of beauty.”'),
('PRO', 4, 10, 'PRO.4.10', 'Listen, my son, and receive my words, and the years of your life will be many.'),
('PRO', 4, 11, 'PRO.4.11', 'I will guide you in the way of wisdom; I will lead you on straight paths.'),
('PRO', 4, 12, 'PRO.4.12', 'When you walk, your steps will not be impeded; when you run, you will not stumble.'),
('PRO', 4, 13, 'PRO.4.13', 'Hold on to instruction; do not let go. Guard it, for it is your life.'),
('PRO', 4, 14, 'PRO.4.14', 'Do not set foot on the path of the wicked or walk in the way of evildoers.'),
('PRO', 4, 15, 'PRO.4.15', 'Avoid it; do not travel on it. Turn from it and pass on by.'),
('PRO', 4, 16, 'PRO.4.16', 'For they cannot sleep unless they do evil; they are deprived of slumber until they make someone fall.'),
('PRO', 4, 17, 'PRO.4.17', 'For they eat the bread of wickedness and drink the wine of violence.'),
('PRO', 4, 18, 'PRO.4.18', 'The path of the righteous is like the first gleam of dawn, shining brighter and brighter until midday.'),
('PRO', 4, 19, 'PRO.4.19', 'But the way of the wicked is like the darkest gloom; they do not know what makes them stumble.'),
('PRO', 4, 20, 'PRO.4.20', 'My son, pay attention to my words; incline your ear to my sayings.'),
('PRO', 4, 21, 'PRO.4.21', 'Do not lose sight of them; keep them within your heart.'),
('PRO', 4, 22, 'PRO.4.22', 'For they are life to those who find them, and health to the whole body.'),
('PRO', 4, 23, 'PRO.4.23', 'Guard your heart with all diligence, for from it flow springs of life.'),
('PRO', 4, 24, 'PRO.4.24', 'Put away deception from your mouth; keep your lips from perverse speech.'),
('PRO', 4, 25, 'PRO.4.25', 'Let your eyes look forward; fix your gaze straight ahead.'),
('PRO', 4, 26, 'PRO.4.26', 'Make a level path for your feet, and all your ways will be sure.'),
('PRO', 4, 27, 'PRO.4.27', 'Do not swerve to the right or to the left; turn your feet away from evil.'),
('PRO', 5, 1, 'PRO.5.1', 'My son, pay attention to my wisdom; incline your ear to my insight,'),
('PRO', 5, 2, 'PRO.5.2', 'that you may maintain discretion and your lips may preserve knowledge.'),
('PRO', 5, 3, 'PRO.5.3', 'Though the lips of the forbidden woman drip honey and her speech is smoother than oil,'),
('PRO', 5, 4, 'PRO.5.4', 'in the end she is bitter as wormwood, sharp as a double-edged sword.'),
('PRO', 5, 5, 'PRO.5.5', 'Her feet go down to death; her steps lead straight to Sheol.'),
('PRO', 5, 6, 'PRO.5.6', 'She does not consider the path of life; she does not know that her ways are unstable.'),
('PRO', 5, 7, 'PRO.5.7', 'So now, my sons, listen to me, and do not turn aside from the words of my mouth.'),
('PRO', 5, 8, 'PRO.5.8', 'Keep your path far from her; do not go near the door of her house,'),
('PRO', 5, 9, 'PRO.5.9', 'lest you concede your vigor to others, and your years to one who is cruel;'),
('PRO', 5, 10, 'PRO.5.10', 'lest strangers feast on your wealth, and your labors enrich the house of a foreigner.'),
('PRO', 5, 11, 'PRO.5.11', 'At the end of your life you will groan when your flesh and your body are spent,'),
('PRO', 5, 12, 'PRO.5.12', 'and you will say, “How I hated discipline, and my heart despised reproof!'),
('PRO', 5, 13, 'PRO.5.13', 'I did not listen to the voice of my teachers or incline my ear to my mentors.'),
('PRO', 5, 14, 'PRO.5.14', 'I am on the brink of utter ruin in the midst of the whole assembly.”'),
('PRO', 5, 15, 'PRO.5.15', 'Drink water from your own cistern, and running water from your own well.'),
('PRO', 5, 16, 'PRO.5.16', 'Why should your springs flow in the streets, your streams of water in the public squares?'),
('PRO', 5, 17, 'PRO.5.17', 'Let them be yours alone, never to be shared with strangers.'),
('PRO', 5, 18, 'PRO.5.18', 'May your fountain be blessed, and may you rejoice in the wife of your youth:'),
('PRO', 5, 19, 'PRO.5.19', 'A loving doe, a graceful fawn—may her breasts satisfy you always; may you be captivated by her love forever.'),
('PRO', 5, 20, 'PRO.5.20', 'Why be captivated, my son, by an adulteress, or embrace the bosom of a stranger?'),
('PRO', 5, 21, 'PRO.5.21', 'For a man’s ways are before the eyes of the LORD, and the LORD examines all his paths.'),
('PRO', 5, 22, 'PRO.5.22', 'The iniquities of a wicked man entrap him; the cords of his sin entangle him.'),
('PRO', 5, 23, 'PRO.5.23', 'He dies for lack of discipline, led astray by his own great folly.'),
('PRO', 6, 1, 'PRO.6.1', 'My son, if you have put up security for your neighbor, if you have struck hands in pledge with a stranger,'),
('PRO', 6, 2, 'PRO.6.2', 'if you have been trapped by the words of your lips, ensnared by the words of your mouth,'),
('PRO', 6, 3, 'PRO.6.3', 'then do this, my son, to free yourself, for you have fallen into your neighbor’s hands: Go, humble yourself, and press your plea with your neighbor.'),
('PRO', 6, 4, 'PRO.6.4', 'Allow no sleep to your eyes or slumber to your eyelids.'),
('PRO', 6, 5, 'PRO.6.5', 'Free yourself, like a gazelle from the hand of the hunter, like a bird from the snare of the fowler.'),
('PRO', 6, 6, 'PRO.6.6', 'Walk in the manner of the ant, O slacker; observe its ways and become wise.'),
('PRO', 6, 7, 'PRO.6.7', 'Without a commander, without an overseer or ruler,'),
('PRO', 6, 8, 'PRO.6.8', 'it prepares its provisions in summer; it gathers its food at harvest.'),
('PRO', 6, 9, 'PRO.6.9', 'How long will you lie there, O slacker? When will you get up from your sleep?'),
('PRO', 6, 10, 'PRO.6.10', 'A little sleep, a little slumber, a little folding of the hands to rest,'),
('PRO', 6, 11, 'PRO.6.11', 'and poverty will come upon you like a robber, and need like a bandit.'),
('PRO', 6, 12, 'PRO.6.12', 'A worthless person, a wicked man, walks with a perverse mouth,'),
('PRO', 6, 13, 'PRO.6.13', 'winking his eyes, speaking with his feet, and pointing with his fingers.'),
('PRO', 6, 14, 'PRO.6.14', 'With deceit in his heart he devises evil; he continually sows discord.'),
('PRO', 6, 15, 'PRO.6.15', 'Therefore calamity will come upon him suddenly; in an instant he will be shattered beyond recovery.'),
('PRO', 6, 16, 'PRO.6.16', 'There are six things that the LORD hates, seven that are detestable to Him:'),
('PRO', 6, 17, 'PRO.6.17', 'haughty eyes, a lying tongue, hands that shed innocent blood,'),
('PRO', 6, 18, 'PRO.6.18', 'a heart that devises wicked schemes, feet that run swiftly to evil,'),
('PRO', 6, 19, 'PRO.6.19', 'a false witness who gives false testimony, and one who stirs up discord among brothers.'),
('PRO', 6, 20, 'PRO.6.20', 'My son, keep your father’s commandment, and do not forsake your mother’s teaching.'),
('PRO', 6, 21, 'PRO.6.21', 'Bind them always upon your heart; tie them around your neck.'),
('PRO', 6, 22, 'PRO.6.22', 'When you walk, they will guide you; when you lie down, they will watch over you; when you awake, they will speak to you.'),
('PRO', 6, 23, 'PRO.6.23', 'For this commandment is a lamp, this teaching is a light, and the reproofs of discipline are the way to life,'),
('PRO', 6, 24, 'PRO.6.24', 'to keep you from the evil woman, from the smooth tongue of the adulteress.'),
('PRO', 6, 25, 'PRO.6.25', 'Do not lust in your heart for her beauty or let her captivate you with her eyes.'),
('PRO', 6, 26, 'PRO.6.26', 'For the levy of the prostitute is poverty, and the adulteress preys upon your very life.'),
('PRO', 6, 27, 'PRO.6.27', 'Can a man embrace fire and his clothes not be burned?'),
('PRO', 6, 28, 'PRO.6.28', 'Can a man walk on hot coals without scorching his feet?'),
('PRO', 6, 29, 'PRO.6.29', 'So is he who sleeps with another man’s wife; no one who touches her will go unpunished.'),
('PRO', 6, 30, 'PRO.6.30', 'Men do not despise the thief if he steals to satisfy his hunger.'),
('PRO', 6, 31, 'PRO.6.31', 'Yet if caught, he must pay sevenfold; he must give up all the wealth of his house.'),
('PRO', 6, 32, 'PRO.6.32', 'He who commits adultery lacks judgment; whoever does so destroys himself.'),
('PRO', 6, 33, 'PRO.6.33', 'Wounds and dishonor will befall him, and his reproach will never be wiped away.'),
('PRO', 6, 34, 'PRO.6.34', 'For jealousy enrages a husband, and he will show no mercy in the day of vengeance.'),
('PRO', 6, 35, 'PRO.6.35', 'He will not be appeased by any ransom, or persuaded by lavish gifts.'),
('PRO', 7, 1, 'PRO.7.1', 'My son, keep my words and treasure my commandments within you.'),
('PRO', 7, 2, 'PRO.7.2', 'Keep my commandments and live; guard my teachings as the apple of your eye.'),
('PRO', 7, 3, 'PRO.7.3', 'Tie them to your fingers; write them on the tablet of your heart.'),
('PRO', 7, 4, 'PRO.7.4', 'Say to wisdom, “You are my sister,” and call understanding your kinsman,'),
('PRO', 7, 5, 'PRO.7.5', 'that they may keep you from the adulteress, from the stranger with seductive words.'),
('PRO', 7, 6, 'PRO.7.6', 'For at the window of my house I looked through the lattice.'),
('PRO', 7, 7, 'PRO.7.7', 'I saw among the simple, I noticed among the youths, a young man lacking judgment,'),
('PRO', 7, 8, 'PRO.7.8', 'crossing the street near her corner, strolling down the road to her house,'),
('PRO', 7, 9, 'PRO.7.9', 'at twilight, as the day was fading into the dark of the night.'),
('PRO', 7, 10, 'PRO.7.10', 'Then a woman came out to meet him, with the attire of a harlot and cunning of heart.'),
('PRO', 7, 11, 'PRO.7.11', 'She is loud and defiant; her feet do not remain at home.'),
('PRO', 7, 12, 'PRO.7.12', 'Now in the street, now in the squares, she lurks at every corner.'),
('PRO', 7, 13, 'PRO.7.13', 'She seizes him and kisses him; she brazenly says to him:'),
('PRO', 7, 14, 'PRO.7.14', '“I have made my peace offerings; today I have paid my vows.'),
('PRO', 7, 15, 'PRO.7.15', 'So I came out to meet you; I sought you, and I have found you.'),
('PRO', 7, 16, 'PRO.7.16', 'I have decked my bed with coverings, with colored linen from Egypt.'),
('PRO', 7, 17, 'PRO.7.17', 'I have perfumed my bed with myrrh, with aloes, and with cinnamon.'),
('PRO', 7, 18, 'PRO.7.18', 'Come, let us take our fill of love till morning. Let us delight in loving caresses!'),
('PRO', 7, 19, 'PRO.7.19', 'For my husband is not at home; he has gone on a long journey.'),
('PRO', 7, 20, 'PRO.7.20', 'He took with him a bag of money and will not return till the moon is full.”'),
('PRO', 7, 21, 'PRO.7.21', 'With her great persuasion she entices him; with her flattering lips she lures him.'),
('PRO', 7, 22, 'PRO.7.22', 'He follows her on impulse, like an ox going to the slaughter, like a deer bounding into a trap,'),
('PRO', 7, 23, 'PRO.7.23', 'until an arrow pierces his liver, like a bird darting into a snare—not knowing it will cost him his life.'),
('PRO', 7, 24, 'PRO.7.24', 'Now, my sons, listen to me, and attend to the words of my mouth.'),
('PRO', 7, 25, 'PRO.7.25', 'Do not let your heart turn aside to her ways; do not stray into her paths.'),
('PRO', 7, 26, 'PRO.7.26', 'For she has brought many down to death; her slain are many in number.'),
('PRO', 7, 27, 'PRO.7.27', 'Her house is the road to Sheol, descending to the chambers of death.'),
('PRO', 8, 1, 'PRO.8.1', 'Does not wisdom call out, and understanding raise her voice?'),
('PRO', 8, 2, 'PRO.8.2', 'On the heights overlooking the road, at the crossroads she takes her stand.'),
('PRO', 8, 3, 'PRO.8.3', 'Beside the gates to the city, at the entrances she cries out:'),
('PRO', 8, 4, 'PRO.8.4', '“To you, O men, I call out, and my cry is to the sons of men.'),
('PRO', 8, 5, 'PRO.8.5', 'O simple ones, learn to be shrewd; O fools, gain understanding.'),
('PRO', 8, 6, 'PRO.8.6', 'Listen, for I speak of noble things, and the opening of my lips will reveal right.'),
('PRO', 8, 7, 'PRO.8.7', 'For my mouth will speak the truth, and wickedness is detestable to my lips.'),
('PRO', 8, 8, 'PRO.8.8', 'All the words of my mouth are righteous; none are crooked or perverse.'),
('PRO', 8, 9, 'PRO.8.9', 'They are all plain to the discerning, and upright to those who find knowledge.'),
('PRO', 8, 10, 'PRO.8.10', 'Receive my instruction instead of silver, and knowledge rather than pure gold.'),
('PRO', 8, 11, 'PRO.8.11', 'For wisdom is more precious than rubies, and nothing you desire compares with her.'),
('PRO', 8, 12, 'PRO.8.12', 'I, wisdom, dwell together with prudence, and I find knowledge and discretion.'),
('PRO', 8, 13, 'PRO.8.13', 'To fear the LORD is to hate evil; I hate arrogant pride, evil conduct, and perverse speech.'),
('PRO', 8, 14, 'PRO.8.14', 'Counsel and sound judgment are mine; I have insight and strength.'),
('PRO', 8, 15, 'PRO.8.15', 'By me kings reign, and rulers enact just laws;'),
('PRO', 8, 16, 'PRO.8.16', 'By me princes rule, and all nobles who govern justly.'),
('PRO', 8, 17, 'PRO.8.17', 'I love those who love me, and those who seek me early shall find me.'),
('PRO', 8, 18, 'PRO.8.18', 'With me are riches and honor, enduring wealth and righteousness.'),
('PRO', 8, 19, 'PRO.8.19', 'My fruit is better than gold, pure gold, and my harvest surpasses choice silver.'),
('PRO', 8, 20, 'PRO.8.20', 'I walk in the way of righteousness, along the paths of justice,'),
('PRO', 8, 21, 'PRO.8.21', 'bestowing wealth on those who love me and making their treasuries full.'),
('PRO', 8, 22, 'PRO.8.22', 'The LORD created me as His first course, before His works of old.'),
('PRO', 8, 23, 'PRO.8.23', 'From everlasting I was established, from the beginning, before the earth began.'),
('PRO', 8, 24, 'PRO.8.24', 'When there were no watery depths, I was brought forth, when no springs were overflowing with water.'),
('PRO', 8, 25, 'PRO.8.25', 'Before the mountains were settled, before the hills, I was brought forth,'),
('PRO', 8, 26, 'PRO.8.26', 'before He made the land or fields, or any of the dust of the earth.'),
('PRO', 8, 27, 'PRO.8.27', 'I was there when He established the heavens, when He inscribed a circle on the face of the deep,'),
('PRO', 8, 28, 'PRO.8.28', 'when He established the clouds above, when the fountains of the deep gushed forth,'),
('PRO', 8, 29, 'PRO.8.29', 'when He set a boundary for the sea, so that the waters would not surpass His command, when He marked out the foundations of the earth.'),
('PRO', 8, 30, 'PRO.8.30', 'Then I was a skilled craftsman at His side, and His delight day by day, rejoicing always in His presence.'),
('PRO', 8, 31, 'PRO.8.31', 'I was rejoicing in His whole world, delighting together in the sons of men.'),
('PRO', 8, 32, 'PRO.8.32', 'Now therefore, my sons, listen to me, for blessed are those who keep my ways.'),
('PRO', 8, 33, 'PRO.8.33', 'Listen to instruction and be wise; do not ignore it.'),
('PRO', 8, 34, 'PRO.8.34', 'Blessed is the man who listens to me, watching daily at my doors, waiting at the posts of my doorway.'),
('PRO', 8, 35, 'PRO.8.35', 'For whoever finds me finds life and obtains the favor of the LORD.'),
('PRO', 8, 36, 'PRO.8.36', 'But he who fails to find me harms himself; all who hate me love death.”'),
('PRO', 9, 1, 'PRO.9.1', 'Wisdom has built her house; she has carved out her seven pillars.'),
('PRO', 9, 2, 'PRO.9.2', 'She has prepared her meat and mixed her wine; she has also set her table.'),
('PRO', 9, 3, 'PRO.9.3', 'She has sent out her maidservants; she calls out from the heights of the city.'),
('PRO', 9, 4, 'PRO.9.4', '“Whoever is simple, let him turn in here!” she says to him who lacks judgment.'),
('PRO', 9, 5, 'PRO.9.5', '“Come, eat my bread and drink the wine I have mixed.'),
('PRO', 9, 6, 'PRO.9.6', 'Leave your folly behind, and you will live; walk in the way of understanding.”'),
('PRO', 9, 7, 'PRO.9.7', 'He who corrects a mocker brings shame on himself; he who rebukes a wicked man taints himself.'),
('PRO', 9, 8, 'PRO.9.8', 'Do not rebuke a mocker, or he will hate you; rebuke a wise man, and he will love you.'),
('PRO', 9, 9, 'PRO.9.9', 'Instruct a wise man, and he will be wiser still; teach a righteous man, and he will increase his learning.'),
('PRO', 9, 10, 'PRO.9.10', 'The fear of the LORD is the beginning of wisdom, and knowledge of the Holy One is understanding.'),
('PRO', 9, 11, 'PRO.9.11', 'For through wisdom your days will be multiplied, and years will be added to your life.'),
('PRO', 9, 12, 'PRO.9.12', 'If you are wise, you are wise to your own advantage; but if you scoff, you alone will bear the consequences.'),
('PRO', 9, 13, 'PRO.9.13', 'The woman named Folly is loud; she is naive and knows nothing.'),
('PRO', 9, 14, 'PRO.9.14', 'She sits at the door of her house, on a seat in the heights of the city,'),
('PRO', 9, 15, 'PRO.9.15', 'calling out to those who pass by, who make their paths straight.'),
('PRO', 9, 16, 'PRO.9.16', '“Whoever is simple, let him turn in here!” she says to him who lacks judgment.'),
('PRO', 9, 17, 'PRO.9.17', '“Stolen water is sweet, and bread eaten in secret is tasty!”'),
('PRO', 9, 18, 'PRO.9.18', 'But they do not know that the dead are there, that her guests are in the depths of Sheol.'),
('PRO', 10, 1, 'PRO.10.1', 'The proverbs of Solomon: A wise son brings joy to his father, but a foolish son grief to his mother.'),
('PRO', 10, 2, 'PRO.10.2', 'Ill-gotten treasures profit nothing, but righteousness brings deliverance from death.'),
('PRO', 10, 3, 'PRO.10.3', 'The LORD does not let the righteous go hungry, but He denies the craving of the wicked.'),
('PRO', 10, 4, 'PRO.10.4', 'Idle hands make one poor, but diligent hands bring wealth.'),
('PRO', 10, 5, 'PRO.10.5', 'He who gathers in summer is a wise son, but he who sleeps during harvest is a disgraceful son.'),
('PRO', 10, 6, 'PRO.10.6', 'Blessings are on the head of the righteous, but the mouth of the wicked conceals violence.'),
('PRO', 10, 7, 'PRO.10.7', 'The memory of the righteous is a blessing, but the name of the wicked will rot.'),
('PRO', 10, 8, 'PRO.10.8', 'A wise heart will receive commandments, but foolish lips will come to ruin.'),
('PRO', 10, 9, 'PRO.10.9', 'He who walks in integrity walks securely, but he who perverts his ways will be found out.'),
('PRO', 10, 10, 'PRO.10.10', 'He who winks the eye causes grief, and foolish lips will come to ruin.'),
('PRO', 10, 11, 'PRO.10.11', 'The mouth of the righteous is a fountain of life, but the mouth of the wicked conceals violence.'),
('PRO', 10, 12, 'PRO.10.12', 'Hatred stirs up dissension, but love covers all transgressions.'),
('PRO', 10, 13, 'PRO.10.13', 'Wisdom is found on the lips of the discerning, but a rod is for the back of him who lacks judgment.'),
('PRO', 10, 14, 'PRO.10.14', 'The wise store up knowledge, but the mouth of the fool invites destruction.'),
('PRO', 10, 15, 'PRO.10.15', 'The wealth of the rich man is his fortified city, but poverty is the ruin of the poor.'),
('PRO', 10, 16, 'PRO.10.16', 'The labor of the righteous leads to life, but the gain of the wicked brings punishment.'),
('PRO', 10, 17, 'PRO.10.17', 'Whoever heeds instruction is on the path to life, but he who ignores reproof goes astray.'),
('PRO', 10, 18, 'PRO.10.18', 'The one who conceals hatred has lying lips, and whoever spreads slander is a fool.'),
('PRO', 10, 19, 'PRO.10.19', 'When words are many, sin is unavoidable, but he who restrains his lips is wise.'),
('PRO', 10, 20, 'PRO.10.20', 'The tongue of the righteous is choice silver, but the heart of the wicked has little worth.'),
('PRO', 10, 21, 'PRO.10.21', 'The lips of the righteous feed many, but fools die for lack of judgment.'),
('PRO', 10, 22, 'PRO.10.22', 'The blessing of the LORD enriches, and He adds no sorrow to it.'),
('PRO', 10, 23, 'PRO.10.23', 'The fool delights in shameful conduct, but a man of understanding has wisdom.'),
('PRO', 10, 24, 'PRO.10.24', 'What the wicked man dreads will overtake him, but the desire of the righteous will be granted.'),
('PRO', 10, 25, 'PRO.10.25', 'When the whirlwind passes, the wicked are no more, but the righteous are secure forever.'),
('PRO', 10, 26, 'PRO.10.26', 'Like vinegar to the teeth and smoke to the eyes, so is the slacker to those who send him.'),
('PRO', 10, 27, 'PRO.10.27', 'The fear of the LORD prolongs life, but the years of the wicked will be cut short.'),
('PRO', 10, 28, 'PRO.10.28', 'The hope of the righteous is joy, but the expectations of the wicked will perish.'),
('PRO', 10, 29, 'PRO.10.29', 'The way of the LORD is a refuge to the upright, but destruction awaits those who do evil.'),
('PRO', 10, 30, 'PRO.10.30', 'The righteous will never be shaken, but the wicked will not inhabit the land.'),
('PRO', 10, 31, 'PRO.10.31', 'The mouth of the righteous brings forth wisdom, but a perverse tongue will be cut out.'),
('PRO', 10, 32, 'PRO.10.32', 'The lips of the righteous know what is fitting, but the mouth of the wicked is perverse.'),
('PRO', 11, 1, 'PRO.11.1', 'Dishonest scales are an abomination to the LORD, but an accurate weight is His delight.'),
('PRO', 11, 2, 'PRO.11.2', 'When pride comes, disgrace follows, but with humility comes wisdom.'),
('PRO', 11, 3, 'PRO.11.3', 'The integrity of the upright guides them, but the perversity of the faithless destroys them.'),
('PRO', 11, 4, 'PRO.11.4', 'Riches are worthless in the day of wrath, but righteousness brings deliverance from death.'),
('PRO', 11, 5, 'PRO.11.5', 'The righteousness of the blameless directs their path, but the wicked fall by their own wickedness.'),
('PRO', 11, 6, 'PRO.11.6', 'The righteousness of the upright delivers them, but the faithless are trapped by their own desires.'),
('PRO', 11, 7, 'PRO.11.7', 'When the wicked man dies, his hope perishes, and the hope of his strength vanishes.'),
('PRO', 11, 8, 'PRO.11.8', 'The righteous man is delivered from trouble; in his place the wicked man goes in.'),
('PRO', 11, 9, 'PRO.11.9', 'With his mouth the ungodly man destroys his neighbor, but through knowledge the righteous are rescued.'),
('PRO', 11, 10, 'PRO.11.10', 'When the righteous thrive, the city rejoices, and when the wicked perish, there are shouts of joy.'),
('PRO', 11, 11, 'PRO.11.11', 'By the blessing of the upright a city is built up, but by the mouth of the wicked it is torn down.'),
('PRO', 11, 12, 'PRO.11.12', 'Whoever shows contempt for his neighbor lacks judgment, but a man of understanding remains silent.'),
('PRO', 11, 13, 'PRO.11.13', 'A gossip reveals a secret, but a trustworthy person keeps a confidence.'),
('PRO', 11, 14, 'PRO.11.14', 'For lack of guidance, a nation falls, but with many counselors comes deliverance.'),
('PRO', 11, 15, 'PRO.11.15', 'He who puts up security for a stranger will surely suffer, but the one who hates indebtedness is secure.'),
('PRO', 11, 16, 'PRO.11.16', 'A gracious woman attains honor, but ruthless men gain only wealth.'),
('PRO', 11, 17, 'PRO.11.17', 'A kind man benefits himself, but a cruel man brings trouble on himself.'),
('PRO', 11, 18, 'PRO.11.18', 'The wicked man earns an empty wage, but he who sows righteousness reaps a true reward.'),
('PRO', 11, 19, 'PRO.11.19', 'Genuine righteousness leads to life, but the pursuit of evil brings death.'),
('PRO', 11, 20, 'PRO.11.20', 'The perverse in heart are an abomination to the LORD, but the blameless in their walk are His delight.'),
('PRO', 11, 21, 'PRO.11.21', 'Be assured that the wicked will not go unpunished, but the offspring of the righteous will escape.'),
('PRO', 11, 22, 'PRO.11.22', 'Like a gold ring in a pig’s snout is a beautiful woman who lacks discretion.'),
('PRO', 11, 23, 'PRO.11.23', 'The desire of the righteous leads only to good, but the hope of the wicked brings wrath.'),
('PRO', 11, 24, 'PRO.11.24', 'One gives freely, yet gains even more; another withholds what is right, only to become poor.'),
('PRO', 11, 25, 'PRO.11.25', 'A generous soul will prosper, and he who refreshes others will himself be refreshed.'),
('PRO', 11, 26, 'PRO.11.26', 'The people will curse the hoarder of grain, but blessing will crown the one who sells it.'),
('PRO', 11, 27, 'PRO.11.27', 'He who searches out good finds favor, but evil will come to him who seeks it.'),
('PRO', 11, 28, 'PRO.11.28', 'He who trusts in his riches will fall, but the righteous will thrive like foliage.'),
('PRO', 11, 29, 'PRO.11.29', 'He who brings trouble on his house will inherit the wind, and the fool will be servant to the wise of heart.'),
('PRO', 11, 30, 'PRO.11.30', 'The fruit of the righteous is a tree of life, and he who wins souls is wise.'),
('PRO', 11, 31, 'PRO.11.31', 'If the righteous receive their due on earth, how much more the ungodly and the sinner!'),
('PRO', 12, 1, 'PRO.12.1', 'Whoever loves discipline loves knowledge, but he who hates correction is stupid.'),
('PRO', 12, 2, 'PRO.12.2', 'The good man obtains favor from the LORD, but the LORD condemns a man who devises evil.'),
('PRO', 12, 3, 'PRO.12.3', 'A man cannot be established through wickedness, but the righteous cannot be uprooted.'),
('PRO', 12, 4, 'PRO.12.4', 'A wife of noble character is her husband’s crown, but she who causes shame is like decay in his bones.'),
('PRO', 12, 5, 'PRO.12.5', 'The plans of the righteous are just, but the counsel of the wicked leads to deceit.'),
('PRO', 12, 6, 'PRO.12.6', 'The words of the wicked lie in wait for blood, but the speech of the upright rescues them.'),
('PRO', 12, 7, 'PRO.12.7', 'The wicked are overthrown and perish, but the house of the righteous will stand.'),
('PRO', 12, 8, 'PRO.12.8', 'A man is praised according to his wisdom, but a twisted mind is despised.'),
('PRO', 12, 9, 'PRO.12.9', 'Better to be lightly esteemed yet have a servant, than to be self-important but lack food.'),
('PRO', 12, 10, 'PRO.12.10', 'A righteous man regards the life of his animal, but the tender mercies of the wicked are only cruelty.'),
('PRO', 12, 11, 'PRO.12.11', 'The one who works his land will have plenty of food, but whoever chases fantasies lacks judgment.'),
('PRO', 12, 12, 'PRO.12.12', 'The wicked desire the plunder of evil men, but the root of the righteous flourishes.'),
('PRO', 12, 13, 'PRO.12.13', 'An evil man is trapped by his rebellious speech, but a righteous man escapes from trouble.'),
('PRO', 12, 14, 'PRO.12.14', 'By fruitful speech a man is filled with good things, and the work of his hands returns to him.'),
('PRO', 12, 15, 'PRO.12.15', 'The way of a fool is right in his own eyes, but a wise man listens to counsel.'),
('PRO', 12, 16, 'PRO.12.16', 'A fool’s anger is known at once, but a prudent man overlooks an insult.'),
('PRO', 12, 17, 'PRO.12.17', 'He who speaks the truth declares what is right, but a false witness speaks deceit.'),
('PRO', 12, 18, 'PRO.12.18', 'Speaking rashly is like a piercing sword, but the tongue of the wise brings healing.'),
('PRO', 12, 19, 'PRO.12.19', 'Truthful lips endure forever, but a lying tongue lasts only a moment.'),
('PRO', 12, 20, 'PRO.12.20', 'Deceit is in the hearts of those who devise evil, but the counselors of peace have joy.'),
('PRO', 12, 21, 'PRO.12.21', 'No harm befalls the righteous, but the wicked are filled with trouble.'),
('PRO', 12, 22, 'PRO.12.22', 'Lying lips are detestable to the LORD, but those who deal faithfully are His delight.'),
('PRO', 12, 23, 'PRO.12.23', 'A shrewd man keeps his knowledge to himself, but a foolish heart proclaims its folly.'),
('PRO', 12, 24, 'PRO.12.24', 'The hand of the diligent will rule, but laziness ends in forced labor.'),
('PRO', 12, 25, 'PRO.12.25', 'Anxiety weighs down the heart of a man, but a good word cheers it up.'),
('PRO', 12, 26, 'PRO.12.26', 'A righteous man is cautious in friendship, but the ways of the wicked lead them astray.'),
('PRO', 12, 27, 'PRO.12.27', 'A lazy man does not roast his game, but a diligent man prizes his possession.'),
('PRO', 12, 28, 'PRO.12.28', 'There is life in the path of righteousness, but another path leads to death.'),
('PRO', 13, 1, 'PRO.13.1', 'A wise son heeds his father’s discipline, but a mocker does not listen to rebuke.'),
('PRO', 13, 2, 'PRO.13.2', 'From the fruit of his lips a man enjoys good things, but the desire of the faithless is violence.'),
('PRO', 13, 3, 'PRO.13.3', 'He who guards his mouth protects his life, but the one who opens his lips invites his own ruin.'),
('PRO', 13, 4, 'PRO.13.4', 'The slacker craves yet has nothing, but the soul of the diligent is fully satisfied.'),
('PRO', 13, 5, 'PRO.13.5', 'The righteous hate falsehood, but the wicked bring shame and disgrace.'),
('PRO', 13, 6, 'PRO.13.6', 'Righteousness guards the man of integrity, but wickedness undermines the sinner.'),
('PRO', 13, 7, 'PRO.13.7', 'One pretends to be rich, but has nothing; another pretends to be poor, yet has great wealth.'),
('PRO', 13, 8, 'PRO.13.8', 'Riches may ransom a man’s life, but a poor man hears no threat.'),
('PRO', 13, 9, 'PRO.13.9', 'The light of the righteous shines brightly, but the lamp of the wicked is extinguished.'),
('PRO', 13, 10, 'PRO.13.10', 'Arrogance leads only to strife, but wisdom is with the well-advised.'),
('PRO', 13, 11, 'PRO.13.11', 'Dishonest wealth will dwindle, but what is earned through hard work will be multiplied.'),
('PRO', 13, 12, 'PRO.13.12', 'Hope deferred makes the heart sick, but desire fulfilled is a tree of life.'),
('PRO', 13, 13, 'PRO.13.13', 'He who despises instruction will pay the penalty, but the one who respects a command will be rewarded.'),
('PRO', 13, 14, 'PRO.13.14', 'The teaching of the wise is a fountain of life, turning one from the snares of death.'),
('PRO', 13, 15, 'PRO.13.15', 'Good understanding wins favor, but the way of the faithless is difficult.'),
('PRO', 13, 16, 'PRO.13.16', 'Every prudent man acts with knowledge, but a fool displays his folly.'),
('PRO', 13, 17, 'PRO.13.17', 'A wicked messenger falls into trouble, but a faithful envoy brings healing.'),
('PRO', 13, 18, 'PRO.13.18', 'Poverty and shame come to him who ignores discipline, but whoever heeds correction is honored.'),
('PRO', 13, 19, 'PRO.13.19', 'Desire fulfilled is sweet to the soul, but turning from evil is detestable to fools.'),
('PRO', 13, 20, 'PRO.13.20', 'He who walks with the wise will become wise, but the companion of fools will be destroyed.'),
('PRO', 13, 21, 'PRO.13.21', 'Disaster pursues sinners, but prosperity is the reward of the righteous.'),
('PRO', 13, 22, 'PRO.13.22', 'A good man leaves an inheritance to his children’s children, but the sinner’s wealth is passed to the righteous.'),
('PRO', 13, 23, 'PRO.13.23', 'Abundant food is in the fallow ground of the poor, but without justice it is swept away.'),
('PRO', 13, 24, 'PRO.13.24', 'He who spares the rod hates his son, but he who loves him disciplines him diligently.'),
('PRO', 13, 25, 'PRO.13.25', 'A righteous man eats to his heart’s content, but the stomach of the wicked is empty.'),
('PRO', 14, 1, 'PRO.14.1', 'Every wise woman builds her house, but a foolish one tears it down with her own hands.'),
('PRO', 14, 2, 'PRO.14.2', 'He who walks in uprightness fears the LORD, but the one who is devious in his ways despises Him.'),
('PRO', 14, 3, 'PRO.14.3', 'The proud speech of a fool brings a rod to his back, but the lips of the wise protect them.'),
('PRO', 14, 4, 'PRO.14.4', 'Where there are no oxen, the manger is empty, but an abundant harvest comes through the strength of the ox.'),
('PRO', 14, 5, 'PRO.14.5', 'An honest witness does not deceive, but a dishonest witness pours forth lies.'),
('PRO', 14, 6, 'PRO.14.6', 'A mocker seeks wisdom and finds none, but knowledge comes easily to the discerning.'),
('PRO', 14, 7, 'PRO.14.7', 'Stay away from a foolish man; you will gain no knowledge from his speech.'),
('PRO', 14, 8, 'PRO.14.8', 'The wisdom of the prudent is to discern his way, but the folly of fools deceives them.'),
('PRO', 14, 9, 'PRO.14.9', 'Fools mock the making of amends, but goodwill is found among the upright.'),
('PRO', 14, 10, 'PRO.14.10', 'The heart knows its own bitterness, and no stranger shares in its joy.'),
('PRO', 14, 11, 'PRO.14.11', 'The house of the wicked will be destroyed, but the tent of the upright will flourish.'),
('PRO', 14, 12, 'PRO.14.12', 'There is a way that seems right to a man, but its end is the way of death.'),
('PRO', 14, 13, 'PRO.14.13', 'Even in laughter the heart may ache, and joy may end in sorrow.'),
('PRO', 14, 14, 'PRO.14.14', 'The backslider in heart receives the fill of his own ways, but a good man is rewarded for his ways.'),
('PRO', 14, 15, 'PRO.14.15', 'The simple man believes every word, but the prudent man watches his steps.'),
('PRO', 14, 16, 'PRO.14.16', 'A wise man fears and turns from evil, but a fool is careless and reckless.'),
('PRO', 14, 17, 'PRO.14.17', 'A quick-tempered man acts foolishly, and a devious man is hated.'),
('PRO', 14, 18, 'PRO.14.18', 'The simple inherit folly, but the prudent are crowned with knowledge.'),
('PRO', 14, 19, 'PRO.14.19', 'The evil bow before the good, and the wicked at the gates of the righteous.'),
('PRO', 14, 20, 'PRO.14.20', 'The poor man is hated even by his neighbor, but many are those who love the rich.'),
('PRO', 14, 21, 'PRO.14.21', 'He who despises his neighbor sins, but blessed is he who shows kindness to the poor.'),
('PRO', 14, 22, 'PRO.14.22', 'Do not those who contrive evil go astray? But those who plan goodness find loving devotion and faithfulness.'),
('PRO', 14, 23, 'PRO.14.23', 'There is profit in all labor, but mere talk leads only to poverty.'),
('PRO', 14, 24, 'PRO.14.24', 'The crown of the wise is their wealth, but the effort of fools is folly.'),
('PRO', 14, 25, 'PRO.14.25', 'A truthful witness saves lives, but one who utters lies is deceitful.'),
('PRO', 14, 26, 'PRO.14.26', 'He who fears the LORD is secure in confidence, and his children shall have a place of refuge.'),
('PRO', 14, 27, 'PRO.14.27', 'The fear of the LORD is a fountain of life, turning a man from the snares of death.'),
('PRO', 14, 28, 'PRO.14.28', 'A large population is a king’s splendor, but a lack of subjects is a prince’s ruin.'),
('PRO', 14, 29, 'PRO.14.29', 'A patient man has great understanding, but a quick-tempered man promotes folly.'),
('PRO', 14, 30, 'PRO.14.30', 'A tranquil heart is life to the body, but envy rots the bones.'),
('PRO', 14, 31, 'PRO.14.31', 'Whoever oppresses the poor taunts their Maker, but whoever is kind to the needy honors Him.'),
('PRO', 14, 32, 'PRO.14.32', 'The wicked man is thrown down by his own sin, but the righteous man has a refuge even in death.'),
('PRO', 14, 33, 'PRO.14.33', 'Wisdom rests in the heart of the discerning; even among fools she is known.'),
('PRO', 14, 34, 'PRO.14.34', 'Righteousness exalts a nation, but sin is a disgrace to any people.'),
('PRO', 14, 35, 'PRO.14.35', 'A king delights in a wise servant, but his anger falls on the shameful.'),
('PRO', 15, 1, 'PRO.15.1', 'A gentle answer turns away wrath, but a harsh word stirs up anger.'),
('PRO', 15, 2, 'PRO.15.2', 'The tongue of the wise commends knowledge, but the mouth of the fool spouts folly.'),
('PRO', 15, 3, 'PRO.15.3', 'The eyes of the LORD are in every place, observing the evil and the good.'),
('PRO', 15, 4, 'PRO.15.4', 'A soothing tongue is a tree of life, but a perverse tongue crushes the spirit.'),
('PRO', 15, 5, 'PRO.15.5', 'A fool rejects his father’s discipline, but whoever heeds correction is prudent.'),
('PRO', 15, 6, 'PRO.15.6', 'The house of the righteous has great treasure, but the income of the wicked is trouble.'),
('PRO', 15, 7, 'PRO.15.7', 'The lips of the wise spread knowledge, but not so the hearts of fools.'),
('PRO', 15, 8, 'PRO.15.8', 'The sacrifice of the wicked is detestable to the LORD, but the prayer of the upright is His delight.'),
('PRO', 15, 9, 'PRO.15.9', 'The LORD detests the way of the wicked, but He loves those who pursue righteousness.'),
('PRO', 15, 10, 'PRO.15.10', 'Discipline is harsh for him who leaves the path; he who hates correction will die.'),
('PRO', 15, 11, 'PRO.15.11', 'Sheol and Abaddon lie open before the LORD—how much more the hearts of men!'),
('PRO', 15, 12, 'PRO.15.12', 'A mocker does not love to be reproved, nor will he consult the wise.'),
('PRO', 15, 13, 'PRO.15.13', 'A joyful heart makes a cheerful countenance, but sorrow of the heart crushes the spirit.'),
('PRO', 15, 14, 'PRO.15.14', 'A discerning heart seeks knowledge, but the mouth of a fool feeds on folly.'),
('PRO', 15, 15, 'PRO.15.15', 'All the days of the oppressed are bad, but a cheerful heart has a continual feast.'),
('PRO', 15, 16, 'PRO.15.16', 'Better a little with the fear of the LORD than great treasure with turmoil.'),
('PRO', 15, 17, 'PRO.15.17', 'Better a dish of vegetables where there is love than a fattened ox with hatred.'),
('PRO', 15, 18, 'PRO.15.18', 'A hot-tempered man stirs up strife, but he who is slow to anger calms dispute.'),
('PRO', 15, 19, 'PRO.15.19', 'The way of the slacker is like a hedge of thorns, but the path of the upright is a highway.'),
('PRO', 15, 20, 'PRO.15.20', 'A wise son brings joy to his father, but a foolish man despises his mother.'),
('PRO', 15, 21, 'PRO.15.21', 'Folly is joy to one who lacks judgment, but a man of understanding walks a straight path.'),
('PRO', 15, 22, 'PRO.15.22', 'Plans fail for lack of counsel, but with many advisers they succeed.'),
('PRO', 15, 23, 'PRO.15.23', 'A man takes joy in a fitting reply—and how good is a timely word!'),
('PRO', 15, 24, 'PRO.15.24', 'The path of life leads upward for the wise, that he may avoid going down to Sheol.'),
('PRO', 15, 25, 'PRO.15.25', 'The LORD tears down the house of the proud, but He protects the boundaries of the widow.'),
('PRO', 15, 26, 'PRO.15.26', 'The LORD detests the thoughts of the wicked, but the words of the pure are pleasant to Him.'),
('PRO', 15, 27, 'PRO.15.27', 'He who is greedy for unjust gain brings trouble on his household, but he who hates bribes will live.'),
('PRO', 15, 28, 'PRO.15.28', 'The heart of the righteous ponders how to answer, but the mouth of the wicked blurts out evil.'),
('PRO', 15, 29, 'PRO.15.29', 'The LORD is far from the wicked, but He hears the prayer of the righteous.'),
('PRO', 15, 30, 'PRO.15.30', 'The light of the eyes cheers the heart, and good news nourishes the bones.'),
('PRO', 15, 31, 'PRO.15.31', 'He who listens to life-giving reproof will dwell among the wise.'),
('PRO', 15, 32, 'PRO.15.32', 'He who ignores discipline despises himself, but whoever heeds correction gains understanding.'),
('PRO', 15, 33, 'PRO.15.33', 'The fear of the LORD is the instruction of wisdom, and humility comes before honor.'),
('PRO', 16, 1, 'PRO.16.1', 'The plans of the heart belong to man, but the reply of the tongue is from the LORD.'),
('PRO', 16, 2, 'PRO.16.2', 'All a man’s ways are pure in his own eyes, but his motives are weighed out by the LORD.'),
('PRO', 16, 3, 'PRO.16.3', 'Commit your works to the LORD and your plans will be achieved.'),
('PRO', 16, 4, 'PRO.16.4', 'The LORD has made everything for His purpose—even the wicked for the day of disaster.'),
('PRO', 16, 5, 'PRO.16.5', 'Everyone who is proud in heart is detestable to the LORD; be assured that he will not go unpunished.'),
('PRO', 16, 6, 'PRO.16.6', 'By loving devotion and faithfulness iniquity is atoned for, and by the fear of the LORD one turns aside from evil.'),
('PRO', 16, 7, 'PRO.16.7', 'When a man’s ways please the LORD, He makes even the man’s enemies live at peace with him.'),
('PRO', 16, 8, 'PRO.16.8', 'Better a little with righteousness than great gain with injustice.'),
('PRO', 16, 9, 'PRO.16.9', 'A man’s heart plans his course, but the LORD determines his steps.'),
('PRO', 16, 10, 'PRO.16.10', 'A divine verdict is on the lips of a king; his mouth must not betray justice.'),
('PRO', 16, 11, 'PRO.16.11', 'Honest scales and balances are from the LORD; all the weights in the bag are His concern.'),
('PRO', 16, 12, 'PRO.16.12', 'Wicked behavior is detestable for kings, for a throne is established through righteousness.'),
('PRO', 16, 13, 'PRO.16.13', 'Righteous lips are a king’s delight, and he who speaks honestly is beloved.'),
('PRO', 16, 14, 'PRO.16.14', 'The wrath of a king is a messenger of death, but a wise man will pacify it.'),
('PRO', 16, 15, 'PRO.16.15', 'When a king’s face brightens, there is life; his favor is like a rain cloud in spring.'),
('PRO', 16, 16, 'PRO.16.16', 'How much better to acquire wisdom than gold! To gain understanding is more desirable than silver.'),
('PRO', 16, 17, 'PRO.16.17', 'The highway of the upright leads away from evil; he who guards his way protects his life.'),
('PRO', 16, 18, 'PRO.16.18', 'Pride goes before destruction, and a haughty spirit before a fall.'),
('PRO', 16, 19, 'PRO.16.19', 'It is better to be lowly in spirit among the humble than to divide the spoil with the proud.'),
('PRO', 16, 20, 'PRO.16.20', 'Whoever heeds instruction will find success, and blessed is he who trusts in the LORD.'),
('PRO', 16, 21, 'PRO.16.21', 'The wise in heart are called discerning, and pleasant speech promotes instruction.'),
('PRO', 16, 22, 'PRO.16.22', 'Understanding is a fountain of life to its possessor, but the discipline of fools is folly.'),
('PRO', 16, 23, 'PRO.16.23', 'The heart of the wise man instructs his mouth and adds persuasiveness to his lips.'),
('PRO', 16, 24, 'PRO.16.24', 'Pleasant words are a honeycomb, sweet to the soul and healing to the bones.'),
('PRO', 16, 25, 'PRO.16.25', 'There is a way that seems right to a man, but its end is the way of death.'),
('PRO', 16, 26, 'PRO.16.26', 'A worker’s appetite works for him because his hunger drives him onward.'),
('PRO', 16, 27, 'PRO.16.27', 'A worthless man digs up evil, and his speech is like a scorching fire.'),
('PRO', 16, 28, 'PRO.16.28', 'A perverse man spreads dissension, and a gossip divides close friends.'),
('PRO', 16, 29, 'PRO.16.29', 'A violent man entices his neighbor and leads him down a path that is not good.'),
('PRO', 16, 30, 'PRO.16.30', 'He who winks his eye devises perversity; he who purses his lips is bent on evil.'),
('PRO', 16, 31, 'PRO.16.31', 'Gray hair is a crown of glory; it is attained along the path of righteousness.'),
('PRO', 16, 32, 'PRO.16.32', 'He who is slow to anger is better than a warrior, and he who controls his temper is greater than one who captures a city.'),
('PRO', 16, 33, 'PRO.16.33', 'The lot is cast into the lap, but its every decision is from the LORD.'),
('PRO', 17, 1, 'PRO.17.1', 'Better a dry morsel in quietness than a house full of feasting with strife.'),
('PRO', 17, 2, 'PRO.17.2', 'A wise servant will rule over a disgraceful son and share his inheritance as one of the brothers.'),
('PRO', 17, 3, 'PRO.17.3', 'A crucible for silver and a furnace for gold, but the LORD is the tester of hearts.'),
('PRO', 17, 4, 'PRO.17.4', 'A wicked man listens to evil lips; a liar gives ear to a destructive tongue.'),
('PRO', 17, 5, 'PRO.17.5', 'He who mocks the poor insults their Maker; whoever gloats over calamity will not go unpunished.'),
('PRO', 17, 6, 'PRO.17.6', 'Grandchildren are the crown of the aged, and the glory of a son is his father.'),
('PRO', 17, 7, 'PRO.17.7', 'Eloquent words are unfit for a fool; how much worse are lying lips to a ruler!'),
('PRO', 17, 8, 'PRO.17.8', 'A bribe is a charm to its giver; wherever he turns, he succeeds.'),
('PRO', 17, 9, 'PRO.17.9', 'Whoever conceals an offense promotes love, but he who brings it up separates friends.'),
('PRO', 17, 10, 'PRO.17.10', 'A rebuke cuts into a man of discernment deeper than a hundred lashes cut into a fool.'),
('PRO', 17, 11, 'PRO.17.11', 'An evil man seeks only rebellion; a cruel messenger will be sent against him.'),
('PRO', 17, 12, 'PRO.17.12', 'It is better to meet a bear robbed of her cubs than a fool in his folly.'),
('PRO', 17, 13, 'PRO.17.13', 'If anyone returns evil for good, evil will never leave his house.'),
('PRO', 17, 14, 'PRO.17.14', 'To start a quarrel is to release a flood; so abandon the dispute before it breaks out.'),
('PRO', 17, 15, 'PRO.17.15', 'Acquitting the guilty and condemning the righteous—both are detestable to the LORD.'),
('PRO', 17, 16, 'PRO.17.16', 'Why should the fool have money in his hand with no intention of buying wisdom?'),
('PRO', 17, 17, 'PRO.17.17', 'A friend loves at all times, and a brother is born for adversity.'),
('PRO', 17, 18, 'PRO.17.18', 'A man lacking judgment strikes hands in pledge and puts up security for his neighbor.'),
('PRO', 17, 19, 'PRO.17.19', 'He who loves transgression loves strife; he who builds his gate high invites destruction.'),
('PRO', 17, 20, 'PRO.17.20', 'The one with a perverse heart finds no good, and he whose tongue is deceitful falls into trouble.'),
('PRO', 17, 21, 'PRO.17.21', 'A man fathers a fool to his own grief; the father of a fool has no joy.'),
('PRO', 17, 22, 'PRO.17.22', 'A joyful heart is good medicine, but a broken spirit dries up the bones.'),
('PRO', 17, 23, 'PRO.17.23', 'A wicked man takes a covert bribe to subvert the course of justice.'),
('PRO', 17, 24, 'PRO.17.24', 'Wisdom is the focus of the discerning, but the eyes of a fool wander to the ends of the earth.'),
('PRO', 17, 25, 'PRO.17.25', 'A foolish son brings grief to his father and bitterness to her who bore him.'),
('PRO', 17, 26, 'PRO.17.26', 'It is surely not good to punish the innocent or to flog a noble for his honesty.'),
('PRO', 17, 27, 'PRO.17.27', 'A man of knowledge restrains his words, and a man of understanding maintains a calm spirit.'),
('PRO', 17, 28, 'PRO.17.28', 'Even a fool is considered wise if he keeps silent, and discerning when he holds his tongue.'),
('PRO', 18, 1, 'PRO.18.1', 'He who isolates himself pursues selfish desires; he rebels against all sound judgment.'),
('PRO', 18, 2, 'PRO.18.2', 'A fool does not delight in understanding, but only in airing his opinions.'),
('PRO', 18, 3, 'PRO.18.3', 'With a wicked man comes contempt as well, and shame is accompanied by disgrace.'),
('PRO', 18, 4, 'PRO.18.4', 'The words of a man’s mouth are deep waters; the fountain of wisdom is a bubbling brook.'),
('PRO', 18, 5, 'PRO.18.5', 'Showing partiality to the wicked is not good, nor is depriving the innocent of justice.'),
('PRO', 18, 6, 'PRO.18.6', 'A fool’s lips bring him strife, and his mouth invites a beating.'),
('PRO', 18, 7, 'PRO.18.7', 'A fool’s mouth is his ruin, and his lips are a snare to his soul.'),
('PRO', 18, 8, 'PRO.18.8', 'The words of a gossip are like choice morsels that go down into the inmost being.'),
('PRO', 18, 9, 'PRO.18.9', 'Whoever is slothful in his work is brother to him who destroys.'),
('PRO', 18, 10, 'PRO.18.10', 'The name of the LORD is a strong tower; the righteous run to it and are safe.'),
('PRO', 18, 11, 'PRO.18.11', 'A rich man’s wealth is his fortified city; it is like a high wall in his imagination.'),
('PRO', 18, 12, 'PRO.18.12', 'Before his downfall a man’s heart is proud, but humility comes before honor.'),
('PRO', 18, 13, 'PRO.18.13', 'He who answers a matter before he hears it—this is folly and disgrace to him.'),
('PRO', 18, 14, 'PRO.18.14', 'The spirit of a man can endure his sickness, but who can survive a broken spirit?'),
('PRO', 18, 15, 'PRO.18.15', 'The heart of the discerning acquires knowledge, and the ear of the wise seeks it out.'),
('PRO', 18, 16, 'PRO.18.16', 'A man’s gift opens doors for him, and brings him before great men.'),
('PRO', 18, 17, 'PRO.18.17', 'The first to state his case seems right until another comes and cross-examines him.'),
('PRO', 18, 18, 'PRO.18.18', 'Casting the lot ends quarrels and separates strong opponents.'),
('PRO', 18, 19, 'PRO.18.19', 'An offended brother is harder to win than a fortified city, and disputes are like the bars of a castle.'),
('PRO', 18, 20, 'PRO.18.20', 'From the fruit of his mouth a man’s belly is filled; with the harvest from his lips he is satisfied.'),
('PRO', 18, 21, 'PRO.18.21', 'Life and death are in the power of the tongue, and those who love it will eat its fruit.'),
('PRO', 18, 22, 'PRO.18.22', 'He who finds a wife finds a good thing and obtains favor from the LORD.'),
('PRO', 18, 23, 'PRO.18.23', 'The poor man pleads for mercy, but the rich man answers harshly.'),
('PRO', 18, 24, 'PRO.18.24', 'A man of many companions may come to ruin, but there is a friend who stays closer than a brother.'),
('PRO', 19, 1, 'PRO.19.1', 'Better a poor man who walks with integrity than a fool whose lips are perverse.'),
('PRO', 19, 2, 'PRO.19.2', 'Even zeal is no good without knowledge, and he who hurries his footsteps misses the mark.'),
('PRO', 19, 3, 'PRO.19.3', 'A man’s own folly subverts his way, yet his heart rages against the LORD.'),
('PRO', 19, 4, 'PRO.19.4', 'Wealth attracts many friends, but a poor man is deserted by his friend.'),
('PRO', 19, 5, 'PRO.19.5', 'A false witness will not go unpunished, and one who utters lies will not escape.'),
('PRO', 19, 6, 'PRO.19.6', 'Many seek the favor of the prince, and everyone is a friend of the gift giver.'),
('PRO', 19, 7, 'PRO.19.7', 'All the brothers of a poor man hate him—how much more do his friends avoid him! He may pursue them with pleading, but they are nowhere to be found.'),
('PRO', 19, 8, 'PRO.19.8', 'He who acquires wisdom loves himself; one who safeguards understanding will find success.'),
('PRO', 19, 9, 'PRO.19.9', 'A false witness will not go unpunished, and one who pours out lies will perish.'),
('PRO', 19, 10, 'PRO.19.10', 'Luxury is unseemly for a fool—how much worse for a slave to rule over princes!'),
('PRO', 19, 11, 'PRO.19.11', 'A man’s insight gives him patience, and his virtue is to overlook an offense.'),
('PRO', 19, 12, 'PRO.19.12', 'A king’s rage is like the roar of a lion, but his favor is like dew on the grass.'),
('PRO', 19, 13, 'PRO.19.13', 'A foolish son is his father’s ruin, and a quarrelsome wife is like a constant dripping.'),
('PRO', 19, 14, 'PRO.19.14', 'Houses and wealth are inherited from fathers, but a prudent wife is from the LORD.'),
('PRO', 19, 15, 'PRO.19.15', 'Laziness brings on deep sleep, and an idle soul will suffer hunger.'),
('PRO', 19, 16, 'PRO.19.16', 'He who keeps a commandment preserves his soul, but he who is careless in his ways will die.'),
('PRO', 19, 17, 'PRO.19.17', 'Kindness to the poor is a loan to the LORD, and He will repay the lender.'),
('PRO', 19, 18, 'PRO.19.18', 'Discipline your son, for in that there is hope; do not be party to his death.'),
('PRO', 19, 19, 'PRO.19.19', 'A man of great anger must pay the penalty; if you rescue him, you will have to do so again.'),
('PRO', 19, 20, 'PRO.19.20', 'Listen to counsel and accept discipline, that you may be wise the rest of your days.'),
('PRO', 19, 21, 'PRO.19.21', 'Many plans are in a man’s heart, but the purpose of the LORD will prevail.'),
('PRO', 19, 22, 'PRO.19.22', 'The desire of a man is loving devotion; better to be poor than a liar.'),
('PRO', 19, 23, 'PRO.19.23', 'The fear of the LORD leads to life, that one may rest content, without visitation from harm.'),
('PRO', 19, 24, 'PRO.19.24', 'The slacker buries his hand in the dish; he will not even bring it back to his mouth.'),
('PRO', 19, 25, 'PRO.19.25', 'Strike a mocker, and the simple will beware; rebuke the discerning man, and he will gain knowledge.'),
('PRO', 19, 26, 'PRO.19.26', 'He who assaults his father or evicts his mother is a son who brings shame and disgrace.'),
('PRO', 19, 27, 'PRO.19.27', 'If you cease to hear instruction, my son, you will stray from the words of knowledge.'),
('PRO', 19, 28, 'PRO.19.28', 'A corrupt witness mocks justice, and a wicked mouth swallows iniquity.'),
('PRO', 19, 29, 'PRO.19.29', 'Judgments are prepared for mockers, and beatings for the backs of fools.'),
('PRO', 20, 1, 'PRO.20.1', 'Wine is a mocker, strong drink is a brawler, and whoever is led astray by them is not wise.'),
('PRO', 20, 2, 'PRO.20.2', 'The terror of a king is like the roar of a lion; whoever provokes him forfeits his own life.'),
('PRO', 20, 3, 'PRO.20.3', 'It is honorable for a man to resolve a dispute, but any fool will quarrel.'),
('PRO', 20, 4, 'PRO.20.4', 'The slacker does not plow in season; at harvest time he looks, but nothing is there.'),
('PRO', 20, 5, 'PRO.20.5', 'The intentions of a man’s heart are deep waters, but a man of understanding draws them out.'),
('PRO', 20, 6, 'PRO.20.6', 'Many a man proclaims his loving devotion, but who can find a trustworthy man?'),
('PRO', 20, 7, 'PRO.20.7', 'The righteous man walks with integrity; blessed are his children after him.'),
('PRO', 20, 8, 'PRO.20.8', 'A king who sits on a throne to judge sifts out all evil with his eyes.'),
('PRO', 20, 9, 'PRO.20.9', 'Who can say, “I have kept my heart pure; I am cleansed from my sin”?'),
('PRO', 20, 10, 'PRO.20.10', 'Differing weights and unequal measures—both are detestable to the LORD.'),
('PRO', 20, 11, 'PRO.20.11', 'Even a young man is known by his actions—whether his conduct is pure and upright.'),
('PRO', 20, 12, 'PRO.20.12', 'Ears that hear and eyes that see—the LORD has made them both.'),
('PRO', 20, 13, 'PRO.20.13', 'Do not love sleep, or you will grow poor; open your eyes, and you will have plenty of food.'),
('PRO', 20, 14, 'PRO.20.14', '“Worthless, worthless!” says the buyer, but on the way out, he gloats.'),
('PRO', 20, 15, 'PRO.20.15', 'There is an abundance of gold and rubies, but lips of knowledge are a rare treasure.'),
('PRO', 20, 16, 'PRO.20.16', 'Take the garment of the one who posts security for a stranger; get collateral if it is for a foreigner.'),
('PRO', 20, 17, 'PRO.20.17', 'Food gained by fraud is sweet to a man, but later his mouth is full of gravel.'),
('PRO', 20, 18, 'PRO.20.18', 'Set plans by consultation, and wage war under sound guidance.'),
('PRO', 20, 19, 'PRO.20.19', 'He who reveals secrets is a constant gossip; avoid the one who babbles with his lips.'),
('PRO', 20, 20, 'PRO.20.20', 'Whoever curses his father or mother, his lamp will be extinguished in deepest darkness.'),
('PRO', 20, 21, 'PRO.20.21', 'An inheritance gained quickly will not be blessed in the end.'),
('PRO', 20, 22, 'PRO.20.22', 'Do not say, “I will avenge this evil!” Wait on the LORD, and He will save you.'),
('PRO', 20, 23, 'PRO.20.23', 'Unequal weights are detestable to the LORD, and dishonest scales are no good.'),
('PRO', 20, 24, 'PRO.20.24', 'A man’s steps are from the LORD, so how can anyone understand his own way?'),
('PRO', 20, 25, 'PRO.20.25', 'It is a trap for a man to dedicate something rashly, only later to reconsider his vows.'),
('PRO', 20, 26, 'PRO.20.26', 'A wise king separates out the wicked and drives the threshing wheel over them.'),
('PRO', 20, 27, 'PRO.20.27', 'The spirit of a man is the lamp of the LORD, searching out his inmost being.'),
('PRO', 20, 28, 'PRO.20.28', 'Loving devotion and faithfulness preserve a king; by these he maintains his throne.'),
('PRO', 20, 29, 'PRO.20.29', 'The glory of young men is their strength, and gray hair is the splendor of the old.'),
('PRO', 20, 30, 'PRO.20.30', 'Lashes and wounds scour evil, and beatings cleanse the inmost parts.'),
('PRO', 21, 1, 'PRO.21.1', 'The king’s heart is a waterway in the hand of the LORD; He directs it where He pleases.'),
('PRO', 21, 2, 'PRO.21.2', 'All a man’s ways seem right to him, but the LORD weighs the heart.'),
('PRO', 21, 3, 'PRO.21.3', 'To do righteousness and justice is more desirable to the LORD than sacrifice.'),
('PRO', 21, 4, 'PRO.21.4', 'Haughty eyes and a proud heart—the guides of the wicked—are sin.'),
('PRO', 21, 5, 'PRO.21.5', 'The plans of the diligent bring plenty, as surely as haste leads to poverty.'),
('PRO', 21, 6, 'PRO.21.6', 'Making a fortune by a lying tongue is a vanishing mist, a deadly pursuit.'),
('PRO', 21, 7, 'PRO.21.7', 'The violence of the wicked will sweep them away because they refuse to do what is just.'),
('PRO', 21, 8, 'PRO.21.8', 'The way of a guilty man is crooked, but the conduct of the innocent is upright.'),
('PRO', 21, 9, 'PRO.21.9', 'Better to live on a corner of the roof than to share a house with a quarrelsome wife.'),
('PRO', 21, 10, 'PRO.21.10', 'The soul of the wicked man craves evil; his neighbor finds no favor in his eyes.'),
('PRO', 21, 11, 'PRO.21.11', 'When a mocker is punished, the simple gain wisdom; and when a wise man is instructed, he acquires knowledge.'),
('PRO', 21, 12, 'PRO.21.12', 'The Righteous One considers the house of the wicked and brings the wicked to ruin.'),
('PRO', 21, 13, 'PRO.21.13', 'Whoever shuts his ears to the cry of the poor, he too shall cry out and receive no answer.'),
('PRO', 21, 14, 'PRO.21.14', 'A gift in secret soothes anger, and a covert bribe pacifies great wrath.'),
('PRO', 21, 15, 'PRO.21.15', 'Justice executed is a joy to the righteous, but a terror to the workers of iniquity.'),
('PRO', 21, 16, 'PRO.21.16', 'The man who strays from the path of understanding will rest in the assembly of the dead.'),
('PRO', 21, 17, 'PRO.21.17', 'He who loves pleasure will become poor; the one who loves wine and oil will never be rich.'),
('PRO', 21, 18, 'PRO.21.18', 'The wicked become a ransom for the righteous, and the faithless for the upright.'),
('PRO', 21, 19, 'PRO.21.19', 'Better to live in the desert than with a contentious and ill-tempered wife.'),
('PRO', 21, 20, 'PRO.21.20', 'Precious treasures and oil are in the dwelling of the wise, but a foolish man consumes them.'),
('PRO', 21, 21, 'PRO.21.21', 'He who pursues righteousness and loving devotion finds life, righteousness, and honor.'),
('PRO', 21, 22, 'PRO.21.22', 'A wise man scales the city of the mighty and pulls down the stronghold in which they trust.'),
('PRO', 21, 23, 'PRO.21.23', 'He who guards his mouth and tongue keeps his soul from distress.'),
('PRO', 21, 24, 'PRO.21.24', 'Mocker is the name of the proud and arrogant man—of him who acts with excessive pride.'),
('PRO', 21, 25, 'PRO.21.25', 'The craving of the slacker kills him because his hands refuse to work.'),
('PRO', 21, 26, 'PRO.21.26', 'All day long he covets more, but the righteous give without restraint.'),
('PRO', 21, 27, 'PRO.21.27', 'The sacrifice of the wicked is detestable—how much more so when brought with ill intent!'),
('PRO', 21, 28, 'PRO.21.28', 'A lying witness will perish, but the man who listens to truth will speak forever.'),
('PRO', 21, 29, 'PRO.21.29', 'A wicked man hardens his face, but the upright man makes his way sure.'),
('PRO', 21, 30, 'PRO.21.30', 'There is no wisdom, no understanding, no counsel that can prevail against the LORD.'),
('PRO', 21, 31, 'PRO.21.31', 'A horse is prepared for the day of battle, but victory is of the LORD.'),
('PRO', 22, 1, 'PRO.22.1', 'A good name is more desirable than great riches; favor is better than silver and gold.'),
('PRO', 22, 2, 'PRO.22.2', 'The rich and the poor have this in common: The LORD is Maker of them all.'),
('PRO', 22, 3, 'PRO.22.3', 'The prudent see danger and take cover, but the simple keep going and suffer the consequences.'),
('PRO', 22, 4, 'PRO.22.4', 'The rewards of humility and the fear of the LORD are wealth and honor and life.'),
('PRO', 22, 5, 'PRO.22.5', 'Thorns and snares lie on the path of the perverse; he who guards his soul stays far from them.'),
('PRO', 22, 6, 'PRO.22.6', 'Train up a child in the way he should go, and when he is old he will not depart from it.'),
('PRO', 22, 7, 'PRO.22.7', 'The rich rule over the poor, and the borrower is slave to the lender.'),
('PRO', 22, 8, 'PRO.22.8', 'He who sows injustice will reap disaster, and the rod of his fury will be destroyed.'),
('PRO', 22, 9, 'PRO.22.9', 'A generous man will be blessed, for he shares his bread with the poor.'),
('PRO', 22, 10, 'PRO.22.10', 'Drive out the mocker, and conflict will depart; even quarreling and insults will cease.'),
('PRO', 22, 11, 'PRO.22.11', 'He who loves a pure heart and gracious lips will have the king for a friend.'),
('PRO', 22, 12, 'PRO.22.12', 'The LORD’s eyes keep watch over knowledge, but He frustrates the words of the faithless.'),
('PRO', 22, 13, 'PRO.22.13', 'The slacker says, “There is a lion outside! I will be slain in the streets!”'),
('PRO', 22, 14, 'PRO.22.14', 'The mouth of an adulteress is a deep pit; he who is under the wrath of the LORD will fall into it.'),
('PRO', 22, 15, 'PRO.22.15', 'Foolishness is bound up in the heart of a child, but the rod of discipline drives it far from him.'),
('PRO', 22, 16, 'PRO.22.16', 'Oppressing the poor to enrich oneself or giving gifts to the rich will surely lead to poverty.'),
('PRO', 22, 17, 'PRO.22.17', 'Incline your ear and hear the words of the wise—apply your mind to my knowledge—'),
('PRO', 22, 18, 'PRO.22.18', 'for it is pleasing when you keep them within you and they are constantly on your lips.'),
('PRO', 22, 19, 'PRO.22.19', 'So that your trust may be in the LORD, I instruct you today—yes, you.'),
('PRO', 22, 20, 'PRO.22.20', 'Have I not written for you thirty sayings about counsel and knowledge,'),
('PRO', 22, 21, 'PRO.22.21', 'to show you true and reliable words, that you may soundly answer those who sent you?'),
('PRO', 22, 22, 'PRO.22.22', 'Do not rob a poor man because he is poor, and do not crush the afflicted at the gate,'),
('PRO', 22, 23, 'PRO.22.23', 'for the LORD will take up their case and will plunder those who rob them.'),
('PRO', 22, 24, 'PRO.22.24', 'Do not make friends with an angry man, and do not associate with a hot-tempered man,'),
('PRO', 22, 25, 'PRO.22.25', 'or you may learn his ways and entangle yourself in a snare.'),
('PRO', 22, 26, 'PRO.22.26', 'Do not be one who gives pledges, who puts up security for debts.'),
('PRO', 22, 27, 'PRO.22.27', 'If you have nothing with which to pay, why should your bed be taken from under you?'),
('PRO', 22, 28, 'PRO.22.28', 'Do not move an ancient boundary stone which your fathers have placed.'),
('PRO', 22, 29, 'PRO.22.29', 'Do you see a man skilled in his work? He will be stationed in the presence of kings; he will not stand before obscure men.'),
('PRO', 23, 1, 'PRO.23.1', 'When you sit down to dine with a ruler, consider carefully what is set before you,'),
('PRO', 23, 2, 'PRO.23.2', 'and put a knife to your throat if you possess a great appetite.'),
('PRO', 23, 3, 'PRO.23.3', 'Do not crave his delicacies, for that food is deceptive.'),
('PRO', 23, 4, 'PRO.23.4', 'Do not wear yourself out to get rich; be wise enough to restrain yourself.'),
('PRO', 23, 5, 'PRO.23.5', 'When you glance at wealth, it disappears, for it makes wings for itself and flies like an eagle to the sky.'),
('PRO', 23, 6, 'PRO.23.6', 'Do not eat the bread of a stingy man, and do not crave his delicacies;'),
('PRO', 23, 7, 'PRO.23.7', 'for he is keeping track, inwardly counting the cost. “Eat and drink,” he says to you, but his heart is not with you.'),
('PRO', 23, 8, 'PRO.23.8', 'You will vomit up what little you have eaten and waste your pleasant words.'),
('PRO', 23, 9, 'PRO.23.9', 'Do not speak to a fool, for he will despise the wisdom of your words.'),
('PRO', 23, 10, 'PRO.23.10', 'Do not move an ancient boundary stone or encroach on the fields of the fatherless,'),
('PRO', 23, 11, 'PRO.23.11', 'for their Redeemer is strong; He will take up their case against you.'),
('PRO', 23, 12, 'PRO.23.12', 'Apply your heart to instruction and your ears to words of knowledge.'),
('PRO', 23, 13, 'PRO.23.13', 'Do not withhold discipline from a child; although you strike him with a rod, he will not die.'),
('PRO', 23, 14, 'PRO.23.14', 'Strike him with a rod, and you will deliver his soul from Sheol.'),
('PRO', 23, 15, 'PRO.23.15', 'My son, if your heart is wise, my own heart will indeed rejoice.'),
('PRO', 23, 16, 'PRO.23.16', 'My inmost being will rejoice when your lips speak what is right.'),
('PRO', 23, 17, 'PRO.23.17', 'Do not let your heart envy sinners, but always continue in the fear of the LORD.'),
('PRO', 23, 18, 'PRO.23.18', 'For surely there is a future, and your hope will not be cut off.'),
('PRO', 23, 19, 'PRO.23.19', 'Listen, my son, and be wise, and guide your heart on the right course.'),
('PRO', 23, 20, 'PRO.23.20', 'Do not join those who drink too much wine or gorge themselves on meat.'),
('PRO', 23, 21, 'PRO.23.21', 'For the drunkard and the glutton will come to poverty, and drowsiness will clothe them in rags.'),
('PRO', 23, 22, 'PRO.23.22', 'Listen to your father who gave you life, and do not despise your mother when she is old.'),
('PRO', 23, 23, 'PRO.23.23', 'Invest in truth and never sell it—in wisdom and instruction and understanding.'),
('PRO', 23, 24, 'PRO.23.24', 'The father of a righteous man will greatly rejoice, and he who fathers a wise son will delight in him.'),
('PRO', 23, 25, 'PRO.23.25', 'May your father and mother be glad, and may she who gave you birth rejoice!'),
('PRO', 23, 26, 'PRO.23.26', 'My son, give me your heart, and let your eyes delight in my ways.'),
('PRO', 23, 27, 'PRO.23.27', 'For a prostitute is a deep pit, and an adulteress is a narrow well.'),
('PRO', 23, 28, 'PRO.23.28', 'Like a robber she lies in wait and multiplies the faithless among men.'),
('PRO', 23, 29, 'PRO.23.29', 'Who has woe? Who has sorrow? Who has contentions? Who has complaints? Who has needless wounds? Who has bloodshot eyes?'),
('PRO', 23, 30, 'PRO.23.30', 'Those who linger over wine, who go to taste mixed drinks.'),
('PRO', 23, 31, 'PRO.23.31', 'Do not gaze at wine while it is red, when it sparkles in the cup and goes down smoothly.'),
('PRO', 23, 32, 'PRO.23.32', 'In the end it bites like a snake and stings like a viper.'),
('PRO', 23, 33, 'PRO.23.33', 'Your eyes will see strange things, and your mind will utter perversities.'),
('PRO', 23, 34, 'PRO.23.34', 'You will be like one sleeping on the high seas or lying on the top of a mast:'),
('PRO', 23, 35, 'PRO.23.35', '“They struck me, but I feel no pain! They beat me, but I did not know it! When can I wake up to search for another drink?”'),
('PRO', 24, 1, 'PRO.24.1', 'Do not envy wicked men or desire their company;'),
('PRO', 24, 2, 'PRO.24.2', 'for their hearts devise violence, and their lips declare trouble.'),
('PRO', 24, 3, 'PRO.24.3', 'By wisdom a house is built and by understanding it is established;'),
('PRO', 24, 4, 'PRO.24.4', 'through knowledge its rooms are filled with every precious and beautiful treasure.'),
('PRO', 24, 5, 'PRO.24.5', 'A wise man is strong, and a man of knowledge enhances his strength.'),
('PRO', 24, 6, 'PRO.24.6', 'Only with sound guidance should you wage war, and victory lies in a multitude of counselors.'),
('PRO', 24, 7, 'PRO.24.7', 'Wisdom is too high for a fool; he does not open his mouth in the meeting place.'),
('PRO', 24, 8, 'PRO.24.8', 'He who plots evil will be called a schemer.'),
('PRO', 24, 9, 'PRO.24.9', 'A foolish scheme is sin, and a mocker is detestable to men.'),
('PRO', 24, 10, 'PRO.24.10', 'If you faint in the day of distress, how small is your strength!'),
('PRO', 24, 11, 'PRO.24.11', 'Rescue those being led away to death, and restrain those stumbling toward the slaughter.'),
('PRO', 24, 12, 'PRO.24.12', 'If you say, “Behold, we did not know about this,” does not He who weighs hearts consider it? Does not the One who guards your life know? Will He not repay a man according to his deeds?'),
('PRO', 24, 13, 'PRO.24.13', 'Eat honey, my son, for it is good, and the honeycomb is sweet to your taste.'),
('PRO', 24, 14, 'PRO.24.14', 'Know therefore that wisdom is sweet to your soul. If you find it, there is a future for you, and your hope will never be cut off.'),
('PRO', 24, 15, 'PRO.24.15', 'Do not lie in wait, O wicked man, near the dwelling of the righteous; do not destroy his resting place.'),
('PRO', 24, 16, 'PRO.24.16', 'For though a righteous man may fall seven times, he still gets up; but the wicked stumble in bad times.'),
('PRO', 24, 17, 'PRO.24.17', 'Do not gloat when your enemy falls, and do not let your heart rejoice when he stumbles,'),
('PRO', 24, 18, 'PRO.24.18', 'or the LORD will see and disapprove, and turn His wrath away from him.'),
('PRO', 24, 19, 'PRO.24.19', 'Do not fret over evildoers, and do not be envious of the wicked.'),
('PRO', 24, 20, 'PRO.24.20', 'For the evil man has no future; the lamp of the wicked will be extinguished.'),
('PRO', 24, 21, 'PRO.24.21', 'My son, fear the LORD and the king, and do not associate with the rebellious.'),
('PRO', 24, 22, 'PRO.24.22', 'For they will bring sudden destruction. Who knows what ruin they can bring?'),
('PRO', 24, 23, 'PRO.24.23', 'These also are sayings of the wise: To show partiality in judgment is not good.'),
('PRO', 24, 24, 'PRO.24.24', 'Whoever tells the guilty, “You are innocent”—peoples will curse him, and nations will denounce him;'),
('PRO', 24, 25, 'PRO.24.25', 'but it will go well with those who convict the guilty, and rich blessing will come upon them.'),
('PRO', 24, 26, 'PRO.24.26', 'An honest answer given is like a kiss on the lips.'),
('PRO', 24, 27, 'PRO.24.27', 'Complete your outdoor work and prepare your field; after that, you may build your house.'),
('PRO', 24, 28, 'PRO.24.28', 'Do not testify against your neighbor without cause, and do not deceive with your lips.'),
('PRO', 24, 29, 'PRO.24.29', 'Do not say, “I will do to him as he has done to me; I will repay the man according to his work.”'),
('PRO', 24, 30, 'PRO.24.30', 'I went past the field of a slacker and by the vineyard of a man lacking judgment.'),
('PRO', 24, 31, 'PRO.24.31', 'Thorns had grown up everywhere, thistles had covered the ground, and the stone wall was broken down.'),
('PRO', 24, 32, 'PRO.24.32', 'I observed and took it to heart; I looked and received instruction:'),
('PRO', 24, 33, 'PRO.24.33', 'A little sleep, a little slumber, a little folding of the hands to rest,'),
('PRO', 24, 34, 'PRO.24.34', 'and poverty will come upon you like a robber, and need like a bandit.'),
('PRO', 25, 1, 'PRO.25.1', 'These are additional proverbs of Solomon, which were copied by the men of Hezekiah king of Judah:'),
('PRO', 25, 2, 'PRO.25.2', 'It is the glory of God to conceal a matter and the glory of kings to search it out.'),
('PRO', 25, 3, 'PRO.25.3', 'As the heavens are high and the earth is deep, so the hearts of kings cannot be searched.'),
('PRO', 25, 4, 'PRO.25.4', 'Remove the dross from the silver, and a vessel for a silversmith will come forth.'),
('PRO', 25, 5, 'PRO.25.5', 'Remove the wicked from the king’s presence, and his throne will be established in righteousness.'),
('PRO', 25, 6, 'PRO.25.6', 'Do not exalt yourself in the presence of the king, and do not stand in the place of great men;'),
('PRO', 25, 7, 'PRO.25.7', 'for it is better to be told, “Come up here!” than to be demoted in the presence of the prince. Even what you have seen with your own eyes,'),
('PRO', 25, 8, 'PRO.25.8', 'do not bring hastily to court. Otherwise, what will you do in the end when your neighbor puts you to shame?'),
('PRO', 25, 9, 'PRO.25.9', 'Argue your case with your neighbor without betraying another’s confidence,'),
('PRO', 25, 10, 'PRO.25.10', 'lest he who hears you bring shame upon you, and your infamy never go away.'),
('PRO', 25, 11, 'PRO.25.11', 'A word fitly spoken is like apples of gold in settings of silver.'),
('PRO', 25, 12, 'PRO.25.12', 'Like an earring of gold or an ornament of fine gold is a wise man’s rebuke to a listening ear.'),
('PRO', 25, 13, 'PRO.25.13', 'Like the cold of snow in the time of harvest is a trustworthy messenger to those who send him; he refreshes the soul of his masters.'),
('PRO', 25, 14, 'PRO.25.14', 'Like clouds and wind without rain is the man who boasts of gifts never given.'),
('PRO', 25, 15, 'PRO.25.15', 'Through patience a ruler can be persuaded, and a gentle tongue can break a bone.'),
('PRO', 25, 16, 'PRO.25.16', 'If you find honey, eat just what you need, lest you have too much and vomit it up.'),
('PRO', 25, 17, 'PRO.25.17', 'Seldom set foot in your neighbor’s house, lest he grow weary and hate you.'),
('PRO', 25, 18, 'PRO.25.18', 'Like a club or sword or sharp arrow is a man who bears false witness against his neighbor.'),
('PRO', 25, 19, 'PRO.25.19', 'Like a broken tooth or a foot out of joint is confidence in a faithless man in time of trouble.'),
('PRO', 25, 20, 'PRO.25.20', 'Like one who removes a garment on a cold day or vinegar poured on a wound is one who sings songs to a heavy heart.'),
('PRO', 25, 21, 'PRO.25.21', 'If your enemy is hungry, give him food to eat, and if he is thirsty, give him water to drink.'),
('PRO', 25, 22, 'PRO.25.22', 'For in so doing, you will heap burning coals on his head, and the LORD will reward you.'),
('PRO', 25, 23, 'PRO.25.23', 'As the north wind brings forth rain, so a backbiting tongue brings angry looks.'),
('PRO', 25, 24, 'PRO.25.24', 'Better to live on a corner of the roof than to share a house with a quarrelsome wife.'),
('PRO', 25, 25, 'PRO.25.25', 'Like cold water to a weary soul is good news from a distant land.'),
('PRO', 25, 26, 'PRO.25.26', 'Like a muddied spring or a polluted well is a righteous man who gives way to the wicked.'),
('PRO', 25, 27, 'PRO.25.27', 'It is not good to eat too much honey or to search out one’s own glory.'),
('PRO', 25, 28, 'PRO.25.28', 'Like a city whose walls are broken down is a man who does not control his temper.'),
('PRO', 26, 1, 'PRO.26.1', 'Like snow in summer and rain at harvest, honor does not befit a fool.'),
('PRO', 26, 2, 'PRO.26.2', 'Like a fluttering sparrow or darting swallow, an undeserved curse does not come to rest.'),
('PRO', 26, 3, 'PRO.26.3', 'A whip for the horse, a bridle for the donkey, and a rod for the backs of fools!'),
('PRO', 26, 4, 'PRO.26.4', 'Do not answer a fool according to his folly, or you yourself will be like him.'),
('PRO', 26, 5, 'PRO.26.5', 'Answer a fool according to his folly, lest he become wise in his own eyes.'),
('PRO', 26, 6, 'PRO.26.6', 'Like cutting off one’s own feet or drinking violence is the sending of a message by the hand of a fool.'),
('PRO', 26, 7, 'PRO.26.7', 'Like lame legs hanging limp is a proverb in the mouth of a fool.'),
('PRO', 26, 8, 'PRO.26.8', 'Like binding a stone into a sling is the giving of honor to a fool.'),
('PRO', 26, 9, 'PRO.26.9', 'Like a thorn that goes into the hand of a drunkard is a proverb in the mouth of a fool.'),
('PRO', 26, 10, 'PRO.26.10', 'Like an archer who wounds at random is he who hires a fool or passerby.'),
('PRO', 26, 11, 'PRO.26.11', 'As a dog returns to its vomit, so a fool repeats his folly.'),
('PRO', 26, 12, 'PRO.26.12', 'Do you see a man who is wise in his own eyes? There is more hope for a fool than for him.'),
('PRO', 26, 13, 'PRO.26.13', 'The slacker says, “A lion is in the road! A fierce lion roams the public square!”'),
('PRO', 26, 14, 'PRO.26.14', 'As a door turns on its hinges, so the slacker turns on his bed.'),
('PRO', 26, 15, 'PRO.26.15', 'The slacker buries his hand in the dish; it wearies him to bring it back to his mouth.'),
('PRO', 26, 16, 'PRO.26.16', 'The slacker is wiser in his own eyes than seven men who answer discreetly.'),
('PRO', 26, 17, 'PRO.26.17', 'Like one who grabs a dog by the ears is a passerby who meddles in a quarrel not his own.'),
('PRO', 26, 18, 'PRO.26.18', 'Like a madman shooting firebrands and deadly arrows,'),
('PRO', 26, 19, 'PRO.26.19', 'so is the man who deceives his neighbor and says, “I was only joking!”'),
('PRO', 26, 20, 'PRO.26.20', 'Without wood, a fire goes out; without gossip, a conflict ceases.'),
('PRO', 26, 21, 'PRO.26.21', 'Like charcoal for embers and wood for fire, so is a quarrelsome man for kindling strife.'),
('PRO', 26, 22, 'PRO.26.22', 'The words of a gossip are like choice morsels that go down into the inmost being.'),
('PRO', 26, 23, 'PRO.26.23', 'Like glaze covering an earthen vessel are burning lips and a wicked heart.'),
('PRO', 26, 24, 'PRO.26.24', 'A hateful man disguises himself with his speech, but he lays up deceit in his heart.'),
('PRO', 26, 25, 'PRO.26.25', 'When he speaks graciously, do not believe him, for seven abominations fill his heart.'),
('PRO', 26, 26, 'PRO.26.26', 'Though his hatred is concealed by deception, his wickedness will be exposed in the assembly.'),
('PRO', 26, 27, 'PRO.26.27', 'He who digs a pit will fall into it, and he who rolls a stone will have it roll back on him.'),
('PRO', 26, 28, 'PRO.26.28', 'A lying tongue hates those it crushes, and a flattering mouth causes ruin.'),
('PRO', 27, 1, 'PRO.27.1', 'Do not boast about tomorrow, for you do not know what a day may bring.'),
('PRO', 27, 2, 'PRO.27.2', 'Let another praise you, and not your own mouth—a stranger, and not your own lips.'),
('PRO', 27, 3, 'PRO.27.3', 'A stone is heavy and sand is a burden, but aggravation from a fool outweighs them both.'),
('PRO', 27, 4, 'PRO.27.4', 'Wrath is cruel and anger is like a flood, but who can withstand jealousy?'),
('PRO', 27, 5, 'PRO.27.5', 'Better an open rebuke than love that is concealed.'),
('PRO', 27, 6, 'PRO.27.6', 'The wounds of a friend are faithful, but the kisses of an enemy are deceitful.'),
('PRO', 27, 7, 'PRO.27.7', 'The soul that is full loathes honey, but to a hungry soul, any bitter thing is sweet.'),
('PRO', 27, 8, 'PRO.27.8', 'Like a bird that strays from its nest is a man who wanders from his home.'),
('PRO', 27, 9, 'PRO.27.9', 'Oil and incense bring joy to the heart, and the counsel of a friend is sweetness to the soul.'),
('PRO', 27, 10, 'PRO.27.10', 'Do not forsake your friend or your father’s friend, and do not go to your brother’s house in the day of your calamity; better a neighbor nearby than a brother far away.'),
('PRO', 27, 11, 'PRO.27.11', 'Be wise, my son, and bring joy to my heart, so that I can answer him who taunts me.'),
('PRO', 27, 12, 'PRO.27.12', 'The prudent see danger and take cover, but the simple keep going and pay the penalty.'),
('PRO', 27, 13, 'PRO.27.13', 'Take the garment of him who posts security for a stranger; get collateral if it is for a foreigner.'),
('PRO', 27, 14, 'PRO.27.14', 'If one blesses his neighbor with a loud voice early in the morning, it will be counted to him as a curse.'),
('PRO', 27, 15, 'PRO.27.15', 'A constant dripping on a rainy day and a contentious woman are alike—'),
('PRO', 27, 16, 'PRO.27.16', 'restraining her is like holding back the wind or grasping oil with one’s right hand.'),
('PRO', 27, 17, 'PRO.27.17', 'As iron sharpens iron, so one man sharpens another.'),
('PRO', 27, 18, 'PRO.27.18', 'Whoever tends a fig tree will eat its fruit, and he who looks after his master will be honored.'),
('PRO', 27, 19, 'PRO.27.19', 'As water reflects the face, so the heart reflects the true man.'),
('PRO', 27, 20, 'PRO.27.20', 'Sheol and Abaddon are never satisfied; so the eyes of man are never satisfied.'),
('PRO', 27, 21, 'PRO.27.21', 'A crucible for silver and a furnace for gold, but a man is tested by the praise accorded him.'),
('PRO', 27, 22, 'PRO.27.22', 'Though you grind a fool like grain with mortar and a pestle, yet his folly will not depart from him.'),
('PRO', 27, 23, 'PRO.27.23', 'Be sure to know the state of your flocks, and pay close attention to your herds;'),
('PRO', 27, 24, 'PRO.27.24', 'for riches are not forever, nor does a crown endure to every generation.'),
('PRO', 27, 25, 'PRO.27.25', 'When hay is removed and new growth appears and the grass from the hills is gathered,'),
('PRO', 27, 26, 'PRO.27.26', 'the lambs will provide you with clothing, and the goats with the price of a field.'),
('PRO', 27, 27, 'PRO.27.27', 'You will have plenty of goats’ milk to feed you—food for your household and nourishment for your maidservants.'),
('PRO', 28, 1, 'PRO.28.1', 'The wicked flee when no one pursues, but the righteous are as bold as a lion.'),
('PRO', 28, 2, 'PRO.28.2', 'A land in rebellion has many rulers, but a man of understanding and knowledge maintains order.'),
('PRO', 28, 3, 'PRO.28.3', 'A destitute leader who oppresses the poor is like a driving rain that leaves no food.'),
('PRO', 28, 4, 'PRO.28.4', 'Those who forsake the law praise the wicked, but those who keep the law resist them.'),
('PRO', 28, 5, 'PRO.28.5', 'Evil men do not understand justice, but those who seek the LORD comprehend fully.'),
('PRO', 28, 6, 'PRO.28.6', 'Better a poor man who walks with integrity than a rich man whose ways are perverse.'),
('PRO', 28, 7, 'PRO.28.7', 'A discerning son keeps the law, but a companion of gluttons disgraces his father.'),
('PRO', 28, 8, 'PRO.28.8', 'He who increases his wealth by interest and usury lays it up for one who is kind to the poor.'),
('PRO', 28, 9, 'PRO.28.9', 'Whoever turns his ear away from hearing the law, even his prayer is detestable.'),
('PRO', 28, 10, 'PRO.28.10', 'He who leads the upright along the path of evil will fall into his own pit, but the blameless will inherit what is good.'),
('PRO', 28, 11, 'PRO.28.11', 'A rich man is wise in his own eyes, but a poor man with discernment sees through him.'),
('PRO', 28, 12, 'PRO.28.12', 'When the righteous triumph, there is great glory, but when the wicked rise, men hide themselves.'),
('PRO', 28, 13, 'PRO.28.13', 'He who conceals his sins will not prosper, but whoever confesses and renounces them will find mercy.'),
('PRO', 28, 14, 'PRO.28.14', 'Blessed is the man who is always reverent, but he who hardens his heart falls into trouble.'),
('PRO', 28, 15, 'PRO.28.15', 'Like a roaring lion or a charging bear is a wicked ruler over a helpless people.'),
('PRO', 28, 16, 'PRO.28.16', 'A leader who lacks judgment is also a great oppressor, but he who hates dishonest profit will prolong his days.'),
('PRO', 28, 17, 'PRO.28.17', 'A man burdened by bloodguilt will flee into the Pit; let no one support him.'),
('PRO', 28, 18, 'PRO.28.18', 'He who walks with integrity will be kept safe, but whoever is perverse in his ways will suddenly fall.'),
('PRO', 28, 19, 'PRO.28.19', 'The one who works his land will have plenty of food, but whoever chases fantasies will have his fill of poverty.'),
('PRO', 28, 20, 'PRO.28.20', 'A faithful man will abound with blessings, but one eager to be rich will not go unpunished.'),
('PRO', 28, 21, 'PRO.28.21', 'To show partiality is not good, yet a man will do wrong for a piece of bread.'),
('PRO', 28, 22, 'PRO.28.22', 'A stingy man hastens after wealth and does not know that poverty awaits him.'),
('PRO', 28, 23, 'PRO.28.23', 'He who rebukes a man will later find more favor than one who flatters with his tongue.'),
('PRO', 28, 24, 'PRO.28.24', 'He who robs his father or mother, saying, “It is not wrong,” is a companion to the man who destroys.'),
('PRO', 28, 25, 'PRO.28.25', 'A greedy man stirs up strife, but he who trusts in the LORD will prosper.'),
('PRO', 28, 26, 'PRO.28.26', 'He who trusts in himself is a fool, but one who walks in wisdom will be safe.'),
('PRO', 28, 27, 'PRO.28.27', 'Whoever gives to the poor will not be in need, but he who hides his eyes will receive many curses.'),
('PRO', 28, 28, 'PRO.28.28', 'When the wicked come to power, people hide themselves; but when they perish, the righteous flourish.'),
('PRO', 29, 1, 'PRO.29.1', 'A man who remains stiff-necked after much reproof will suddenly be shattered beyond recovery.'),
('PRO', 29, 2, 'PRO.29.2', 'When the righteous flourish, the people rejoice, but when the wicked rule, the people groan.'),
('PRO', 29, 3, 'PRO.29.3', 'A man who loves wisdom brings joy to his father, but a companion of prostitutes squanders his wealth.'),
('PRO', 29, 4, 'PRO.29.4', 'By justice a king brings stability to the land, but a man who exacts tribute demolishes it.'),
('PRO', 29, 5, 'PRO.29.5', 'A man who flatters his neighbor spreads a net for his feet.'),
('PRO', 29, 6, 'PRO.29.6', 'An evil man is caught by his own sin, but a righteous one sings and rejoices.'),
('PRO', 29, 7, 'PRO.29.7', 'The righteous consider the cause of the poor, but the wicked have no regard for such concerns.'),
('PRO', 29, 8, 'PRO.29.8', 'Mockers inflame a city, but the wise turn away anger.'),
('PRO', 29, 9, 'PRO.29.9', 'If a wise man goes to court with a fool, there will be raving and laughing with no resolution.'),
('PRO', 29, 10, 'PRO.29.10', 'Men of bloodshed hate a blameless man, but the upright care for his life.'),
('PRO', 29, 11, 'PRO.29.11', 'A fool vents all his anger, but a wise man holds it back.'),
('PRO', 29, 12, 'PRO.29.12', 'If a ruler listens to lies, all his officials will be wicked.'),
('PRO', 29, 13, 'PRO.29.13', 'The poor man and the oppressor have this in common: The LORD gives light to the eyes of both.'),
('PRO', 29, 14, 'PRO.29.14', 'A king who judges the poor with fairness—his throne will be established forever.'),
('PRO', 29, 15, 'PRO.29.15', 'A rod of correction imparts wisdom, but a child left to himself disgraces his mother.'),
('PRO', 29, 16, 'PRO.29.16', 'When the wicked thrive, rebellion increases; but the righteous will see their downfall.'),
('PRO', 29, 17, 'PRO.29.17', 'Discipline your son, and he will give you rest; he will bring delight to your soul.'),
('PRO', 29, 18, 'PRO.29.18', 'Where there is no vision, the people cast off restraint; but blessed is he who keeps the Law.'),
('PRO', 29, 19, 'PRO.29.19', 'A servant cannot be corrected by words alone; though he understands, he will not respond.'),
('PRO', 29, 20, 'PRO.29.20', 'Do you see a man who speaks in haste? There is more hope for a fool than for him.'),
('PRO', 29, 21, 'PRO.29.21', 'A servant pampered from his youth will bring grief in the end.'),
('PRO', 29, 22, 'PRO.29.22', 'An angry man stirs up dissension, and a hot-tempered man abounds in transgression.'),
('PRO', 29, 23, 'PRO.29.23', 'A man’s pride will bring him low, but a humble spirit will obtain honor.'),
('PRO', 29, 24, 'PRO.29.24', 'A partner to a thief hates his own soul; he receives the oath but does not testify.'),
('PRO', 29, 25, 'PRO.29.25', 'The fear of man is a snare, but whoever trusts in the LORD is set securely on high.'),
('PRO', 29, 26, 'PRO.29.26', 'Many seek the ruler’s favor, but a man receives justice from the LORD.'),
('PRO', 29, 27, 'PRO.29.27', 'An unjust man is detestable to the righteous, and one whose way is upright is detestable to the wicked.'),
('PRO', 30, 1, 'PRO.30.1', 'These are the words of Agur son of Jakeh—the burden that this man declared to Ithiel: “I am weary, O God, and worn out.'),
('PRO', 30, 2, 'PRO.30.2', 'Surely I am the most ignorant of men, and I lack the understanding of a man.'),
('PRO', 30, 3, 'PRO.30.3', 'I have not learned wisdom, and I have no knowledge of the Holy One.'),
('PRO', 30, 4, 'PRO.30.4', 'Who has ascended to heaven and come down? Who has gathered the wind in His hands? Who has bound up the waters in His cloak? Who has established all the ends of the earth? What is His name, and what is the name of His Son—surely you know!'),
('PRO', 30, 5, 'PRO.30.5', 'Every word of God is flawless; He is a shield to those who take refuge in Him.'),
('PRO', 30, 6, 'PRO.30.6', 'Do not add to His words, lest He rebuke you and prove you a liar.'),
('PRO', 30, 7, 'PRO.30.7', 'Two things I ask of You—do not refuse me before I die:'),
('PRO', 30, 8, 'PRO.30.8', 'Keep falsehood and deceitful words far from me. Give me neither poverty nor riches; feed me with the bread that is my portion.'),
('PRO', 30, 9, 'PRO.30.9', 'Otherwise, I may have too much and deny You, saying, ‘Who is the LORD?’ Or I may become poor and steal, profaning the name of my God.'),
('PRO', 30, 10, 'PRO.30.10', 'Do not slander a servant to his master, or he will curse you, and you will bear the guilt.'),
('PRO', 30, 11, 'PRO.30.11', 'There is a generation of those who curse their fathers and do not bless their mothers.'),
('PRO', 30, 12, 'PRO.30.12', 'There is a generation of those who are pure in their own eyes and yet unwashed of their filth.'),
('PRO', 30, 13, 'PRO.30.13', 'There is a generation—how haughty are their eyes and pretentious are their glances—'),
('PRO', 30, 14, 'PRO.30.14', 'there is a generation whose teeth are swords and whose jaws are knives, devouring the oppressed from the earth and the needy from among men.'),
('PRO', 30, 15, 'PRO.30.15', 'The leech has two daughters: Give and Give. There are three things that are never satisfied, four that never say, ‘Enough!’:'),
('PRO', 30, 16, 'PRO.30.16', 'Sheol, the barren womb, land never satisfied with water, and fire that never says, ‘Enough!’'),
('PRO', 30, 17, 'PRO.30.17', 'As for the eye that mocks a father and scorns obedience to a mother, may the ravens of the valley pluck it out and young vultures devour it.'),
('PRO', 30, 18, 'PRO.30.18', 'There are three things too wonderful for me, four that I cannot understand:'),
('PRO', 30, 19, 'PRO.30.19', 'the way of an eagle in the sky, the way of a snake on a rock, the way of a ship at sea, and the way of a man with a maiden.'),
('PRO', 30, 20, 'PRO.30.20', 'This is the way of an adulteress: She eats and wipes her mouth and says, ‘I have done nothing wrong.’'),
('PRO', 30, 21, 'PRO.30.21', 'Under three things the earth trembles, under four it cannot bear up:'),
('PRO', 30, 22, 'PRO.30.22', 'a servant who becomes king, a fool who is filled with food,'),
('PRO', 30, 23, 'PRO.30.23', 'an unloved woman who marries, and a maidservant who supplants her mistress.'),
('PRO', 30, 24, 'PRO.30.24', 'Four things on earth are small, yet they are exceedingly wise:'),
('PRO', 30, 25, 'PRO.30.25', 'The ants are creatures of little strength, yet they store up their food in the summer;'),
('PRO', 30, 26, 'PRO.30.26', 'the rock badgers are creatures of little power, yet they make their homes in the rocks;'),
('PRO', 30, 27, 'PRO.30.27', 'the locusts have no king, yet they all advance in formation;'),
('PRO', 30, 28, 'PRO.30.28', 'and the lizard can be caught in one’s hands, yet it is found in the palaces of kings.'),
('PRO', 30, 29, 'PRO.30.29', 'There are three things that are stately in their stride, and four that are impressive in their walk:'),
('PRO', 30, 30, 'PRO.30.30', 'a lion, mighty among beasts, refusing to retreat before anything;'),
('PRO', 30, 31, 'PRO.30.31', 'a strutting rooster; a he-goat; and a king with his army around him.'),
('PRO', 30, 32, 'PRO.30.32', 'If you have foolishly exalted yourself or if you have plotted evil, put your hand over your mouth.'),
('PRO', 30, 33, 'PRO.30.33', 'For as the churning of milk yields butter, and the twisting of the nose draws blood, so the stirring of anger brings forth strife.”'),
('PRO', 31, 1, 'PRO.31.1', 'These are the words of King Lemuel—the burden that his mother taught him:'),
('PRO', 31, 2, 'PRO.31.2', 'What shall I say, O my son? What, O son of my womb? What, O son of my vows?'),
('PRO', 31, 3, 'PRO.31.3', 'Do not spend your strength on women or your vigor on those who ruin kings.'),
('PRO', 31, 4, 'PRO.31.4', 'It is not for kings, O Lemuel, it is not for kings to drink wine, or for rulers to crave strong drink,'),
('PRO', 31, 5, 'PRO.31.5', 'lest they drink and forget what is decreed, depriving all the oppressed of justice.'),
('PRO', 31, 6, 'PRO.31.6', 'Give strong drink to one who is perishing, and wine to the bitter in soul.'),
('PRO', 31, 7, 'PRO.31.7', 'Let him drink and forget his poverty, and remember his misery no more.'),
('PRO', 31, 8, 'PRO.31.8', 'Open your mouth for those with no voice, for the cause of all the dispossessed.'),
('PRO', 31, 9, 'PRO.31.9', 'Open your mouth, judge righteously, and defend the cause of the poor and needy.'),
('PRO', 31, 10, 'PRO.31.10', 'A wife of noble character, who can find? She is far more precious than rubies.'),
('PRO', 31, 11, 'PRO.31.11', 'The heart of her husband trusts in her, and he lacks nothing of value.'),
('PRO', 31, 12, 'PRO.31.12', 'She brings him good and not harm all the days of her life.'),
('PRO', 31, 13, 'PRO.31.13', 'She selects wool and flax and works with eager hands.'),
('PRO', 31, 14, 'PRO.31.14', 'She is like the merchant ships, bringing her food from afar.'),
('PRO', 31, 15, 'PRO.31.15', 'She rises while it is still night to provide food for her household and portions for her maidservants.'),
('PRO', 31, 16, 'PRO.31.16', 'She appraises a field and buys it; from her earnings she plants a vineyard.'),
('PRO', 31, 17, 'PRO.31.17', 'She girds herself with strength and shows that her arms are strong.'),
('PRO', 31, 18, 'PRO.31.18', 'She sees that her gain is good, and her lamp is not extinguished at night.'),
('PRO', 31, 19, 'PRO.31.19', 'She stretches out her hands to the distaff and grasps the spindle with her fingers.'),
('PRO', 31, 20, 'PRO.31.20', 'She opens her arms to the poor and reaches out her hands to the needy.'),
('PRO', 31, 21, 'PRO.31.21', 'When it snows, she has no fear for her household, for they are all clothed in scarlet.'),
('PRO', 31, 22, 'PRO.31.22', 'She makes coverings for her bed; her clothing is fine linen and purple.'),
('PRO', 31, 23, 'PRO.31.23', 'Her husband is known at the city gates, where he sits among the elders of the land.'),
('PRO', 31, 24, 'PRO.31.24', 'She makes linen garments and sells them; she delivers sashes to the merchants.'),
('PRO', 31, 25, 'PRO.31.25', 'Strength and honor are her clothing, and she can laugh at the days to come.'),
('PRO', 31, 26, 'PRO.31.26', 'She opens her mouth with wisdom, and faithful instruction is on her tongue.'),
('PRO', 31, 27, 'PRO.31.27', 'She watches over the affairs of her household and does not eat the bread of idleness.'),
('PRO', 31, 28, 'PRO.31.28', 'Her children rise up and call her blessed; her husband praises her as well:'),
('PRO', 31, 29, 'PRO.31.29', '“Many daughters have done noble things, but you surpass them all!”'),
('PRO', 31, 30, 'PRO.31.30', 'Charm is deceptive and beauty is fleeting, but a woman who fears the LORD is to be praised.'),
('PRO', 31, 31, 'PRO.31.31', 'Give her the fruit of her hands, and let her works praise her at the gates.'),
('ECC', 1, 1, 'ECC.1.1', 'These are the words of the Teacher, the son of David, king in Jerusalem:'),
('ECC', 1, 2, 'ECC.1.2', '“Futility of futilities,” says the Teacher, “futility of futilities! Everything is futile!”'),
('ECC', 1, 3, 'ECC.1.3', 'What does a man gain from all his labor, at which he toils under the sun?'),
('ECC', 1, 4, 'ECC.1.4', 'Generations come and generations go, but the earth remains forever.'),
('ECC', 1, 5, 'ECC.1.5', 'The sun rises and the sun sets; it hurries back to where it rises.'),
('ECC', 1, 6, 'ECC.1.6', 'The wind blows southward, then turns northward; round and round it swirls, ever returning on its course.'),
('ECC', 1, 7, 'ECC.1.7', 'All the rivers flow into the sea, yet the sea is never full; to the place from which the streams come, there again they flow.'),
('ECC', 1, 8, 'ECC.1.8', 'All things are wearisome, more than one can describe; the eye is not satisfied with seeing, nor the ear content with hearing.'),
('ECC', 1, 9, 'ECC.1.9', 'What has been will be again, and what has been done will be done again; there is nothing new under the sun.'),
('ECC', 1, 10, 'ECC.1.10', 'Is there a case where one can say, “Look, this is new”? It has already existed in the ages before us.'),
('ECC', 1, 11, 'ECC.1.11', 'There is no remembrance of those who came before, and those yet to come will not be remembered by those who follow after.'),
('ECC', 1, 12, 'ECC.1.12', 'I, the Teacher, was king over Israel in Jerusalem.'),
('ECC', 1, 13, 'ECC.1.13', 'And I set my mind to seek and explore by wisdom all that is done under heaven. What a miserable task God has laid upon the sons of men to occupy them!'),
('ECC', 1, 14, 'ECC.1.14', 'I have seen all the things that are done under the sun, and have found them all to be futile, a pursuit of the wind.'),
('ECC', 1, 15, 'ECC.1.15', 'What is crooked cannot be straightened, and what is lacking cannot be counted.'),
('ECC', 1, 16, 'ECC.1.16', 'I said to myself, “Behold, I have grown and increased in wisdom beyond all those before me who were over Jerusalem, and my mind has observed a wealth of wisdom and knowledge.”'),
('ECC', 1, 17, 'ECC.1.17', 'So I set my mind to know wisdom and madness and folly; I learned that this, too, is a pursuit of the wind.'),
('ECC', 1, 18, 'ECC.1.18', 'For with much wisdom comes much sorrow, and as knowledge grows, grief increases.'),
('ECC', 2, 1, 'ECC.2.1', 'I said to myself, “Come now, I will test you with pleasure; enjoy what is good!” But it proved to be futile.'),
('ECC', 2, 2, 'ECC.2.2', 'I said of laughter, “It is folly,” and of pleasure, “What does it accomplish?”'),
('ECC', 2, 3, 'ECC.2.3', 'I sought to cheer my body with wine and to embrace folly—my mind still guiding me with wisdom—until I could see what was worthwhile for men to do under heaven during the few days of their lives.'),
('ECC', 2, 4, 'ECC.2.4', 'I expanded my pursuits. I built houses and planted vineyards for myself.'),
('ECC', 2, 5, 'ECC.2.5', 'I made gardens and parks for myself, where I planted all kinds of fruit trees.'),
('ECC', 2, 6, 'ECC.2.6', 'I built reservoirs to water my groves of flourishing trees.'),
('ECC', 2, 7, 'ECC.2.7', 'I acquired menservants and maidservants, and servants were born in my house. I also owned more herds and flocks than anyone in Jerusalem before me,'),
('ECC', 2, 8, 'ECC.2.8', 'and I accumulated for myself silver and gold and the treasure of kings and provinces. I gathered to myself male and female singers, and the delights of the sons of men—many concubines.'),
('ECC', 2, 9, 'ECC.2.9', 'So I became great and surpassed all in Jerusalem who had preceded me; and my wisdom remained with me.'),
('ECC', 2, 10, 'ECC.2.10', 'Anything my eyes desired, I did not deny myself. I refused my heart no pleasure. For my heart took delight in all my work, and this was the reward for all my labor.'),
('ECC', 2, 11, 'ECC.2.11', 'Yet when I considered all the works that my hands had accomplished and what I had toiled to achieve, I found everything to be futile, a pursuit of the wind; there was nothing to be gained under the sun.'),
('ECC', 2, 12, 'ECC.2.12', 'Then I turned to consider wisdom and madness and folly; for what more can the king’s successor do than what has already been accomplished?'),
('ECC', 2, 13, 'ECC.2.13', 'And I saw that wisdom exceeds folly, just as light exceeds darkness:'),
('ECC', 2, 14, 'ECC.2.14', 'The wise man has eyes in his head, but the fool walks in darkness. Yet I also came to realize that one fate overcomes them both.'),
('ECC', 2, 15, 'ECC.2.15', 'So I said to myself, “The fate of the fool will also befall me. What then have I gained by being wise?” And I said to myself that this too is futile.'),
('ECC', 2, 16, 'ECC.2.16', 'For there is no lasting remembrance of the wise, just as with the fool, seeing that both will be forgotten in the days to come. Alas, the wise man will die just like the fool!'),
('ECC', 2, 17, 'ECC.2.17', 'So I hated life, because the work that is done under the sun was grievous to me. For everything is futile and a pursuit of the wind.'),
('ECC', 2, 18, 'ECC.2.18', 'I hated all for which I had toiled under the sun, because I must leave it to the man who comes after me.'),
('ECC', 2, 19, 'ECC.2.19', 'And who knows whether that man will be wise or foolish? Yet he will take over all the labor at which I have worked skillfully under the sun. This too is futile.'),
('ECC', 2, 20, 'ECC.2.20', 'So my heart began to despair over all the labor that I had done under the sun.'),
('ECC', 2, 21, 'ECC.2.21', 'When there is a man who has labored with wisdom, knowledge, and skill, and he must give his portion to a man who has not worked for it, this too is futile and a great evil.'),
('ECC', 2, 22, 'ECC.2.22', 'For what does a man get for all the toil and striving with which he labors under the sun?'),
('ECC', 2, 23, 'ECC.2.23', 'Indeed, all his days are filled with grief, and his task is sorrowful; even at night, his mind does not rest. This too is futile.'),
('ECC', 2, 24, 'ECC.2.24', 'Nothing is better for a man than to eat and drink and enjoy his work. I have also seen that this is from the hand of God.'),
('ECC', 2, 25, 'ECC.2.25', 'For apart from Him, who can eat and who can find enjoyment?'),
('ECC', 2, 26, 'ECC.2.26', 'To the man who is pleasing in His sight, He gives wisdom and knowledge and joy, but to the sinner He assigns the task of gathering and accumulating that which he will hand over to one who pleases God. This too is futile and a pursuit of the wind.'),
('ECC', 3, 1, 'ECC.3.1', 'To everything there is a season, and a time for every purpose under heaven:'),
('ECC', 3, 2, 'ECC.3.2', 'a time to be born and a time to die, a time to plant and a time to uproot,'),
('ECC', 3, 3, 'ECC.3.3', 'a time to kill and a time to heal, a time to break down and a time to build,'),
('ECC', 3, 4, 'ECC.3.4', 'a time to weep and a time to laugh, a time to mourn and a time to dance,'),
('ECC', 3, 5, 'ECC.3.5', 'a time to cast away stones and a time to gather stones together, a time to embrace and a time to refrain from embracing,'),
('ECC', 3, 6, 'ECC.3.6', 'a time to search and a time to count as lost, a time to keep and a time to discard,'),
('ECC', 3, 7, 'ECC.3.7', 'a time to tear and a time to mend, a time to be silent and a time to speak,'),
('ECC', 3, 8, 'ECC.3.8', 'a time to love and a time to hate, a time for war and a time for peace.'),
('ECC', 3, 9, 'ECC.3.9', 'What does the worker gain from his toil?'),
('ECC', 3, 10, 'ECC.3.10', 'I have seen the burden that God has laid upon the sons of men to occupy them.'),
('ECC', 3, 11, 'ECC.3.11', 'He has made everything beautiful in its time. He has also set eternity in the hearts of men, yet they cannot fathom the work that God has done from beginning to end.'),
('ECC', 3, 12, 'ECC.3.12', 'I know that there is nothing better for them than to rejoice and do good while they live,'),
('ECC', 3, 13, 'ECC.3.13', 'and also that every man should eat and drink and find satisfaction in all his labor—this is the gift of God.'),
('ECC', 3, 14, 'ECC.3.14', 'I know that everything God does endures forever; nothing can be added to it or taken from it. God does it so that they should fear Him.'),
('ECC', 3, 15, 'ECC.3.15', 'What exists has already been, and what will be has already been, for God will call to account what has passed.'),
('ECC', 3, 16, 'ECC.3.16', 'Furthermore, I saw under the sun that in the place of judgment there is wickedness, and in the place of righteousness there is wickedness.'),
('ECC', 3, 17, 'ECC.3.17', 'I said in my heart, “God will judge the righteous and the wicked, since there is a time for every activity and every deed.”'),
('ECC', 3, 18, 'ECC.3.18', 'I said to myself, “As for the sons of men, God tests them so that they may see for themselves that they are but beasts.”'),
('ECC', 3, 19, 'ECC.3.19', 'For the fates of both men and beasts are the same: As one dies, so dies the other—they all have the same breath. Man has no advantage over the animals, since everything is futile.'),
('ECC', 3, 20, 'ECC.3.20', 'All go to one place; all come from dust, and all return to dust.'),
('ECC', 3, 21, 'ECC.3.21', 'Who knows if the spirit of man rises upward and the spirit of the animal descends into the earth?'),
('ECC', 3, 22, 'ECC.3.22', 'I have seen that there is nothing better for a man than to enjoy his work, because that is his lot. For who can bring him to see what will come after him?'),
('ECC', 4, 1, 'ECC.4.1', 'Again I looked, and I considered all the oppression taking place under the sun. I saw the tears of the oppressed, and they had no comforter; the power lay in the hands of their oppressors, and there was no comforter.'),
('ECC', 4, 2, 'ECC.4.2', 'So I admired the dead, who had already died, above the living, who are still alive.'),
('ECC', 4, 3, 'ECC.4.3', 'But better than both is he who has not yet existed, who has not seen the evil that is done under the sun.'),
('ECC', 4, 4, 'ECC.4.4', 'I saw that all labor and success spring from a man’s envy of his neighbor. This too is futile and a pursuit of the wind.'),
('ECC', 4, 5, 'ECC.4.5', 'The fool folds his hands and consumes his own flesh.'),
('ECC', 4, 6, 'ECC.4.6', 'Better one handful with tranquility than two handfuls with toil and pursuit of the wind.'),
('ECC', 4, 7, 'ECC.4.7', 'Again, I saw futility under the sun.'),
('ECC', 4, 8, 'ECC.4.8', 'There is a man all alone, without even a son or brother. And though there is no end to his labor, his eyes are still not content with his wealth: “For whom do I toil and bereave my soul of enjoyment?” This too is futile—a miserable task.'),
('ECC', 4, 9, 'ECC.4.9', 'Two are better than one, because they have a good return for their labor.'),
('ECC', 4, 10, 'ECC.4.10', 'For if one falls down, his companion can lift him up; but pity the one who falls without another to help him up!'),
('ECC', 4, 11, 'ECC.4.11', 'Again, if two lie down together, they will keep warm; but how can one keep warm alone?'),
('ECC', 4, 12, 'ECC.4.12', 'And though one may be overpowered, two can resist. Moreover, a cord of three strands is not quickly broken.'),
('ECC', 4, 13, 'ECC.4.13', 'Better is a poor but wise youth than an old but foolish king who no longer knows how to take a warning.'),
('ECC', 4, 14, 'ECC.4.14', 'For the youth has come from the prison to the kingship, though he was born poor in his own kingdom.'),
('ECC', 4, 15, 'ECC.4.15', 'I saw that all who lived and walked under the sun followed this second one, the youth who succeeded the king.'),
('ECC', 4, 16, 'ECC.4.16', 'There is no limit to all the people who were before them. Yet the successor will not be celebrated by those who come even later. This too is futile and a pursuit of the wind.'),
('ECC', 5, 1, 'ECC.5.1', 'Guard your steps when you go to the house of God. Draw near to listen rather than to offer the sacrifice of fools, who do not know that they do wrong.'),
('ECC', 5, 2, 'ECC.5.2', 'Do not be quick to speak, and do not be hasty in your heart to utter a word before God. For God is in heaven and you are on earth. So let your words be few.'),
('ECC', 5, 3, 'ECC.5.3', 'As a dream comes through many cares, so the speech of a fool comes with many words.'),
('ECC', 5, 4, 'ECC.5.4', 'When you make a vow to God, do not delay in fulfilling it, because He takes no pleasure in fools. Fulfill your vow.'),
('ECC', 5, 5, 'ECC.5.5', 'It is better not to vow than to make a vow and not fulfill it.'),
('ECC', 5, 6, 'ECC.5.6', 'Do not let your mouth cause your flesh to sin, and do not tell the messenger that your vow was a mistake. Why should God be angry with your words and destroy the work of your hands?'),
('ECC', 5, 7, 'ECC.5.7', 'For as many dreams bring futility, so do many words. Therefore, fear God.'),
('ECC', 5, 8, 'ECC.5.8', 'If you see the oppression of the poor and the denial of justice and righteousness in the province, do not be astonished at the matter; for one official is watched by a superior, and others higher still are over them.'),
('ECC', 5, 9, 'ECC.5.9', 'The produce of the earth is taken by all; the king himself profits from the fields.'),
('ECC', 5, 10, 'ECC.5.10', 'He who loves money is never satisfied by money, and he who loves wealth is never satisfied by income. This too is futile.'),
('ECC', 5, 11, 'ECC.5.11', 'When good things increase, so do those who consume them; what then is the profit to the owner, except to behold them with his eyes?'),
('ECC', 5, 12, 'ECC.5.12', 'The sleep of the worker is sweet, whether he eats little or much, but the abundance of the rich man permits him no sleep.'),
('ECC', 5, 13, 'ECC.5.13', 'There is a grievous evil I have seen under the sun: wealth hoarded to the harm of its owner,'),
('ECC', 5, 14, 'ECC.5.14', 'or wealth lost in a failed venture, so when that man has a son there is nothing to pass on.'),
('ECC', 5, 15, 'ECC.5.15', 'As a man came from his mother’s womb, so he will depart again, naked as he arrived. He takes nothing for his labor to carry in his hands.'),
('ECC', 5, 16, 'ECC.5.16', 'This too is a grievous affliction: Exactly as a man is born, so he will depart. What does he gain as he toils for the wind?'),
('ECC', 5, 17, 'ECC.5.17', 'Moreover, all his days he eats in darkness, with much sorrow, sickness, and anger.'),
('ECC', 5, 18, 'ECC.5.18', 'Here is what I have seen to be good and fitting: to eat and drink, and to find satisfaction in all the labor one does under the sun during the few days of life that God has given him—for this is his lot.'),
('ECC', 5, 19, 'ECC.5.19', 'Furthermore, God has given riches and wealth to every man, and He has enabled him to enjoy them, to accept his lot, and to rejoice in his labor. This is a gift from God.'),
('ECC', 5, 20, 'ECC.5.20', 'For a man seldom considers the days of his life, because God keeps him occupied with the joy of his heart.'),
('ECC', 6, 1, 'ECC.6.1', 'There is another evil I have seen under the sun, and it weighs heavily upon mankind:'),
('ECC', 6, 2, 'ECC.6.2', 'God gives a man riches, wealth, and honor, so that he lacks nothing his heart desires; but God does not allow him to enjoy them. Instead, a stranger will enjoy them. This is futile and a grievous affliction.'),
('ECC', 6, 3, 'ECC.6.3', 'A man may father a hundred children and live for many years; yet no matter how long he lives, if he is unsatisfied with his prosperity and does not even receive a proper burial, I say that a stillborn child is better off than he.'),
('ECC', 6, 4, 'ECC.6.4', 'For a stillborn child enters in futility and departs in darkness, and his name is shrouded in obscurity.'),
('ECC', 6, 5, 'ECC.6.5', 'The child, though neither seeing the sun nor knowing anything, has more rest than that man,'),
('ECC', 6, 6, 'ECC.6.6', 'even if he lives a thousand years twice over but fails to enjoy his prosperity. Do not all go to the same place?'),
('ECC', 6, 7, 'ECC.6.7', 'All a man’s labor is for his mouth, yet his appetite is never satisfied.'),
('ECC', 6, 8, 'ECC.6.8', 'What advantage, then, has the wise man over the fool? What gain comes to the poor man who knows how to conduct himself before others?'),
('ECC', 6, 9, 'ECC.6.9', 'Better what the eye can see than the wandering of desire. This too is futile and a pursuit of the wind.'),
('ECC', 6, 10, 'ECC.6.10', 'Whatever exists was named long ago, and it is known what man is; but he cannot contend with one stronger than he.'),
('ECC', 6, 11, 'ECC.6.11', 'For the more words, the more futility—and how does that profit anyone?'),
('ECC', 6, 12, 'ECC.6.12', 'For who knows what is good for a man during the few days in which he passes through his fleeting life like a shadow? Who can tell a man what will come after him under the sun?'),
('ECC', 7, 1, 'ECC.7.1', 'A good name is better than fine perfume, and one’s day of death is better than his day of birth.'),
('ECC', 7, 2, 'ECC.7.2', 'It is better to enter a house of mourning than a house of feasting, since death is the end of every man, and the living should take this to heart.'),
('ECC', 7, 3, 'ECC.7.3', 'Sorrow is better than laughter, for a sad countenance is good for the heart.'),
('ECC', 7, 4, 'ECC.7.4', 'The heart of the wise is in the house of mourning, but the heart of fools is in the house of pleasure.'),
('ECC', 7, 5, 'ECC.7.5', 'It is better to heed a wise man’s rebuke than to listen to the song of fools.'),
('ECC', 7, 6, 'ECC.7.6', 'For like the crackling of thorns under the pot, so is the laughter of the fool. This too is futile.'),
('ECC', 7, 7, 'ECC.7.7', 'Surely extortion turns a wise man into a fool, and a bribe corrupts the heart.'),
('ECC', 7, 8, 'ECC.7.8', 'The end of a matter is better than the beginning, and a patient spirit is better than a proud one.'),
('ECC', 7, 9, 'ECC.7.9', 'Do not be quickly provoked in your spirit, for anger settles in the lap of a fool.'),
('ECC', 7, 10, 'ECC.7.10', 'Do not say, “Why were the old days better than these?” For it is unwise of you to ask about this.'),
('ECC', 7, 11, 'ECC.7.11', 'Wisdom, like an inheritance, is good, and it benefits those who see the sun.'),
('ECC', 7, 12, 'ECC.7.12', 'For wisdom, like money, is a shelter, and the advantage of knowledge is that wisdom preserves the life of its owner.'),
('ECC', 7, 13, 'ECC.7.13', 'Consider the work of God: Who can straighten what He has bent?'),
('ECC', 7, 14, 'ECC.7.14', 'In the day of prosperity, be joyful, but in the day of adversity, consider this: God has made one of these along with the other, so that a man cannot discover anything that will come after him.'),
('ECC', 7, 15, 'ECC.7.15', 'In my futile life I have seen both of these: A righteous man perishing in his righteousness, and a wicked man living long in his wickedness.'),
('ECC', 7, 16, 'ECC.7.16', 'Do not be overly righteous, and do not make yourself too wise. Why should you destroy yourself?'),
('ECC', 7, 17, 'ECC.7.17', 'Do not be excessively wicked, and do not be a fool. Why should you die before your time?'),
('ECC', 7, 18, 'ECC.7.18', 'It is good to grasp the one and not let the other slip from your hand. For he who fears God will follow both warnings.'),
('ECC', 7, 19, 'ECC.7.19', 'Wisdom makes the wise man stronger than ten rulers in a city.'),
('ECC', 7, 20, 'ECC.7.20', 'Surely there is no righteous man on earth who does good and never sins.'),
('ECC', 7, 21, 'ECC.7.21', 'Do not pay attention to every word that is spoken, or you may hear your servant cursing you.'),
('ECC', 7, 22, 'ECC.7.22', 'For you know in your heart that many times you yourself have cursed others.'),
('ECC', 7, 23, 'ECC.7.23', 'All this I tested by wisdom, saying, “I resolve to be wise.” But it was beyond me.'),
('ECC', 7, 24, 'ECC.7.24', 'What exists is out of reach and very deep. Who can fathom it?'),
('ECC', 7, 25, 'ECC.7.25', 'I directed my mind to understand, to explore, to search out wisdom and explanations, and to understand the stupidity of wickedness and the folly of madness.'),
('ECC', 7, 26, 'ECC.7.26', 'And I find more bitter than death the woman who is a snare, whose heart is a net, and whose hands are chains. The man who pleases God escapes her, but the sinner is ensnared.'),
('ECC', 7, 27, 'ECC.7.27', '“Behold,” says the Teacher, “I have discovered this by adding one thing to another to find an explanation.'),
('ECC', 7, 28, 'ECC.7.28', 'While my soul was still searching but not finding, among a thousand I have found one upright man, but among all these I have not found one such woman.'),
('ECC', 7, 29, 'ECC.7.29', 'Only this have I found: I have discovered that God made mankind upright, but they have sought out many schemes.”'),
('ECC', 8, 1, 'ECC.8.1', 'Who is like the wise man? Who knows the interpretation of a matter? A man’s wisdom brightens his face, and the sternness of his face is changed.'),
('ECC', 8, 2, 'ECC.8.2', 'Keep the king’s command, I say, because of your oath before God.'),
('ECC', 8, 3, 'ECC.8.3', 'Do not hasten to leave his presence, and do not persist in a bad cause, for he will do whatever he pleases.'),
('ECC', 8, 4, 'ECC.8.4', 'For the king’s word is supreme, and who can say to him, “What are you doing?”'),
('ECC', 8, 5, 'ECC.8.5', 'Whoever keeps his command will come to no harm, and a wise heart knows the right time and procedure.'),
('ECC', 8, 6, 'ECC.8.6', 'For there is a right time and procedure to every purpose, though a man’s misery weighs heavily upon him.'),
('ECC', 8, 7, 'ECC.8.7', 'Since no one knows what will happen, who can tell him what is to come?'),
('ECC', 8, 8, 'ECC.8.8', 'As no man has power over the wind to contain it, so no one has authority over his day of death. As no one can be discharged in wartime, so wickedness will not release those who practice it.'),
('ECC', 8, 9, 'ECC.8.9', 'All this I have seen, applying my mind to every deed that is done under the sun; there is a time when one man lords it over another to his own detriment.'),
('ECC', 8, 10, 'ECC.8.10', 'Then too, I saw the burial of the wicked who used to go in and out of the holy place, and they were praised in the city where they had done so. This too is futile.'),
('ECC', 8, 11, 'ECC.8.11', 'When the sentence for a crime is not speedily executed, the hearts of men become fully set on doing evil.'),
('ECC', 8, 12, 'ECC.8.12', 'Although a sinner does evil a hundred times and still lives long, yet I also know that it will go well with those who fear God, who are reverent in His presence.'),
('ECC', 8, 13, 'ECC.8.13', 'Yet because the wicked do not fear God, it will not go well with them, and their days will not lengthen like a shadow.'),
('ECC', 8, 14, 'ECC.8.14', 'There is a futility that is done on the earth: There are righteous men who get what the actions of the wicked deserve, and there are wicked men who get what the actions of the righteous deserve. I say that this too is futile.'),
('ECC', 8, 15, 'ECC.8.15', 'So I commended the enjoyment of life, because there is nothing better for a man under the sun than to eat and drink and be merry. For this joy will accompany him in his labor during the days of his life that God gives him under the sun.'),
('ECC', 8, 16, 'ECC.8.16', 'When I applied my mind to know wisdom and to observe the task that one performs on the earth—though his eyes do not see sleep in the day or even in the night—'),
('ECC', 8, 17, 'ECC.8.17', 'I saw every work of God, and that a man is unable to comprehend the work that is done under the sun. Despite his efforts to search it out, he cannot find its meaning; even if the wise man claims to know, he is unable to comprehend.'),
('ECC', 9, 1, 'ECC.9.1', 'So I took all this to heart and concluded that the righteous and the wise, as well as their deeds, are in God’s hands. Man does not know what lies ahead, whether love or hate.'),
('ECC', 9, 2, 'ECC.9.2', 'It is the same for all: There is a common fate for the righteous and the wicked, for the good and the bad, for the clean and the unclean, for the one who sacrifices and the one who does not. As it is for the good, so it is for the sinner; as it is for the one who makes a vow, so it is for the one who refuses to take a vow.'),
('ECC', 9, 3, 'ECC.9.3', 'This is an evil in everything that is done under the sun: There is one fate for everyone. Furthermore, the hearts of men are full of evil and madness while they are alive, and afterward they join the dead.'),
('ECC', 9, 4, 'ECC.9.4', 'There is hope, however, for anyone who is among the living; for even a live dog is better than a dead lion.'),
('ECC', 9, 5, 'ECC.9.5', 'For the living know that they will die, but the dead know nothing. They have no further reward, because the memory of them is forgotten.'),
('ECC', 9, 6, 'ECC.9.6', 'Their love, their hate, and their envy have already vanished, and they will never again have a share in all that is done under the sun.'),
('ECC', 9, 7, 'ECC.9.7', 'Go, eat your bread with joy, and drink your wine with a cheerful heart, for God has already approved your works:'),
('ECC', 9, 8, 'ECC.9.8', 'Let your garments always be white, and never spare the oil for your head.'),
('ECC', 9, 9, 'ECC.9.9', 'Enjoy life with your beloved wife all the days of the fleeting life that God has given you under the sun—all your fleeting days. For this is your portion in life and in your labor under the sun.'),
('ECC', 9, 10, 'ECC.9.10', 'Whatever you find to do with your hands, do it with all your might, for in Sheol, where you are going, there is no work or planning or knowledge or wisdom.'),
('ECC', 9, 11, 'ECC.9.11', 'I saw something else under the sun: The race is not to the swift, nor the battle to the strong; neither is the bread to the wise, nor the wealth to the intelligent, nor the favor to the skillful. For time and chance happen to all.'),
('ECC', 9, 12, 'ECC.9.12', 'For surely no man knows his time: Like fish caught in a cruel net or birds trapped in a snare, so men are ensnared in an evil time that suddenly falls upon them.'),
('ECC', 9, 13, 'ECC.9.13', 'I have also seen this wisdom under the sun, and it was great to me:'),
('ECC', 9, 14, 'ECC.9.14', 'There was a small city with few men. A mighty king came against it, surrounded it, and built large siege ramps against it.'),
('ECC', 9, 15, 'ECC.9.15', 'Now a poor wise man was found in the city, and he saved the city by his wisdom. Yet no one remembered that poor man.'),
('ECC', 9, 16, 'ECC.9.16', 'And I said, “Wisdom is better than strength, but the wisdom of the poor man is despised, and his words are not heeded.”'),
('ECC', 9, 17, 'ECC.9.17', 'The calm words of the wise are heeded over the shouts of a ruler among fools.'),
('ECC', 9, 18, 'ECC.9.18', 'Wisdom is better than weapons of war, but one sinner destroys much good.'),
('ECC', 10, 1, 'ECC.10.1', 'As dead flies bring a stench to the perfumer’s oil, so a little folly outweighs wisdom and honor.'),
('ECC', 10, 2, 'ECC.10.2', 'A wise man’s heart inclines to the right, but the heart of a fool to the left.'),
('ECC', 10, 3, 'ECC.10.3', 'Even as the fool walks along the road, his sense is lacking, and he shows everyone that he is a fool.'),
('ECC', 10, 4, 'ECC.10.4', 'If the ruler’s temper flares against you, do not abandon your post, for calmness lays great offenses to rest.'),
('ECC', 10, 5, 'ECC.10.5', 'There is an evil I have seen under the sun—an error that proceeds from the ruler:'),
('ECC', 10, 6, 'ECC.10.6', 'Folly is appointed to great heights, but the rich sit in lowly positions.'),
('ECC', 10, 7, 'ECC.10.7', 'I have seen slaves on horseback, while princes go on foot like slaves.'),
('ECC', 10, 8, 'ECC.10.8', 'He who digs a pit may fall into it, and he who breaches a wall may be bitten by a snake.'),
('ECC', 10, 9, 'ECC.10.9', 'The one who quarries stones may be injured by them, and he who splits logs endangers himself.'),
('ECC', 10, 10, 'ECC.10.10', 'If the axe is dull and the blade unsharpened, more strength must be exerted, but skill produces success.'),
('ECC', 10, 11, 'ECC.10.11', 'If the snake bites before it is charmed, there is no profit for the charmer.'),
('ECC', 10, 12, 'ECC.10.12', 'The words of a wise man’s mouth are gracious, but the lips of a fool consume him.'),
('ECC', 10, 13, 'ECC.10.13', 'The beginning of his talk is folly, and the end of his speech is evil madness.'),
('ECC', 10, 14, 'ECC.10.14', 'Yet the fool multiplies words. No one knows what is coming, and who can tell him what will come after him?'),
('ECC', 10, 15, 'ECC.10.15', 'The toil of a fool wearies him, for he does not know the way to the city.'),
('ECC', 10, 16, 'ECC.10.16', 'Woe to you, O land whose king is a youth, and whose princes feast in the morning.'),
('ECC', 10, 17, 'ECC.10.17', 'Blessed are you, O land whose king is a son of nobles, and whose princes feast at the proper time—for strength and not for drunkenness.'),
('ECC', 10, 18, 'ECC.10.18', 'Through laziness the roof caves in, and in the hands of the idle, the house leaks.'),
('ECC', 10, 19, 'ECC.10.19', 'A feast is prepared for laughter, and wine makes life merry, but money is the answer for everything.'),
('ECC', 10, 20, 'ECC.10.20', 'Do not curse the king even in your thoughts, or curse the rich even in your bedroom, for a bird of the air may carry your words, and a winged creature may report your speech.'),
('ECC', 11, 1, 'ECC.11.1', 'Cast your bread upon the waters, for after many days you will find it again.'),
('ECC', 11, 2, 'ECC.11.2', 'Divide your portion among seven, or even eight, for you do not know what disaster may befall the land.'),
('ECC', 11, 3, 'ECC.11.3', 'If the clouds are full, they will pour out rain upon the earth; whether a tree falls to the south or to the north, in the place where it falls, there it will lie.'),
('ECC', 11, 4, 'ECC.11.4', 'He who watches the wind will fail to sow, and he who observes the clouds will fail to reap.'),
('ECC', 11, 5, 'ECC.11.5', 'As you do not know the path of the wind, or how the bones are formed in a mother’s womb, so you cannot understand the work of God, the Maker of all things.'),
('ECC', 11, 6, 'ECC.11.6', 'Sow your seed in the morning, and do not rest your hands in the evening, for you do not know which will succeed, whether this or that, or if both will equally prosper.'),
('ECC', 11, 7, 'ECC.11.7', 'Light is sweet, and it pleases the eyes to see the sun.'),
('ECC', 11, 8, 'ECC.11.8', 'So if a man lives many years, let him rejoice in them all. But let him remember the days of darkness, for they will be many. Everything to come is futile.'),
('ECC', 11, 9, 'ECC.11.9', 'Rejoice, O young man, while you are young, and let your heart be glad in the days of your youth. Walk in the ways of your heart and in the sight of your eyes, but know that for all these things God will bring you to judgment.'),
('ECC', 11, 10, 'ECC.11.10', 'So banish sorrow from your heart, and cast off pain from your body, for youth and vigor are fleeting.'),
('ECC', 12, 1, 'ECC.12.1', 'Remember your Creator in the days of your youth, before the days of adversity come and the years approach of which you will say, “I find no pleasure in them,”'),
('ECC', 12, 2, 'ECC.12.2', 'before the light of the sun, moon, and stars is darkened, and the clouds return after the rain,'),
('ECC', 12, 3, 'ECC.12.3', 'on the day the keepers of the house tremble and the strong men stoop, when those grinding cease because they are few and those watching through windows see dimly,'),
('ECC', 12, 4, 'ECC.12.4', 'when the doors to the street are shut and the sound of the mill fades away, when one rises at the sound of a bird and all the daughters of song grow faint,'),
('ECC', 12, 5, 'ECC.12.5', 'when men fear the heights and dangers of the road, when the almond tree blossoms, the grasshopper loses its spring, and the caper berry shrivels—for then man goes to his eternal home and mourners walk the streets.'),
('ECC', 12, 6, 'ECC.12.6', 'Remember Him before the silver cord is snapped and the golden bowl is crushed, before the pitcher is shattered at the spring and the wheel is broken at the well,'),
('ECC', 12, 7, 'ECC.12.7', 'before the dust returns to the ground from which it came and the spirit returns to God who gave it.'),
('ECC', 12, 8, 'ECC.12.8', '“Futility of futilities,” says the Teacher. “Everything is futile!”'),
('ECC', 12, 9, 'ECC.12.9', 'Not only was the Teacher wise, but he also taught the people knowledge; he pondered, searched out, and arranged many proverbs.'),
('ECC', 12, 10, 'ECC.12.10', 'The Teacher searched to find delightful sayings and to record accurate words of truth.'),
('ECC', 12, 11, 'ECC.12.11', 'The words of the wise are like goads, and the anthologies of the masters are like firmly embedded nails driven by a single Shepherd.'),
('ECC', 12, 12, 'ECC.12.12', 'And by these, my son, be further warned: There is no end to the making of many books, and much study wearies the body.'),
('ECC', 12, 13, 'ECC.12.13', 'When all has been heard, the conclusion of the matter is this: Fear God and keep His commandments, because this is the whole duty of man.'),
('ECC', 12, 14, 'ECC.12.14', 'For God will bring every deed into judgment, along with every hidden thing, whether good or evil.'),
('SNG', 1, 1, 'SNG.1.1', 'This is Solomon’s Song of Songs.'),
('SNG', 1, 2, 'SNG.1.2', 'Let him kiss me with the kisses of his mouth! For your love is more delightful than wine.'),
('SNG', 1, 3, 'SNG.1.3', 'The fragrance of your perfume is pleasing; your name is like perfume poured out. No wonder the maidens adore you.'),
('SNG', 1, 4, 'SNG.1.4', 'Take me away with you—let us hurry! May the king bring me to his chambers. We will rejoice and delight in you; we will praise your love more than wine. It is only right that they adore you.'),
('SNG', 1, 5, 'SNG.1.5', 'I am dark, yet lovely, O daughters of Jerusalem, like the tents of Kedar, like the curtains of Solomon.'),
('SNG', 1, 6, 'SNG.1.6', 'Do not stare because I am dark, for the sun has gazed upon me. My mother’s sons were angry with me; they made me a keeper of the vineyards, but my own vineyard I have neglected.'),
('SNG', 1, 7, 'SNG.1.7', 'Tell me, O one I love, where do you pasture your sheep? Where do you rest them at midday? Why should I be like a veiled woman beside the flocks of your companions?'),
('SNG', 1, 8, 'SNG.1.8', 'If you do not know, O fairest of women, follow the tracks of the flock, and graze your young goats near the tents of the shepherds.'),
('SNG', 1, 9, 'SNG.1.9', 'I compare you, my darling, to a mare among Pharaoh’s chariots.'),
('SNG', 1, 10, 'SNG.1.10', 'Your cheeks are beautiful with ornaments, your neck with strings of jewels.'),
('SNG', 1, 11, 'SNG.1.11', 'We will make you ornaments of gold, studded with beads of silver.'),
('SNG', 1, 12, 'SNG.1.12', 'While the king was at his table, my perfume spread its fragrance.'),
('SNG', 1, 13, 'SNG.1.13', 'My beloved is to me a sachet of myrrh resting between my breasts.'),
('SNG', 1, 14, 'SNG.1.14', 'My beloved is to me a cluster of henna blossoms in the vineyards of En-gedi.'),
('SNG', 1, 15, 'SNG.1.15', 'How beautiful you are, my darling! Oh, how very beautiful! Your eyes are like doves.'),
('SNG', 1, 16, 'SNG.1.16', 'How handsome you are, my beloved! Oh, how delightful! The soft grass is our bed.'),
('SNG', 1, 17, 'SNG.1.17', 'The beams of our house are cedars; our rafters are fragrant firs.'),
('SNG', 2, 1, 'SNG.2.1', 'I am a rose of Sharon, a lily of the valley.'),
('SNG', 2, 2, 'SNG.2.2', 'Like a lily among the thorns is my darling among the maidens.'),
('SNG', 2, 3, 'SNG.2.3', 'Like an apple tree among the trees of the forest is my beloved among the young men. I delight to sit in his shade, and his fruit is sweet to my taste.'),
('SNG', 2, 4, 'SNG.2.4', 'He has brought me to the house of wine, and his banner over me is love.'),
('SNG', 2, 5, 'SNG.2.5', 'Sustain me with raisins; refresh me with apples, for I am faint with love.'),
('SNG', 2, 6, 'SNG.2.6', 'His left hand is under my head, and his right arm embraces me.'),
('SNG', 2, 7, 'SNG.2.7', 'O daughters of Jerusalem, I adjure you by the gazelles and does of the field: Do not arouse or awaken love until the time is right.'),
('SNG', 2, 8, 'SNG.2.8', 'Listen! My beloved approaches. Look! Here he comes, leaping across the mountains, bounding over the hills.'),
('SNG', 2, 9, 'SNG.2.9', 'My beloved is like a gazelle or a young stag. Look, he stands behind our wall, gazing through the windows, peering through the lattice.'),
('SNG', 2, 10, 'SNG.2.10', 'My beloved calls to me, “Arise, my darling. Come away with me, my beautiful one.'),
('SNG', 2, 11, 'SNG.2.11', 'For now the winter is past; the rain is over and gone.'),
('SNG', 2, 12, 'SNG.2.12', 'The flowers have appeared in the countryside; the season of singing has come, and the cooing of turtledoves is heard in our land.'),
('SNG', 2, 13, 'SNG.2.13', 'The fig tree ripens its figs; the blossoming vines spread their fragrance. Arise, come away, my darling; come away with me, my beautiful one.”'),
('SNG', 2, 14, 'SNG.2.14', 'O my dove in the clefts of the rock, in the crevices of the cliff, let me see your face, let me hear your voice; for your voice is sweet, and your countenance is lovely.'),
('SNG', 2, 15, 'SNG.2.15', 'Catch for us the foxes—the little foxes that ruin the vineyards—for our vineyards are in bloom.'),
('SNG', 2, 16, 'SNG.2.16', 'My beloved is mine and I am his; he pastures his flock among the lilies.'),
('SNG', 2, 17, 'SNG.2.17', 'Before the day breaks and shadows flee, turn, my beloved, and be like a gazelle or a young stag on the mountains of Bether.'),
('SNG', 3, 1, 'SNG.3.1', 'On my bed at night I sought the one I love; I sought him, but did not find him.'),
('SNG', 3, 2, 'SNG.3.2', 'I will arise now and go about the city, through the streets and squares. I will seek the one I love. So I sought him but did not find him.'),
('SNG', 3, 3, 'SNG.3.3', 'I encountered the watchmen on their rounds of the city: “Have you seen the one I love?”'),
('SNG', 3, 4, 'SNG.3.4', 'I had just passed them when I found the one I love. I held him and would not let go until I had brought him to my mother’s house, to the chamber of the one who conceived me.'),
('SNG', 3, 5, 'SNG.3.5', 'O daughters of Jerusalem, I adjure you by the gazelles and does of the field: Do not arouse or awaken love until the time is right.'),
('SNG', 3, 6, 'SNG.3.6', 'Who is this coming up from the wilderness like a column of smoke, scented with myrrh and frankincense from all the spices of the merchant?'),
('SNG', 3, 7, 'SNG.3.7', 'Behold, it is Solomon’s carriage, escorted by sixty of the mightiest men of Israel.'),
('SNG', 3, 8, 'SNG.3.8', 'All are skilled with the sword, experienced in warfare. Each has his sword at his side prepared for the terror of the night.'),
('SNG', 3, 9, 'SNG.3.9', 'King Solomon has made his carriage out of the timber of Lebanon.'),
('SNG', 3, 10, 'SNG.3.10', 'He has made its posts of silver, its base of gold, its seat of purple fabric. Its interior is inlaid with love by the daughters of Jerusalem.'),
('SNG', 3, 11, 'SNG.3.11', 'Come out, O daughters of Zion, and gaze at King Solomon, wearing the crown with which his mother crowned him on the day of his wedding—the day of his heart’s rejoicing.'),
('SNG', 4, 1, 'SNG.4.1', 'How beautiful you are, my darling—how very beautiful! Your eyes are like doves behind your veil. Your hair is like a flock of goats streaming down Mount Gilead.'),
('SNG', 4, 2, 'SNG.4.2', 'Your teeth are like a flock of newly shorn sheep coming up from the washing; each has its twin, and not one of them is lost.'),
('SNG', 4, 3, 'SNG.4.3', 'Your lips are like a scarlet ribbon, and your mouth is lovely. Your brow behind your veil is like a slice of pomegranate.'),
('SNG', 4, 4, 'SNG.4.4', 'Your neck is like the tower of David, built with rows of stones; on it hang a thousand shields, all of them shields of warriors.'),
('SNG', 4, 5, 'SNG.4.5', 'Your breasts are like two fawns, twins of a gazelle grazing among the lilies.'),
('SNG', 4, 6, 'SNG.4.6', 'Before the day breaks and the shadows flee, I will make my way to the mountain of myrrh and to the hill of frankincense.'),
('SNG', 4, 7, 'SNG.4.7', 'You are altogether beautiful, my darling; in you there is no flaw.'),
('SNG', 4, 8, 'SNG.4.8', 'Come with me from Lebanon, my bride, come with me from Lebanon! Descend from the peak of Amana, from the summits of Senir and Hermon, from the dens of the lions, from the mountains of the leopards.'),
('SNG', 4, 9, 'SNG.4.9', 'You have captured my heart, my sister, my bride; you have stolen my heart with one glance of your eyes, with one jewel of your neck.'),
('SNG', 4, 10, 'SNG.4.10', 'How delightful is your love, my sister, my bride! Your love is much better than wine, and the fragrance of your perfume than all spices.'),
('SNG', 4, 11, 'SNG.4.11', 'Your lips, my bride, drip sweetness like the honeycomb; honey and milk are under your tongue, and the fragrance of your garments is like the aroma of Lebanon.'),
('SNG', 4, 12, 'SNG.4.12', 'My sister, my bride, you are a garden locked up, a spring enclosed, a fountain sealed.'),
('SNG', 4, 13, 'SNG.4.13', 'Your branches are an orchard of pomegranates with the choicest of fruits, with henna and nard,'),
('SNG', 4, 14, 'SNG.4.14', 'with nard and saffron, with calamus and cinnamon, with every kind of frankincense tree, with myrrh and aloes, with all the finest spices.'),
('SNG', 4, 15, 'SNG.4.15', 'You are a garden spring, a well of fresh water flowing down from Lebanon.'),
('SNG', 4, 16, 'SNG.4.16', 'Awake, O north wind, and come, O south wind. Breathe on my garden and spread the fragrance of its spices. Let my beloved come into his garden and taste its choicest fruits.'),
('SNG', 5, 1, 'SNG.5.1', 'I have come to my garden, my sister, my bride; I have gathered my myrrh with my spice. I have eaten my honeycomb with my honey; I have drunk my wine with my milk. Eat, O friends, and drink; drink freely, O beloved.'),
('SNG', 5, 2, 'SNG.5.2', 'I sleep, but my heart is awake. A sound! My beloved is knocking: “Open to me, my sister, my darling, my dove, my flawless one. My head is drenched with dew, my hair with the dampness of the night.”'),
('SNG', 5, 3, 'SNG.5.3', 'I have taken off my robe—must I put it back on? I have washed my feet—must I soil them again?'),
('SNG', 5, 4, 'SNG.5.4', 'My beloved put his hand to the latch; my heart pounded for him.'),
('SNG', 5, 5, 'SNG.5.5', 'I rose up to open for my beloved. My hands dripped with myrrh, my fingers with flowing myrrh on the handles of the bolt.'),
('SNG', 5, 6, 'SNG.5.6', 'I opened for my beloved, but he had turned and gone. My heart sank at his departure. I sought him but did not find him. I called, but he did not answer.'),
('SNG', 5, 7, 'SNG.5.7', 'I encountered the watchmen on their rounds of the city. They beat me and bruised me; they took away my cloak, those guardians of the walls.'),
('SNG', 5, 8, 'SNG.5.8', 'O daughters of Jerusalem, I adjure you, if you find my beloved, tell him I am sick with love.'),
('SNG', 5, 9, 'SNG.5.9', 'How is your beloved better than others, O most beautiful among women? How is your beloved better than another, that you charge us so?'),
('SNG', 5, 10, 'SNG.5.10', 'My beloved is dazzling and ruddy, outstanding among ten thousand.'),
('SNG', 5, 11, 'SNG.5.11', 'His head is purest gold; his hair is wavy and black as a raven.'),
('SNG', 5, 12, 'SNG.5.12', 'His eyes are like doves beside the streams of water, bathed in milk and mounted like jewels.'),
('SNG', 5, 13, 'SNG.5.13', 'His cheeks are like beds of spice, towers of perfume. His lips are like lilies, dripping with flowing myrrh.'),
('SNG', 5, 14, 'SNG.5.14', 'His arms are rods of gold set with beryl. His body is polished ivory bedecked with sapphires.'),
('SNG', 5, 15, 'SNG.5.15', 'His legs are pillars of marble set on bases of pure gold. His appearance is like Lebanon, as majestic as the cedars.'),
('SNG', 5, 16, 'SNG.5.16', 'His mouth is most sweet; he is altogether lovely. This is my beloved, and this is my friend, O daughters of Jerusalem.'),
('SNG', 6, 1, 'SNG.6.1', 'Where has your beloved gone, O most beautiful among women? Which way has he turned? We will seek him with you.'),
('SNG', 6, 2, 'SNG.6.2', 'My beloved has gone down to his garden, to the beds of spices, to pasture his flock in the gardens and to gather lilies.'),
('SNG', 6, 3, 'SNG.6.3', 'I belong to my beloved and he belongs to me; he pastures his flock among the lilies.'),
('SNG', 6, 4, 'SNG.6.4', 'You are as beautiful, my darling, as Tirzah, as lovely as Jerusalem, as majestic as troops with banners.'),
('SNG', 6, 5, 'SNG.6.5', 'Turn your eyes away from me, for they have overcome me. Your hair is like a flock of goats streaming down from Gilead.'),
('SNG', 6, 6, 'SNG.6.6', 'Your teeth are like a flock of sheep coming up from the washing; each has its twin, and not one of them is lost.'),
('SNG', 6, 7, 'SNG.6.7', 'Your brow behind your veil is like a slice of pomegranate.'),
('SNG', 6, 8, 'SNG.6.8', 'There are sixty queens and eighty concubines, and maidens without number,'),
('SNG', 6, 9, 'SNG.6.9', 'but my dove, my perfect one, is unique, the favorite of the mother who bore her. The maidens see her and call her blessed; the queens and concubines sing her praises.'),
('SNG', 6, 10, 'SNG.6.10', 'Who is this who shines like the dawn, as fair as the moon, as bright as the sun, as majestic as the stars in procession?'),
('SNG', 6, 11, 'SNG.6.11', 'I went down to the walnut grove to see the blossoms of the valley, to see if the vines were budding or the pomegranates were in bloom.'),
('SNG', 6, 12, 'SNG.6.12', 'Before I realized it, my desire had set me among the royal chariots of my people.'),
('SNG', 6, 13, 'SNG.6.13', 'Come back, come back, O Shulammite! Come back, come back, that we may gaze upon you. Why do you look at the Shulammite, as on the dance of Mahanaim?'),
('SNG', 7, 1, 'SNG.7.1', 'How beautiful are your sandaled feet, O daughter of the prince! The curves of your thighs are like jewels, the handiwork of a master.'),
('SNG', 7, 2, 'SNG.7.2', 'Your navel is a rounded goblet; it never lacks blended wine. Your waist is a mound of wheat encircled by the lilies.'),
('SNG', 7, 3, 'SNG.7.3', 'Your breasts are like two fawns, twins of a gazelle.'),
('SNG', 7, 4, 'SNG.7.4', 'Your neck is like a tower made of ivory; your eyes are like the pools of Heshbon by the gate of Bath-rabbim; your nose is like the tower of Lebanon, facing toward Damascus.'),
('SNG', 7, 5, 'SNG.7.5', 'Your head crowns you like Mount Carmel, the hair of your head like purple threads; the king is captured in your tresses.'),
('SNG', 7, 6, 'SNG.7.6', 'How fair and pleasant you are, O love, with your delights!'),
('SNG', 7, 7, 'SNG.7.7', 'Your stature is like a palm tree; your breasts are clusters of fruit.'),
('SNG', 7, 8, 'SNG.7.8', 'I said, “I will climb the palm tree; I will take hold of its fruit.” May your breasts be like clusters of the vine, the fragrance of your breath like apples,'),
('SNG', 7, 9, 'SNG.7.9', 'and your mouth like the finest wine. May it flow smoothly to my beloved, gliding gently over lips and teeth.'),
('SNG', 7, 10, 'SNG.7.10', 'I belong to my beloved, and his desire is for me.'),
('SNG', 7, 11, 'SNG.7.11', 'Come, my beloved, let us go to the countryside; let us spend the night among the wildflowers.'),
('SNG', 7, 12, 'SNG.7.12', 'Let us go early to the vineyards to see if the vine has budded, if the blossom has opened, if the pomegranates are in bloom—there I will give you my love.'),
('SNG', 7, 13, 'SNG.7.13', 'The mandrakes send forth a fragrance, and at our door is every delicacy, new as well as old, that I have treasured up for you, my beloved.'),
('SNG', 8, 1, 'SNG.8.1', 'O that you were to me like a brother who nursed at my mother’s breasts! If I found you outdoors, I would kiss you, and no one would despise me.'),
('SNG', 8, 2, 'SNG.8.2', 'I would lead you and bring you to the house of my mother who taught me. I would give you spiced wine to drink, the nectar of my pomegranates.'),
('SNG', 8, 3, 'SNG.8.3', 'His left hand is under my head, and his right arm embraces me.'),
('SNG', 8, 4, 'SNG.8.4', 'O daughters of Jerusalem, I adjure you: Do not arouse or awaken love until the time is right.'),
('SNG', 8, 5, 'SNG.8.5', 'Who is this coming up from the wilderness, leaning on her beloved? I roused you under the apple tree; there your mother conceived you; there she travailed and brought you forth.'),
('SNG', 8, 6, 'SNG.8.6', 'Set me as a seal over your heart, as a seal upon your arm. For love is as strong as death, its jealousy as unrelenting as Sheol. Its sparks are fiery flames, the fiercest blaze of all.'),
('SNG', 8, 7, 'SNG.8.7', 'Mighty waters cannot quench love; rivers cannot sweep it away. If a man were to give all the wealth of his house for love, his offer would be utterly scorned.'),
('SNG', 8, 8, 'SNG.8.8', 'We have a little sister, and her breasts are not yet grown. What shall we do for our sister on the day she is spoken for?'),
('SNG', 8, 9, 'SNG.8.9', 'If she is a wall, we will build a tower of silver upon her. If she is a door, we will enclose her with panels of cedar.'),
('SNG', 8, 10, 'SNG.8.10', 'I am a wall, and my breasts are like towers. So I have become in his eyes like one who brings peace.'),
('SNG', 8, 11, 'SNG.8.11', 'Solomon had a vineyard in Baal-hamon. He leased it to the tenants. For its fruit, each was to bring a thousand shekels of silver.'),
('SNG', 8, 12, 'SNG.8.12', 'But my own vineyard is mine to give; the thousand shekels are for you, O Solomon, and two hundred are for those who tend its fruit.'),
('SNG', 8, 13, 'SNG.8.13', 'You who dwell in the gardens, my companions are listening for your voice. Let me hear it!'),
('SNG', 8, 14, 'SNG.8.14', 'Come away, my beloved, and be like a gazelle or a young stag on the mountains of spices.'),
('ISA', 1, 1, 'ISA.1.1', 'This is the vision concerning Judah and Jerusalem that Isaiah son of Amoz saw during the reigns of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.'),
('ISA', 1, 2, 'ISA.1.2', 'Listen, O heavens, and give ear, O earth, for the LORD has spoken: “I have raised children and brought them up, but they have rebelled against Me.'),
('ISA', 1, 3, 'ISA.1.3', 'The ox knows its owner, and the donkey its master’s manger, but Israel does not know; My people do not understand.”'),
('ISA', 1, 4, 'ISA.1.4', 'Alas, O sinful nation, a people laden with iniquity, a brood of evildoers, children who act corruptly! They have forsaken the LORD; they have despised the Holy One of Israel and turned their backs on Him.'),
('ISA', 1, 5, 'ISA.1.5', 'Why do you want more beatings? Why do you keep rebelling? Your head has a massive wound, and your whole heart is afflicted.'),
('ISA', 1, 6, 'ISA.1.6', 'From the sole of your foot to the top of your head, there is no soundness—only wounds and welts and festering sores neither cleansed nor bandaged nor soothed with oil.'),
('ISA', 1, 7, 'ISA.1.7', 'Your land is desolate; your cities are burned with fire. Foreigners devour your fields before you—a desolation demolished by strangers.'),
('ISA', 1, 8, 'ISA.1.8', 'And the Daughter of Zion is abandoned like a shelter in a vineyard, like a shack in a cucumber field, like a city besieged.'),
('ISA', 1, 9, 'ISA.1.9', 'Unless the LORD of Hosts had left us a few survivors, we would have become like Sodom, we would have resembled Gomorrah.'),
('ISA', 1, 10, 'ISA.1.10', 'Hear the word of the LORD, you rulers of Sodom; listen to the instruction of our God, you people of Gomorrah!'),
('ISA', 1, 11, 'ISA.1.11', '“What good to Me is your multitude of sacrifices?” says the LORD. “I am full from the burnt offerings of rams and the fat of well-fed cattle; I take no delight in the blood of bulls and lambs and goats.'),
('ISA', 1, 12, 'ISA.1.12', 'When you come to appear before Me, who has required this of you—this trampling of My courts?'),
('ISA', 1, 13, 'ISA.1.13', 'Bring your worthless offerings no more; your incense is detestable to Me. New Moons, Sabbaths, and convocations—I cannot endure iniquity in a solemn assembly.'),
('ISA', 1, 14, 'ISA.1.14', 'I hate your New Moons and your appointed feasts. They have become a burden to Me; I am weary of bearing them.'),
('ISA', 1, 15, 'ISA.1.15', 'When you spread out your hands in prayer, I will hide My eyes from you; even though you multiply your prayers, I will not listen. Your hands are covered with blood.'),
('ISA', 1, 16, 'ISA.1.16', 'Wash and cleanse yourselves. Remove your evil deeds from My sight. Stop doing evil!'),
('ISA', 1, 17, 'ISA.1.17', 'Learn to do right; seek justice and correct the oppressor. Defend the fatherless and plead the case of the widow.”'),
('ISA', 1, 18, 'ISA.1.18', '“Come now, let us reason together,” says the LORD. “Though your sins are like scarlet, they will be as white as snow; though they are as red as crimson, they will become like wool.'),
('ISA', 1, 19, 'ISA.1.19', 'If you are willing and obedient, you will eat the best of the land.'),
('ISA', 1, 20, 'ISA.1.20', 'But if you resist and rebel, you will be devoured by the sword.” For the mouth of the LORD has spoken.'),
('ISA', 1, 21, 'ISA.1.21', 'See how the faithful city has become a harlot! She once was full of justice; righteousness resided within her, but now only murderers!'),
('ISA', 1, 22, 'ISA.1.22', 'Your silver has become dross; your fine wine is diluted with water.'),
('ISA', 1, 23, 'ISA.1.23', 'Your rulers are rebels, friends of thieves. They all love bribes and chasing after rewards. They do not defend the fatherless, and the plea of the widow never comes before them.'),
('ISA', 1, 24, 'ISA.1.24', 'Therefore the Lord GOD of Hosts, the Mighty One of Israel, declares: “Ah, I will be relieved of My foes and avenge Myself on My enemies.'),
('ISA', 1, 25, 'ISA.1.25', 'I will turn My hand against you; I will thoroughly purge your dross; I will remove all your impurities.'),
('ISA', 1, 26, 'ISA.1.26', 'I will restore your judges as at first, and your counselors as at the beginning. After that you will be called the City of Righteousness, the Faithful City.”'),
('ISA', 1, 27, 'ISA.1.27', 'Zion will be redeemed with justice, her repentant ones with righteousness.'),
('ISA', 1, 28, 'ISA.1.28', 'But rebels and sinners will together be shattered, and those who forsake the LORD will perish.'),
('ISA', 1, 29, 'ISA.1.29', 'Surely you will be ashamed of the sacred oaks in which you have delighted; you will be embarrassed by the gardens that you have chosen.'),
('ISA', 1, 30, 'ISA.1.30', 'For you will become like an oak whose leaves are withered, like a garden without water.'),
('ISA', 1, 31, 'ISA.1.31', 'The strong man will become tinder and his work will be a spark; both will burn together, with no one to quench the flames.'),
('ISA', 2, 1, 'ISA.2.1', 'This is the message that was revealed to Isaiah son of Amoz concerning Judah and Jerusalem:'),
('ISA', 2, 2, 'ISA.2.2', 'In the last days the mountain of the house of the LORD will be established as the chief of the mountains; it will be raised above the hills, and all nations will stream to it.'),
('ISA', 2, 3, 'ISA.2.3', 'And many peoples will come and say: “Come, let us go up to the mountain of the LORD, to the house of the God of Jacob. He will teach us His ways so that we may walk in His paths.” For the law will go forth from Zion, and the word of the LORD from Jerusalem.'),
('ISA', 2, 4, 'ISA.2.4', 'Then He will judge between the nations and arbitrate for many peoples. They will beat their swords into plowshares and their spears into pruning hooks. Nation will no longer take up the sword against nation, nor train anymore for war.'),
('ISA', 2, 5, 'ISA.2.5', 'Come, O house of Jacob, let us walk in the light of the LORD.'),
('ISA', 2, 6, 'ISA.2.6', 'For You have abandoned Your people, the house of Jacob, because they are filled with influences from the east; they are soothsayers like the Philistines; they strike hands with the children of foreigners.'),
('ISA', 2, 7, 'ISA.2.7', 'Their land is full of silver and gold, with no limit to their treasures; their land is full of horses, with no limit to their chariots.'),
('ISA', 2, 8, 'ISA.2.8', 'Their land is full of idols; they bow down to the work of their hands, to what their fingers have made.'),
('ISA', 2, 9, 'ISA.2.9', 'So mankind is brought low, and man is humbled—do not forgive them!'),
('ISA', 2, 10, 'ISA.2.10', 'Go into the rocks and hide in the dust from the terror of the LORD and the splendor of His majesty.'),
('ISA', 2, 11, 'ISA.2.11', 'The proud look of man will be humbled, and the loftiness of men brought low; the LORD alone will be exalted in that day.'),
('ISA', 2, 12, 'ISA.2.12', 'For the Day of the LORD of Hosts will come against all the proud and lofty, against all that is exalted—it will be humbled—'),
('ISA', 2, 13, 'ISA.2.13', 'against all the cedars of Lebanon, lofty and lifted up, against all the oaks of Bashan,'),
('ISA', 2, 14, 'ISA.2.14', 'against all the tall mountains, against all the high hills,'),
('ISA', 2, 15, 'ISA.2.15', 'against every high tower, against every fortified wall,'),
('ISA', 2, 16, 'ISA.2.16', 'against every ship of Tarshish, and against every stately vessel.'),
('ISA', 2, 17, 'ISA.2.17', 'So the pride of man will be brought low, and the loftiness of men will be humbled; the LORD alone will be exalted in that day,'),
('ISA', 2, 18, 'ISA.2.18', 'and the idols will vanish completely.'),
('ISA', 2, 19, 'ISA.2.19', 'Men will flee to caves in the rocks and holes in the ground, away from the terror of the LORD and from the splendor of His majesty, when He rises to shake the earth.'),
('ISA', 2, 20, 'ISA.2.20', 'In that day men will cast away to the moles and bats their idols of silver and gold—the idols they made to worship.'),
('ISA', 2, 21, 'ISA.2.21', 'They will flee to caverns in the rocks and crevices in the cliffs, away from the terror of the LORD and from the splendor of His majesty, when He rises to shake the earth.'),
('ISA', 2, 22, 'ISA.2.22', 'Put no more trust in man, who has only the breath in his nostrils. Of what account is he?'),
('ISA', 3, 1, 'ISA.3.1', 'For behold, the Lord GOD of Hosts is about to remove from Jerusalem and Judah both supply and support: the whole supply of food and water,'),
('ISA', 3, 2, 'ISA.3.2', 'the mighty man and the warrior, the judge and the prophet, the soothsayer and the elder,'),
('ISA', 3, 3, 'ISA.3.3', 'the commander of fifty and the dignitary, the counselor, the cunning magician, and the clever enchanter.'),
('ISA', 3, 4, 'ISA.3.4', '“I will make mere lads their leaders, and children will rule over them.”'),
('ISA', 3, 5, 'ISA.3.5', 'The people will oppress one another, man against man, neighbor against neighbor; the young will rise up against the old, and the base against the honorable.'),
('ISA', 3, 6, 'ISA.3.6', 'A man will seize his brother within his father’s house: “You have a cloak—you be our leader! Take charge of this heap of rubble.”'),
('ISA', 3, 7, 'ISA.3.7', 'On that day he will cry aloud: “I am not a healer. I have no food or clothing in my house. Do not make me leader of the people!”'),
('ISA', 3, 8, 'ISA.3.8', 'For Jerusalem has stumbled and Judah has fallen because they spoke and acted against the LORD, defying His glorious presence.'),
('ISA', 3, 9, 'ISA.3.9', 'The expression on their faces testifies against them, and like Sodom they flaunt their sin; they do not conceal it. Woe to them, for they have brought disaster upon themselves.'),
('ISA', 3, 10, 'ISA.3.10', 'Tell the righteous it will be well with them, for they will enjoy the fruit of their labor.'),
('ISA', 3, 11, 'ISA.3.11', 'Woe to the wicked; disaster is upon them! For they will be repaid with what their hands have done.'),
('ISA', 3, 12, 'ISA.3.12', 'Youths oppress My people, and women rule over them. O My people, your guides mislead you; they turn you from your paths.'),
('ISA', 3, 13, 'ISA.3.13', 'The LORD arises to contend; He stands to judge the people.'),
('ISA', 3, 14, 'ISA.3.14', 'The LORD brings this charge against the elders and leaders of His people: “You have devoured the vineyard; the plunder of the poor is in your houses.'),
('ISA', 3, 15, 'ISA.3.15', 'Why do you crush My people and grind the faces of the poor?” declares the Lord GOD of Hosts.'),
('ISA', 3, 16, 'ISA.3.16', 'The LORD also says: “Because the daughters of Zion are haughty—walking with heads held high and wanton eyes, prancing and skipping as they go, jingling the bracelets on their ankles—'),
('ISA', 3, 17, 'ISA.3.17', 'the Lord will bring sores on the heads of the daughters of Zion, and the LORD will make their foreheads bare.”'),
('ISA', 3, 18, 'ISA.3.18', 'In that day the Lord will take away their finery: their anklets and headbands and crescents;'),
('ISA', 3, 19, 'ISA.3.19', 'their pendants, bracelets, and veils;'),
('ISA', 3, 20, 'ISA.3.20', 'their headdresses, ankle chains, and sashes; their perfume bottles and charms;'),
('ISA', 3, 21, 'ISA.3.21', 'their signet rings and nose rings;'),
('ISA', 3, 22, 'ISA.3.22', 'their festive robes, capes, cloaks, and purses;'),
('ISA', 3, 23, 'ISA.3.23', 'and their mirrors, linen garments, tiaras, and shawls.'),
('ISA', 3, 24, 'ISA.3.24', 'Instead of fragrance there will be a stench; instead of a belt, a rope; instead of styled hair, baldness; instead of fine clothing, sackcloth; instead of beauty, shame.'),
('ISA', 3, 25, 'ISA.3.25', 'Your men will fall by the sword, and your warriors in battle.'),
('ISA', 3, 26, 'ISA.3.26', 'And the gates of Zion will lament and mourn; destitute, she will sit on the ground.'),
('ISA', 4, 1, 'ISA.4.1', 'In that day seven women will take hold of one man and say, “We will eat our own bread and provide our own clothes. Just let us be called by your name. Take away our disgrace!”'),
('ISA', 4, 2, 'ISA.4.2', 'On that day the Branch of the LORD will be beautiful and glorious, and the fruit of the land will be the pride and glory of Israel’s survivors.'),
('ISA', 4, 3, 'ISA.4.3', 'Whoever remains in Zion and whoever is left in Jerusalem will be called holy—all in Jerusalem who are recorded among the living—'),
('ISA', 4, 4, 'ISA.4.4', 'when the Lord has washed away the filth of the daughters of Zion and cleansed the bloodstains from the heart of Jerusalem by a spirit of judgment and a spirit of fire.'),
('ISA', 4, 5, 'ISA.4.5', 'Then the LORD will create over all of Mount Zion and over her assemblies a cloud of smoke by day and a glowing flame of fire by night. For over all the glory there will be a canopy,'),
('ISA', 4, 6, 'ISA.4.6', 'a shelter to give shade from the heat by day, and a refuge and hiding place from the storm and the rain.'),
('ISA', 5, 1, 'ISA.5.1', 'I will sing for my beloved a song of his vineyard: My beloved had a vineyard on a very fertile hill.'),
('ISA', 5, 2, 'ISA.5.2', 'He dug it up and cleared the stones and planted the finest vines. He built a watchtower in the middle and dug out a winepress as well. He waited for the vineyard to yield good grapes, but the fruit it produced was sour!'),
('ISA', 5, 3, 'ISA.5.3', '“And now, O dwellers of Jerusalem and men of Judah, I exhort you to judge between Me and My vineyard.'),
('ISA', 5, 4, 'ISA.5.4', 'What more could have been done for My vineyard than I have done for it? Why, when I expected sweet grapes, did it bring forth sour fruit?'),
('ISA', 5, 5, 'ISA.5.5', 'Now I will tell you what I am about to do to My vineyard: I will take away its hedge, and it will be consumed; I will tear down its wall, and it will be trampled.'),
('ISA', 5, 6, 'ISA.5.6', 'I will make it a wasteland, neither pruned nor cultivated, and thorns and briers will grow up. I will command the clouds that rain shall not fall on it.”'),
('ISA', 5, 7, 'ISA.5.7', 'For the vineyard of the LORD of Hosts is the house of Israel, and the men of Judah are the plant of His delight. He looked for justice, but saw bloodshed; for righteousness, but heard a cry of distress.'),
('ISA', 5, 8, 'ISA.5.8', 'Woe to you who add house to house and join field to field until no place is left and you live alone in the land.'),
('ISA', 5, 9, 'ISA.5.9', 'I heard the LORD of Hosts declare: “Surely many houses will become desolate, great mansions left unoccupied.'),
('ISA', 5, 10, 'ISA.5.10', 'For ten acres of vineyard will yield but a bath of wine, and a homer of seed only an ephah of grain.”'),
('ISA', 5, 11, 'ISA.5.11', 'Woe to those who rise early in the morning in pursuit of strong drink, who linger into the evening, to be inflamed by wine.'),
('ISA', 5, 12, 'ISA.5.12', 'At their feasts are the lyre and harp, tambourines and flutes and wine. They disregard the actions of the LORD and fail to see the work of His hands.'),
('ISA', 5, 13, 'ISA.5.13', 'Therefore My people will go into exile for their lack of understanding; their dignitaries are starving and their masses are parched with thirst.'),
('ISA', 5, 14, 'ISA.5.14', 'Therefore Sheol enlarges its throat and opens wide its enormous jaws, and down go Zion’s nobles and masses, her revelers and carousers!'),
('ISA', 5, 15, 'ISA.5.15', 'So mankind will be brought low, and each man humbled; the arrogant will lower their eyes.'),
('ISA', 5, 16, 'ISA.5.16', 'But the LORD of Hosts will be exalted by His justice, and the holy God will show Himself holy in righteousness.'),
('ISA', 5, 17, 'ISA.5.17', 'Lambs will graze as in their own pastures, and strangers will feed in the ruins of the wealthy.'),
('ISA', 5, 18, 'ISA.5.18', 'Woe to those who draw iniquity with cords of deceit and pull sin along with cart ropes,'),
('ISA', 5, 19, 'ISA.5.19', 'to those who say, “Let Him hurry and hasten His work so that we may see it! Let the plan of the Holy One of Israel come so that we may know it!”'),
('ISA', 5, 20, 'ISA.5.20', 'Woe to those who call evil good and good evil, who turn darkness to light and light to darkness, who replace bitter with sweet and sweet with bitter.'),
('ISA', 5, 21, 'ISA.5.21', 'Woe to those who are wise in their own eyes and clever in their own sight.'),
('ISA', 5, 22, 'ISA.5.22', 'Woe to those who are heroes in drinking wine and champions in mixing strong drink,'),
('ISA', 5, 23, 'ISA.5.23', 'who acquit the guilty for a bribe and deprive the innocent of justice.'),
('ISA', 5, 24, 'ISA.5.24', 'Therefore, as a tongue of fire consumes the straw, and as dry grass shrivels in the flame, so their roots will decay and their blossoms will blow away like dust; for they have rejected the instruction of the LORD of Hosts and despised the word of the Holy One of Israel.'),
('ISA', 5, 25, 'ISA.5.25', 'Therefore the anger of the LORD burns against His people; His hand is raised against them to strike them down. The mountains quake, and the corpses lie like refuse in the streets. Despite all this, His anger is not turned away; His hand is still upraised.'),
('ISA', 5, 26, 'ISA.5.26', 'He lifts a banner for the distant nations and whistles for those at the ends of the earth. Behold—how speedily and swiftly they come!'),
('ISA', 5, 27, 'ISA.5.27', 'None of them grows weary or stumbles; no one slumbers or sleeps. No belt is loose and no sandal strap is broken.'),
('ISA', 5, 28, 'ISA.5.28', 'Their arrows are sharpened, and all their bows are strung. The hooves of their horses are like flint; their chariot wheels are like a whirlwind.'),
('ISA', 5, 29, 'ISA.5.29', 'Their roaring is like that of a lion; they roar like young lions. They growl and seize their prey; they carry it away, and no one can rescue it.'),
('ISA', 5, 30, 'ISA.5.30', 'In that day they will roar over it, like the roaring of the sea. If one looks over the land, he will see darkness and distress; even the light will be obscured by clouds.'),
('ISA', 6, 1, 'ISA.6.1', 'In the year that King Uzziah died, I saw the Lord seated on a throne, high and exalted; and the train of His robe filled the temple.'),
('ISA', 6, 2, 'ISA.6.2', 'Above Him stood seraphim, each having six wings: With two wings they covered their faces, with two they covered their feet, and with two they were flying.'),
('ISA', 6, 3, 'ISA.6.3', 'And they were calling out to one another: “Holy, holy, holy is the LORD of Hosts; all the earth is full of His glory.”'),
('ISA', 6, 4, 'ISA.6.4', 'At the sound of their voices the doorposts and thresholds shook, and the temple was filled with smoke.'),
('ISA', 6, 5, 'ISA.6.5', 'Then I said: “Woe is me, for I am ruined, because I am a man of unclean lips dwelling among a people of unclean lips; for my eyes have seen the King, the LORD of Hosts.”'),
('ISA', 6, 6, 'ISA.6.6', 'Then one of the seraphim flew to me, and in his hand was a glowing coal that he had taken with tongs from the altar.'),
('ISA', 6, 7, 'ISA.6.7', 'And with it he touched my mouth and said: “Now that this has touched your lips, your iniquity is removed and your sin is atoned for.”'),
('ISA', 6, 8, 'ISA.6.8', 'Then I heard the voice of the Lord saying: “Whom shall I send? Who will go for Us?” And I said: “Here am I. Send me!”'),
('ISA', 6, 9, 'ISA.6.9', 'And He replied: “Go and tell this people, ‘Be ever hearing, but never understanding; be ever seeing, but never perceiving.’'),
('ISA', 6, 10, 'ISA.6.10', 'Make the hearts of this people calloused; deafen their ears and close their eyes. Otherwise they might see with their eyes, hear with their ears, understand with their hearts, and turn and be healed.”'),
('ISA', 6, 11, 'ISA.6.11', 'Then I asked: “How long, O Lord?” And He replied: “Until the cities lie ruined and without inhabitant, until the houses are left unoccupied and the land is desolate and ravaged,'),
('ISA', 6, 12, 'ISA.6.12', 'until the LORD has driven men far away and the land is utterly forsaken.'),
('ISA', 6, 13, 'ISA.6.13', 'And though a tenth remains in the land, it will be burned again. As the terebinth and oak leave stumps when felled, so the holy seed will be a stump in the land.”'),
('ISA', 7, 1, 'ISA.7.1', 'Now in the days that Ahaz son of Jotham, the son of Uzziah, was king of Judah, Rezin king of Aram marched up to wage war against Jerusalem. He was accompanied by Pekah son of Remaliah the king of Israel, but he could not overpower the city.'),
('ISA', 7, 2, 'ISA.7.2', 'When it was reported to the house of David that Aram was in league with Ephraim, the hearts of Ahaz and his people trembled like trees in the forest shaken by the wind.'),
('ISA', 7, 3, 'ISA.7.3', 'Then the LORD said to Isaiah, “Go out with your son Shear-jashub to meet Ahaz at the end of the aqueduct that feeds the upper pool, on the road to the Launderer’s Field,'),
('ISA', 7, 4, 'ISA.7.4', 'and say to him: Calm down and be quiet. Do not be afraid or disheartened over these two smoldering stubs of firewood—over the fierce anger of Rezin and Aram and of the son of Remaliah.'),
('ISA', 7, 5, 'ISA.7.5', 'For Aram, along with Ephraim and the son of Remaliah, has plotted your ruin, saying:'),
('ISA', 7, 6, 'ISA.7.6', '‘Let us invade Judah, terrorize it, and divide it among ourselves. Then we can install the son of Tabeal over it as king.’'),
('ISA', 7, 7, 'ISA.7.7', 'But this is what the Lord GOD says: ‘It will not arise; it will not happen.'),
('ISA', 7, 8, 'ISA.7.8', 'For the head of Aram is Damascus, and the head of Damascus is Rezin. Within sixty-five years Ephraim will be shattered as a people.'),
('ISA', 7, 9, 'ISA.7.9', 'The head of Ephraim is Samaria, and the head of Samaria is the son of Remaliah. If you do not stand firm in your faith, then you will not stand at all.’”'),
('ISA', 7, 10, 'ISA.7.10', 'Again the LORD spoke to Ahaz, saying,'),
('ISA', 7, 11, 'ISA.7.11', '“Ask for a sign from the LORD your God, whether from the depths of Sheol or the heights of heaven.”'),
('ISA', 7, 12, 'ISA.7.12', 'But Ahaz replied, “I will not ask; I will not test the LORD.”'),
('ISA', 7, 13, 'ISA.7.13', 'Then Isaiah said, “Hear now, O house of David! Is it not enough to try the patience of men? Will you try the patience of my God as well?'),
('ISA', 7, 14, 'ISA.7.14', 'Therefore the Lord Himself will give you a sign: Behold, the virgin will be with child and give birth to a son, and will call Him Immanuel.'),
('ISA', 7, 15, 'ISA.7.15', 'By the time He knows enough to reject evil and choose good, He will be eating curds and honey.'),
('ISA', 7, 16, 'ISA.7.16', 'For before the boy knows enough to reject evil and choose good, the land of the two kings you dread will be laid waste.'),
('ISA', 7, 17, 'ISA.7.17', 'The LORD will bring on you and on your people and on the house of your father a time unlike any since the day Ephraim separated from Judah—He will bring the king of Assyria.”'),
('ISA', 7, 18, 'ISA.7.18', 'On that day the LORD will whistle to the flies at the farthest streams of the Nile and to the bees in the land of Assyria.'),
('ISA', 7, 19, 'ISA.7.19', 'And they will all come and settle in the steep ravines and clefts of the rocks, in all the thornbushes and watering holes.'),
('ISA', 7, 20, 'ISA.7.20', 'On that day the Lord will use a razor hired from beyond the Euphrates—the king of Assyria—to shave your head and the hair of your legs, and to remove your beard as well.'),
('ISA', 7, 21, 'ISA.7.21', 'On that day a man will raise a young cow and two sheep,'),
('ISA', 7, 22, 'ISA.7.22', 'and from the abundance of milk they give, he will eat curds; for all who remain in the land will eat curds and honey.'),
('ISA', 7, 23, 'ISA.7.23', 'And on that day, in every place that had a thousand vines worth a thousand shekels of silver, only briers and thorns will be found.'),
('ISA', 7, 24, 'ISA.7.24', 'Men will go there with bow and arrow, for the land will be covered with briers and thorns.'),
('ISA', 7, 25, 'ISA.7.25', 'For fear of the briers and thorns, you will no longer traverse the hills once tilled by the hoe; they will become places for oxen to graze and sheep to trample.'),
('ISA', 8, 1, 'ISA.8.1', 'Then the LORD said to me, “Take a large scroll and write on it with an ordinary stylus: Maher-shalal-hash-baz.'),
('ISA', 8, 2, 'ISA.8.2', 'And I will appoint for Myself trustworthy witnesses—Uriah the priest and Zechariah son of Jeberekiah.”'),
('ISA', 8, 3, 'ISA.8.3', 'And I had relations with the prophetess, and she conceived and gave birth to a son. The LORD said to me, “Name him Maher-shalal-hash-baz.'),
('ISA', 8, 4, 'ISA.8.4', 'For before the boy knows how to cry ‘Father’ or ‘Mother,’ the wealth of Damascus and the plunder of Samaria will be carried off by the king of Assyria.”'),
('ISA', 8, 5, 'ISA.8.5', 'And the LORD spoke to me further:'),
('ISA', 8, 6, 'ISA.8.6', '“Because this people has rejected the gently flowing waters of Shiloah and rejoiced in Rezin and the son of Remaliah,'),
('ISA', 8, 7, 'ISA.8.7', 'the Lord will surely bring against them the mighty floodwaters of the Euphrates—the king of Assyria and all his pomp. It will overflow its channels and overrun its banks.'),
('ISA', 8, 8, 'ISA.8.8', 'It will pour into Judah, swirling and sweeping over it, reaching up to the neck; its spreading streams will cover your entire land, O Immanuel!'),
('ISA', 8, 9, 'ISA.8.9', 'Huddle together, O peoples, and be shattered; pay attention, all you distant lands; prepare for battle, and be shattered; prepare for battle, and be shattered!'),
('ISA', 8, 10, 'ISA.8.10', 'Devise a plan, but it will be thwarted; state a proposal, but it will not happen. For God is with us.”'),
('ISA', 8, 11, 'ISA.8.11', 'For this is what the LORD has spoken to me with a strong hand, instructing me not to walk in the way of this people:'),
('ISA', 8, 12, 'ISA.8.12', '“Do not call conspiracy everything these people regard as conspiracy. Do not fear what they fear; do not live in dread.'),
('ISA', 8, 13, 'ISA.8.13', 'The LORD of Hosts is the One you shall regard as holy. Only He should be feared; only He should be dreaded.'),
('ISA', 8, 14, 'ISA.8.14', 'And He will be a sanctuary—but to both houses of Israel a stone of stumbling and a rock of offense, to the dwellers of Jerusalem a trap and a snare.'),
('ISA', 8, 15, 'ISA.8.15', 'Many will stumble over these; they will fall and be broken; they will be ensnared and captured.”'),
('ISA', 8, 16, 'ISA.8.16', 'Bind up the testimony and seal the law among my disciples.'),
('ISA', 8, 17, 'ISA.8.17', 'I will wait for the LORD, who is hiding His face from the house of Jacob. I will put my trust in Him.'),
('ISA', 8, 18, 'ISA.8.18', 'Here am I, and the children the LORD has given me as signs and symbols in Israel from the LORD of Hosts, who dwells on Mount Zion.'),
('ISA', 8, 19, 'ISA.8.19', 'When men tell you to consult mediums and spiritists who whisper and mutter, shouldn’t a people consult their God instead? Why consult the dead on behalf of the living?'),
('ISA', 8, 20, 'ISA.8.20', 'To the law and to the testimony! If they do not speak according to this word, they have no light of dawn.'),
('ISA', 8, 21, 'ISA.8.21', 'They will roam the land, dejected and hungry. When they are famished, they will become enraged; and looking upward, they will curse their king and their God.'),
('ISA', 8, 22, 'ISA.8.22', 'Then they will look to the earth and see only distress and darkness and the gloom of anguish. And they will be driven into utter darkness.'),
('ISA', 9, 1, 'ISA.9.1', 'Nevertheless, there will be no more gloom for those in distress. In the past He humbled the land of Zebulun and the land of Naphtali, but in the future He will honor the Way of the Sea, beyond the Jordan, Galilee of the nations:'),
('ISA', 9, 2, 'ISA.9.2', 'The people walking in darkness have seen a great light; on those living in the land of the shadow of death, a light has dawned.'),
('ISA', 9, 3, 'ISA.9.3', 'You have enlarged the nation and increased its joy. The people rejoice before You as they rejoice at harvest time, as men rejoice in dividing the plunder.'),
('ISA', 9, 4, 'ISA.9.4', 'For as in the day of Midian You have shattered the yoke of their burden, the bar across their shoulders, and the rod of their oppressor.'),
('ISA', 9, 5, 'ISA.9.5', 'For every trampling boot of battle and every garment rolled in blood will be burned as fuel for the fire.'),
('ISA', 9, 6, 'ISA.9.6', 'For unto us a child is born, unto us a son is given, and the government will be upon His shoulders. And He will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.'),
('ISA', 9, 7, 'ISA.9.7', 'Of the increase of His government and peace there will be no end. He will reign on the throne of David and over his kingdom, to establish and sustain it with justice and righteousness from that time and forevermore. The zeal of the LORD of Hosts will accomplish this.'),
('ISA', 9, 8, 'ISA.9.8', 'The Lord has sent a message against Jacob, and it has fallen upon Israel.'),
('ISA', 9, 9, 'ISA.9.9', 'All the people will know it—Ephraim and the dwellers of Samaria. With pride and arrogance of heart they will say:'),
('ISA', 9, 10, 'ISA.9.10', '“The bricks have fallen, but we will rebuild with finished stone; the sycamores have been felled, but we will replace them with cedars.”'),
('ISA', 9, 11, 'ISA.9.11', 'The LORD has raised up the foes of Rezin against him and joined his enemies together.'),
('ISA', 9, 12, 'ISA.9.12', 'Aram from the east and Philistia from the west have devoured Israel with open mouths. Despite all this, His anger is not turned away; His hand is still upraised.'),
('ISA', 9, 13, 'ISA.9.13', 'But the people did not return to Him who struck them; they did not seek the LORD of Hosts.'),
('ISA', 9, 14, 'ISA.9.14', 'So the LORD will cut off Israel’s head and tail, both palm branch and reed in a single day.'),
('ISA', 9, 15, 'ISA.9.15', 'The head is the elder and honorable man, and the tail is the prophet who teaches lies.'),
('ISA', 9, 16, 'ISA.9.16', 'For those who guide this people mislead them, and those they mislead are swallowed up.'),
('ISA', 9, 17, 'ISA.9.17', 'Therefore the Lord takes no pleasure in their young men; He has no compassion on their fatherless and widows. For every one of them is godless and wicked, and every mouth speaks folly. Despite all this, His anger is not turned away; His hand is still upraised.'),
('ISA', 9, 18, 'ISA.9.18', 'For wickedness burns like a fire that consumes the thorns and briers and kindles the forest thickets, which roll upward in billows of smoke.'),
('ISA', 9, 19, 'ISA.9.19', 'By the wrath of the LORD of Hosts the land is scorched, and the people are fuel for the fire. No man even spares his brother.'),
('ISA', 9, 20, 'ISA.9.20', 'They carve out what is on the right, but they are still hungry; they eat what is on the left, but they are still not satisfied. Each one devours the flesh of his own offspring.'),
('ISA', 9, 21, 'ISA.9.21', 'Manasseh devours Ephraim, and Ephraim Manasseh; together they turn against Judah. Despite all this, His anger is not turned away; His hand is still upraised.'),
('ISA', 10, 1, 'ISA.10.1', 'Woe to those who enact unjust statutes and issue oppressive decrees,'),
('ISA', 10, 2, 'ISA.10.2', 'to deprive the poor of fair treatment and withhold justice from the oppressed of My people, to make widows their prey and orphans their plunder.'),
('ISA', 10, 3, 'ISA.10.3', 'What will you do on the day of reckoning when devastation comes from afar? To whom will you flee for help? Where will you leave your wealth?'),
('ISA', 10, 4, 'ISA.10.4', 'Nothing will remain but to crouch among the captives or fall among the slain. Despite all this, His anger is not turned away; His hand is still upraised.'),
('ISA', 10, 5, 'ISA.10.5', 'Woe to Assyria, the rod of My anger; the staff in their hands is My wrath.'),
('ISA', 10, 6, 'ISA.10.6', 'I will send him against a godless nation; I will dispatch him against a people destined for My rage, to take spoils and seize plunder, and to trample them down like clay in the streets.'),
('ISA', 10, 7, 'ISA.10.7', 'But this is not his intention; this is not his plan. For it is in his heart to destroy and cut off many nations.'),
('ISA', 10, 8, 'ISA.10.8', '“Are not all my commanders kings?” he says.'),
('ISA', 10, 9, 'ISA.10.9', '“Is not Calno like Carchemish? Is not Hamath like Arpad? Is not Samaria like Damascus?'),
('ISA', 10, 10, 'ISA.10.10', 'As my hand seized the idolatrous kingdoms whose images surpassed those of Jerusalem and Samaria,'),
('ISA', 10, 11, 'ISA.10.11', 'and as I have done to Samaria and its idols, will I not also do to Jerusalem and her idols?”'),
('ISA', 10, 12, 'ISA.10.12', 'So when the Lord has completed all His work against Mount Zion and Jerusalem, He will say, “I will punish the king of Assyria for the fruit of his arrogant heart and the proud look in his eyes.'),
('ISA', 10, 13, 'ISA.10.13', 'For he says: ‘By the strength of my hand I have done this, and by my wisdom, for I am clever. I have removed the boundaries of nations and plundered their treasures; like a mighty one I subdued their rulers.'),
('ISA', 10, 14, 'ISA.10.14', 'My hand reached as into a nest to seize the wealth of the nations. Like one gathering abandoned eggs, I gathered all the earth. No wing fluttered, no beak opened or chirped.’”'),
('ISA', 10, 15, 'ISA.10.15', 'Does an axe raise itself above the one who swings it? Does a saw boast over him who saws with it? It would be like a rod waving the one who lifts it, or a staff lifting him who is not wood!'),
('ISA', 10, 16, 'ISA.10.16', 'Therefore the Lord GOD of Hosts will send a wasting disease among Assyria’s stout warriors, and under his pomp will be kindled a fire like a burning flame.'),
('ISA', 10, 17, 'ISA.10.17', 'And the Light of Israel will become a fire, and its Holy One a flame. In a single day it will burn and devour Assyria’s thorns and thistles.'),
('ISA', 10, 18, 'ISA.10.18', 'The splendor of its forests and orchards, both soul and body, it will completely destroy, as a sickness consumes a man.'),
('ISA', 10, 19, 'ISA.10.19', 'The remaining trees of its forests will be so few that a child could count them.'),
('ISA', 10, 20, 'ISA.10.20', 'On that day the remnant of Israel and the survivors of the house of Jacob will no longer depend on him who struck them, but they will truly rely on the LORD, the Holy One of Israel.'),
('ISA', 10, 21, 'ISA.10.21', 'A remnant will return—a remnant of Jacob—to the Mighty God.'),
('ISA', 10, 22, 'ISA.10.22', 'Though your people, O Israel, be like the sand of the sea, only a remnant will return. Destruction has been decreed, overflowing with righteousness.'),
('ISA', 10, 23, 'ISA.10.23', 'For the Lord GOD of Hosts will carry out the destruction decreed upon the whole land.'),
('ISA', 10, 24, 'ISA.10.24', 'Therefore this is what the Lord GOD of Hosts says: “O My people who dwell in Zion, do not fear Assyria, who strikes you with a rod and lifts his staff against you as the Egyptians did.'),
('ISA', 10, 25, 'ISA.10.25', 'For in just a little while My fury against you will subside, and My anger will turn to their destruction.”'),
('ISA', 10, 26, 'ISA.10.26', 'And the LORD of Hosts will brandish a whip against them, as when He struck Midian at the rock of Oreb. He will raise His staff over the sea, as He did in Egypt.'),
('ISA', 10, 27, 'ISA.10.27', 'On that day the burden will be lifted from your shoulders, and the yoke from your neck. The yoke will be broken because your neck will be too large.'),
('ISA', 10, 28, 'ISA.10.28', 'Assyria has entered Aiath and passed through Migron, storing their supplies at Michmash.'),
('ISA', 10, 29, 'ISA.10.29', 'They have crossed at the ford: “We will spend the night at Geba.” Ramah trembles; Gibeah of Saul flees.'),
('ISA', 10, 30, 'ISA.10.30', 'Cry aloud, O Daughter of Gallim! Listen, O Laishah! O wretched Anathoth!'),
('ISA', 10, 31, 'ISA.10.31', 'Madmenah flees; the people of Gebim take refuge.'),
('ISA', 10, 32, 'ISA.10.32', 'Yet today they will halt at Nob, shaking a fist at the mount of Daughter Zion, at the hill of Jerusalem.'),
('ISA', 10, 33, 'ISA.10.33', 'Behold, the Lord GOD of Hosts will lop off the branches with terrifying power. The tall trees will be cut down, the lofty ones will be felled.'),
('ISA', 10, 34, 'ISA.10.34', 'He will clear the forest thickets with an axe, and Lebanon will fall before the Mighty One.'),
('ISA', 11, 1, 'ISA.11.1', 'Then a shoot will spring up from the stump of Jesse, and a Branch from his roots will bear fruit.'),
('ISA', 11, 2, 'ISA.11.2', 'The Spirit of the LORD will rest on Him—the Spirit of wisdom and understanding, the Spirit of counsel and strength, the Spirit of knowledge and fear of the LORD.'),
('ISA', 11, 3, 'ISA.11.3', 'And He will delight in the fear of the LORD. He will not judge by what His eyes see, and He will not decide by what His ears hear,'),
('ISA', 11, 4, 'ISA.11.4', 'but with righteousness He will judge the poor, and with equity He will decide for the lowly of the earth. He will strike the earth with the rod of His mouth and slay the wicked with the breath of His lips.'),
('ISA', 11, 5, 'ISA.11.5', 'Righteousness will be the belt around His hips, and faithfulness the sash around His waist.'),
('ISA', 11, 6, 'ISA.11.6', 'The wolf will live with the lamb, and the leopard will lie down with the goat; the calf and young lion and fatling will be together, and a little child will lead them.'),
('ISA', 11, 7, 'ISA.11.7', 'The cow will graze with the bear, their young will lie down together, and the lion will eat straw like the ox.'),
('ISA', 11, 8, 'ISA.11.8', 'The infant will play by the cobra’s den, and the toddler will reach into the viper’s nest.'),
('ISA', 11, 9, 'ISA.11.9', 'They will neither harm nor destroy on all My holy mountain, for the earth will be full of the knowledge of the LORD as the sea is full of water.'),
('ISA', 11, 10, 'ISA.11.10', 'On that day the Root of Jesse will stand as a banner for the peoples. The nations will seek Him, and His place of rest will be glorious.'),
('ISA', 11, 11, 'ISA.11.11', 'On that day the Lord will extend His hand a second time to recover the remnant of His people from Assyria, from Egypt, from Pathros, from Cush, from Elam, from Shinar, from Hamath, and from the islands of the sea.'),
('ISA', 11, 12, 'ISA.11.12', 'He will raise a banner for the nations and gather the exiles of Israel; He will collect the scattered of Judah from the four corners of the earth.'),
('ISA', 11, 13, 'ISA.11.13', 'Then the jealousy of Ephraim will depart, and the adversaries of Judah will be cut off. Ephraim will no longer envy Judah, nor will Judah harass Ephraim.'),
('ISA', 11, 14, 'ISA.11.14', 'They will swoop down on the slopes of the Philistines to the west; together they will plunder the sons of the east. They will lay their hands on Edom and Moab, and the Ammonites will be subject to them.'),
('ISA', 11, 15, 'ISA.11.15', 'The LORD will devote to destruction the gulf of the Sea of Egypt; with a scorching wind He will sweep His hand over the Euphrates. He will split it into seven streams for men to cross with dry sandals.'),
('ISA', 11, 16, 'ISA.11.16', 'There will be a highway for the remnant of His people who remain from Assyria, as there was for Israel when they came up from the land of Egypt.'),
('ISA', 12, 1, 'ISA.12.1', 'In that day you will say: “O LORD, I will praise You. Although You were angry with me, Your anger has turned away, and You have comforted me.'),
('ISA', 12, 2, 'ISA.12.2', 'Surely God is my salvation; I will trust and not be afraid. For the LORD GOD is my strength and my song, and He also has become my salvation.”'),
('ISA', 12, 3, 'ISA.12.3', 'With joy you will draw water from the springs of salvation,'),
('ISA', 12, 4, 'ISA.12.4', 'and on that day you will say: “Give praise to the LORD; proclaim His name! Make His works known among the peoples; declare that His name is exalted.'),
('ISA', 12, 5, 'ISA.12.5', 'Sing to the LORD, for He has done glorious things. Let this be known in all the earth.'),
('ISA', 12, 6, 'ISA.12.6', 'Cry out and sing, O citizen of Zion, for great among you is the Holy One of Israel.”'),
('ISA', 13, 1, 'ISA.13.1', 'This is the burden against Babylon that Isaiah son of Amoz received:'),
('ISA', 13, 2, 'ISA.13.2', 'Raise a banner on a barren hilltop; call aloud to them. Wave your hand, that they may enter the gates of the nobles.'),
('ISA', 13, 3, 'ISA.13.3', 'I have commanded My sanctified ones; I have even summoned My warriors to execute My wrath and exult in My triumph.'),
('ISA', 13, 4, 'ISA.13.4', 'Listen, a tumult on the mountains, like that of a great multitude! Listen, an uproar among the kingdoms, like nations gathered together! The LORD of Hosts is mobilizing an army for war.'),
('ISA', 13, 5, 'ISA.13.5', 'They are coming from faraway lands, from the ends of the heavens—the LORD and the weapons of His wrath—to destroy the whole country.'),
('ISA', 13, 6, 'ISA.13.6', 'Wail, for the Day of the LORD is near; it will come as destruction from the Almighty.'),
('ISA', 13, 7, 'ISA.13.7', 'Therefore all hands will fall limp, and every man’s heart will melt.'),
('ISA', 13, 8, 'ISA.13.8', 'Terror, pain, and anguish will seize them; they will writhe like a woman in labor. They will look at one another, their faces flushed with fear.'),
('ISA', 13, 9, 'ISA.13.9', 'Behold, the Day of the LORD is coming—cruel, with fury and burning anger—to make the earth a desolation and to destroy the sinners within it.'),
('ISA', 13, 10, 'ISA.13.10', 'For the stars of heaven and their constellations will not give their light. The rising sun will be darkened, and the moon will not give its light.'),
('ISA', 13, 11, 'ISA.13.11', 'I will punish the world for its evil and the wicked for their iniquity. I will end the haughtiness of the arrogant and lay low the pride of the ruthless.'),
('ISA', 13, 12, 'ISA.13.12', 'I will make man scarcer than pure gold, and mankind rarer than the gold of Ophir.'),
('ISA', 13, 13, 'ISA.13.13', 'Therefore I will make the heavens tremble, and the earth will be shaken from its place at the wrath of the LORD of Hosts on the day of His burning anger.'),
('ISA', 13, 14, 'ISA.13.14', 'Like a hunted gazelle, like a sheep without a shepherd, each will return to his own people, each will flee to his native land.'),
('ISA', 13, 15, 'ISA.13.15', 'Whoever is caught will be stabbed, and whoever is captured will die by the sword.'),
('ISA', 13, 16, 'ISA.13.16', 'Their infants will be dashed to pieces before their eyes, their houses will be looted, and their wives will be ravished.'),
('ISA', 13, 17, 'ISA.13.17', 'Behold, I will stir up against them the Medes, who have no regard for silver and no desire for gold.'),
('ISA', 13, 18, 'ISA.13.18', 'Their bows will dash young men to pieces; they will have no mercy on the fruit of the womb; they will not look with pity on the children.'),
('ISA', 13, 19, 'ISA.13.19', 'And Babylon, the jewel of the kingdoms, the glory of the pride of the Chaldeans, will be overthrown by God like Sodom and Gomorrah.'),
('ISA', 13, 20, 'ISA.13.20', 'She will never be inhabited or settled from generation to generation; no nomad will pitch his tent there, no shepherd will rest his flock there.'),
('ISA', 13, 21, 'ISA.13.21', 'But desert creatures will lie down there, and howling creatures will fill her houses. Ostriches will dwell there, and wild goats will leap about.'),
('ISA', 13, 22, 'ISA.13.22', 'Hyenas will howl in her fortresses and jackals in her luxurious palaces. Babylon’s time is at hand, and her days will not be prolonged.'),
('ISA', 14, 1, 'ISA.14.1', 'For the LORD will have compassion on Jacob; once again He will choose Israel and settle them in their own land. The foreigner will join them and unite with the house of Jacob.'),
('ISA', 14, 2, 'ISA.14.2', 'The nations will escort Israel and bring it to its homeland. Then the house of Israel will possess the nations as menservants and maidservants in the LORD’s land. They will make captives of their captors and rule over their oppressors.'),
('ISA', 14, 3, 'ISA.14.3', 'On the day that the LORD gives you rest from your pain and torment, and from the hard labor into which you were forced,'),
('ISA', 14, 4, 'ISA.14.4', 'you will sing this song of contempt against the king of Babylon: How the oppressor has ceased, and how his fury has ended!'),
('ISA', 14, 5, 'ISA.14.5', 'The LORD has broken the staff of the wicked, the scepter of the rulers.'),
('ISA', 14, 6, 'ISA.14.6', 'It struck the peoples in anger with unceasing blows; it subdued the nations in rage with relentless persecution.'),
('ISA', 14, 7, 'ISA.14.7', 'All the earth is at peace and at rest; they break out in song.'),
('ISA', 14, 8, 'ISA.14.8', 'Even the cypresses and cedars of Lebanon exult over you: “Since you have been laid low, no woodcutter comes against us.”'),
('ISA', 14, 9, 'ISA.14.9', 'Sheol beneath is eager to meet you upon your arrival. It stirs the spirits of the dead to greet you—all the rulers of the earth. It makes all the kings of the nations rise from their thrones.'),
('ISA', 14, 10, 'ISA.14.10', 'They will all respond to you, saying, “You too have become weak, as we are; you have become like us!”'),
('ISA', 14, 11, 'ISA.14.11', 'Your pomp has been brought down to Sheol, along with the music of your harps. Maggots are your bed and worms your blanket.'),
('ISA', 14, 12, 'ISA.14.12', 'How you have fallen from heaven, O day star, son of the dawn! You have been cut down to the ground, O destroyer of nations.'),
('ISA', 14, 13, 'ISA.14.13', 'You said in your heart: “I will ascend to the heavens; I will raise my throne above the stars of God. I will sit on the mount of assembly, in the far reaches of the north.'),
('ISA', 14, 14, 'ISA.14.14', 'I will ascend above the tops of the clouds; I will make myself like the Most High.”'),
('ISA', 14, 15, 'ISA.14.15', 'But you will be brought down to Sheol, to the lowest depths of the Pit.'),
('ISA', 14, 16, 'ISA.14.16', 'Those who see you will stare; they will ponder your fate: “Is this the man who shook the earth and made the kingdoms tremble,'),
('ISA', 14, 17, 'ISA.14.17', 'who turned the world into a desert and destroyed its cities, who refused to let the captives return to their homes?”'),
('ISA', 14, 18, 'ISA.14.18', 'All the kings of the nations lie in state, each in his own tomb.'),
('ISA', 14, 19, 'ISA.14.19', 'But you are cast out of your grave like a rejected branch, covered by those slain with the sword, and dumped into a rocky pit like a carcass trampled underfoot.'),
('ISA', 14, 20, 'ISA.14.20', 'You will not join them in burial, since you have destroyed your land and slaughtered your own people. The offspring of the wicked will never again be mentioned.'),
('ISA', 14, 21, 'ISA.14.21', 'Prepare a place to slaughter his sons for the iniquities of their forefathers. They will never rise up to possess a land or cover the earth with their cities.'),
('ISA', 14, 22, 'ISA.14.22', '“I will rise up against them,” declares the LORD of Hosts. “I will cut off from Babylon her name and her remnant, her offspring and her posterity,” declares the LORD.'),
('ISA', 14, 23, 'ISA.14.23', '“I will make her a place for owls and for swamplands; I will sweep her away with the broom of destruction,” declares the LORD of Hosts.'),
('ISA', 14, 24, 'ISA.14.24', 'The LORD of Hosts has sworn: “Surely, as I have planned, so will it be; as I have purposed, so will it stand.'),
('ISA', 14, 25, 'ISA.14.25', 'I will break Assyria in My land; I will trample him on My mountain. His yoke will be taken off My people, and his burden removed from their shoulders.”'),
('ISA', 14, 26, 'ISA.14.26', 'This is the plan devised for the whole earth, and this is the hand stretched out over all the nations.'),
('ISA', 14, 27, 'ISA.14.27', 'The LORD of Hosts has purposed, and who can thwart Him? His hand is outstretched, so who can turn it back?'),
('ISA', 14, 28, 'ISA.14.28', 'In the year that King Ahaz died, this burden was received:'),
('ISA', 14, 29, 'ISA.14.29', 'Do not rejoice, all you Philistines, that the rod that struck you is broken. For a viper will spring from the root of the snake, and a flying serpent from its egg.'),
('ISA', 14, 30, 'ISA.14.30', 'Then the firstborn of the poor will find pasture, and the needy will lie down in safety, but I will kill your root by famine, and your remnant will be slain.'),
('ISA', 14, 31, 'ISA.14.31', 'Wail, O gate! Cry out, O city! Melt away, all you Philistines! For a cloud of smoke comes from the north, and there are no stragglers in its ranks.'),
('ISA', 14, 32, 'ISA.14.32', 'What answer will be given to the envoys of that nation? “The LORD has founded Zion, where His afflicted people will find refuge.”'),
('ISA', 15, 1, 'ISA.15.1', 'This is the burden against Moab: Ar in Moab is ruined, destroyed in a night! Kir in Moab is devastated, destroyed in a night!'),
('ISA', 15, 2, 'ISA.15.2', 'Dibon goes up to its temple to weep at its high places. Moab wails over Nebo, as well as over Medeba. Every head is shaved, every beard is cut off.'),
('ISA', 15, 3, 'ISA.15.3', 'In its streets they wear sackcloth; on the rooftops and in the public squares they all wail, falling down weeping.'),
('ISA', 15, 4, 'ISA.15.4', 'Heshbon and Elealeh cry out; their voices are heard as far as Jahaz. Therefore the soldiers of Moab cry out; their souls tremble within.'),
('ISA', 15, 5, 'ISA.15.5', 'My heart cries out over Moab; her fugitives flee as far as Zoar, as far as Eglath-shelishiyah. With weeping they ascend the slope of Luhith; they lament their destruction on the road to Horonaim.'),
('ISA', 15, 6, 'ISA.15.6', 'The waters of Nimrim are dried up, and the grass is withered; the vegetation is gone, and the greenery is no more.'),
('ISA', 15, 7, 'ISA.15.7', 'So they carry their wealth and belongings over the Brook of the Willows.'),
('ISA', 15, 8, 'ISA.15.8', 'For their outcry echoes to the border of Moab. Their wailing reaches Eglaim; it is heard in Beer-elim.'),
('ISA', 15, 9, 'ISA.15.9', 'The waters of Dimon are full of blood, but I will bring more upon Dimon—a lion upon the fugitives of Moab and upon the remnant of the land.'),
('ISA', 16, 1, 'ISA.16.1', 'Send the tribute lambs to the ruler of the land, from Sela in the desert to the mount of Daughter Zion.'),
('ISA', 16, 2, 'ISA.16.2', 'Like fluttering birds pushed out of the nest, so are the daughters of Moab at the fords of the Arnon:'),
('ISA', 16, 3, 'ISA.16.3', '“Give us counsel; render a decision. Shelter us at noonday with shade as dark as night. Hide the refugees; do not betray the one who flees.'),
('ISA', 16, 4, 'ISA.16.4', 'Let my fugitives stay with you; be a refuge for Moab from the destroyer.” When the oppressor has gone, destruction has ceased, and the oppressors have vanished from the land,'),
('ISA', 16, 5, 'ISA.16.5', 'in loving devotion a throne will be established in the tent of David. A judge seeking justice and hastening righteousness will sit on it in faithfulness.'),
('ISA', 16, 6, 'ISA.16.6', 'We have heard of Moab’s pomposity, his exceeding pride and conceit, his overflowing arrogance. But his boasting is empty.'),
('ISA', 16, 7, 'ISA.16.7', 'Therefore let Moab wail; let them wail together for Moab. Moan for the raisin cakes of Kir-hareseth, you who are utterly stricken.'),
('ISA', 16, 8, 'ISA.16.8', 'For the fields of Heshbon have withered, along with the grapevines of Sibmah. The rulers of the nations have trampled its choicest vines, which had reached as far as Jazer and spread toward the desert. Their shoots had spread out and passed over the sea.'),
('ISA', 16, 9, 'ISA.16.9', 'So I weep with Jazer for the vines of Sibmah; I drench Heshbon and Elealeh with my tears. Triumphant shouts have fallen silent over your summer fruit and your harvest.'),
('ISA', 16, 10, 'ISA.16.10', 'Joy and gladness are removed from the orchard; no one sings or shouts in the vineyards. No one tramples the grapes in the winepresses; I have put an end to the cheering.'),
('ISA', 16, 11, 'ISA.16.11', 'Therefore my heart laments for Moab like a harp, my inmost being for Kir-heres.'),
('ISA', 16, 12, 'ISA.16.12', 'When Moab appears on the high place, when he wearies himself and enters his sanctuary to pray, it will do him no good.'),
('ISA', 16, 13, 'ISA.16.13', 'This is the message that the LORD spoke earlier concerning Moab.'),
('ISA', 16, 14, 'ISA.16.14', 'And now the LORD says, “In three years, as a hired worker counts the years, Moab’s splendor will become an object of contempt, with all her many people. And those who are left will be few and feeble.”'),
('ISA', 17, 1, 'ISA.17.1', 'This is the burden against Damascus: “Behold, Damascus is no longer a city; it has become a heap of ruins.'),
('ISA', 17, 2, 'ISA.17.2', 'The cities of Aroer are forsaken; they will be left to the flocks, which will lie down with no one to fear.'),
('ISA', 17, 3, 'ISA.17.3', 'The fortress will disappear from Ephraim, and the sovereignty from Damascus. The remnant of Aram will be like the splendor of the Israelites,” declares the LORD of Hosts.'),
('ISA', 17, 4, 'ISA.17.4', '“In that day the splendor of Jacob will fade, and the fat of his body will waste away,'),
('ISA', 17, 5, 'ISA.17.5', 'as the reaper gathers the standing grain and harvests the ears with his arm, as one gleans heads of grain in the Valley of Rephaim.'),
('ISA', 17, 6, 'ISA.17.6', 'Yet gleanings will remain, like an olive tree that has been beaten—two or three berries atop the tree, four or five on its fruitful branches,” declares the LORD, the God of Israel.'),
('ISA', 17, 7, 'ISA.17.7', 'In that day men will look to their Maker and turn their eyes to the Holy One of Israel.'),
('ISA', 17, 8, 'ISA.17.8', 'They will not look to the altars they have fashioned with their hands or to the Asherahs and incense altars they have made with their fingers.'),
('ISA', 17, 9, 'ISA.17.9', 'In that day their strong cities will be like forsaken thickets and summits, abandoned to the Israelites and to utter desolation.'),
('ISA', 17, 10, 'ISA.17.10', 'For you have forgotten the God of your salvation and failed to remember the Rock of your refuge. Therefore, though you cultivate delightful plots and set out cuttings from exotic vines—'),
('ISA', 17, 11, 'ISA.17.11', 'though on the day you plant you make them grow, and on that morning you help your seed sprout—yet the harvest will vanish on the day of disease and incurable pain.'),
('ISA', 17, 12, 'ISA.17.12', 'Alas, the tumult of many peoples; they rage like the roaring seas and clamoring nations; they rumble like the crashing of mighty waters.'),
('ISA', 17, 13, 'ISA.17.13', 'The nations rage like the rush of many waters. He rebukes them, and they flee far away, driven before the wind like chaff on the hills, like tumbleweeds before a gale.'),
('ISA', 17, 14, 'ISA.17.14', 'In the evening, there is sudden terror! Before morning, they are no more! This is the portion of those who loot us and the lot of those who plunder us.'),
('ISA', 18, 1, 'ISA.18.1', 'Woe to the land of whirring wings, along the rivers of Cush,'),
('ISA', 18, 2, 'ISA.18.2', 'which sends couriers by sea, in papyrus vessels on the waters. Go, swift messengers, to a people tall and smooth-skinned, to a people widely feared, to a powerful nation of strange speech, whose land is divided by rivers.'),
('ISA', 18, 3, 'ISA.18.3', 'All you people of the world and dwellers of the earth, when a banner is raised on the mountains, you will see it; when a ram’s horn sounds, you will hear it.'),
('ISA', 18, 4, 'ISA.18.4', 'For this is what the LORD has told me: “I will quietly look on from My dwelling place, like shimmering heat in the sunshine, like a cloud of dew in the heat of harvest.”'),
('ISA', 18, 5, 'ISA.18.5', 'For before the harvest, when the blossom is gone and the flower becomes a ripening grape, He will cut off the shoots with a pruning knife and remove and discard the branches.'),
('ISA', 18, 6, 'ISA.18.6', 'They will all be left to the mountain birds of prey, and to the beasts of the land. The birds will feed on them in summer, and all the wild animals in winter.'),
('ISA', 18, 7, 'ISA.18.7', 'At that time gifts will be brought to the LORD of Hosts—from a people tall and smooth-skinned, from a people widely feared, from a powerful nation of strange speech, whose land is divided by rivers—to Mount Zion, the place of the Name of the LORD of Hosts.'),
('ISA', 19, 1, 'ISA.19.1', 'This is the burden against Egypt: Behold, the LORD rides on a swift cloud; He is coming to Egypt. The idols of Egypt will tremble before Him, and the hearts of the Egyptians will melt within them.'),
('ISA', 19, 2, 'ISA.19.2', '“So I will incite Egyptian against Egyptian; brother will fight against brother, neighbor against neighbor, city against city, and kingdom against kingdom.'),
('ISA', 19, 3, 'ISA.19.3', 'Then the spirit of the Egyptians will be emptied out from among them, and I will frustrate their plans, so that they will resort to idols and spirits of the dead, to mediums and spiritists.'),
('ISA', 19, 4, 'ISA.19.4', 'I will deliver the Egyptians into the hands of a harsh master, and a fierce king will rule over them,” declares the Lord GOD of Hosts.'),
('ISA', 19, 5, 'ISA.19.5', 'The waters of the Nile will dry up, and the riverbed will be parched and empty.'),
('ISA', 19, 6, 'ISA.19.6', 'The canals will stink; the streams of Egypt will trickle and dry up; the reeds and rushes will wither.'),
('ISA', 19, 7, 'ISA.19.7', 'The bulrushes by the Nile, by the mouth of the river, and all the fields sown along the Nile, will wither, blow away, and be no more.'),
('ISA', 19, 8, 'ISA.19.8', 'Then the fishermen will mourn, all who cast a hook into the Nile will lament, and those who spread nets on the waters will pine away.'),
('ISA', 19, 9, 'ISA.19.9', 'The workers in flax will be dismayed, and the weavers of fine linen will turn pale.'),
('ISA', 19, 10, 'ISA.19.10', 'The workers in cloth will be dejected, and all the hired workers will be sick at heart.'),
('ISA', 19, 11, 'ISA.19.11', 'The princes of Zoan are mere fools; Pharaoh’s wise counselors give senseless advice. How can you say to Pharaoh, “I am one of the wise, a son of eastern kings”?'),
('ISA', 19, 12, 'ISA.19.12', 'Where are your wise men now? Let them tell you and reveal what the LORD of Hosts has planned against Egypt.'),
('ISA', 19, 13, 'ISA.19.13', 'The princes of Zoan have become fools; the princes of Memphis are deceived. The cornerstones of her tribes have led Egypt astray.'),
('ISA', 19, 14, 'ISA.19.14', 'The LORD has poured into her a spirit of confusion. Egypt has been led astray in all she does, as a drunkard staggers through his own vomit.'),
('ISA', 19, 15, 'ISA.19.15', 'There is nothing Egypt can do—head or tail, palm or reed.'),
('ISA', 19, 16, 'ISA.19.16', 'In that day the Egyptians will be like women. They will tremble with fear beneath the uplifted hand of the LORD of Hosts, when He brandishes it against them.'),
('ISA', 19, 17, 'ISA.19.17', 'The land of Judah will bring terror to Egypt; whenever Judah is mentioned, Egypt will tremble over what the LORD of Hosts has planned against it.'),
('ISA', 19, 18, 'ISA.19.18', 'In that day five cities in the land of Egypt will speak the language of Canaan and swear allegiance to the LORD of Hosts. One of them will be called the City of the Sun.'),
('ISA', 19, 19, 'ISA.19.19', 'In that day there will be an altar to the LORD in the center of the land of Egypt, and a pillar to the LORD near her border.'),
('ISA', 19, 20, 'ISA.19.20', 'It will be a sign and a witness to the LORD of Hosts in the land of Egypt. When they cry out to the LORD because of their oppressors, He will send them a savior and defender to rescue them.'),
('ISA', 19, 21, 'ISA.19.21', 'The LORD will make Himself known to Egypt, and on that day Egypt will acknowledge the LORD. They will worship with sacrifices and offerings; they will make vows to the LORD and fulfill them.'),
('ISA', 19, 22, 'ISA.19.22', 'And the LORD will strike Egypt with a plague; He will strike them but heal them. They will turn to the LORD, and He will hear their prayers and heal them.'),
('ISA', 19, 23, 'ISA.19.23', 'In that day there will be a highway from Egypt to Assyria. The Assyrians will go to Egypt, and the Egyptians to Assyria. The Egyptians and Assyrians will worship together.'),
('ISA', 19, 24, 'ISA.19.24', 'In that day Israel will join a three-party alliance with Egypt and Assyria—a blessing upon the earth.'),
('ISA', 19, 25, 'ISA.19.25', 'The LORD of Hosts will bless them, saying, “Blessed be Egypt My people, Assyria My handiwork, and Israel My inheritance.”'),
('ISA', 20, 1, 'ISA.20.1', 'Before the year that the chief commander, sent by Sargon king of Assyria, came to Ashdod and attacked and captured it,'),
('ISA', 20, 2, 'ISA.20.2', 'the LORD had already spoken through Isaiah son of Amoz, saying, “Go, remove the sackcloth from your waist and the sandals from your feet.” And Isaiah did so, walking around naked and barefoot.'),
('ISA', 20, 3, 'ISA.20.3', 'Then the LORD said, “Just as My servant Isaiah has gone naked and barefoot for three years as a sign and omen against Egypt and Cush,'),
('ISA', 20, 4, 'ISA.20.4', 'so the king of Assyria will lead away the captives of Egypt and the exiles of Cush, young and old alike, naked and barefoot, with bared buttocks—to Egypt’s shame.'),
('ISA', 20, 5, 'ISA.20.5', 'Those who made Cush their hope and Egypt their boast will be dismayed and ashamed.'),
('ISA', 20, 6, 'ISA.20.6', 'And on that day the dwellers of this coastland will say, ‘See what has happened to our source of hope, those to whom we fled for help and deliverance from the king of Assyria! How then can we escape?’”'),
('ISA', 21, 1, 'ISA.21.1', 'This is the burden against the Desert by the Sea: Like whirlwinds sweeping through the Negev, an invader comes from the desert, from a land of terror.'),
('ISA', 21, 2, 'ISA.21.2', 'A dire vision is declared to me: “The traitor still betrays, and the destroyer still destroys. Go up, O Elam! Lay siege, O Media! I will put an end to all her groaning.”'),
('ISA', 21, 3, 'ISA.21.3', 'Therefore my body is filled with anguish. Pain grips me, like the pains of a woman in labor. I am bewildered to hear, I am dismayed to see.'),
('ISA', 21, 4, 'ISA.21.4', 'My heart falters; fear makes me tremble. The twilight I desired has turned to horror.'),
('ISA', 21, 5, 'ISA.21.5', 'They prepare a table, they lay out a carpet, they eat, they drink! Rise up, O princes, oil the shields!'),
('ISA', 21, 6, 'ISA.21.6', 'For this is what the Lord says to me: “Go, post a lookout and have him report what he sees.'),
('ISA', 21, 7, 'ISA.21.7', 'When he sees chariots with teams of horsemen, riders on donkeys, riders on camels, he must be alert, fully alert.”'),
('ISA', 21, 8, 'ISA.21.8', 'Then the lookout shouted: “Day after day, my lord, I stand on the watchtower; night after night I stay at my post.'),
('ISA', 21, 9, 'ISA.21.9', 'Look, here come the riders, horsemen in pairs.” And one answered, saying: “Fallen, fallen is Babylon! All the images of her gods lie shattered on the ground!”'),
('ISA', 21, 10, 'ISA.21.10', 'O my people, crushed on the threshing floor, I tell you what I have heard from the LORD of Hosts, the God of Israel.'),
('ISA', 21, 11, 'ISA.21.11', 'This is the burden against Dumah: One calls to me from Seir, “Watchman, what is left of the night? Watchman, what is left of the night?”'),
('ISA', 21, 12, 'ISA.21.12', 'The watchman replies, “Morning has come, but also the night. If you would inquire, then inquire. Come back yet again.”'),
('ISA', 21, 13, 'ISA.21.13', 'This is the burden against Arabia: In the thickets of Arabia you must lodge, O caravans of Dedanites.'),
('ISA', 21, 14, 'ISA.21.14', 'Bring water for the thirsty, O dwellers of Tema; meet the refugees with food.'),
('ISA', 21, 15, 'ISA.21.15', 'For they flee from the sword—the sword that is drawn—from the bow that is bent, and from the stress of battle.'),
('ISA', 21, 16, 'ISA.21.16', 'For this is what the Lord says to me: “Within one year, as a hired worker would count it, all the glory of Kedar will be gone.'),
('ISA', 21, 17, 'ISA.21.17', 'The remaining archers, the warriors of Kedar, will be few.” For the LORD, the God of Israel, has spoken.'),
('ISA', 22, 1, 'ISA.22.1', 'This is the burden against the Valley of Vision: What ails you now, that you have all gone up to the rooftops,'),
('ISA', 22, 2, 'ISA.22.2', 'O city of commotion, O town of revelry? Your slain did not die by the sword, nor were they killed in battle.'),
('ISA', 22, 3, 'ISA.22.3', 'All your rulers have fled together, captured without a bow. All your fugitives were captured together, having fled to a distant place.'),
('ISA', 22, 4, 'ISA.22.4', 'Therefore I said, “Turn away from me, let me weep bitterly! Do not try to console me over the destruction of the daughter of my people.”'),
('ISA', 22, 5, 'ISA.22.5', 'For the Lord GOD of Hosts has set a day of tumult and trampling and confusion in the Valley of Vision—of breaking down the walls and crying to the mountains.'),
('ISA', 22, 6, 'ISA.22.6', 'Elam takes up a quiver, with chariots and horsemen, and Kir uncovers the shield.'),
('ISA', 22, 7, 'ISA.22.7', 'Your choicest valleys are full of chariots, and horsemen are posted at the gates.'),
('ISA', 22, 8, 'ISA.22.8', 'He has uncovered the defenses of Judah. On that day you looked to the weapons in the House of the Forest.'),
('ISA', 22, 9, 'ISA.22.9', 'You saw that there were many breaches in the walls of the City of David. You collected water from the lower pool.'),
('ISA', 22, 10, 'ISA.22.10', 'You counted the houses of Jerusalem and tore them down to strengthen the wall.'),
('ISA', 22, 11, 'ISA.22.11', 'You built a reservoir between the walls for the waters of the ancient pool, but you did not look to the One who made it, or consider Him who planned it long ago.'),
('ISA', 22, 12, 'ISA.22.12', 'On that day the Lord GOD of Hosts called for weeping and wailing, for shaven heads and the wearing of sackcloth.'),
('ISA', 22, 13, 'ISA.22.13', 'But look, there is joy and gladness, butchering of cattle and slaughtering of sheep, eating of meat and drinking of wine: “Let us eat and drink, for tomorrow we die!”'),
('ISA', 22, 14, 'ISA.22.14', 'The LORD of Hosts has revealed in my hearing: “Until your dying day, this sin of yours will never be atoned for,” says the Lord GOD of Hosts.'),
('ISA', 22, 15, 'ISA.22.15', 'This is what the Lord GOD of Hosts says: “Go, say to Shebna, the steward in charge of the palace:'),
('ISA', 22, 16, 'ISA.22.16', 'What are you doing here, and who authorized you to carve out a tomb for yourself here—to chisel your tomb in the height and cut your resting place in the rock?'),
('ISA', 22, 17, 'ISA.22.17', 'Look, O mighty man! The LORD is about to shake you violently. He will take hold of you,'),
('ISA', 22, 18, 'ISA.22.18', 'roll you into a ball, and sling you into a wide land. There you will die, and there your glorious chariots will remain—a disgrace to the house of your master.'),
('ISA', 22, 19, 'ISA.22.19', 'I will remove you from office, and you will be ousted from your position.'),
('ISA', 22, 20, 'ISA.22.20', 'On that day I will summon My servant, Eliakim son of Hilkiah.'),
('ISA', 22, 21, 'ISA.22.21', 'I will clothe him with your robe and tie your sash around him. I will put your authority in his hand, and he will be a father to the dwellers of Jerusalem and to the house of Judah.'),
('ISA', 22, 22, 'ISA.22.22', 'I will place on his shoulder the key to the house of David. What he opens no one can shut, and what he shuts no one can open.'),
('ISA', 22, 23, 'ISA.22.23', 'I will drive him like a peg into a firm place, and he will be a throne of glory for the house of his father.'),
('ISA', 22, 24, 'ISA.22.24', 'So they will hang on him all the glory of his father’s house: the descendants and the offshoots—all the lesser vessels, from bowls to every kind of jar.'),
('ISA', 22, 25, 'ISA.22.25', 'In that day, declares the LORD of Hosts, the peg driven into a firm place will give way; it will be sheared off and fall, and the load upon it will be cut down.” Indeed, the LORD has spoken.'),
('ISA', 23, 1, 'ISA.23.1', 'This is the burden against Tyre: Wail, O ships of Tarshish, for Tyre is laid waste, without house or harbor. Word has reached them from the land of Cyprus.'),
('ISA', 23, 2, 'ISA.23.2', 'Be silent, O dwellers of the coastland, you merchants of Sidon, whose traders have crossed the sea.'),
('ISA', 23, 3, 'ISA.23.3', 'On the great waters came the grain of Shihor; the harvest of the Nile was the revenue of Tyre; she was the merchant of the nations.'),
('ISA', 23, 4, 'ISA.23.4', 'Be ashamed, O Sidon, the stronghold of the sea, for the sea has spoken: “I have not been in labor or given birth. I have not raised young men or brought up young women.”'),
('ISA', 23, 5, 'ISA.23.5', 'When the report reaches Egypt, they will writhe in agony over the news of Tyre.'),
('ISA', 23, 6, 'ISA.23.6', 'Cross over to Tarshish; wail, O inhabitants of the coastland!'),
('ISA', 23, 7, 'ISA.23.7', 'Is this your jubilant city, whose origin is from antiquity, whose feet have taken her to settle far away?'),
('ISA', 23, 8, 'ISA.23.8', 'Who planned this against Tyre, the bestower of crowns, whose traders are princes, whose merchants are renowned on the earth?'),
('ISA', 23, 9, 'ISA.23.9', 'The LORD of Hosts planned it, to defile all its glorious beauty, to disgrace all the renowned of the earth.'),
('ISA', 23, 10, 'ISA.23.10', 'Cultivate your land like the Nile, O Daughter of Tarshish; there is no longer a harbor.'),
('ISA', 23, 11, 'ISA.23.11', 'The LORD has stretched out His hand over the sea; He has made kingdoms tremble. He has given a command that the strongholds of Canaan be destroyed.'),
('ISA', 23, 12, 'ISA.23.12', 'He said, “You shall rejoice no more, O oppressed Virgin Daughter of Sidon. Get up and cross over to Cyprus—even there you will find no rest.”'),
('ISA', 23, 13, 'ISA.23.13', 'Look at the land of the Chaldeans—a people now of no account. The Assyrians destined it for the desert creatures; they set up their siege towers and stripped its palaces. They brought it to ruin.'),
('ISA', 23, 14, 'ISA.23.14', 'Wail, O ships of Tarshish, for your harbor has been destroyed!'),
('ISA', 23, 15, 'ISA.23.15', 'At that time Tyre will be forgotten for seventy years—the span of a king’s life. But at the end of seventy years, it will happen to Tyre as in the song of the harlot:'),
('ISA', 23, 16, 'ISA.23.16', '“Take up your harp, stroll through the city, O forgotten harlot. Make sweet melody, sing many a song, so you will be remembered.”'),
('ISA', 23, 17, 'ISA.23.17', 'And at the end of seventy years, the LORD will restore Tyre. Then she will return to hire as a prostitute and sell herself to all the kingdoms on the face of the earth.'),
('ISA', 23, 18, 'ISA.23.18', 'Yet her profits and wages will be set apart to the LORD; they will not be stored or saved, for her profit will go to those who live before the LORD, for abundant food and fine clothing.'),
('ISA', 24, 1, 'ISA.24.1', 'Behold, the LORD lays waste the earth and leaves it in ruins. He will twist its surface and scatter its inhabitants—'),
('ISA', 24, 2, 'ISA.24.2', 'people and priest alike, servant and master, maid and mistress, buyer and seller, lender and borrower, creditor and debtor.'),
('ISA', 24, 3, 'ISA.24.3', 'The earth will be utterly laid waste and thoroughly plundered. For the LORD has spoken this word.'),
('ISA', 24, 4, 'ISA.24.4', 'The earth mourns and withers; the world languishes and fades; the exalted of the earth waste away.'),
('ISA', 24, 5, 'ISA.24.5', 'The earth is defiled by its people; they have transgressed the laws; they have overstepped the decrees and broken the everlasting covenant.'),
('ISA', 24, 6, 'ISA.24.6', 'Therefore a curse has consumed the earth, and its inhabitants must bear the guilt; the earth’s dwellers have been burned, and only a few survive.'),
('ISA', 24, 7, 'ISA.24.7', 'The new wine dries up, the vine withers. All the merrymakers now groan.'),
('ISA', 24, 8, 'ISA.24.8', 'The joyful tambourines have ceased; the noise of revelers has stopped; the joyful harp is silent.'),
('ISA', 24, 9, 'ISA.24.9', 'They no longer sing and drink wine; strong drink is bitter to those who consume it.'),
('ISA', 24, 10, 'ISA.24.10', 'The city of chaos is shattered; every house is closed to entry.'),
('ISA', 24, 11, 'ISA.24.11', 'In the streets they cry out for wine. All joy turns to gloom; rejoicing is exiled from the land.'),
('ISA', 24, 12, 'ISA.24.12', 'The city is left in ruins; its gate is reduced to rubble.'),
('ISA', 24, 13, 'ISA.24.13', 'So will it be on the earth and among the nations, like a harvested olive tree, like a gleaning after a grape harvest.'),
('ISA', 24, 14, 'ISA.24.14', 'They raise their voices, they shout for joy; from the west they proclaim the majesty of the LORD.'),
('ISA', 24, 15, 'ISA.24.15', 'Therefore glorify the LORD in the east. Extol the name of the LORD, the God of Israel in the islands of the sea.'),
('ISA', 24, 16, 'ISA.24.16', 'From the ends of the earth we hear singing: “Glory to the Righteous One.” But I said, “I am wasting away! I am wasting away! Woe is me.” The treacherous betray; the treacherous deal in treachery.'),
('ISA', 24, 17, 'ISA.24.17', 'Terror and pit and snare await you, O dweller of the earth.'),
('ISA', 24, 18, 'ISA.24.18', 'Whoever flees the sound of panic will fall into the pit, and whoever climbs from the pit will be caught in the snare. For the windows of heaven are open, and the foundations of the earth are shaken.'),
('ISA', 24, 19, 'ISA.24.19', 'The earth is utterly broken apart, the earth is split open, the earth is shaken violently.'),
('ISA', 24, 20, 'ISA.24.20', 'The earth staggers like a drunkard and sways like a shack. Earth’s rebellion weighs it down, and it falls, never to rise again.'),
('ISA', 24, 21, 'ISA.24.21', 'In that day the LORD will punish the host of heaven above and the kings of the earth below.'),
('ISA', 24, 22, 'ISA.24.22', 'They will be gathered together like prisoners in a pit. They will be confined to a dungeon and punished after many days.'),
('ISA', 24, 23, 'ISA.24.23', 'The moon will be confounded and the sun will be ashamed; for the LORD of Hosts will reign on Mount Zion and in Jerusalem, and before His elders with great glory.'),
('ISA', 25, 1, 'ISA.25.1', 'O LORD, You are my God! I will exalt You; I will praise Your name. For You have worked wonders—plans formed long ago—in perfect faithfulness.'),
('ISA', 25, 2, 'ISA.25.2', 'Indeed, You have made the city a heap of rubble, the fortified town a ruin. The fortress of strangers is a city no more; it will never be rebuilt.'),
('ISA', 25, 3, 'ISA.25.3', 'Therefore, a strong people will honor You. The cities of ruthless nations will revere You.'),
('ISA', 25, 4, 'ISA.25.4', 'For You have been a refuge for the poor, a stronghold for the needy in distress, a refuge from the storm, a shade from the heat. For the breath of the ruthless is like rain against a wall,'),
('ISA', 25, 5, 'ISA.25.5', 'like heat in a dry land. You subdue the uproar of foreigners. As the shade of a cloud cools the heat, so the song of the ruthless is silenced.'),
('ISA', 25, 6, 'ISA.25.6', 'On this mountain the LORD of Hosts will prepare a lavish banquet for all the peoples, a feast of aged wine, of choice meat, of finely aged wine.'),
('ISA', 25, 7, 'ISA.25.7', 'On this mountain He will swallow up the shroud that enfolds all peoples, the sheet that covers all nations;'),
('ISA', 25, 8, 'ISA.25.8', 'He will swallow up death forever. The Lord GOD will wipe away the tears from every face and remove the disgrace of His people from the whole earth. For the LORD has spoken.'),
('ISA', 25, 9, 'ISA.25.9', 'And in that day it will be said, “Surely this is our God; we have waited for Him, and He has saved us. This is the LORD for whom we have waited. Let us rejoice and be glad in His salvation.”'),
('ISA', 25, 10, 'ISA.25.10', 'For the hand of the LORD will rest on this mountain. But Moab will be trampled in his place as straw is trodden into the dung pile.'),
('ISA', 25, 11, 'ISA.25.11', 'He will spread out his hands within it, as a swimmer spreads his arms to swim. His pride will be brought low, despite the skill of his hands.'),
('ISA', 25, 12, 'ISA.25.12', 'The high-walled fortress will be brought down, cast to the ground, into the dust.'),
('ISA', 26, 1, 'ISA.26.1', 'In that day this song will be sung in the land of Judah: We have a strong city; salvation is established as its walls and ramparts.'),
('ISA', 26, 2, 'ISA.26.2', 'Open the gates so a righteous nation may enter—one that remains faithful.'),
('ISA', 26, 3, 'ISA.26.3', 'You will keep in perfect peace the steadfast of mind, because he trusts in You.'),
('ISA', 26, 4, 'ISA.26.4', 'Trust in the LORD forever, because GOD the LORD is the Rock eternal.'),
('ISA', 26, 5, 'ISA.26.5', 'For He has humbled those who dwell on high; He lays the lofty city low. He brings it down to the ground; He casts it into the dust.'),
('ISA', 26, 6, 'ISA.26.6', 'Feet trample it down—the feet of the oppressed, the steps of the poor.'),
('ISA', 26, 7, 'ISA.26.7', 'The path of the righteous is level; You clear a straight path for the upright.'),
('ISA', 26, 8, 'ISA.26.8', 'Yes, we wait for You, O LORD; we walk in the path of Your judgments. Your name and renown are the desire of our souls.'),
('ISA', 26, 9, 'ISA.26.9', 'My soul longs for You in the night; indeed, my spirit seeks You at dawn. For when Your judgments come upon the earth, the people of the world learn righteousness.'),
('ISA', 26, 10, 'ISA.26.10', 'Though grace is shown to the wicked man, he does not learn righteousness. In the land of righteousness he acts unjustly and fails to see the majesty of the LORD.'),
('ISA', 26, 11, 'ISA.26.11', 'O LORD, Your hand is upraised, but they do not see it. They will see Your zeal for Your people and be put to shame. The fire set for Your enemies will consume them!'),
('ISA', 26, 12, 'ISA.26.12', 'O LORD, You will establish peace for us. For all that we have accomplished, You have done for us.'),
('ISA', 26, 13, 'ISA.26.13', 'O LORD our God, other lords besides You have ruled over us, but Your name alone do we confess.'),
('ISA', 26, 14, 'ISA.26.14', 'The dead will not live; the departed spirits will not rise. Therefore You have punished and destroyed them; You have wiped out all memory of them.'),
('ISA', 26, 15, 'ISA.26.15', 'You have enlarged the nation, O LORD; You have enlarged the nation. You have gained glory for Yourself; You have extended all the borders of the land.'),
('ISA', 26, 16, 'ISA.26.16', 'O LORD, they sought You in their distress; when You disciplined them, they poured out a quiet prayer.'),
('ISA', 26, 17, 'ISA.26.17', 'As a woman with child about to give birth writhes and cries out in pain, so were we in Your presence, O LORD.'),
('ISA', 26, 18, 'ISA.26.18', 'We were with child; we writhed in pain; but we gave birth to wind. We have given no salvation to the earth, nor brought any life into the world.'),
('ISA', 26, 19, 'ISA.26.19', 'Your dead will live; their bodies will rise. Awake and sing, you who dwell in the dust! For your dew is like the dew of the morning, and the earth will bring forth her dead.'),
('ISA', 26, 20, 'ISA.26.20', 'Go, my people, enter your rooms and shut your doors behind you. Hide yourselves a little while until the wrath has passed.'),
('ISA', 26, 21, 'ISA.26.21', 'For behold, the LORD is coming out of His dwelling to punish the inhabitants of the earth for their iniquity. The earth will reveal her bloodshed and will no longer conceal her slain.'),
('ISA', 27, 1, 'ISA.27.1', 'In that day the LORD will take His sharp, great, and mighty sword, and bring judgment on Leviathan the fleeing serpent—Leviathan the coiling serpent—and He will slay the dragon of the sea.'),
('ISA', 27, 2, 'ISA.27.2', 'In that day: “Sing about a fruitful vineyard.'),
('ISA', 27, 3, 'ISA.27.3', 'I, the LORD, am its keeper; I water it continually. I guard it night and day so no one can disturb it;'),
('ISA', 27, 4, 'ISA.27.4', 'I am not angry. If only thorns and briers confronted Me, I would march and trample them, I would burn them to the ground.'),
('ISA', 27, 5, 'ISA.27.5', 'Or let them lay claim to My protection; let them make peace with Me—yes, let them make peace with Me.”'),
('ISA', 27, 6, 'ISA.27.6', 'In the days to come, Jacob will take root. Israel will bud and blossom and fill the whole world with fruit.'),
('ISA', 27, 7, 'ISA.27.7', 'Has the LORD struck Israel as He struck her oppressors? Was she killed like those who slayed her?'),
('ISA', 27, 8, 'ISA.27.8', 'By warfare and exile You contended with her and removed her with a fierce wind, as on the day the east wind blows.'),
('ISA', 27, 9, 'ISA.27.9', 'Therefore Jacob’s guilt will be atoned for, and the full fruit of the removal of his sin will be this: When he makes all the altar stones like crushed bits of chalk, no Asherah poles or incense altars will remain standing.'),
('ISA', 27, 10, 'ISA.27.10', 'For the fortified city lies deserted—a homestead abandoned, a wilderness forsaken. There the calves graze, and there they lie down; they strip its branches bare.'),
('ISA', 27, 11, 'ISA.27.11', 'When its limbs are dry, they are broken off. Women come and use them for kindling; for this is a people without understanding. Therefore their Maker has no compassion on them, and their Creator shows them no favor.'),
('ISA', 27, 12, 'ISA.27.12', 'In that day the LORD will thresh from the flowing Euphrates to the Wadi of Egypt, and you, O Israelites, will be gathered one by one.'),
('ISA', 27, 13, 'ISA.27.13', 'And in that day a great ram’s horn will sound, and those who were perishing in Assyria will come forth with those who were exiles in Egypt. And they will worship the LORD on the holy mountain in Jerusalem.'),
('ISA', 28, 1, 'ISA.28.1', 'Woe to the majestic crown of Ephraim’s drunkards, to the fading flower of his glorious splendor, set on the summit above the fertile valley, the pride of those overcome by wine.'),
('ISA', 28, 2, 'ISA.28.2', 'Behold, the Lord has one who is strong and mighty. Like a hailstorm or destructive tempest, like a driving rain or flooding downpour, he will smash that crown to the ground.'),
('ISA', 28, 3, 'ISA.28.3', 'The majestic crown of Ephraim’s drunkards will be trampled underfoot.'),
('ISA', 28, 4, 'ISA.28.4', 'The fading flower of his beautiful splendor, set on the summit above the fertile valley, will be like a ripe fig before the summer harvest: Whoever sees it will take it in his hand and swallow it.'),
('ISA', 28, 5, 'ISA.28.5', 'On that day the LORD of Hosts will be a crown of glory, a diadem of splendor to the remnant of His people,'),
('ISA', 28, 6, 'ISA.28.6', 'a spirit of justice to him who sits in judgment, and a strength to those who repel the onslaught at the gate.'),
('ISA', 28, 7, 'ISA.28.7', 'These also stagger from wine and stumble from strong drink: Priests and prophets reel from strong drink and are befuddled by wine. They stumble because of strong drink, muddled in their visions and stumbling in their judgments.'),
('ISA', 28, 8, 'ISA.28.8', 'For all their tables are covered with vomit; there is not a place without filth.'),
('ISA', 28, 9, 'ISA.28.9', 'Whom is He trying to teach? To whom is He explaining His message? To infants just weaned from milk? To babies removed from the breast?'),
('ISA', 28, 10, 'ISA.28.10', 'For they hear: “Order on order, order on order, line on line, line on line; a little here, a little there.”'),
('ISA', 28, 11, 'ISA.28.11', 'Indeed, with mocking lips and foreign tongues, He will speak to this people'),
('ISA', 28, 12, 'ISA.28.12', 'to whom He has said: “This is the place of rest, let the weary rest; this is the place of repose.” But they would not listen.'),
('ISA', 28, 13, 'ISA.28.13', 'Then the word of the LORD to them will become: “Order on order, order on order, line on line, line on line; a little here, a little there,” so that they will go stumbling backward and will be injured, ensnared, and captured.'),
('ISA', 28, 14, 'ISA.28.14', 'Therefore hear the word of the LORD, O scoffers who rule this people in Jerusalem.'),
('ISA', 28, 15, 'ISA.28.15', 'For you said, “We have made a covenant with death; we have fashioned an agreement with Sheol. When the overwhelming scourge passes through it will not touch us, because we have made lies our refuge and falsehood our hiding place.”'),
('ISA', 28, 16, 'ISA.28.16', 'So this is what the Lord GOD says: “See, I lay a stone in Zion, a tested stone, a precious cornerstone, a sure foundation; the one who believes will never be shaken.'),
('ISA', 28, 17, 'ISA.28.17', 'I will make justice the measuring line and righteousness the level. Hail will sweep away your refuge of lies, and water will flood your hiding place.'),
('ISA', 28, 18, 'ISA.28.18', 'Your covenant with death will be dissolved, and your agreement with Sheol will not stand. When the overwhelming scourge passes through, you will be trampled by it.'),
('ISA', 28, 19, 'ISA.28.19', 'As often as it passes through, it will carry you away; it will sweep through morning after morning, by day and by night.” The understanding of this message will bring sheer terror.'),
('ISA', 28, 20, 'ISA.28.20', 'Indeed, the bed is too short to stretch out on, and the blanket too small to wrap around you.'),
('ISA', 28, 21, 'ISA.28.21', 'For the LORD will rise up as at Mount Perazim. He will rouse Himself as in the Valley of Gibeon, to do His work, His strange work, and to perform His task, His disturbing task.'),
('ISA', 28, 22, 'ISA.28.22', 'So now, do not mock, or your shackles will become heavier. Indeed, I have heard from the Lord GOD of Hosts a decree of destruction against the whole land.'),
('ISA', 28, 23, 'ISA.28.23', 'Listen and hear my voice. Pay attention and hear what I say.'),
('ISA', 28, 24, 'ISA.28.24', 'Does the plowman plow for planting every day? Does he continuously loosen and harrow the soil?'),
('ISA', 28, 25, 'ISA.28.25', 'When he has leveled its surface, does he not sow caraway and scatter cumin? He plants wheat in rows and barley in plots, and rye within its border.'),
('ISA', 28, 26, 'ISA.28.26', 'For his God instructs and teaches him properly.'),
('ISA', 28, 27, 'ISA.28.27', 'Surely caraway is not threshed with a sledge, and the wheel of a cart is not rolled over the cumin. But caraway is beaten out with a stick, and cumin with a rod.'),
('ISA', 28, 28, 'ISA.28.28', 'Grain for bread must be ground, but it is not endlessly threshed. Though the wheels of the cart roll over it, the horses do not crush it.'),
('ISA', 28, 29, 'ISA.28.29', 'This also comes from the LORD of Hosts, who is wonderful in counsel and excellent in wisdom.'),
('ISA', 29, 1, 'ISA.29.1', 'Woe to you, O Ariel, the city of Ariel where David camped! Year upon year let your festivals recur.'),
('ISA', 29, 2, 'ISA.29.2', 'And I will constrain Ariel, and there will be mourning and lamentation; she will be like an altar hearth before Me.'),
('ISA', 29, 3, 'ISA.29.3', 'I will camp in a circle around you; I will besiege you with towers and set up siege works against you.'),
('ISA', 29, 4, 'ISA.29.4', 'You will be brought low, you will speak from the ground, and out of the dust your words will be muffled. Your voice will be like a spirit from the ground; your speech will whisper out of the dust.'),
('ISA', 29, 5, 'ISA.29.5', 'But your many foes will be like fine dust, the multitude of the ruthless like blowing chaff. Then suddenly, in an instant,'),
('ISA', 29, 6, 'ISA.29.6', 'you will be visited by the LORD of Hosts with thunder and earthquake and loud noise, with windstorm and tempest and consuming flame of fire.'),
('ISA', 29, 7, 'ISA.29.7', 'All the many nations going out to battle against Ariel—even all who war against her, laying siege and attacking her—will be like a dream, like a vision in the night,'),
('ISA', 29, 8, 'ISA.29.8', 'as when a hungry man dreams he is eating, then awakens still hungry; as when a thirsty man dreams he is drinking, then awakens faint and parched. So will it be for all the many nations who go to battle against Mount Zion.'),
('ISA', 29, 9, 'ISA.29.9', 'Stop and be astonished; blind yourselves and be sightless; be drunk, but not with wine; stagger, but not from strong drink.'),
('ISA', 29, 10, 'ISA.29.10', 'For the LORD has poured out on you a spirit of deep sleep. He has shut your eyes, O prophets; He has covered your heads, O seers.'),
('ISA', 29, 11, 'ISA.29.11', 'And the entire vision will be to you like the words sealed in a scroll. If it is handed to someone to read, he will say, “I cannot, because it is sealed.”'),
('ISA', 29, 12, 'ISA.29.12', 'Or if the scroll is handed to one unable to read, he will say, “I cannot read.”'),
('ISA', 29, 13, 'ISA.29.13', 'Therefore the Lord said: “These people draw near to Me with their mouths and honor Me with their lips, but their hearts are far from Me. Their worship of Me is but rules taught by men.'),
('ISA', 29, 14, 'ISA.29.14', 'Therefore I will again confound these people with wonder upon wonder. The wisdom of the wise will vanish, and the intelligence of the intelligent will be hidden.”'),
('ISA', 29, 15, 'ISA.29.15', 'Woe to those who dig deep to hide their plans from the LORD. In darkness they do their works and say, “Who sees us, and who will know?”'),
('ISA', 29, 16, 'ISA.29.16', 'You have turned things upside down, as if the potter were regarded as clay. Shall what is formed say to him who formed it, “He did not make me”? Can the pottery say of the potter, “He has no understanding”?'),
('ISA', 29, 17, 'ISA.29.17', 'In a very short time, will not Lebanon become an orchard, and the orchard seem like a forest?'),
('ISA', 29, 18, 'ISA.29.18', 'On that day the deaf will hear the words of the scroll, and out of the deep darkness the eyes of the blind will see.'),
('ISA', 29, 19, 'ISA.29.19', 'The humble will increase their joy in the LORD, and the poor among men will rejoice in the Holy One of Israel.'),
('ISA', 29, 20, 'ISA.29.20', 'For the ruthless will vanish, the mockers will disappear, and all who look for evil will be cut down—'),
('ISA', 29, 21, 'ISA.29.21', 'those who indict a man with a word, who ensnare the mediator at the gate, and who with false charges deprive the innocent of justice.'),
('ISA', 29, 22, 'ISA.29.22', 'Therefore the LORD who redeemed Abraham says of the house of Jacob: “No longer will Jacob be ashamed and no more will his face grow pale.'),
('ISA', 29, 23, 'ISA.29.23', 'For when he sees his children around him, the work of My hands, they will honor My name, they will sanctify the Holy One of Jacob, and they will stand in awe of the God of Israel.'),
('ISA', 29, 24, 'ISA.29.24', 'Then the wayward in spirit will come to understanding, and those who grumble will accept instruction.”'),
('ISA', 30, 1, 'ISA.30.1', '“Woe to the rebellious children,” declares the LORD, “to those who carry out a plan that is not Mine, who form an alliance, but against My will, heaping up sin upon sin.'),
('ISA', 30, 2, 'ISA.30.2', 'They set out to go down to Egypt without asking My advice, to seek shelter under Pharaoh’s protection and take refuge in Egypt’s shade.'),
('ISA', 30, 3, 'ISA.30.3', 'But Pharaoh’s protection will become your shame, and the refuge of Egypt’s shade your disgrace.'),
('ISA', 30, 4, 'ISA.30.4', 'For though their princes are at Zoan and their envoys have arrived in Hanes,'),
('ISA', 30, 5, 'ISA.30.5', 'everyone will be put to shame because of a people useless to them. They bring neither help nor benefit, but only shame and disgrace.”'),
('ISA', 30, 6, 'ISA.30.6', 'This is the burden against the beasts of the Negev: Through a land of hardship and distress, of lioness and lion, of viper and flying serpent, they carry their wealth on the backs of donkeys and their treasures on the humps of camels, to a people of no profit to them.'),
('ISA', 30, 7, 'ISA.30.7', 'Egypt’s help is futile and empty; therefore I have called her Rahab Who Sits Still.'),
('ISA', 30, 8, 'ISA.30.8', 'Go now, write it on a tablet in their presence and inscribe it on a scroll; it will be for the days to come, a witness forever and ever.'),
('ISA', 30, 9, 'ISA.30.9', 'These are rebellious people, deceitful children, children unwilling to obey the LORD’s instruction.'),
('ISA', 30, 10, 'ISA.30.10', 'They say to the seers, “Stop seeing visions!” and to the prophets, “Do not prophesy to us the truth! Speak to us pleasant words; prophesy illusions.'),
('ISA', 30, 11, 'ISA.30.11', 'Get out of the way; turn off the road. Rid us of the Holy One of Israel!”'),
('ISA', 30, 12, 'ISA.30.12', 'Therefore this is what the Holy One of Israel says: “Because you have rejected this message, trusting in oppression and relying on deceit,'),
('ISA', 30, 13, 'ISA.30.13', 'this iniquity of yours is like a breach about to fail, a bulge in a high wall, whose collapse will come suddenly—in an instant!'),
('ISA', 30, 14, 'ISA.30.14', 'It will break in pieces like a potter’s jar, shattered so that no fragment can be found. Not a shard will be found in the dust large enough to scoop the coals from a hearth or to skim the water from a cistern.”'),
('ISA', 30, 15, 'ISA.30.15', 'For the Lord GOD, the Holy One of Israel, has said: “By repentance and rest you would be saved; your strength would lie in quiet confidence—but you were not willing.”'),
('ISA', 30, 16, 'ISA.30.16', '“No,” you say, “we will flee on horses.” Therefore you will flee! “We will ride swift horses,” but your pursuers will be faster.'),
('ISA', 30, 17, 'ISA.30.17', 'A thousand will flee at the threat of one; at the threat of five you will all flee, until you are left alone like a pole on a mountaintop, like a banner on a hill.'),
('ISA', 30, 18, 'ISA.30.18', 'Therefore the LORD longs to be gracious to you; therefore He rises to show you compassion, for the LORD is a just God. Blessed are all who wait for Him.'),
('ISA', 30, 19, 'ISA.30.19', 'O people in Zion who dwell in Jerusalem, you will weep no more. He will surely be gracious when you cry for help; when He hears, He will answer you.'),
('ISA', 30, 20, 'ISA.30.20', 'The Lord will give you the bread of adversity and the water of affliction, but your Teacher will no longer hide Himself—with your own eyes you will see Him.'),
('ISA', 30, 21, 'ISA.30.21', 'And whether you turn to the right or to the left, your ears will hear this command behind you: “This is the way. Walk in it.”'),
('ISA', 30, 22, 'ISA.30.22', 'So you will desecrate your silver-plated idols and your gold-plated images. You will throw them away like menstrual cloths, saying to them, “Be gone!”'),
('ISA', 30, 23, 'ISA.30.23', 'Then He will send rain for the seed that you have sown in the ground, and the food that comes from your land will be rich and plentiful. On that day your cattle will graze in open pastures.'),
('ISA', 30, 24, 'ISA.30.24', 'The oxen and donkeys that work the ground will eat salted fodder, winnowed with shovel and pitchfork.'),
('ISA', 30, 25, 'ISA.30.25', 'And from every high mountain and every raised hill, streams of water will flow in the day of great slaughter, when the towers fall.'),
('ISA', 30, 26, 'ISA.30.26', 'The light of the moon will be as bright as the sun, and the light of the sun will be seven times brighter—like the light of seven days—on the day that the LORD binds up the brokenness of His people and heals the wounds He has inflicted.'),
('ISA', 30, 27, 'ISA.30.27', 'Behold, the Name of the LORD comes from afar, with burning anger and dense smoke. His lips are full of fury, and His tongue is like a consuming fire.'),
('ISA', 30, 28, 'ISA.30.28', 'His breath is like a rushing torrent that rises to the neck. He comes to sift the nations in a sieve of destruction; He bridles the jaws of the peoples to lead them astray.'),
('ISA', 30, 29, 'ISA.30.29', 'You will sing as on the night of a holy festival, and your heart will rejoice like one who walks to the music of a flute, going up to the mountain of the LORD, to the Rock of Israel.'),
('ISA', 30, 30, 'ISA.30.30', 'And the LORD will cause His majestic voice to be heard and His mighty arm to be revealed, striking in angry wrath with a flame of consuming fire, and with cloudburst, storm, and hailstones.'),
('ISA', 30, 31, 'ISA.30.31', 'For Assyria will be shattered at the voice of the LORD; He will strike them with His scepter.'),
('ISA', 30, 32, 'ISA.30.32', 'And with every stroke of the rod of punishment that the LORD brings down on them, the tambourines and lyres will sound as He battles with weapons brandished.'),
('ISA', 30, 33, 'ISA.30.33', 'For Topheth has long been prepared; it has been made ready for the king. Its funeral pyre is deep and wide, with plenty of fire and wood. The breath of the LORD, like a torrent of burning sulfur, sets it ablaze.'),
('ISA', 31, 1, 'ISA.31.1', 'Woe to those who go down to Egypt for help, who rely on horses, who trust in their abundance of chariots and in their multitude of horsemen. They do not look to the Holy One of Israel; they do not seek the LORD.'),
('ISA', 31, 2, 'ISA.31.2', 'Yet He too is wise and brings disaster; He does not call back His words. He will rise up against the house of the wicked and against the allies of evildoers.'),
('ISA', 31, 3, 'ISA.31.3', 'But the Egyptians are men, not God; their horses are flesh, not spirit. When the LORD stretches out His hand, the helper will stumble, and the one he helps will fall; both will perish together.'),
('ISA', 31, 4, 'ISA.31.4', 'For this is what the LORD has said to me: “Like a lion roaring or a young lion over its prey—and though a band of shepherds is called out against it, it is not terrified by their shouting or subdued by their clamor—so the LORD of Hosts will come down to do battle on Mount Zion and its heights.'),
('ISA', 31, 5, 'ISA.31.5', 'Like birds hovering overhead, so the LORD of Hosts will protect Jerusalem. He will shield it and deliver it; He will pass over it and preserve it.”'),
('ISA', 31, 6, 'ISA.31.6', 'Return to the One against whom you have so blatantly rebelled, O children of Israel.'),
('ISA', 31, 7, 'ISA.31.7', 'For on that day, every one of you will reject the idols of silver and gold that your own hands have sinfully made.'),
('ISA', 31, 8, 'ISA.31.8', '“Then Assyria will fall, but not by the sword of man; a sword will devour them, but not one made by mortals. They will flee before the sword, and their young men will be put to forced labor.'),
('ISA', 31, 9, 'ISA.31.9', 'Their rock will pass away for fear, and their princes will panic at the sight of the battle standard,” declares the LORD, whose fire is in Zion, whose furnace is in Jerusalem.'),
('ISA', 32, 1, 'ISA.32.1', 'Behold, a king will reign in righteousness, and princes will rule with justice.'),
('ISA', 32, 2, 'ISA.32.2', 'Each will be like a shelter from the wind, a refuge from the storm, like streams of water in a dry land, like the shadow of a great rock in an arid land.'),
('ISA', 32, 3, 'ISA.32.3', 'Then the eyes of those who see will no longer be closed, and the ears of those who hear will listen.'),
('ISA', 32, 4, 'ISA.32.4', 'The mind of the rash will know and understand, and the stammering tongue will speak clearly and fluently.'),
('ISA', 32, 5, 'ISA.32.5', 'No longer will a fool be called noble, nor a scoundrel be respected.'),
('ISA', 32, 6, 'ISA.32.6', 'For a fool speaks foolishness; his mind plots iniquity. He practices ungodliness and speaks falsely about the LORD; he leaves the hungry empty and deprives the thirsty of drink.'),
('ISA', 32, 7, 'ISA.32.7', 'The weapons of the scoundrel are destructive; he hatches plots to destroy the poor with lies, even when the plea of the needy is just.'),
('ISA', 32, 8, 'ISA.32.8', 'But a noble man makes honorable plans; he stands up for worthy causes.'),
('ISA', 32, 9, 'ISA.32.9', 'Stand up, you complacent women; listen to me. Give ear to my word, you overconfident daughters.'),
('ISA', 32, 10, 'ISA.32.10', 'In a little more than a year you will tremble, O secure ones. For the grape harvest will fail and the fruit harvest will not arrive.'),
('ISA', 32, 11, 'ISA.32.11', 'Shudder, you ladies of leisure; tremble, you daughters of complacency. Strip yourselves bare and put sackcloth around your waists.'),
('ISA', 32, 12, 'ISA.32.12', 'Beat your breasts for the pleasant fields, for the fruitful vines,'),
('ISA', 32, 13, 'ISA.32.13', 'and for the land of my people, overgrown with thorns and briers—even for every house of merriment in this city of revelry.'),
('ISA', 32, 14, 'ISA.32.14', 'For the palace will be forsaken, the busy city abandoned. The hill and the watchtower will become caves forever—the delight of wild donkeys and a pasture for flocks—'),
('ISA', 32, 15, 'ISA.32.15', 'until the Spirit is poured out upon us from on high. Then the desert will be an orchard, and the orchard will seem like a forest.'),
('ISA', 32, 16, 'ISA.32.16', 'Then justice will inhabit the wilderness, and righteousness will dwell in the fertile field.'),
('ISA', 32, 17, 'ISA.32.17', 'The work of righteousness will be peace; the service of righteousness will be quiet confidence forever.'),
('ISA', 32, 18, 'ISA.32.18', 'Then my people will dwell in a peaceful place, in safe and secure places of rest.'),
('ISA', 32, 19, 'ISA.32.19', 'But hail will level the forest, and the city will sink to the depths.'),
('ISA', 32, 20, 'ISA.32.20', 'Blessed are those who sow beside abundant waters, who let the ox and donkey range freely.'),
('ISA', 33, 1, 'ISA.33.1', 'Woe to you, O destroyer never destroyed, O traitor never betrayed! When you have finished destroying, you will be destroyed. When you have finished betraying, you will be betrayed.'),
('ISA', 33, 2, 'ISA.33.2', 'O LORD, be gracious to us! We wait for You. Be our strength every morning and our salvation in time of trouble.'),
('ISA', 33, 3, 'ISA.33.3', 'The peoples flee the thunder of Your voice; the nations scatter when You rise.'),
('ISA', 33, 4, 'ISA.33.4', 'Your spoil, O nations, is gathered as by locusts; like a swarm of locusts men sweep over it.'),
('ISA', 33, 5, 'ISA.33.5', 'The LORD is exalted, for He dwells on high; He has filled Zion with justice and righteousness.'),
('ISA', 33, 6, 'ISA.33.6', 'He will be the sure foundation for your times, a storehouse of salvation, wisdom, and knowledge. The fear of the LORD is Zion’s treasure.'),
('ISA', 33, 7, 'ISA.33.7', 'Behold, their valiant ones cry aloud in the streets; the envoys of peace weep bitterly.'),
('ISA', 33, 8, 'ISA.33.8', 'The highways are deserted; travel has ceased. The treaty has been broken, the witnesses are despised, and human life is disregarded.'),
('ISA', 33, 9, 'ISA.33.9', 'The land mourns and languishes; Lebanon is ashamed and decayed. Sharon is like a desert; Bashan and Carmel shake off their leaves.'),
('ISA', 33, 10, 'ISA.33.10', '“Now I will arise,” says the LORD. “Now I will lift Myself up. Now I will be exalted.'),
('ISA', 33, 11, 'ISA.33.11', 'You conceive chaff; you give birth to stubble. Your breath is a fire that will consume you.'),
('ISA', 33, 12, 'ISA.33.12', 'The peoples will be burned to ashes, like thorns cut down and set ablaze.'),
('ISA', 33, 13, 'ISA.33.13', 'You who are far off, hear what I have done; you who are near, acknowledge My might.”'),
('ISA', 33, 14, 'ISA.33.14', 'The sinners in Zion are afraid; trembling grips the ungodly: “Who of us can dwell with a consuming fire? Who of us can dwell with everlasting flames?”'),
('ISA', 33, 15, 'ISA.33.15', 'He who walks righteously and speaks with sincerity, who refuses gain from extortion, whose hand never takes a bribe, who stops his ears against murderous plots and shuts his eyes tightly against evil—'),
('ISA', 33, 16, 'ISA.33.16', 'he will dwell on the heights; the mountain fortress will be his refuge; his food will be provided and his water assured.'),
('ISA', 33, 17, 'ISA.33.17', 'Your eyes will see the King in His beauty and behold a land that stretches afar.'),
('ISA', 33, 18, 'ISA.33.18', 'Your mind will ponder the former terror: “Where is he who tallies? Where is he who weighs? Where is he who counts the towers?”'),
('ISA', 33, 19, 'ISA.33.19', 'You will no longer see the insolent, a people whose speech is unintelligible, who stammer in a language you cannot understand.'),
('ISA', 33, 20, 'ISA.33.20', 'Look upon Zion, the city of our appointed feasts. Your eyes will see Jerusalem, a peaceful pasture, a tent that does not wander; its tent pegs will not be pulled up, nor will any of its cords be broken.'),
('ISA', 33, 21, 'ISA.33.21', 'But there the Majestic One, our LORD, will be for us a place of rivers and wide canals, where no galley with oars will row, and no majestic vessel will pass.'),
('ISA', 33, 22, 'ISA.33.22', 'For the LORD is our Judge, the LORD is our lawgiver, the LORD is our King. It is He who will save us.'),
('ISA', 33, 23, 'ISA.33.23', 'Your ropes are slack; they cannot secure the mast or spread the sail. Then an abundance of spoils will be divided, and even the lame will carry off plunder.'),
('ISA', 33, 24, 'ISA.33.24', 'And no resident of Zion will say, “I am sick.” The people who dwell there will be forgiven of iniquity.'),
('ISA', 34, 1, 'ISA.34.1', 'Come near, O nations, to listen; pay attention, O peoples. Let the earth hear, and all that fills it, the world and all that springs from it.'),
('ISA', 34, 2, 'ISA.34.2', 'The LORD is angry with all the nations and furious with all their armies. He will devote them to destruction; He will give them over to slaughter.'),
('ISA', 34, 3, 'ISA.34.3', 'Their slain will be left unburied, and the stench of their corpses will rise; the mountains will flow with their blood.'),
('ISA', 34, 4, 'ISA.34.4', 'All the stars of heaven will be dissolved. The skies will be rolled up like a scroll, and all their stars will fall like withered leaves from the vine, like foliage from the fig tree.'),
('ISA', 34, 5, 'ISA.34.5', 'When My sword has drunk its fill in the heavens, then it will come down upon Edom, upon the people I have devoted to destruction.'),
('ISA', 34, 6, 'ISA.34.6', 'The sword of the LORD is bathed in blood. It drips with fat—with the blood of lambs and goats, with the fat of the kidneys of rams. For the LORD has a sacrifice in Bozrah, a great slaughter in the land of Edom.'),
('ISA', 34, 7, 'ISA.34.7', 'And the wild oxen will fall with them, the young bulls with the strong ones. Their land will be drenched with blood, and their soil will be soaked with fat.'),
('ISA', 34, 8, 'ISA.34.8', 'For the LORD has a day of vengeance, a year of recompense for the cause of Zion.'),
('ISA', 34, 9, 'ISA.34.9', 'Edom’s streams will be turned to tar, and her soil to sulfur; her land will become a blazing pitch.'),
('ISA', 34, 10, 'ISA.34.10', 'It will not be quenched—day or night. Its smoke will ascend forever. From generation to generation it will lie desolate; no one will ever again pass through it.'),
('ISA', 34, 11, 'ISA.34.11', 'The desert owl and screech owl will possess it, and the great owl and raven will dwell in it. The LORD will stretch out over Edom a measuring line of chaos and a plumb line of destruction.'),
('ISA', 34, 12, 'ISA.34.12', 'No nobles will be left to proclaim a king, and all her princes will come to nothing.'),
('ISA', 34, 13, 'ISA.34.13', 'Her towers will be overgrown with thorns, her fortresses with thistles and briers. She will become a haunt for jackals, an abode for ostriches.'),
('ISA', 34, 14, 'ISA.34.14', 'The desert creatures will meet with hyenas, and one wild goat will call to another. There the night creature will settle and find her place of repose.'),
('ISA', 34, 15, 'ISA.34.15', 'There the owl will make her nest; she will lay and hatch her eggs and gather her brood under her shadow. Even there the birds of prey will gather, each with its mate.'),
('ISA', 34, 16, 'ISA.34.16', 'Search and read the scroll of the LORD: Not one of these will go missing, not one will lack her mate, because He has ordered it by His mouth, and He will gather them by His Spirit.'),
('ISA', 34, 17, 'ISA.34.17', 'He has allotted their portion; His hand has distributed it by measure. They will possess it forever; they will dwell in it from generation to generation.'),
('ISA', 35, 1, 'ISA.35.1', 'The wilderness and the dry land will be glad; the desert will rejoice and blossom like a rose.'),
('ISA', 35, 2, 'ISA.35.2', 'It will bloom profusely and rejoice with joy and singing. The glory of Lebanon will be given to it, the splendor of Carmel and Sharon. They will see the glory of the LORD, the splendor of our God.'),
('ISA', 35, 3, 'ISA.35.3', 'Strengthen the limp hands and steady the feeble knees!'),
('ISA', 35, 4, 'ISA.35.4', 'Say to those with anxious hearts: “Be strong, do not fear! Behold, your God will come with vengeance. With divine retribution He will come to save you.”'),
('ISA', 35, 5, 'ISA.35.5', 'Then the eyes of the blind will be opened and the ears of the deaf unstopped.'),
('ISA', 35, 6, 'ISA.35.6', 'Then the lame will leap like a deer and the mute tongue will shout for joy. For waters will gush forth in the wilderness, and streams in the desert.'),
('ISA', 35, 7, 'ISA.35.7', 'The parched ground will become a pool, the thirsty land springs of water. In the haunt where jackals once lay, there will be grass and reeds and papyrus.'),
('ISA', 35, 8, 'ISA.35.8', 'And there will be a highway called the Way of Holiness. The unclean will not travel it—only those who walk in the Way—and fools will not stray onto it.'),
('ISA', 35, 9, 'ISA.35.9', 'No lion will be there, and no vicious beast will go up on it. Such will not be found there, but the redeemed will walk upon it.'),
('ISA', 35, 10, 'ISA.35.10', 'So the redeemed of the LORD will return and enter Zion with singing, crowned with everlasting joy. Gladness and joy will overtake them, and sorrow and sighing will flee.'),
('ISA', 36, 1, 'ISA.36.1', 'In the fourteenth year of Hezekiah’s reign, Sennacherib king of Assyria attacked and captured all the fortified cities of Judah.'),
('ISA', 36, 2, 'ISA.36.2', 'And the king of Assyria sent the Rabshakeh, with a great army, from Lachish to King Hezekiah at Jerusalem. And he stopped by the aqueduct of the upper pool, on the road to the Launderer’s Field.'),
('ISA', 36, 3, 'ISA.36.3', 'Then Eliakim son of Hilkiah the palace administrator, Shebna the scribe, and Joah son of Asaph the recorder, went out to him.'),
('ISA', 36, 4, 'ISA.36.4', 'The Rabshakeh said to them, “Tell Hezekiah that this is what the great king, the king of Assyria, says: What is the basis of this confidence of yours?'),
('ISA', 36, 5, 'ISA.36.5', 'You claim to have a strategy and strength for war, but these are empty words. In whom are you now trusting, that you have rebelled against me?'),
('ISA', 36, 6, 'ISA.36.6', 'Look now, you are trusting in Egypt, that splintered reed of a staff that will pierce the hand of anyone who leans on it. Such is Pharaoh king of Egypt to all who trust in him.'),
('ISA', 36, 7, 'ISA.36.7', 'But if you say to me, ‘We trust in the LORD our God,’ is He not the One whose high places and altars Hezekiah has removed, saying to Judah and Jerusalem, ‘You must worship before this altar’?'),
('ISA', 36, 8, 'ISA.36.8', 'Now, therefore, make a bargain with my master, the king of Assyria. I will give you two thousand horses—if you can put riders on them!'),
('ISA', 36, 9, 'ISA.36.9', 'For how can you repel a single officer among the least of my master’s servants when you depend on Egypt for chariots and horsemen?'),
('ISA', 36, 10, 'ISA.36.10', 'So now, was it apart from the LORD that I have come up against this land to destroy it? The LORD Himself said to me, ‘Go up against this land and destroy it.’”'),
('ISA', 36, 11, 'ISA.36.11', 'Then Eliakim, Shebna, and Joah said to the Rabshakeh, “Please speak to your servants in Aramaic, since we understand it. Do not speak to us in Hebrew in the hearing of the people on the wall.”'),
('ISA', 36, 12, 'ISA.36.12', 'But the Rabshakeh replied, “Has my master sent me to speak these words only to you and your master, and not to the men sitting on the wall, who are destined with you to eat their own dung and drink their own urine?”'),
('ISA', 36, 13, 'ISA.36.13', 'Then the Rabshakeh stood and called out loudly in Hebrew: “Hear the words of the great king, the king of Assyria!'),
('ISA', 36, 14, 'ISA.36.14', 'This is what the king says: Do not let Hezekiah deceive you, for he cannot deliver you.'),
('ISA', 36, 15, 'ISA.36.15', 'Do not let Hezekiah persuade you to trust in the LORD when he says, ‘The LORD will surely deliver us; this city will not be given into the hand of the king of Assyria.’'),
('ISA', 36, 16, 'ISA.36.16', 'Do not listen to Hezekiah, for this is what the king of Assyria says: Make peace with me and come out to me. Then every one of you will eat from his own vine and his own fig tree, and drink water from his own cistern,'),
('ISA', 36, 17, 'ISA.36.17', 'until I come and take you away to a land like your own—a land of grain and new wine, a land of bread and vineyards.'),
('ISA', 36, 18, 'ISA.36.18', 'Do not let Hezekiah mislead you when he says, ‘The LORD will deliver us.’ Has the god of any nation ever delivered his land from the hand of the king of Assyria?'),
('ISA', 36, 19, 'ISA.36.19', 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim? Have they delivered Samaria from my hand?'),
('ISA', 36, 20, 'ISA.36.20', 'Who among all the gods of these lands has delivered his land from my hand? How then can the LORD deliver Jerusalem from my hand?”'),
('ISA', 36, 21, 'ISA.36.21', 'But the people remained silent and did not answer a word, for Hezekiah had commanded, “Do not answer him.”'),
('ISA', 36, 22, 'ISA.36.22', 'Then Hilkiah’s son Eliakim the palace administrator, Shebna the scribe, and Asaph’s son Joah the recorder came to Hezekiah with their clothes torn, and they relayed to him the words of the Rabshakeh.'),
('ISA', 37, 1, 'ISA.37.1', 'On hearing this report, King Hezekiah tore his clothes, put on sackcloth, and entered the house of the LORD.'),
('ISA', 37, 2, 'ISA.37.2', 'And he sent Eliakim the palace administrator, Shebna the scribe, and the leading priests, all wearing sackcloth, to the prophet Isaiah son of Amoz'),
('ISA', 37, 3, 'ISA.37.3', 'to tell him, “This is what Hezekiah says: Today is a day of distress, rebuke, and disgrace; for children have come to the point of birth, but there is no strength to deliver them.'),
('ISA', 37, 4, 'ISA.37.4', 'Perhaps the LORD your God will hear the words of the Rabshakeh, whom his master the king of Assyria has sent to defy the living God, and He will rebuke him for the words that the LORD your God has heard. Therefore lift up a prayer for the remnant that still survives.”'),
('ISA', 37, 5, 'ISA.37.5', 'So the servants of King Hezekiah went to Isaiah,'),
('ISA', 37, 6, 'ISA.37.6', 'who replied, “Tell your master that this is what the LORD says: ‘Do not be afraid of the words you have heard, with which the servants of the king of Assyria have blasphemed Me.'),
('ISA', 37, 7, 'ISA.37.7', 'Behold, I will put a spirit in him so that he will hear a rumor and return to his own land, where I will cause him to fall by the sword.’”'),
('ISA', 37, 8, 'ISA.37.8', 'When the Rabshakeh heard that the king of Assyria had left Lachish, he withdrew and found the king fighting against Libnah.'),
('ISA', 37, 9, 'ISA.37.9', 'Now Sennacherib had been warned about Tirhakah king of Cush: “He has set out to fight against you.” On hearing this, Sennacherib sent messengers to Hezekiah, saying,'),
('ISA', 37, 10, 'ISA.37.10', '“Give this message to Hezekiah king of Judah: ‘Do not let your God, in whom you trust, deceive you by saying that Jerusalem will not be delivered into the hand of the king of Assyria.'),
('ISA', 37, 11, 'ISA.37.11', 'Surely you have heard what the kings of Assyria have done to all the other countries, devoting them to destruction. Will you then be spared?'),
('ISA', 37, 12, 'ISA.37.12', 'Did the gods of the nations destroyed by my fathers rescue those nations—the gods of Gozan, Haran, and Rezeph, and of the people of Eden in Telassar?'),
('ISA', 37, 13, 'ISA.37.13', 'Where are the kings of Hamath, Arpad, Sepharvaim, Hena, and Ivvah?’”'),
('ISA', 37, 14, 'ISA.37.14', 'So Hezekiah received the letter from the messengers, read it, and went up to the house of the LORD and spread it out before the LORD.'),
('ISA', 37, 15, 'ISA.37.15', 'And Hezekiah prayed to the LORD:'),
('ISA', 37, 16, 'ISA.37.16', '“O LORD of Hosts, God of Israel, enthroned above the cherubim, You alone are God over all the kingdoms of the earth. You made the heavens and the earth.'),
('ISA', 37, 17, 'ISA.37.17', 'Incline Your ear, O LORD, and hear; open Your eyes, O LORD, and see. Listen to all the words that Sennacherib has sent to defy the living God.'),
('ISA', 37, 18, 'ISA.37.18', 'Truly, O LORD, the kings of Assyria have laid waste all these countries and their lands.'),
('ISA', 37, 19, 'ISA.37.19', 'They have cast their gods into the fire and destroyed them, for they were not gods, but only wood and stone—the work of human hands.'),
('ISA', 37, 20, 'ISA.37.20', 'And now, O LORD our God, save us from his hand, so that all the kingdoms of the earth may know that You alone, O LORD, are God.”'),
('ISA', 37, 21, 'ISA.37.21', 'Then Isaiah son of Amoz sent a message to Hezekiah: “This is what the LORD, the God of Israel, says: Because you have prayed to Me concerning Sennacherib king of Assyria,'),
('ISA', 37, 22, 'ISA.37.22', 'this is the word that the LORD has spoken against him: ‘The Virgin Daughter of Zion despises you and mocks you; the Daughter of Jerusalem shakes her head behind you.'),
('ISA', 37, 23, 'ISA.37.23', 'Whom have you taunted and blasphemed? Against whom have you raised your voice and lifted your eyes in pride? Against the Holy One of Israel!'),
('ISA', 37, 24, 'ISA.37.24', 'Through your servants you have taunted the Lord, and you have said: “With my many chariots I have ascended to the heights of the mountains, to the remote peaks of Lebanon. I have cut down its tallest cedars, the finest of its cypresses. I have reached its farthest heights, the densest of its forests.'),
('ISA', 37, 25, 'ISA.37.25', 'I have dug wells and drunk foreign waters. With the soles of my feet I have dried up all the streams of Egypt.”'),
('ISA', 37, 26, 'ISA.37.26', 'Have you not heard? Long ago I ordained it; in days of old I planned it. Now I have brought it to pass, that you should crush fortified cities into piles of rubble.'),
('ISA', 37, 27, 'ISA.37.27', 'Therefore their inhabitants, devoid of power, are dismayed and ashamed. They are like plants in the field, tender green shoots, grass on the rooftops, scorched before it is grown.'),
('ISA', 37, 28, 'ISA.37.28', 'But I know your sitting down, your going out and coming in, and your raging against Me.'),
('ISA', 37, 29, 'ISA.37.29', 'Because your rage and arrogance against Me have reached My ears, I will put My hook in your nose and My bit in your mouth; I will send you back the way you came.’'),
('ISA', 37, 30, 'ISA.37.30', 'And this will be a sign to you, O Hezekiah: This year you will eat what grows on its own, and in the second year what springs from the same. But in the third year you will sow and reap; you will plant vineyards and eat their fruit.'),
('ISA', 37, 31, 'ISA.37.31', 'And the surviving remnant of the house of Judah will again take root below and bear fruit above.'),
('ISA', 37, 32, 'ISA.37.32', 'For a remnant will go forth from Jerusalem, and survivors from Mount Zion. The zeal of the LORD of Hosts will accomplish this.'),
('ISA', 37, 33, 'ISA.37.33', 'So this is what the LORD says about the king of Assyria: ‘He will not enter this city or shoot an arrow into it. He will not come before it with a shield or build up a siege ramp against it.'),
('ISA', 37, 34, 'ISA.37.34', 'He will go back the way he came, and he will not enter this city,’ declares the LORD.'),
('ISA', 37, 35, 'ISA.37.35', '‘I will defend this city and save it for My own sake and for the sake of My servant David.’”'),
('ISA', 37, 36, 'ISA.37.36', 'Then the angel of the LORD went out and struck down 185,000 men in the camp of the Assyrians. When the people got up the next morning, there were all the dead bodies!'),
('ISA', 37, 37, 'ISA.37.37', 'So Sennacherib king of Assyria broke camp and withdrew. He returned to Nineveh and stayed there.'),
('ISA', 37, 38, 'ISA.37.38', 'One day, while he was worshiping in the temple of his god Nisroch, his sons Adrammelech and Sharezer put him to the sword and escaped to the land of Ararat. And his son Esar-haddon reigned in his place.'),
('ISA', 38, 1, 'ISA.38.1', 'In those days Hezekiah became mortally ill. The prophet Isaiah son of Amoz came to him and said, “This is what the LORD says: ‘Put your house in order, for you are about to die; you will not recover.’”'),
('ISA', 38, 2, 'ISA.38.2', 'Then Hezekiah turned his face to the wall and prayed to the LORD,'),
('ISA', 38, 3, 'ISA.38.3', 'saying, “Please, O LORD, remember how I have walked before You faithfully and with wholehearted devotion; I have done what is good in Your sight.” And Hezekiah wept bitterly.'),
('ISA', 38, 4, 'ISA.38.4', 'And the word of the LORD came to Isaiah, saying,'),
('ISA', 38, 5, 'ISA.38.5', '“Go and tell Hezekiah that this is what the LORD, the God of your father David, says: ‘I have heard your prayer; I have seen your tears. Behold, I will add fifteen years to your life.'),
('ISA', 38, 6, 'ISA.38.6', 'And I will deliver you and this city from the hand of the king of Assyria. I will defend this city.'),
('ISA', 38, 7, 'ISA.38.7', 'This will be a sign to you from the LORD that He will do what He has promised:'),
('ISA', 38, 8, 'ISA.38.8', 'I will make the sun’s shadow that falls on the stairway of Ahaz go back ten steps.’” So the sunlight went back the ten steps it had descended.'),
('ISA', 38, 9, 'ISA.38.9', 'This is a writing by Hezekiah king of Judah after his illness and recovery:'),
('ISA', 38, 10, 'ISA.38.10', 'I said, “In the prime of my life I must go through the gates of Sheol and be deprived of the remainder of my years.”'),
('ISA', 38, 11, 'ISA.38.11', 'I said, “I will never again see the LORD, even the LORD, in the land of the living; I will no longer look on mankind with those who dwell in this world.'),
('ISA', 38, 12, 'ISA.38.12', 'My dwelling has been picked up and removed from me like a shepherd’s tent. I have rolled up my life like a weaver; He cuts me off from the loom; from day until night You make an end of me.'),
('ISA', 38, 13, 'ISA.38.13', 'I composed myself until the morning. Like a lion He breaks all my bones; from day until night You make an end of me.'),
('ISA', 38, 14, 'ISA.38.14', 'I chirp like a swallow or crane; I moan like a dove. My eyes grow weak as I look upward. O Lord, I am oppressed; be my security.”'),
('ISA', 38, 15, 'ISA.38.15', 'What can I say? He has spoken to me, and He Himself has done this. I will walk slowly all my years because of the anguish of my soul.'),
('ISA', 38, 16, 'ISA.38.16', 'O Lord, by such things men live, and in all of them my spirit finds life. You have restored me to health and have let me live.'),
('ISA', 38, 17, 'ISA.38.17', 'Surely for my own welfare I had such great anguish; but Your love has delivered me from the pit of oblivion, for You have cast all my sins behind Your back.'),
('ISA', 38, 18, 'ISA.38.18', 'For Sheol cannot thank You; Death cannot praise You. Those who descend to the Pit cannot hope for Your faithfulness.'),
('ISA', 38, 19, 'ISA.38.19', 'The living, only the living, can thank You, as I do today; fathers will tell their children about Your faithfulness.'),
('ISA', 38, 20, 'ISA.38.20', 'The LORD will save me; we will play songs on stringed instruments all the days of our lives in the house of the LORD.'),
('ISA', 38, 21, 'ISA.38.21', 'Now Isaiah had said, “Prepare a lump of pressed figs and apply it to the boil, and he will recover.”'),
('ISA', 38, 22, 'ISA.38.22', 'And Hezekiah had asked, “What will be the sign that I will go up to the house of the LORD?”'),
('ISA', 39, 1, 'ISA.39.1', 'At that time Merodach-baladan son of Baladan king of Babylon sent letters and a gift to Hezekiah, for he had heard about Hezekiah’s illness and recovery.'),
('ISA', 39, 2, 'ISA.39.2', 'And Hezekiah welcomed the envoys gladly and showed them what was in his treasure house—the silver, the gold, the spices, and the precious oil, as well as his entire armory—all that was found in his storehouses. There was nothing in his palace or in all his dominion that Hezekiah did not show them.'),
('ISA', 39, 3, 'ISA.39.3', 'Then the prophet Isaiah went to King Hezekiah and asked, “Where did those men come from, and what did they say to you?” “They came to me from a distant land,” Hezekiah replied, “from Babylon.”'),
('ISA', 39, 4, 'ISA.39.4', '“What have they seen in your palace?” Isaiah asked. “They have seen everything in my palace,” answered Hezekiah. “There is nothing among my treasures that I did not show them.”'),
('ISA', 39, 5, 'ISA.39.5', 'Then Isaiah said to Hezekiah, “Hear the word of the LORD of Hosts:'),
('ISA', 39, 6, 'ISA.39.6', 'The time will surely come when everything in your palace and all that your fathers have stored up until this day will be carried off to Babylon. Nothing will be left, says the LORD.'),
('ISA', 39, 7, 'ISA.39.7', 'And some of your descendants, your own flesh and blood, will be taken away to be eunuchs in the palace of the king of Babylon.”'),
('ISA', 39, 8, 'ISA.39.8', 'But Hezekiah said to Isaiah, “The word of the LORD that you have spoken is good.” For he thought, “At least there will be peace and security in my lifetime.”'),
('ISA', 40, 1, 'ISA.40.1', '“Comfort, comfort My people,” says your God.'),
('ISA', 40, 2, 'ISA.40.2', '“Speak tenderly to Jerusalem, and proclaim to her that her forced labor has been completed; her iniquity has been pardoned. For she has received from the hand of the LORD double for all her sins.”'),
('ISA', 40, 3, 'ISA.40.3', 'A voice of one calling: “Prepare the way for the LORD in the wilderness; make a straight highway for our God in the desert.'),
('ISA', 40, 4, 'ISA.40.4', 'Every valley shall be lifted up, and every mountain and hill made low; the uneven ground will become smooth, and the rugged land a plain.'),
('ISA', 40, 5, 'ISA.40.5', 'And the glory of the LORD will be revealed, and all humanity together will see it.” For the mouth of the LORD has spoken.'),
('ISA', 40, 6, 'ISA.40.6', 'A voice says, “Cry out!” And I asked, “What should I cry out?” “All flesh is like grass, and all its glory like the flowers of the field.'),
('ISA', 40, 7, 'ISA.40.7', 'The grass withers and the flowers fall when the breath of the LORD blows on them; indeed, the people are grass.'),
('ISA', 40, 8, 'ISA.40.8', 'The grass withers and the flowers fall, but the word of our God stands forever.”'),
('ISA', 40, 9, 'ISA.40.9', 'Go up on a high mountain, O Zion, herald of good news. Raise your voice loudly, O Jerusalem, herald of good news. Lift it up, do not be afraid! Say to the cities of Judah, “Here is your God!”'),
('ISA', 40, 10, 'ISA.40.10', 'Behold, the Lord GOD comes with might, and His arm establishes His rule. His reward is with Him, and His recompense accompanies Him.'),
('ISA', 40, 11, 'ISA.40.11', 'He tends His flock like a shepherd; He gathers the lambs in His arms and carries them close to His heart. He gently leads the nursing ewes.'),
('ISA', 40, 12, 'ISA.40.12', 'Who has measured the waters in the hollow of his hand, or marked off the heavens with the span of his hand? Who has held the dust of the earth in a basket, or weighed the mountains on a scale and the hills with a balance?'),
('ISA', 40, 13, 'ISA.40.13', 'Who has directed the Spirit of the LORD, or informed Him as His counselor?'),
('ISA', 40, 14, 'ISA.40.14', 'Whom did He consult to enlighten Him, and who taught Him the paths of justice? Who imparted knowledge to Him and showed Him the way of understanding?'),
('ISA', 40, 15, 'ISA.40.15', 'Surely the nations are like a drop in a bucket; they are considered a speck of dust on the scales; He lifts up the islands like fine dust.'),
('ISA', 40, 16, 'ISA.40.16', 'Lebanon is not sufficient for fuel, nor its animals enough for a burnt offering.'),
('ISA', 40, 17, 'ISA.40.17', 'All the nations are as nothing before Him; He regards them as nothingness and emptiness.'),
('ISA', 40, 18, 'ISA.40.18', 'To whom will you liken God? To what image will you compare Him?'),
('ISA', 40, 19, 'ISA.40.19', 'To an idol that a craftsman casts and a metalworker overlays with gold and fits with silver chains?'),
('ISA', 40, 20, 'ISA.40.20', 'One lacking such an offering chooses wood that will not rot. He seeks a skilled craftsman to set up an idol that will not topple.'),
('ISA', 40, 21, 'ISA.40.21', 'Do you not know? Have you not heard? Has it not been declared to you from the beginning? Have you not understood since the foundation of the earth?'),
('ISA', 40, 22, 'ISA.40.22', 'He sits enthroned above the circle of the earth; its dwellers are like grasshoppers. He stretches out the heavens like a curtain, and spreads them out like a tent to dwell in.'),
('ISA', 40, 23, 'ISA.40.23', 'He brings the princes to nothing and makes the rulers of the earth meaningless.'),
('ISA', 40, 24, 'ISA.40.24', 'No sooner are they planted, no sooner are they sown, no sooner have their stems taken root in the ground, than He blows on them and they wither, and a whirlwind sweeps them away like stubble.'),
('ISA', 40, 25, 'ISA.40.25', '“To whom will you liken Me, or who is My equal?” asks the Holy One.'),
('ISA', 40, 26, 'ISA.40.26', 'Lift up your eyes on high: Who created all these? He leads forth the starry host by number; He calls each one by name. Because of His great power and mighty strength, not one of them is missing.'),
('ISA', 40, 27, 'ISA.40.27', 'Why do you say, O Jacob, and why do you assert, O Israel, “My way is hidden from the LORD, and my claim is ignored by my God”?'),
('ISA', 40, 28, 'ISA.40.28', 'Do you not know? Have you not heard? The LORD is the everlasting God, the Creator of the ends of the earth. He will not grow tired or weary; His understanding is beyond searching out.'),
('ISA', 40, 29, 'ISA.40.29', 'He gives power to the faint and increases the strength of the weak.'),
('ISA', 40, 30, 'ISA.40.30', 'Even youths grow tired and weary, and young men stumble and fall.'),
('ISA', 40, 31, 'ISA.40.31', 'But those who wait upon the LORD will renew their strength; they will mount up with wings like eagles; they will run and not grow weary, they will walk and not faint.'),
('ISA', 41, 1, 'ISA.41.1', '“Be silent before Me, O islands, and let the peoples renew their strength. Let them come forward and testify; let us together draw near for judgment.'),
('ISA', 41, 2, 'ISA.41.2', 'Who has aroused one from the east and called him to his feet in righteousness? He hands nations over to him and subdues kings before him. He turns them to dust with his sword, to windblown chaff with his bow.'),
('ISA', 41, 3, 'ISA.41.3', 'He pursues them, going on safely, hardly touching the path with his feet.'),
('ISA', 41, 4, 'ISA.41.4', 'Who has performed this and carried it out, calling forth the generations from the beginning? I, the LORD—the first and the last—I am He.”'),
('ISA', 41, 5, 'ISA.41.5', 'The islands see and fear; the ends of the earth tremble. They approach and come forward.'),
('ISA', 41, 6, 'ISA.41.6', 'Each one helps the other and says to his brother, “Be strong!”'),
('ISA', 41, 7, 'ISA.41.7', 'The craftsman encourages the goldsmith, and he who wields the hammer cheers him who strikes the anvil, saying of the welding, “It is good.” He nails it down so it will not be toppled.'),
('ISA', 41, 8, 'ISA.41.8', '“But you, O Israel, My servant, Jacob, whom I have chosen, descendant of Abraham My friend—'),
('ISA', 41, 9, 'ISA.41.9', 'I brought you from the ends of the earth and called you from its farthest corners. I said, ‘You are My servant.’ I have chosen and not rejected you.'),
('ISA', 41, 10, 'ISA.41.10', 'Do not fear, for I am with you; do not be afraid, for I am your God. I will strengthen you; I will surely help you; I will uphold you with My righteous right hand.'),
('ISA', 41, 11, 'ISA.41.11', 'Behold, all who rage against you will be ashamed and disgraced; those who contend with you will be reduced to nothing and will perish.'),
('ISA', 41, 12, 'ISA.41.12', 'You will seek them but will not find them. Those who wage war against you will come to nothing.'),
('ISA', 41, 13, 'ISA.41.13', 'For I am the LORD your God, who takes hold of your right hand and tells you: Do not fear, I will help you.'),
('ISA', 41, 14, 'ISA.41.14', 'Do not fear, O Jacob, you worm, O few men of Israel. I will help you,” declares the LORD. “Your Redeemer is the Holy One of Israel.'),
('ISA', 41, 15, 'ISA.41.15', 'Behold, I will make you into a threshing sledge, new and sharp, with many teeth. You will thresh the mountains and crush them, and reduce the hills to chaff.'),
('ISA', 41, 16, 'ISA.41.16', 'You will winnow them, and a wind will carry them away; a gale will scatter them. But you will rejoice in the LORD; you will glory in the Holy One of Israel.'),
('ISA', 41, 17, 'ISA.41.17', 'The poor and needy seek water, but there is none; their tongues are parched with thirst. I, the LORD, will answer them; I, the God of Israel, will not forsake them.'),
('ISA', 41, 18, 'ISA.41.18', 'I will open rivers on the barren heights, and fountains in the middle of the valleys. I will turn the desert into a pool of water, and the dry land into flowing springs.'),
('ISA', 41, 19, 'ISA.41.19', 'I will plant cedars in the wilderness, acacias, myrtles, and olive trees. I will set cypresses in the desert, elms and boxwood together,'),
('ISA', 41, 20, 'ISA.41.20', 'so that all may see and know, may consider and understand, that the hand of the LORD has done this and the Holy One of Israel has created it.”'),
('ISA', 41, 21, 'ISA.41.21', '“Present your case,” says the LORD. “Submit your arguments,” says the King of Jacob.'),
('ISA', 41, 22, 'ISA.41.22', '“Let them come and tell us what will happen. Tell the former things, so that we may reflect on them and know the outcome. Or announce to us what is coming.'),
('ISA', 41, 23, 'ISA.41.23', 'Tell us the things that are to come, so that we may know that you are gods. Yes, do something good or evil, that we may look on together in dismay.'),
('ISA', 41, 24, 'ISA.41.24', 'Behold, you are nothing and your work is of no value. Anyone who chooses you is detestable.'),
('ISA', 41, 25, 'ISA.41.25', 'I have raised up one from the north, and he has come—one from the east who calls on My name. He will march over rulers as if they were mortar, like a potter who treads the clay.'),
('ISA', 41, 26, 'ISA.41.26', 'Who has declared this from the beginning, so that we may know, and from times past, so that we may say: ‘He was right’? No one announced it, no one foretold it, no one heard your words.'),
('ISA', 41, 27, 'ISA.41.27', 'I was the first to tell Zion: ‘Look, here they are!’ And I gave to Jerusalem a herald of good news.'),
('ISA', 41, 28, 'ISA.41.28', 'When I look, there is no one; there is no counselor among them; when I ask them, they have nothing to say.'),
('ISA', 41, 29, 'ISA.41.29', 'See, they are all a delusion; their works amount to nothing; their images are as empty as the wind.'),
('ISA', 42, 1, 'ISA.42.1', '“Here is My Servant, whom I uphold, My Chosen One, in whom My soul delights. I will put My Spirit on Him, and He will bring justice to the nations.'),
('ISA', 42, 2, 'ISA.42.2', 'He will not cry out or raise His voice, nor make His voice heard in the streets.'),
('ISA', 42, 3, 'ISA.42.3', 'A bruised reed He will not break and a smoldering wick He will not extinguish; He will faithfully bring forth justice.'),
('ISA', 42, 4, 'ISA.42.4', 'He will not grow weak or discouraged before He has established justice on the earth. In His law the islands will put their hope.”'),
('ISA', 42, 5, 'ISA.42.5', 'This is what God the LORD says—He who created the heavens and stretched them out, who spread out the earth and its offspring, who gives breath to the people on it and life to those who walk in it:'),
('ISA', 42, 6, 'ISA.42.6', '“I, the LORD, have called you for a righteous purpose, and I will take hold of your hand. I will keep you and appoint you to be a covenant for the people and a light to the nations,'),
('ISA', 42, 7, 'ISA.42.7', 'to open the eyes of the blind, to bring prisoners out of the dungeon and those sitting in darkness out from the prison house.'),
('ISA', 42, 8, 'ISA.42.8', 'I am the LORD; that is My name! I will not yield My glory to another or My praise to idols.'),
('ISA', 42, 9, 'ISA.42.9', 'Behold, the former things have happened, and now I declare new things. Before they spring forth I proclaim them to you.”'),
('ISA', 42, 10, 'ISA.42.10', 'Sing to the LORD a new song—His praise from the ends of the earth—you who go down to the sea, and all that is in it, you islands, and all who dwell in them.'),
('ISA', 42, 11, 'ISA.42.11', 'Let the desert and its cities raise their voices; let the villages of Kedar cry aloud. Let the people of Sela sing for joy; let them cry out from the mountaintops.'),
('ISA', 42, 12, 'ISA.42.12', 'Let them give glory to the LORD and declare His praise in the islands.'),
('ISA', 42, 13, 'ISA.42.13', 'The LORD goes forth like a mighty one; He stirs up His zeal like a warrior. He shouts; yes, He roars in triumph over His enemies:'),
('ISA', 42, 14, 'ISA.42.14', '“I have kept silent from ages past; I have remained quiet and restrained. But now I will groan like a woman in labor; I will at once gasp and pant.'),
('ISA', 42, 15, 'ISA.42.15', 'I will lay waste the mountains and hills and dry up all their vegetation. I will turn the rivers into dry land and drain the marshes.'),
('ISA', 42, 16, 'ISA.42.16', 'I will lead the blind by a way they did not know; I will guide them on unfamiliar paths. I will turn darkness into light before them and rough places into level ground. These things I will do for them, and I will not forsake them.'),
('ISA', 42, 17, 'ISA.42.17', 'But those who trust in idols and say to molten images, ‘You are our gods!’ will be turned back in utter shame.'),
('ISA', 42, 18, 'ISA.42.18', 'Listen, you deaf ones; look, you blind ones, that you may see!'),
('ISA', 42, 19, 'ISA.42.19', 'Who is blind but My servant, or deaf like the messenger I am sending? Who is blind like My covenant partner, or blind like the servant of the LORD?'),
('ISA', 42, 20, 'ISA.42.20', 'Though seeing many things, you do not keep watch. Though your ears are open, you do not hear.”'),
('ISA', 42, 21, 'ISA.42.21', 'The LORD was pleased, for the sake of His righteousness, to magnify His law and make it glorious.'),
('ISA', 42, 22, 'ISA.42.22', 'But this is a people plundered and looted, all trapped in caves or imprisoned in dungeons. They have become plunder with no one to rescue them, and loot with no one to say, “Send them back!”'),
('ISA', 42, 23, 'ISA.42.23', 'Who among you will pay attention to this? Who will listen and obey hereafter?'),
('ISA', 42, 24, 'ISA.42.24', 'Who gave Jacob up for spoil, and Israel to the plunderers? Was it not the LORD, against whom we have sinned? They were unwilling to walk in His ways, and they would not obey His law.'),
('ISA', 42, 25, 'ISA.42.25', 'So He poured out on them His furious anger and the fierceness of battle. It enveloped them in flames, but they did not understand; it consumed them, but they did not take it to heart.'),
('ISA', 43, 1, 'ISA.43.1', 'But now, this is what the LORD says—He who created you, O Jacob, and He who formed you, O Israel: “Do not fear, for I have redeemed you; I have called you by your name; you are Mine!'),
('ISA', 43, 2, 'ISA.43.2', 'When you pass through the waters, I will be with you; and when you go through the rivers, they will not overwhelm you. When you walk through the fire, you will not be scorched; the flames will not set you ablaze.'),
('ISA', 43, 3, 'ISA.43.3', 'For I am the LORD your God, the Holy One of Israel, your Savior; I give Egypt for your ransom, Cush and Seba in your place.'),
('ISA', 43, 4, 'ISA.43.4', 'Because you are precious and honored in My sight, and because I love you, I will give men in exchange for you and nations in place of your life.'),
('ISA', 43, 5, 'ISA.43.5', 'Do not be afraid, for I am with you; I will bring your offspring from the east and gather you from the west.'),
('ISA', 43, 6, 'ISA.43.6', 'I will say to the north, ‘Give them up!’ and to the south, ‘Do not hold them back!’ Bring My sons from afar, and My daughters from the ends of the earth—'),
('ISA', 43, 7, 'ISA.43.7', 'everyone called by My name and created for My glory, whom I have indeed formed and made.”'),
('ISA', 43, 8, 'ISA.43.8', 'Bring out a people who have eyes but are blind, and who have ears but are deaf.'),
('ISA', 43, 9, 'ISA.43.9', 'All the nations gather together and the peoples assemble. Who among them can declare this, and proclaim to us the former things? Let them present their witnesses to vindicate them, so that others may hear and say, “It is true.”'),
('ISA', 43, 10, 'ISA.43.10', '“You are My witnesses,” declares the LORD, “and My servant whom I have chosen, so that you may consider and believe Me and understand that I am He. Before Me no god was formed, and after Me none will come.'),
('ISA', 43, 11, 'ISA.43.11', 'I, yes I, am the LORD, and there is no Savior but Me.'),
('ISA', 43, 12, 'ISA.43.12', 'I alone decreed and saved and proclaimed—I, and not some foreign god among you. So you are My witnesses,” declares the LORD, “that I am God.'),
('ISA', 43, 13, 'ISA.43.13', 'Even from eternity I am He, and none can deliver out of My hand. When I act, who can reverse it?”'),
('ISA', 43, 14, 'ISA.43.14', 'Thus says the LORD your Redeemer, the Holy One of Israel: “For your sake, I will send to Babylon and bring them all as fugitives, even the Chaldeans, in the ships in which they rejoice.'),
('ISA', 43, 15, 'ISA.43.15', 'I am the LORD, your Holy One, the Creator of Israel, and your King.”'),
('ISA', 43, 16, 'ISA.43.16', 'Thus says the LORD, who makes a way in the sea and a path through the surging waters,'),
('ISA', 43, 17, 'ISA.43.17', 'who brings out the chariots and horses, the armies and warriors together, to lie down, never to rise again; to be extinguished, snuffed out like a wick:'),
('ISA', 43, 18, 'ISA.43.18', '“Do not call to mind the former things; pay no attention to the things of old.'),
('ISA', 43, 19, 'ISA.43.19', 'Behold, I am about to do something new; even now it is coming. Do you not see it? Indeed, I will make a way in the wilderness and streams in the desert.'),
('ISA', 43, 20, 'ISA.43.20', 'The beasts of the field will honor Me, the jackals and the ostriches, because I provide water in the wilderness and rivers in the desert, to give drink to My chosen people.'),
('ISA', 43, 21, 'ISA.43.21', 'The people I formed for Myself will declare My praise.'),
('ISA', 43, 22, 'ISA.43.22', 'But you have not called on Me, O Jacob, because you have grown weary of Me, O Israel.'),
('ISA', 43, 23, 'ISA.43.23', 'You have not brought Me sheep for burnt offerings, nor honored Me with your sacrifices. I have not burdened you with offerings, nor wearied you with frankincense.'),
('ISA', 43, 24, 'ISA.43.24', 'You have not bought Me sweet cane with your silver, nor satisfied Me with the fat of your sacrifices. But you have burdened Me with your sins; you have wearied Me with your iniquities.'),
('ISA', 43, 25, 'ISA.43.25', 'I, yes I, am He who blots out your transgressions for My own sake and remembers your sins no more.'),
('ISA', 43, 26, 'ISA.43.26', 'Remind Me, let us argue the matter together. State your case, so that you may be vindicated.'),
('ISA', 43, 27, 'ISA.43.27', 'Your first father sinned, and your spokesmen rebelled against Me.'),
('ISA', 43, 28, 'ISA.43.28', 'So I will disgrace the princes of your sanctuary, and I will devote Jacob to destruction and Israel to reproach.”'),
('ISA', 44, 1, 'ISA.44.1', 'But now listen, O Jacob My servant, Israel, whom I have chosen.'),
('ISA', 44, 2, 'ISA.44.2', 'This is the word of the LORD, your Maker, who formed you from the womb and who will help you: “Do not be afraid, O Jacob My servant, Jeshurun, whom I have chosen.'),
('ISA', 44, 3, 'ISA.44.3', 'For I will pour water on the thirsty land, and currents on the dry ground. I will pour out My Spirit on your descendants, and My blessing on your offspring.'),
('ISA', 44, 4, 'ISA.44.4', 'They will sprout among the grass like willows by flowing streams.'),
('ISA', 44, 5, 'ISA.44.5', 'One will say, ‘I belong to the LORD,’ another will call himself by the name of Jacob, and still another will write on his hand, ‘The LORD’s,’ and will take the name of Israel.”'),
('ISA', 44, 6, 'ISA.44.6', 'Thus says the LORD, the King and Redeemer of Israel, the LORD of Hosts: “I am the first and I am the last, and there is no God but Me.'),
('ISA', 44, 7, 'ISA.44.7', 'Who then is like Me? Let him say so! Let him declare his case before Me, since I established an ancient people. Let him foretell the things to come, and what is to take place.'),
('ISA', 44, 8, 'ISA.44.8', 'Do not tremble or fear. Have I not told you and declared it long ago? You are My witnesses! Is there any God but Me? There is no other Rock; I know not one.”'),
('ISA', 44, 9, 'ISA.44.9', 'All makers of idols are nothing, and the things they treasure are worthless. Their witnesses fail to see or comprehend, so they are put to shame.'),
('ISA', 44, 10, 'ISA.44.10', 'Who fashions a god or casts an idol which profits him nothing?'),
('ISA', 44, 11, 'ISA.44.11', 'Behold, all his companions will be put to shame, for the craftsmen themselves are only human. Let them all assemble and take their stand; they will all be brought to terror and shame.'),
('ISA', 44, 12, 'ISA.44.12', 'The blacksmith takes a tool and labors over the coals; he fashions an idol with hammers and forges it with his strong arms. Yet he grows hungry and loses his strength; he fails to drink water and grows faint.'),
('ISA', 44, 13, 'ISA.44.13', 'The woodworker extends a measuring line; he marks it out with a stylus; he shapes it with chisels and outlines it with a compass. He fashions it in the likeness of man, like man in all his glory, that it may dwell in a shrine.'),
('ISA', 44, 14, 'ISA.44.14', 'He cuts down cedars or retrieves a cypress or oak. He lets it grow strong among the trees of the forest. He plants a laurel, and the rain makes it grow.'),
('ISA', 44, 15, 'ISA.44.15', 'It serves as fuel for man. He takes some of it to warm himself, and he kindles a fire and bakes his bread. He also fashions it into a god and worships it; he makes an idol and bows down to it.'),
('ISA', 44, 16, 'ISA.44.16', 'He burns half of it in the fire, and he roasts meat on that half. He eats the roast and is satisfied. Indeed, he warms himself and says, “Ah! I am warm; I see the fire.”'),
('ISA', 44, 17, 'ISA.44.17', 'From the rest he makes a god, his graven image. He bows down to it and worships; he prays to it and says, “Save me, for you are my god.”'),
('ISA', 44, 18, 'ISA.44.18', 'They do not comprehend or discern, for He has shut their eyes so they cannot see and closed their minds so they cannot understand.'),
('ISA', 44, 19, 'ISA.44.19', 'And no one considers in his heart, no one has the knowledge or insight to say, “I burned half of it in the fire, and I baked bread on its coals; I roasted meat and I ate. Shall I make something detestable with the rest of it? Shall I bow down to a block of wood?”'),
('ISA', 44, 20, 'ISA.44.20', 'He feeds on ashes. His deluded heart has led him astray, and he cannot deliver himself or say, “Is not this thing in my right hand a lie?”'),
('ISA', 44, 21, 'ISA.44.21', 'Remember these things, O Jacob, for you are My servant, O Israel. I have made you, and you are My servant; O Israel, I will never forget you.'),
('ISA', 44, 22, 'ISA.44.22', 'I have blotted out your transgressions like a cloud, and your sins like a mist. Return to Me, for I have redeemed you.'),
('ISA', 44, 23, 'ISA.44.23', 'Sing for joy, O heavens, for the LORD has done this; shout aloud, O depths of the earth. Break forth in song, O mountains, you forests and all your trees. For the LORD has redeemed Jacob, and revealed His glory in Israel.'),
('ISA', 44, 24, 'ISA.44.24', 'Thus says the LORD, your Redeemer who formed you from the womb: “I am the LORD, who has made all things, who alone stretched out the heavens, who by Myself spread out the earth,'),
('ISA', 44, 25, 'ISA.44.25', 'who foils the signs of false prophets and makes fools of diviners, who confounds the wise and turns their knowledge into nonsense,'),
('ISA', 44, 26, 'ISA.44.26', 'who confirms the message of His servant and fulfills the counsel of His messengers, who says of Jerusalem, ‘She will be inhabited,’ and of the cities of Judah, ‘They will be rebuilt, and I will restore their ruins,’'),
('ISA', 44, 27, 'ISA.44.27', 'who says to the depths of the sea, ‘Be dry, and I will dry up your currents,’'),
('ISA', 44, 28, 'ISA.44.28', 'who says of Cyrus, ‘My shepherd will fulfill all that I desire,’ who says of Jerusalem, ‘She will be rebuilt,’ and of the temple, ‘Let its foundation be laid.’”'),
('ISA', 45, 1, 'ISA.45.1', 'This is what the LORD says to Cyrus His anointed, whose right hand I have grasped to subdue nations before him, to disarm kings, to open the doors before him, so that the gates will not be shut:'),
('ISA', 45, 2, 'ISA.45.2', '“I will go before you and level the mountains; I will break down the gates of bronze and cut through the bars of iron.'),
('ISA', 45, 3, 'ISA.45.3', 'I will give you the treasures of darkness and the riches hidden in secret places, so that you may know that I am the LORD, the God of Israel, who calls you by name.'),
('ISA', 45, 4, 'ISA.45.4', 'For the sake of Jacob My servant and Israel My chosen one, I call you by name; I have given you a title of honor, though you have not known Me.'),
('ISA', 45, 5, 'ISA.45.5', 'I am the LORD, and there is no other; there is no God but Me. I will equip you for battle, though you have not known Me,'),
('ISA', 45, 6, 'ISA.45.6', 'so that all may know, from where the sun rises to where it sets, that there is none but Me; I am the LORD, and there is no other.'),
('ISA', 45, 7, 'ISA.45.7', 'I form the light and create the darkness; I bring prosperity and create calamity. I, the LORD, do all these things.'),
('ISA', 45, 8, 'ISA.45.8', 'Drip down, O heavens, from above, and let the skies pour down righteousness. Let the earth open up that salvation may sprout and righteousness spring up with it; I, the LORD, have created it.'),
('ISA', 45, 9, 'ISA.45.9', 'Woe to him who quarrels with his Maker—one clay pot among many. Does the clay ask the potter, ‘What are you making?’ Does your work say, ‘He has no hands’?'),
('ISA', 45, 10, 'ISA.45.10', 'Woe to him who says to his father, ‘What have you begotten?’ or to his mother, ‘What have you brought forth?’”'),
('ISA', 45, 11, 'ISA.45.11', 'Thus says the LORD, the Holy One of Israel, and its Maker: “Concerning things to come, do you question Me about My sons, or instruct Me in the work of My hands?'),
('ISA', 45, 12, 'ISA.45.12', 'It is I who made the earth and created man upon it. It was My hands that stretched out the heavens, and I ordained all their host.'),
('ISA', 45, 13, 'ISA.45.13', 'I will raise up Cyrus in righteousness, and I will make all his ways straight. He will rebuild My city and set My exiles free, but not for payment or reward, says the LORD of Hosts.”'),
('ISA', 45, 14, 'ISA.45.14', 'This is what the LORD says: “The products of Egypt and the merchandise of Cush, along with the Sabeans, men of stature, will come over to you and will be yours; they will trudge behind you; they will come over in chains and bow down to you. They will confess to you: ‘God is indeed with you, and there is no other; there is no other God.’”'),
('ISA', 45, 15, 'ISA.45.15', 'Truly You are a God who hides Himself, O God of Israel, the Savior.'),
('ISA', 45, 16, 'ISA.45.16', 'They will all be put to shame and humiliated; the makers of idols will depart together in disgrace.'),
('ISA', 45, 17, 'ISA.45.17', 'But Israel will be saved by the LORD with an everlasting salvation; you will not be put to shame or humiliated, to ages everlasting.'),
('ISA', 45, 18, 'ISA.45.18', 'For thus says the LORD, who created the heavens—He is God; He formed the earth and fashioned it; He established it; He did not create it to be empty, but formed it to be inhabited: “I am the LORD, and there is no other.'),
('ISA', 45, 19, 'ISA.45.19', 'I have not spoken in secret, from a place in a land of darkness. I did not say to the descendants of Jacob, ‘Seek Me in a wasteland.’ I, the LORD, speak the truth; I say what is right.'),
('ISA', 45, 20, 'ISA.45.20', 'Come, gather together, and draw near, you fugitives from the nations. Ignorant are those who carry idols of wood and pray to a god that cannot save.'),
('ISA', 45, 21, 'ISA.45.21', 'Speak up and present your case—yes, let them take counsel together. Who foretold this long ago? Who announced it from ancient times? Was it not I, the LORD? There is no other God but Me, a righteous God and Savior; there is none but Me.'),
('ISA', 45, 22, 'ISA.45.22', 'Turn to Me and be saved, all the ends of the earth; for I am God, and there is no other.'),
('ISA', 45, 23, 'ISA.45.23', 'By Myself I have sworn; truth has gone out from My mouth, a word that will not be revoked: Every knee will bow before Me, every tongue will swear allegiance.'),
('ISA', 45, 24, 'ISA.45.24', 'Surely they will say of Me, ‘In the LORD alone are righteousness and strength.’” All who rage against Him will come to Him and be put to shame.'),
('ISA', 45, 25, 'ISA.45.25', 'In the LORD all descendants of Israel will be justified and will exult.'),
('ISA', 46, 1, 'ISA.46.1', 'Bel crouches; Nebo cowers. Their idols weigh down beasts and cattle. The images you carry are burdensome, a load to the weary animal.'),
('ISA', 46, 2, 'ISA.46.2', 'The gods cower; they crouch together, unable to relieve the burden; but they themselves go into captivity.'),
('ISA', 46, 3, 'ISA.46.3', '“Listen to Me, O house of Jacob, all the remnant of the house of Israel, who have been sustained from the womb, carried along since birth.'),
('ISA', 46, 4, 'ISA.46.4', 'Even to your old age, I will be the same, and I will bear you up when you turn gray. I have made you, and I will carry you; I will sustain you and deliver you.'),
('ISA', 46, 5, 'ISA.46.5', 'To whom will you liken Me or count Me equal? To whom will you compare Me, that we should be alike?'),
('ISA', 46, 6, 'ISA.46.6', 'They pour out their bags of gold and weigh out silver on scales; they hire a goldsmith to fashion it into a god, so they can bow down and worship.'),
('ISA', 46, 7, 'ISA.46.7', 'They lift it to their shoulder and carry it along; they set it in its place, and there it stands, not budging from that spot. They cry out to it, but it does not answer; it saves no one from his troubles.'),
('ISA', 46, 8, 'ISA.46.8', 'Remember this and be brave; take it to heart, you transgressors!'),
('ISA', 46, 9, 'ISA.46.9', 'Remember what happened long ago, for I am God, and there is no other; I am God, and there is none like Me.'),
('ISA', 46, 10, 'ISA.46.10', 'I declare the end from the beginning, and from ancient times what is still to come. I say, ‘My purpose will stand, and all My good pleasure I will accomplish.’'),
('ISA', 46, 11, 'ISA.46.11', 'I summon a bird of prey from the east, a man for My purpose from a far-off land. Truly I have spoken, and truly I will bring it to pass. I have planned it, and I will surely do it.'),
('ISA', 46, 12, 'ISA.46.12', 'Listen to Me, you stubborn people, far removed from righteousness:'),
('ISA', 46, 13, 'ISA.46.13', 'I am bringing My righteousness near; it is not far away, and My salvation will not be delayed. I will grant salvation to Zion and adorn Israel with My splendor.'),
('ISA', 47, 1, 'ISA.47.1', '“Go down and sit in the dust, O Virgin Daughter of Babylon. Sit on the ground without a throne, O Daughter of the Chaldeans! For you will no longer be called tender or delicate.'),
('ISA', 47, 2, 'ISA.47.2', 'Take millstones and grind flour; remove your veil; strip off your skirt, bare your thigh, and wade through the streams.'),
('ISA', 47, 3, 'ISA.47.3', 'Your nakedness will be uncovered and your shame will be exposed. I will take vengeance; I will spare no one.”'),
('ISA', 47, 4, 'ISA.47.4', 'Our Redeemer—the LORD of Hosts is His name—is the Holy One of Israel.'),
('ISA', 47, 5, 'ISA.47.5', '“Sit in silence and go into darkness, O Daughter of the Chaldeans. For you will no longer be called the queen of kingdoms.'),
('ISA', 47, 6, 'ISA.47.6', 'I was angry with My people; I profaned My heritage, and I placed them under your control. You showed them no mercy; even on the elderly you laid a most heavy yoke.'),
('ISA', 47, 7, 'ISA.47.7', 'You said, ‘I will be queen forever.’ You did not take these things to heart or consider their outcome.'),
('ISA', 47, 8, 'ISA.47.8', 'So now hear this, O lover of luxury who sits securely, who says to herself, ‘I am, and there is none besides me. I will never be a widow or know the loss of children.’'),
('ISA', 47, 9, 'ISA.47.9', 'These two things will overtake you in a moment, in a single day: loss of children, and widowhood. They will come upon you in full measure, in spite of your many sorceries and the potency of your spells.'),
('ISA', 47, 10, 'ISA.47.10', 'You were secure in your wickedness; you said, ‘No one sees me.’ Your wisdom and knowledge led you astray; you told yourself, ‘I am, and there is none besides me.’'),
('ISA', 47, 11, 'ISA.47.11', 'But disaster will come upon you; you will not know how to charm it away. A calamity will befall you that you will be unable to ward off. Devastation will happen to you suddenly and unexpectedly.'),
('ISA', 47, 12, 'ISA.47.12', 'So take your stand with your spells and with your many sorceries, with which you have wearied yourself from your youth. Perhaps you will succeed; perhaps you will inspire terror!'),
('ISA', 47, 13, 'ISA.47.13', 'You are wearied by your many counselors; let them come forward now and save you—your astrologers who observe the stars, who monthly predict your fate.'),
('ISA', 47, 14, 'ISA.47.14', 'Surely they are like stubble; the fire will burn them up. They cannot deliver themselves from the power of the flame. There will be no coals to warm them or fire to sit beside.'),
('ISA', 47, 15, 'ISA.47.15', 'This is what they are to you—those with whom you have labored and traded from youth—each one strays in his own direction; not one of them can save you.'),
('ISA', 48, 1, 'ISA.48.1', '“Listen to this, O house of Jacob, you who are called by the name of Israel, who have descended from the line of Judah, who swear by the name of the LORD, who invoke the God of Israel—but not in truth or righteousness—'),
('ISA', 48, 2, 'ISA.48.2', 'who indeed call yourselves after the holy city and lean on the God of Israel; the LORD of Hosts is His name.'),
('ISA', 48, 3, 'ISA.48.3', 'I foretold the former things long ago; they came out of My mouth and I proclaimed them. Suddenly I acted, and they came to pass.'),
('ISA', 48, 4, 'ISA.48.4', 'For I knew that you are stubborn; your neck is iron and your forehead is bronze.'),
('ISA', 48, 5, 'ISA.48.5', 'Therefore I declared it to you long ago; I announced it before it came to pass, so that you could not claim, ‘My idol has done this; my carved image and molten god has ordained it.’'),
('ISA', 48, 6, 'ISA.48.6', 'You have heard these things; look at them all. Will you not acknowledge them? From now on I will tell you of new things, hidden things unknown to you.'),
('ISA', 48, 7, 'ISA.48.7', 'They are created now, and not long ago; you have not heard of them before today. So you cannot claim, ‘I already knew them!’'),
('ISA', 48, 8, 'ISA.48.8', 'You have never heard; you have never understood; for a long time your ears have not been open. For I knew how deceitful you are; you have been called a rebel from birth.'),
('ISA', 48, 9, 'ISA.48.9', 'For the sake of My name I will delay My wrath; for the sake of My praise I will restrain it, so that you will not be cut off.'),
('ISA', 48, 10, 'ISA.48.10', 'See, I have refined you, but not as silver; I have tested you in the furnace of affliction.'),
('ISA', 48, 11, 'ISA.48.11', 'For My own sake, My very own sake, I will act; for how can I let Myself be defamed? I will not yield My glory to another.'),
('ISA', 48, 12, 'ISA.48.12', 'Listen to Me, O Jacob, and Israel, whom I have called: I am He; I am the first, and I am the last.'),
('ISA', 48, 13, 'ISA.48.13', 'Surely My own hand founded the earth, and My right hand spread out the heavens; when I summon them, they stand up together.'),
('ISA', 48, 14, 'ISA.48.14', 'Come together, all of you, and listen: Which of the idols has foretold these things? The LORD’s chosen ally will carry out His desire against Babylon, and His arm will be against the Chaldeans.'),
('ISA', 48, 15, 'ISA.48.15', 'I, even I, have spoken; yes, I have called him. I have brought him, and he will succeed in his mission.'),
('ISA', 48, 16, 'ISA.48.16', 'Come near to Me and listen to this: From the beginning I have not spoken in secret; from the time it happened, I was there.” And now the Lord GOD has sent me, accompanied by His Spirit.'),
('ISA', 48, 17, 'ISA.48.17', 'Thus says the LORD your Redeemer, the Holy One of Israel: “I am the LORD your God, who teaches you for your benefit, who directs you in the way you should go.'),
('ISA', 48, 18, 'ISA.48.18', 'If only you had paid attention to My commandments, your peace would have been like a river, and your righteousness like waves of the sea.'),
('ISA', 48, 19, 'ISA.48.19', 'Your descendants would have been as countless as the sand, and your offspring as numerous as its grains; their name would never be cut off or eliminated from My presence.”'),
('ISA', 48, 20, 'ISA.48.20', 'Leave Babylon! Flee from the Chaldeans! Declare it with a shout of joy, proclaim it, let it go out to the ends of the earth, saying, “The LORD has redeemed His servant Jacob!”'),
('ISA', 48, 21, 'ISA.48.21', 'They did not thirst when He led them through the deserts; He made water flow for them from the rock; He split the rock, and water gushed out.'),
('ISA', 48, 22, 'ISA.48.22', '“There is no peace,” says the LORD, “for the wicked.”'),
('ISA', 49, 1, 'ISA.49.1', 'Listen to Me, O islands; pay attention, O distant peoples: The LORD called Me from the womb; from the body of My mother He named Me.'),
('ISA', 49, 2, 'ISA.49.2', 'He made My mouth like a sharp sword; He hid Me in the shadow of His hand. He made Me like a polished arrow; He hid Me in His quiver.'),
('ISA', 49, 3, 'ISA.49.3', 'He said to Me, “You are My Servant, Israel, in whom I will display My glory.”'),
('ISA', 49, 4, 'ISA.49.4', 'But I said, “I have labored in vain, I have spent My strength in futility and vanity; yet My vindication is with the LORD, and My reward is with My God.”'),
('ISA', 49, 5, 'ISA.49.5', 'And now says the LORD, who formed Me from the womb to be His Servant, to bring Jacob back to Him, that Israel might be gathered to Him—for I am honored in the sight of the LORD, and My God is My strength—'),
('ISA', 49, 6, 'ISA.49.6', 'He says: “It is not enough for You to be My Servant, to raise up the tribes of Jacob, and to restore the protected ones of Israel. I will also make You a light for the nations, to bring My salvation to the ends of the earth.”'),
('ISA', 49, 7, 'ISA.49.7', 'Thus says the LORD, the Redeemer and Holy One of Israel, to Him who was despised and abhorred by the nation, to the Servant of rulers: “Kings will see You and rise, and princes will bow down, because of the LORD, who is faithful, the Holy One of Israel, who has chosen You.”'),
('ISA', 49, 8, 'ISA.49.8', 'This is what the LORD says: “In the time of favor I will answer You, and in the day of salvation I will help You; I will keep You and appoint You to be a covenant for the people, to restore the land, to apportion its desolate inheritances,'),
('ISA', 49, 9, 'ISA.49.9', 'to say to the prisoners, ‘Come out,’ and to those in darkness, ‘Show yourselves.’ They will feed along the pathways, and find pasture on every barren hill.'),
('ISA', 49, 10, 'ISA.49.10', 'They will not hunger or thirst, nor will scorching heat or sun beat down on them. For He who has compassion on them will guide them and lead them beside springs of water.'),
('ISA', 49, 11, 'ISA.49.11', 'I will turn all My mountains into roads, and My highways will be raised up.'),
('ISA', 49, 12, 'ISA.49.12', 'Behold, they will come from far away, from the north and from the west, and from the land of Aswan.”'),
('ISA', 49, 13, 'ISA.49.13', 'Shout for joy, O heavens; rejoice, O earth; break forth in song, O mountains! For the LORD has comforted His people, and He will have compassion on His afflicted ones.'),
('ISA', 49, 14, 'ISA.49.14', 'But Zion said, “The LORD has forsaken me; the Lord has forgotten me!”'),
('ISA', 49, 15, 'ISA.49.15', '“Can a woman forget her nursing child, or lack compassion for the son of her womb? Even if she could forget, I will not forget you!'),
('ISA', 49, 16, 'ISA.49.16', 'Behold, I have inscribed you on the palms of My hands; your walls are ever before Me.'),
('ISA', 49, 17, 'ISA.49.17', 'Your builders hasten back; your destroyers and wreckers depart from you.'),
('ISA', 49, 18, 'ISA.49.18', 'Lift up your eyes and look around. They all gather together; they come to you. As surely as I live,” declares the LORD, “you will wear them all as jewelry and put them on like a bride.'),
('ISA', 49, 19, 'ISA.49.19', 'For your ruined and desolate places and your ravaged land will now indeed be too small for your people, and those who devoured you will be far away.'),
('ISA', 49, 20, 'ISA.49.20', 'Yet the children of your bereavement will say in your hearing, ‘This place is too small for us; make room for us to live here.’'),
('ISA', 49, 21, 'ISA.49.21', 'Then you will say in your heart, ‘Who has begotten these for me? I was bereaved and barren; I was exiled and rejected. So who has reared them? Look, I was left all alone, so where did they come from?’”'),
('ISA', 49, 22, 'ISA.49.22', 'This is what the Lord GOD says: “Behold, I will lift up My hand to the nations, and raise My banner to the peoples. They will bring your sons in their arms and carry your daughters on their shoulders.'),
('ISA', 49, 23, 'ISA.49.23', 'Kings will be your foster fathers, and their queens your nursing mothers. They will bow to you facedown and lick the dust at your feet. Then you will know that I am the LORD; those who hope in Me will never be put to shame.”'),
('ISA', 49, 24, 'ISA.49.24', 'Can the plunder be snatched from the mighty, or the captives of a tyrant be delivered?'),
('ISA', 49, 25, 'ISA.49.25', 'Indeed, this is what the LORD says: “Even the captives of the mighty will be taken away, and the plunder of the tyrant will be retrieved; I will contend with those who contend with you, and I will save your children.'),
('ISA', 49, 26, 'ISA.49.26', 'I will make your oppressors eat their own flesh; they will be drunk on their own blood, as with wine. Then all mankind will know that I, the LORD, am your Savior and your Redeemer, the Mighty One of Jacob.”'),
('ISA', 50, 1, 'ISA.50.1', 'This is what the LORD says: “Where is your mother’s certificate of divorce with which I sent her away? Or to which of My creditors did I sell you? Look, you were sold for your iniquities, and for your transgressions your mother was sent away.'),
('ISA', 50, 2, 'ISA.50.2', 'Why was no one there when I arrived? Why did no one answer when I called? Is My hand too short to redeem you? Or do I lack the strength to deliver you? Behold, My rebuke dries up the sea; I turn the rivers into a desert; the fish rot for lack of water and die of thirst.'),
('ISA', 50, 3, 'ISA.50.3', 'I clothe the heavens in black and make sackcloth their covering.”'),
('ISA', 50, 4, 'ISA.50.4', 'The Lord GOD has given Me the tongue of discipleship, to sustain the weary with a word. He awakens Me morning by morning; He awakens My ear to listen as a disciple.'),
('ISA', 50, 5, 'ISA.50.5', 'The Lord GOD has opened My ears, and I have not been rebellious, nor have I turned back.'),
('ISA', 50, 6, 'ISA.50.6', 'I offered My back to those who struck Me, and My cheeks to those who tore out My beard. I did not hide My face from scorn and spittle.'),
('ISA', 50, 7, 'ISA.50.7', 'Because the Lord GOD helps Me, I have not been disgraced; therefore I have set My face like flint, and I know that I will not be put to shame.'),
('ISA', 50, 8, 'ISA.50.8', 'The One who vindicates Me is near. Who will dare to contend with Me? Let us confront each other! Who has a case against Me? Let him approach Me!'),
('ISA', 50, 9, 'ISA.50.9', 'Surely the Lord GOD helps Me. Who is there to condemn Me? See, they will all wear out like a garment; the moths will devour them.'),
('ISA', 50, 10, 'ISA.50.10', 'Who among you fears the LORD and obeys the voice of His Servant? Who among you walks in darkness and has no light? Let him trust in the name of the LORD; let him lean on his God.'),
('ISA', 50, 11, 'ISA.50.11', 'Behold, all you who kindle a fire, who array yourselves with firebrands, walk in the light of your fire and of the firebrands you have lit! This is what you will receive from My hand: You will lie down in a place of torment.'),
('ISA', 51, 1, 'ISA.51.1', '“Listen to Me, you who pursue righteousness, you who seek the LORD: Look to the rock from which you were cut, and to the quarry from which you were hewn.'),
('ISA', 51, 2, 'ISA.51.2', 'Look to Abraham your father, and to Sarah who gave you birth. When I called him, he was but one; then I blessed him and multiplied him.'),
('ISA', 51, 3, 'ISA.51.3', 'For the LORD will comfort Zion and will look with compassion on all her ruins; He will make her wilderness like Eden and her desert like the garden of the LORD. Joy and gladness will be found in her, thanksgiving and melodious song.'),
('ISA', 51, 4, 'ISA.51.4', 'Pay attention to Me, My people, and listen to Me, My nation; for a law will go out from Me, and My justice will become a light to the nations; I will bring it about quickly.'),
('ISA', 51, 5, 'ISA.51.5', 'My righteousness draws near, My salvation is on the way, and My arms will bring justice to the nations. The islands will look for Me and wait in hope for My arm.'),
('ISA', 51, 6, 'ISA.51.6', 'Lift up your eyes to the heavens, and look at the earth below; for the heavens will vanish like smoke, the earth will wear out like a garment, and its people will die like gnats. But My salvation will last forever, and My righteousness will never fail.'),
('ISA', 51, 7, 'ISA.51.7', 'Listen to Me, you who know what is right, you people with My law in your hearts: Do not fear the scorn of men; do not be broken by their insults.'),
('ISA', 51, 8, 'ISA.51.8', 'For the moth will devour them like a garment, and the worm will eat them like wool. But My righteousness will last forever, My salvation through all generations.”'),
('ISA', 51, 9, 'ISA.51.9', 'Awake, awake, put on strength, O arm of the LORD. Wake up as in days past, as in generations of old. Was it not You who cut Rahab to pieces, who pierced through the dragon?'),
('ISA', 51, 10, 'ISA.51.10', 'Was it not You who dried up the sea, the waters of the great deep, who made a road in the depths of the sea for the redeemed to cross over?'),
('ISA', 51, 11, 'ISA.51.11', 'So the redeemed of the LORD will return and enter Zion with singing, crowned with everlasting joy. Gladness and joy will overtake them, and sorrow and sighing will flee.'),
('ISA', 51, 12, 'ISA.51.12', '“I, even I, am He who comforts you. Why should you be afraid of mortal man, of a son of man who withers like grass?'),
('ISA', 51, 13, 'ISA.51.13', 'But you have forgotten the LORD, your Maker, who stretched out the heavens and laid the foundations of the earth. You live in terror all day long because of the fury of the oppressor who is bent on destruction. But where is the fury of the oppressor?'),
('ISA', 51, 14, 'ISA.51.14', 'The captive will soon be freed; he will not die in the dungeon, and his bread will not be lacking.'),
('ISA', 51, 15, 'ISA.51.15', 'For I am the LORD your God who stirs up the sea so that its waves roar—the LORD of Hosts is His name.'),
('ISA', 51, 16, 'ISA.51.16', 'I have put My words in your mouth, and covered you with the shadow of My hand, to establish the heavens, to found the earth, and to say to Zion, ‘You are My people.’”'),
('ISA', 51, 17, 'ISA.51.17', 'Awake, awake! Rise up, O Jerusalem, you who have drunk from the hand of the LORD the cup of His fury; you who have drained the goblet to the dregs—the cup that makes men stagger.'),
('ISA', 51, 18, 'ISA.51.18', 'Among all the sons she bore, there is no one to guide her; among all the sons she brought up, there is no one to take her hand.'),
('ISA', 51, 19, 'ISA.51.19', 'These pairs have befallen you: devastation and destruction, famine and sword. Who will grieve for you? Who can comfort you?'),
('ISA', 51, 20, 'ISA.51.20', 'Your sons have fainted; they lie at the head of every street, like an antelope in a net. They are full of the wrath of the LORD, the rebuke of your God.'),
('ISA', 51, 21, 'ISA.51.21', 'Therefore now hear this, you afflicted one, drunken, but not with wine.'),
('ISA', 51, 22, 'ISA.51.22', 'Thus says your Lord, the LORD, even your God, who defends His people: “See, I have removed from your hand the cup of staggering. From that goblet, the cup of My fury, you will never drink again.'),
('ISA', 51, 23, 'ISA.51.23', 'I will place it in the hands of your tormentors, who told you: ‘Lie down, so we can walk over you,’ so that you made your back like the ground, like a street to be traversed.”'),
('ISA', 52, 1, 'ISA.52.1', 'Awake, awake, clothe yourself with strength, O Zion! Put on your garments of splendor, O Jerusalem, holy city! For the uncircumcised and unclean will no longer enter you.'),
('ISA', 52, 2, 'ISA.52.2', 'Shake off your dust! Rise up and sit on your throne, O Jerusalem. Remove the chains from your neck, O captive Daughter of Zion.'),
('ISA', 52, 3, 'ISA.52.3', 'For this is what the LORD says: “You were sold for nothing, and without money you will be redeemed.”'),
('ISA', 52, 4, 'ISA.52.4', 'For this is what the Lord GOD says: “At first My people went down to Egypt to live, then Assyria oppressed them without cause.'),
('ISA', 52, 5, 'ISA.52.5', 'And now what have I here? declares the LORD. For My people have been taken without cause; those who rule them taunt, declares the LORD, and My name is blasphemed continually all day long.'),
('ISA', 52, 6, 'ISA.52.6', 'Therefore My people will know My name; therefore they will know on that day that I am He who speaks. Here I am!”'),
('ISA', 52, 7, 'ISA.52.7', 'How beautiful on the mountains are the feet of those who bring good news, who proclaim peace, who bring good tidings, who proclaim salvation, who say to Zion, “Your God reigns!”'),
('ISA', 52, 8, 'ISA.52.8', 'Listen! Your watchmen lift up their voices, together they shout for joy. For every eye will see when the LORD returns to Zion.'),
('ISA', 52, 9, 'ISA.52.9', 'Break forth in joy, sing together, O ruins of Jerusalem, for the LORD has comforted His people; He has redeemed Jerusalem.'),
('ISA', 52, 10, 'ISA.52.10', 'The LORD has bared His holy arm in the sight of all the nations; all the ends of the earth will see the salvation of our God.'),
('ISA', 52, 11, 'ISA.52.11', 'Depart, depart, go out from there! Touch no unclean thing; come out from it, purify yourselves, you who carry the vessels of the LORD.'),
('ISA', 52, 12, 'ISA.52.12', 'For you will not leave in a hurry nor flee in haste, for the LORD goes before you, and the God of Israel is your rear guard.'),
('ISA', 52, 13, 'ISA.52.13', 'Behold, My Servant will prosper; He will be raised and lifted up and highly exalted.'),
('ISA', 52, 14, 'ISA.52.14', 'Just as many were appalled at Him—His appearance was disfigured beyond that of any man, and His form was marred beyond human likeness—'),
('ISA', 52, 15, 'ISA.52.15', 'so He will sprinkle many nations. Kings will shut their mouths because of Him. For they will see what they have not been told, and they will understand what they have not heard.'),
('ISA', 53, 1, 'ISA.53.1', 'Who has believed our message? And to whom has the arm of the LORD been revealed?'),
('ISA', 53, 2, 'ISA.53.2', 'He grew up before Him like a tender shoot, and like a root out of dry ground. He had no stately form or majesty to attract us, no beauty that we should desire Him.'),
('ISA', 53, 3, 'ISA.53.3', 'He was despised and rejected by men, a man of sorrows, acquainted with grief. Like one from whom men hide their faces, He was despised, and we esteemed Him not.'),
('ISA', 53, 4, 'ISA.53.4', 'Surely He took up our infirmities and carried our sorrows; yet we considered Him stricken, struck down by God, and afflicted.'),
('ISA', 53, 5, 'ISA.53.5', 'But He was pierced for our transgressions, He was crushed for our iniquities; the punishment that brought us peace was upon Him, and by His stripes we are healed.'),
('ISA', 53, 6, 'ISA.53.6', 'We all like sheep have gone astray, each one has turned to his own way; and the LORD has laid upon Him the iniquity of us all.'),
('ISA', 53, 7, 'ISA.53.7', 'He was oppressed and afflicted, yet He did not open His mouth. He was led like a lamb to the slaughter, and as a sheep before her shearers is silent, so He did not open His mouth.'),
('ISA', 53, 8, 'ISA.53.8', 'By oppression and judgment He was taken away, and who can recount His descendants? For He was cut off from the land of the living; He was stricken for the transgression of My people.'),
('ISA', 53, 9, 'ISA.53.9', 'He was assigned a grave with the wicked, and with a rich man in His death, although He had done no violence, nor was any deceit in His mouth.'),
('ISA', 53, 10, 'ISA.53.10', 'Yet it was the LORD’s will to crush Him and to cause Him to suffer; and when His soul is made a guilt offering, He will see His offspring, He will prolong His days, and the good pleasure of the LORD will prosper in His hand.'),
('ISA', 53, 11, 'ISA.53.11', 'After the anguish of His soul, He will see the light of life and be satisfied. By His knowledge My righteous Servant will justify many, and He will bear their iniquities.'),
('ISA', 53, 12, 'ISA.53.12', 'Therefore I will allot Him a portion with the great, and He will divide the spoils with the strong, because He has poured out His life unto death, and He was numbered with the transgressors. Yet He bore the sin of many and made intercession for the transgressors.'),
('ISA', 54, 1, 'ISA.54.1', '“Shout for joy, O barren woman, who bears no children; break forth in song and cry aloud, you who have never travailed; because more are the children of the desolate woman than of her who has a husband,” says the LORD.'),
('ISA', 54, 2, 'ISA.54.2', '“Enlarge the site of your tent, stretch out the curtains of your dwellings, do not hold back. Lengthen your ropes and drive your stakes in deep.'),
('ISA', 54, 3, 'ISA.54.3', 'For you will spread out to the right and left; your descendants will dispossess the nations and inhabit the desolate cities.'),
('ISA', 54, 4, 'ISA.54.4', 'Do not be afraid, for you will not be put to shame; do not be intimidated, for you will not be humiliated. For you will forget the shame of your youth and will remember no more the reproach of your widowhood.'),
('ISA', 54, 5, 'ISA.54.5', 'For your husband is your Maker—the LORD of Hosts is His name—the Holy One of Israel is your Redeemer; He is called the God of all the earth.'),
('ISA', 54, 6, 'ISA.54.6', 'For the LORD has called you back, like a wife deserted and wounded in spirit, like the rejected wife of one’s youth,” says your God.'),
('ISA', 54, 7, 'ISA.54.7', '“For a brief moment I forsook you, but with great compassion I will bring you back.'),
('ISA', 54, 8, 'ISA.54.8', 'In a surge of anger I hid My face from you for a moment, but with everlasting kindness I will have compassion on you,” says the LORD your Redeemer.'),
('ISA', 54, 9, 'ISA.54.9', '“For to Me this is like the days of Noah, when I swore that the waters of Noah would never again cover the earth. So I have sworn that I will not be angry with you or rebuke you.'),
('ISA', 54, 10, 'ISA.54.10', 'Though the mountains may be removed and the hills may be shaken, My loving devotion will not depart from you, and My covenant of peace will not be broken,” says the LORD, who has compassion on you.'),
('ISA', 54, 11, 'ISA.54.11', '“O afflicted city, lashed by storms, without solace, surely I will set your stones in antimony and lay your foundations with sapphires.'),
('ISA', 54, 12, 'ISA.54.12', 'I will make your pinnacles of rubies, your gates of sparkling jewels, and all your walls of precious stones.'),
('ISA', 54, 13, 'ISA.54.13', 'Then all your sons will be taught by the LORD, and great will be their prosperity.'),
('ISA', 54, 14, 'ISA.54.14', 'In righteousness you will be established, far from oppression, for you will have no fear. Terror will be far removed, for it will not come near you.'),
('ISA', 54, 15, 'ISA.54.15', 'If anyone attacks you, it is not from Me; whoever assails you will fall before you.'),
('ISA', 54, 16, 'ISA.54.16', 'Behold, I have created the craftsman who fans the coals into flame and forges a weapon fit for its task; and I have created the destroyer to wreak havoc.'),
('ISA', 54, 17, 'ISA.54.17', 'No weapon formed against you shall prosper, and you will refute every tongue that accuses you. This is the heritage of the servants of the LORD, and their vindication is from Me,” declares the LORD.'),
('ISA', 55, 1, 'ISA.55.1', '“Come, all you who are thirsty, come to the waters; and you without money, come, buy, and eat! Come, buy wine and milk without money and without cost!'),
('ISA', 55, 2, 'ISA.55.2', 'Why spend money on that which is not bread, and your labor on that which does not satisfy? Listen carefully to Me, and eat what is good, and your soul will delight in the richest of foods.'),
('ISA', 55, 3, 'ISA.55.3', 'Incline your ear and come to Me; listen, so that your soul may live. I will make with you an everlasting covenant—My loving devotion promised to David.'),
('ISA', 55, 4, 'ISA.55.4', 'Behold, I have made him a witness to the nations, a leader and commander of the peoples.'),
('ISA', 55, 5, 'ISA.55.5', 'Surely you will summon a nation you do not know, and nations who do not know you will run to you. For the LORD your God, the Holy One of Israel, has bestowed glory on you.”'),
('ISA', 55, 6, 'ISA.55.6', 'Seek the LORD while He may be found; call on Him while He is near.'),
('ISA', 55, 7, 'ISA.55.7', 'Let the wicked man forsake his way and the unrighteous man his thoughts; let him return to the LORD, that He may have compassion, and to our God, for He will freely pardon.'),
('ISA', 55, 8, 'ISA.55.8', '“For My thoughts are not your thoughts, neither are your ways My ways,” declares the LORD.'),
('ISA', 55, 9, 'ISA.55.9', '“For as the heavens are higher than the earth, so My ways are higher than your ways and My thoughts than your thoughts.'),
('ISA', 55, 10, 'ISA.55.10', 'For just as rain and snow fall from heaven and do not return without watering the earth, making it bud and sprout, and providing seed to sow and food to eat,'),
('ISA', 55, 11, 'ISA.55.11', 'so My word that proceeds from My mouth will not return to Me empty, but it will accomplish what I please, and it will prosper where I send it.'),
('ISA', 55, 12, 'ISA.55.12', 'You will indeed go out with joy and be led forth in peace; the mountains and hills will burst into song before you, and all the trees of the field will clap their hands.'),
('ISA', 55, 13, 'ISA.55.13', 'Instead of the thornbush, the cypress will grow, and instead of the brier, the myrtle will spring up; this will make a name for the LORD, an everlasting sign, never to be destroyed.”'),
('ISA', 56, 1, 'ISA.56.1', 'This is what the LORD says: “Maintain justice and do what is right, for My salvation is coming soon, and My righteousness will be revealed.'),
('ISA', 56, 2, 'ISA.56.2', 'Blessed is the man who does this, and the son of man who holds it fast, who keeps the Sabbath without profaning it and keeps his hand from doing any evil.”'),
('ISA', 56, 3, 'ISA.56.3', 'Let no foreigner who has joined himself to the LORD say, “The LORD will utterly exclude me from His people.” And let the eunuch not say, “I am but a dry tree.”'),
('ISA', 56, 4, 'ISA.56.4', 'For this is what the LORD says: “To the eunuchs who keep My Sabbaths, who choose what pleases Me and hold fast to My covenant—'),
('ISA', 56, 5, 'ISA.56.5', 'I will give them, in My house and within My walls, a memorial and a name better than that of sons and daughters. I will give them an everlasting name that will not be cut off.'),
('ISA', 56, 6, 'ISA.56.6', 'And the foreigners who join themselves to the LORD to minister to Him, to love the name of the LORD, and to be His servants—all who keep the Sabbath without profaning it and who hold fast to My covenant—'),
('ISA', 56, 7, 'ISA.56.7', 'I will bring them to My holy mountain and make them joyful in My house of prayer. Their burnt offerings and sacrifices will be accepted on My altar, for My house will be called a house of prayer for all the nations.”'),
('ISA', 56, 8, 'ISA.56.8', 'Thus declares the Lord GOD, who gathers the dispersed of Israel: “I will gather to them still others besides those already gathered.”'),
('ISA', 56, 9, 'ISA.56.9', 'Come, all you beasts of the field; eat greedily, all you beasts of the forest.'),
('ISA', 56, 10, 'ISA.56.10', 'Israel’s watchmen are blind, they are all oblivious; they are all mute dogs, they cannot bark; they are dreamers lying around, loving to slumber.'),
('ISA', 56, 11, 'ISA.56.11', 'Like ravenous dogs, they are never satisfied. They are shepherds with no discernment; they all turn to their own way, each one seeking his own gain:'),
('ISA', 56, 12, 'ISA.56.12', '“Come, let me get the wine, let us imbibe the strong drink, and tomorrow will be like today, only far better!”'),
('ISA', 57, 1, 'ISA.57.1', 'The righteous perish, and no one takes it to heart; devout men are taken away, while no one considers that the righteous are taken away from the presence of evil.'),
('ISA', 57, 2, 'ISA.57.2', 'Those who walk uprightly enter into peace; they find rest, lying down in death.'),
('ISA', 57, 3, 'ISA.57.3', '“But come here, you sons of a sorceress, you offspring of adulterers and prostitutes!'),
('ISA', 57, 4, 'ISA.57.4', 'Whom are you mocking? At whom do you sneer and stick out your tongue? Are you not children of transgression, offspring of deceit,'),
('ISA', 57, 5, 'ISA.57.5', 'who burn with lust among the oaks, under every luxuriant tree, who slaughter your children in the valleys, under the clefts of the rocks?'),
('ISA', 57, 6, 'ISA.57.6', 'Your portion is among the smooth stones of the valley; indeed, they are your lot. Even to them you have poured out a drink offering and offered a grain offering. Should I relent because of these?'),
('ISA', 57, 7, 'ISA.57.7', 'On a high and lofty hill you have made your bed, and there you went up to offer sacrifices.'),
('ISA', 57, 8, 'ISA.57.8', 'Behind the door and doorpost you have set up your memorial. Forsaking Me, you uncovered your bed; you climbed up and opened it wide. And you have made a pact with those whose bed you have loved; you have gazed upon their nakedness.'),
('ISA', 57, 9, 'ISA.57.9', 'You went to Molech with oil and multiplied your perfumes. You have sent your envoys a great distance; you have descended even to Sheol itself.'),
('ISA', 57, 10, 'ISA.57.10', 'You are wearied by your many journeys, but you did not say, “There is no hope!” You found renewal of your strength; therefore you did not grow weak.'),
('ISA', 57, 11, 'ISA.57.11', 'Whom have you dreaded and feared, so that you lied and failed to remember Me or take this to heart? Is it not because I have long been silent that you do not fear Me?'),
('ISA', 57, 12, 'ISA.57.12', 'I will expose your righteousness and your works, and they will not profit you.'),
('ISA', 57, 13, 'ISA.57.13', 'When you cry out, let your companies of idols deliver you! Yet the wind will carry off all of them, a breath will take them away. But he who seeks refuge in Me will inherit the land and possess My holy mountain.”'),
('ISA', 57, 14, 'ISA.57.14', 'And it will be said, “Build it up, build it up, prepare the way, take every obstacle out of the way of My people.”'),
('ISA', 57, 15, 'ISA.57.15', 'For thus says the One who is high and lifted up, who inhabits eternity, whose name is Holy: “I dwell in a high and holy place, and with the oppressed and humble in spirit, to restore the spirit of the lowly and revive the heart of the contrite.'),
('ISA', 57, 16, 'ISA.57.16', 'For I will not accuse you forever, nor will I always be angry; for then the spirit of man would grow weak before Me—the breath of life I have made.'),
('ISA', 57, 17, 'ISA.57.17', 'I was enraged by his sinful greed, so I struck him and hid My face in anger; yet he kept turning back to the desires of his heart.'),
('ISA', 57, 18, 'ISA.57.18', 'I have seen his ways, but I will heal him; I will guide him and restore comfort to him and his mourners,'),
('ISA', 57, 19, 'ISA.57.19', 'bringing praise to their lips. Peace, peace to those far and near,” says the LORD, “and I will heal them.”'),
('ISA', 57, 20, 'ISA.57.20', 'But the wicked are like the storm-tossed sea, for it cannot be still, and its waves churn up mire and muck.'),
('ISA', 57, 21, 'ISA.57.21', '“There is no peace,” says my God, “for the wicked.”'),
('ISA', 58, 1, 'ISA.58.1', '“Cry aloud, do not hold back! Raise your voice like a ram’s horn. Declare to My people their transgression and to the house of Jacob their sins.'),
('ISA', 58, 2, 'ISA.58.2', 'For day after day they seek Me and delight to know My ways, like a nation that does what is right and does not forsake the justice of their God. They ask Me for righteous judgments; they delight in the nearness of God.”'),
('ISA', 58, 3, 'ISA.58.3', '“Why have we fasted, and You have not seen? Why have we humbled ourselves, and You have not noticed?” “Behold, on the day of your fast, you do as you please, and you oppress all your workers.'),
('ISA', 58, 4, 'ISA.58.4', 'You fast with contention and strife to strike viciously with your fist. You cannot fast as you do today and have your voice be heard on high.'),
('ISA', 58, 5, 'ISA.58.5', 'Is this the fast I have chosen: a day for a man to deny himself, to bow his head like a reed, and to spread out sackcloth and ashes? Will you call this a fast and a day acceptable to the LORD?'),
('ISA', 58, 6, 'ISA.58.6', 'Isn’t this the fast that I have chosen: to break the chains of wickedness, to untie the cords of the yoke, to set the oppressed free and tear off every yoke?'),
('ISA', 58, 7, 'ISA.58.7', 'Isn’t it to share your bread with the hungry, to bring the poor and homeless into your home, to clothe the naked when you see him, and not to turn away from your own flesh and blood?'),
('ISA', 58, 8, 'ISA.58.8', 'Then your light will break forth like the dawn, and your healing will come quickly. Your righteousness will go before you, and the glory of the LORD will be your rear guard.'),
('ISA', 58, 9, 'ISA.58.9', 'Then you will call, and the LORD will answer; you will cry out, and He will say, ‘Here I am.’ If you remove the yoke from your midst, the pointing of the finger and malicious talk,'),
('ISA', 58, 10, 'ISA.58.10', 'and if you give yourself to the hungry and satisfy the afflicted soul, then your light will go forth in the darkness, and your night will be like noonday.'),
('ISA', 58, 11, 'ISA.58.11', 'The LORD will always guide you; He will satisfy you in a sun-scorched land and strengthen your frame. You will be like a well-watered garden, like a spring whose waters never fail.'),
('ISA', 58, 12, 'ISA.58.12', 'Your people will rebuild the ancient ruins; you will restore the age-old foundations; you will be called Repairer of the Breach, Restorer of the Streets of Dwelling.'),
('ISA', 58, 13, 'ISA.58.13', 'If you turn your foot from breaking the Sabbath, from doing as you please on My holy day, if you call the Sabbath a delight, and the LORD’s holy day honorable, if you honor it by not going your own way or seeking your own pleasure or speaking idle words,'),
('ISA', 58, 14, 'ISA.58.14', 'then you will delight yourself in the LORD, and I will make you ride on the heights of the land and feed you with the heritage of your father Jacob.” For the mouth of the LORD has spoken.'),
('ISA', 59, 1, 'ISA.59.1', 'Surely the arm of the LORD is not too short to save, nor His ear too dull to hear.'),
('ISA', 59, 2, 'ISA.59.2', 'But your iniquities have built barriers between you and your God, and your sins have hidden His face from you, so that He does not hear.'),
('ISA', 59, 3, 'ISA.59.3', 'For your hands are stained with blood, and your fingers with iniquity; your lips have spoken lies, and your tongue mutters injustice.'),
('ISA', 59, 4, 'ISA.59.4', 'No one calls for justice; no one pleads his case honestly. They rely on empty pleas; they tell lies; they conceive mischief and give birth to iniquity.'),
('ISA', 59, 5, 'ISA.59.5', 'They hatch the eggs of vipers and weave a spider’s web. Whoever eats their eggs will die; crack one open, and a viper is hatched.'),
('ISA', 59, 6, 'ISA.59.6', 'Their cobwebs cannot be made into clothing, and they cannot cover themselves with their works. Their deeds are sinful deeds, and acts of violence are in their hands.'),
('ISA', 59, 7, 'ISA.59.7', 'Their feet run to evil; they are swift to shed innocent blood. Their thoughts are sinful thoughts; ruin and destruction lie in their wake.'),
('ISA', 59, 8, 'ISA.59.8', 'The way of peace they have not known, and there is no justice in their tracks. They have turned them into crooked paths; no one who treads on them will know peace.'),
('ISA', 59, 9, 'ISA.59.9', 'Therefore justice is far from us, and righteousness does not reach us. We hope for light, but there is darkness; for brightness, but we walk in gloom.'),
('ISA', 59, 10, 'ISA.59.10', 'Like the blind, we feel our way along the wall, groping like those without eyes. We stumble at midday as in the twilight; among the vigorous we are like the dead.'),
('ISA', 59, 11, 'ISA.59.11', 'We all growl like bears and moan like doves. We hope for justice, but find none, for salvation, but it is far from us.'),
('ISA', 59, 12, 'ISA.59.12', 'For our transgressions are multiplied before You, and our sins testify against us. Our transgressions are indeed with us, and we know our iniquities:'),
('ISA', 59, 13, 'ISA.59.13', 'rebelling and denying the LORD, turning away from our God, speaking oppression and revolt, conceiving and uttering lies from the heart.'),
('ISA', 59, 14, 'ISA.59.14', 'So justice is turned away, and righteousness stands at a distance. For truth has stumbled in the public square, and honesty cannot enter.'),
('ISA', 59, 15, 'ISA.59.15', 'Truth is missing, and whoever turns from evil becomes prey. The LORD looked and was displeased that there was no justice.'),
('ISA', 59, 16, 'ISA.59.16', 'He saw that there was no man; He was amazed that there was no one to intercede. So His own arm brought salvation, and His own righteousness sustained Him.'),
('ISA', 59, 17, 'ISA.59.17', 'He put on righteousness like a breastplate, and the helmet of salvation on His head; He put on garments of vengeance and wrapped Himself in a cloak of zeal.'),
('ISA', 59, 18, 'ISA.59.18', 'So He will repay according to their deeds: fury to His enemies, retribution to His foes, and recompense to the islands.'),
('ISA', 59, 19, 'ISA.59.19', 'So shall they fear the name of the LORD where the sun sets, and His glory where it rises. For He will come like a raging flood, driven by the breath of the LORD.'),
('ISA', 59, 20, 'ISA.59.20', '“The Redeemer will come to Zion, to those in Jacob who turn from transgression,” declares the LORD.'),
('ISA', 59, 21, 'ISA.59.21', '“As for Me, this is My covenant with them,” says the LORD. “My Spirit will not depart from you, and My words that I have put in your mouth will not depart from your mouth or from the mouths of your children and grandchildren, from now on and forevermore,” says the LORD.'),
('ISA', 60, 1, 'ISA.60.1', 'Arise, shine, for your light has come, and the glory of the LORD rises upon you.'),
('ISA', 60, 2, 'ISA.60.2', 'For behold, darkness covers the earth, and thick darkness is over the peoples; but the LORD will rise upon you, and His glory will appear over you.'),
('ISA', 60, 3, 'ISA.60.3', 'Nations will come to your light, and kings to the brightness of your dawn.'),
('ISA', 60, 4, 'ISA.60.4', 'Lift up your eyes and look around: They all gather and come to you; your sons will come from afar, and your daughters will be carried on the arm.'),
('ISA', 60, 5, 'ISA.60.5', 'Then you will look and be radiant, and your heart will tremble and swell with joy, because the riches of the sea will be brought to you, and the wealth of the nations will come to you.'),
('ISA', 60, 6, 'ISA.60.6', 'Caravans of camels will cover your land, young camels of Midian and Ephah, and all from Sheba will come, bearing gold and frankincense and proclaiming the praises of the LORD.'),
('ISA', 60, 7, 'ISA.60.7', 'All the flocks of Kedar will be gathered to you; the rams of Nebaioth will serve you and go up on My altar with acceptance; I will adorn My glorious house.'),
('ISA', 60, 8, 'ISA.60.8', 'Who are these who fly like clouds, like doves to their shelters?'),
('ISA', 60, 9, 'ISA.60.9', 'Surely the islands will wait for Me, with the ships of Tarshish in the lead, to bring your children from afar, with their silver and gold, to the honor of the LORD your God, the Holy One of Israel, for He has glorified you.'),
('ISA', 60, 10, 'ISA.60.10', 'Foreigners will rebuild your walls, and their kings will serve you. Although I struck you in anger, yet in favor I will show you mercy.'),
('ISA', 60, 11, 'ISA.60.11', 'Your gates will always stand open; they will never be shut, day or night, so that the wealth of the nations may be brought into you, with their kings being led in procession.'),
('ISA', 60, 12, 'ISA.60.12', 'For the nation or kingdom that will not serve you will perish; it will be utterly destroyed.'),
('ISA', 60, 13, 'ISA.60.13', 'The glory of Lebanon will come to you—its cypress, elm, and boxwood together—to adorn the place of My sanctuary, and I will glorify the place of My feet.'),
('ISA', 60, 14, 'ISA.60.14', 'The sons of your oppressors will come and bow down to you; all who reviled you will fall facedown at your feet and call you the City of the LORD, Zion of the Holy One of Israel.'),
('ISA', 60, 15, 'ISA.60.15', 'Whereas you have been forsaken and despised, with no one passing through, I will make you an everlasting pride, a joy from age to age.'),
('ISA', 60, 16, 'ISA.60.16', 'You will drink the milk of nations and nurse at the breasts of royalty; you will know that I, the LORD, am your Savior and your Redeemer, the Mighty One of Jacob.'),
('ISA', 60, 17, 'ISA.60.17', 'Instead of bronze I will bring you gold; I will bring silver in place of iron, bronze instead of wood, and iron instead of stones. I will appoint peace as your governor and righteousness as your ruler.'),
('ISA', 60, 18, 'ISA.60.18', 'No longer will violence be heard in your land, nor ruin or destruction within your borders. But you will name your walls Salvation and your gates Praise.'),
('ISA', 60, 19, 'ISA.60.19', 'No longer will the sun be your light by day, nor the brightness of the moon shine on your night; for the LORD will be your everlasting light, and your God will be your splendor.'),
('ISA', 60, 20, 'ISA.60.20', 'Your sun will no longer set, and your moon will not wane; for the LORD will be your everlasting light, and the days of your sorrow will cease.'),
('ISA', 60, 21, 'ISA.60.21', 'Then all your people will be righteous; they will possess the land forever; they are the branch of My planting, the work of My hands, so that I may be glorified.'),
('ISA', 60, 22, 'ISA.60.22', 'The least of you will become a thousand, and the smallest a mighty nation. I am the LORD; in its time I will accomplish it quickly.'),
('ISA', 61, 1, 'ISA.61.1', 'The Spirit of the Lord GOD is on Me, because the LORD has anointed Me to preach good news to the poor. He has sent Me to bind up the brokenhearted, to proclaim liberty to the captives and freedom to the prisoners,'),
('ISA', 61, 2, 'ISA.61.2', 'to proclaim the year of the LORD’s favor and the day of our God’s vengeance, to comfort all who mourn,'),
('ISA', 61, 3, 'ISA.61.3', 'to console the mourners in Zion—to give them a crown of beauty for ashes, the oil of joy for mourning, and a garment of praise for a spirit of despair. So they will be called oaks of righteousness, the planting of the LORD, that He may be glorified.'),
('ISA', 61, 4, 'ISA.61.4', 'They will rebuild the ancient ruins; they will restore the places long devastated; they will renew the ruined cities, the desolations of many generations.'),
('ISA', 61, 5, 'ISA.61.5', 'Strangers will stand and feed your flocks, and foreigners will be your plowmen and vinedressers.'),
('ISA', 61, 6, 'ISA.61.6', 'But you will be called the priests of the LORD; they will speak of you as ministers of our God; you will feed on the wealth of nations, and you will boast in their riches.'),
('ISA', 61, 7, 'ISA.61.7', 'Instead of shame, My people will have a double portion, and instead of humiliation, they will rejoice in their share; and so they will inherit a double portion in their land, and everlasting joy will be theirs.'),
('ISA', 61, 8, 'ISA.61.8', 'For I, the LORD, love justice; I hate robbery and iniquity; in My faithfulness I will give them their recompense and make an everlasting covenant with them.'),
('ISA', 61, 9, 'ISA.61.9', 'Their descendants will be known among the nations, and their offspring among the peoples. All who see them will acknowledge that they are a people the LORD has blessed.'),
('ISA', 61, 10, 'ISA.61.10', 'I will rejoice greatly in the LORD, my soul will exult in my God; for He has clothed me with garments of salvation and wrapped me in a robe of righteousness, as a bridegroom wears a priestly headdress, as a bride adorns herself with her jewels.'),
('ISA', 61, 11, 'ISA.61.11', 'For as the earth brings forth its growth, and as a garden enables seed to spring up, so the Lord GOD will cause righteousness and praise to spring up before all the nations.'),
('ISA', 62, 1, 'ISA.62.1', 'For Zion’s sake I will not keep silent, and for Jerusalem’s sake I will not keep still, until her righteousness shines like a bright light, her salvation like a blazing torch.'),
('ISA', 62, 2, 'ISA.62.2', 'Nations will see your righteousness, and all kings your glory. You will be called by a new name that the mouth of the LORD will bestow.'),
('ISA', 62, 3, 'ISA.62.3', 'You will be a crown of glory in the hand of the LORD, a royal diadem in the palm of your God.'),
('ISA', 62, 4, 'ISA.62.4', 'No longer will you be called Forsaken, nor your land named Desolate; but you will be called Hephzibah, and your land Beulah; for the LORD will take delight in you, and your land will be His bride.'),
('ISA', 62, 5, 'ISA.62.5', 'For as a young man marries a young woman, so your sons will marry you; and as a bridegroom rejoices over his bride, so your God will rejoice over you.'),
('ISA', 62, 6, 'ISA.62.6', 'On your walls, O Jerusalem, I have posted watchmen; they will never be silent day or night. You who call on the LORD shall take no rest for yourselves,'),
('ISA', 62, 7, 'ISA.62.7', 'nor give Him any rest until He establishes Jerusalem and makes her the praise of the earth.'),
('ISA', 62, 8, 'ISA.62.8', 'The LORD has sworn by His right hand and by His mighty arm: “Never again will I give your grain to your enemies for food, nor will foreigners drink the new wine for which you have toiled.'),
('ISA', 62, 9, 'ISA.62.9', 'For those who harvest grain will eat it and praise the LORD, and those who gather grapes will drink the wine in My holy courts.”'),
('ISA', 62, 10, 'ISA.62.10', 'Go out, go out through the gates; prepare the way for the people! Build it up, build up the highway; clear away the stones; raise a banner for the nations!'),
('ISA', 62, 11, 'ISA.62.11', 'Behold, the LORD has proclaimed to the ends of the earth, “Say to Daughter Zion: See, your Savior comes! Look, His reward is with Him, and His recompense goes before Him.”'),
('ISA', 62, 12, 'ISA.62.12', 'And they will be called the Holy People, the Redeemed of The LORD; and you will be called Sought Out, A City Not Forsaken.'),
('ISA', 63, 1, 'ISA.63.1', 'Who is this coming from Edom, from Bozrah with crimson-stained garments? Who is this robed in splendor, marching in the greatness of His strength? “It is I, proclaiming vindication, mighty to save.”'),
('ISA', 63, 2, 'ISA.63.2', 'Why are Your clothes red, and Your garments like one who treads the winepress?'),
('ISA', 63, 3, 'ISA.63.3', '“I have trodden the winepress alone, and no one from the nations was with Me. I trampled them in My anger and trod them down in My fury; their blood spattered My garments, and all My clothes were stained.'),
('ISA', 63, 4, 'ISA.63.4', 'For the day of vengeance was in My heart, and the year of My redemption had come.'),
('ISA', 63, 5, 'ISA.63.5', 'I looked, but there was no one to help; I was appalled that no one assisted. So My arm brought Me salvation, and My own wrath upheld Me.'),
('ISA', 63, 6, 'ISA.63.6', 'I trampled the nations in My anger; in My wrath I made them drunk and poured out their blood on the ground.”'),
('ISA', 63, 7, 'ISA.63.7', 'I will make known the LORD’s loving devotion and His praiseworthy acts, because of all that the LORD has done for us—the many good things for the house of Israel according to His great compassion and loving devotion.'),
('ISA', 63, 8, 'ISA.63.8', 'For He said, “They are surely My people, sons who will not be disloyal.” So He became their Savior.'),
('ISA', 63, 9, 'ISA.63.9', 'In all their distress, He too was afflicted, and the Angel of His Presence saved them. In His love and compassion He redeemed them; He lifted them up and carried them all the days of old.'),
('ISA', 63, 10, 'ISA.63.10', 'But they rebelled and grieved His Holy Spirit. So He turned and became their enemy, and He Himself fought against them.'),
('ISA', 63, 11, 'ISA.63.11', 'Then His people remembered the days of old, the days of Moses. Where is He who brought them through the sea with the shepherds of His flock? Where is the One who set His Holy Spirit among them,'),
('ISA', 63, 12, 'ISA.63.12', 'who sent His glorious arm to lead them by the right hand of Moses, who divided the waters before them to gain for Himself everlasting renown,'),
('ISA', 63, 13, 'ISA.63.13', 'who led them through the depths like a horse in the wilderness, so that they did not stumble?'),
('ISA', 63, 14, 'ISA.63.14', 'Like cattle going down to the valley, the Spirit of the LORD gave them rest. You led Your people this way to make for Yourself a glorious name.'),
('ISA', 63, 15, 'ISA.63.15', 'Look down from heaven and see, from Your holy and glorious habitation. Where are Your zeal and might? Your yearning and compassion for me are restrained.'),
('ISA', 63, 16, 'ISA.63.16', 'Yet You are our Father, though Abraham does not know us and Israel does not acknowledge us. You, O LORD, are our Father; our Redeemer from Everlasting is Your name.'),
('ISA', 63, 17, 'ISA.63.17', 'Why, O LORD, do You make us stray from Your ways and harden our hearts from fearing You? Return, for the sake of Your servants, the tribes of Your heritage.'),
('ISA', 63, 18, 'ISA.63.18', 'For a short while Your people possessed Your holy place, but our enemies have trampled Your sanctuary.'),
('ISA', 63, 19, 'ISA.63.19', 'We have become like those You never ruled, like those not called by Your name.'),
('ISA', 64, 1, 'ISA.64.1', 'If only You would rend the heavens and come down, so that mountains would quake at Your presence,'),
('ISA', 64, 2, 'ISA.64.2', 'as fire kindles the brushwood and causes the water to boil, to make Your name known to Your enemies, so that the nations will tremble at Your presence!'),
('ISA', 64, 3, 'ISA.64.3', 'When You did awesome works that we did not expect, You came down, and the mountains trembled at Your presence.'),
('ISA', 64, 4, 'ISA.64.4', 'From ancient times no one has heard, no ear has perceived, no eye has seen any God besides You, who acts on behalf of those who wait for Him.'),
('ISA', 64, 5, 'ISA.64.5', 'You welcome those who gladly do right, who remember Your ways. Surely You were angry, for we sinned. How can we be saved if we remain in our sins?'),
('ISA', 64, 6, 'ISA.64.6', 'Each of us has become like something unclean, and all our righteous acts are like filthy rags; we all wither like a leaf, and our iniquities carry us away like the wind.'),
('ISA', 64, 7, 'ISA.64.7', 'No one calls on Your name or strives to take hold of You. For You have hidden Your face from us and delivered us into the hand of our iniquity.'),
('ISA', 64, 8, 'ISA.64.8', 'But now, O LORD, You are our Father; we are the clay, and You are the potter; we are all the work of Your hand.'),
('ISA', 64, 9, 'ISA.64.9', 'Do not be angry, O LORD, beyond measure; do not remember our iniquity forever. Oh, look upon us, we pray; we are all Your people!'),
('ISA', 64, 10, 'ISA.64.10', 'Your holy cities have become a wilderness. Zion has become a wasteland and Jerusalem a desolation.'),
('ISA', 64, 11, 'ISA.64.11', 'Our holy and beautiful temple, where our fathers praised You, has been burned with fire, and all that was dear to us lies in ruins.'),
('ISA', 64, 12, 'ISA.64.12', 'After all this, O LORD, will You restrain Yourself? Will You keep silent and afflict us beyond measure?'),
('ISA', 65, 1, 'ISA.65.1', '“I revealed Myself to those who did not ask for Me; I was found by those who did not seek Me. To a nation that did not call My name, I said, ‘Here I am! Here I am!’'),
('ISA', 65, 2, 'ISA.65.2', 'All day long I have held out My hands to an obstinate people who walk in the wrong path, who follow their own imaginations,'),
('ISA', 65, 3, 'ISA.65.3', 'to a people who continually provoke Me to My face, sacrificing in the gardens and burning incense on altars of brick,'),
('ISA', 65, 4, 'ISA.65.4', 'sitting among the graves, spending nights in secret places, eating the meat of pigs and polluted broth from their bowls.'),
('ISA', 65, 5, 'ISA.65.5', 'They say, ‘Keep to yourself; do not come near me, for I am holier than you!’ Such people are smoke in My nostrils, a fire that burns all day long.'),
('ISA', 65, 6, 'ISA.65.6', 'Behold, it is written before Me: I will not keep silent, but I will repay; I will pay it back into their laps,'),
('ISA', 65, 7, 'ISA.65.7', 'both for your iniquities and for those of your fathers,” says the LORD. “Because they burned incense on the mountains and scorned Me on the hills, I will measure into their laps full payment for their former deeds.”'),
('ISA', 65, 8, 'ISA.65.8', 'This is what the LORD says: “As the new wine is found in a cluster of grapes, and men say, ‘Do not destroy it, for it contains a blessing,’ so I will act on behalf of My servants; I will not destroy them all.'),
('ISA', 65, 9, 'ISA.65.9', 'And I will bring forth descendants from Jacob, and heirs from Judah; My elect will possess My mountains, and My servants will dwell there.'),
('ISA', 65, 10, 'ISA.65.10', 'Sharon will become a pasture for flocks, and the Valley of Achor a resting place for herds, for My people who seek Me.'),
('ISA', 65, 11, 'ISA.65.11', 'But you who forsake the LORD, who forget My holy mountain, who set a table for Fortune and fill bowls of mixed wine for Destiny,'),
('ISA', 65, 12, 'ISA.65.12', 'I will destine you for the sword, and you will all kneel down to be slaughtered, because I called and you did not answer, I spoke and you did not listen; you did evil in My sight and chose that in which I did not delight.”'),
('ISA', 65, 13, 'ISA.65.13', 'Therefore this is what the Lord GOD says: “My servants will eat, but you will go hungry; My servants will drink, but you will go thirsty; My servants will rejoice, but you will be put to shame.'),
('ISA', 65, 14, 'ISA.65.14', 'My servants will shout for joy with a glad heart, but you will cry out with a heavy heart and wail with a broken spirit.'),
('ISA', 65, 15, 'ISA.65.15', 'You will leave behind your name as a curse for My chosen ones, and the Lord GOD will slay you; but to His servants He will give another name.'),
('ISA', 65, 16, 'ISA.65.16', 'Whoever invokes a blessing in the land will do so by the God of truth, and whoever takes an oath in the land will swear by the God of truth. For the former troubles will be forgotten and hidden from My sight.'),
('ISA', 65, 17, 'ISA.65.17', 'For behold, I will create new heavens and a new earth. The former things will not be remembered, nor will they come to mind.'),
('ISA', 65, 18, 'ISA.65.18', 'But be glad and rejoice forever in what I create; for I will create Jerusalem to be a joy and its people to be a delight.'),
('ISA', 65, 19, 'ISA.65.19', 'I will rejoice in Jerusalem and take delight in My people. The sounds of weeping and crying will no longer be heard in her.'),
('ISA', 65, 20, 'ISA.65.20', 'No longer will a nursing infant live but a few days, or an old man fail to live out his years. For the youth will die at a hundred years, and he who fails to reach a hundred will be considered accursed.'),
('ISA', 65, 21, 'ISA.65.21', 'They will build houses and dwell in them; they will plant vineyards and eat their fruit.'),
('ISA', 65, 22, 'ISA.65.22', 'No longer will they build houses for others to inhabit, nor plant for others to eat. For as is the lifetime of a tree, so will be the days of My people, and My chosen ones will fully enjoy the work of their hands.'),
('ISA', 65, 23, 'ISA.65.23', 'They will not labor in vain or bear children doomed to disaster; for they will be a people blessed by the LORD—they and their descendants with them.'),
('ISA', 65, 24, 'ISA.65.24', 'Even before they call, I will answer, and while they are still speaking, I will hear.'),
('ISA', 65, 25, 'ISA.65.25', 'The wolf and the lamb will feed together, and the lion will eat straw like the ox, but the food of the serpent will be dust. They will neither harm nor destroy on all My holy mountain,” says the LORD.'),
('ISA', 66, 1, 'ISA.66.1', 'This is what the LORD says: “Heaven is My throne, and earth is My footstool. What kind of house will you build for Me? Or where will My place of repose be?'),
('ISA', 66, 2, 'ISA.66.2', 'Has not My hand made all these things? And so they came into being,” declares the LORD. “This is the one I will esteem: he who is humble and contrite in spirit, who trembles at My word.'),
('ISA', 66, 3, 'ISA.66.3', 'Whoever slaughters an ox is like one who slays a man; whoever sacrifices a lamb is like one who breaks a dog’s neck; whoever presents a grain offering is like one who offers pig’s blood; whoever offers frankincense is like one who blesses an idol. Indeed, they have chosen their own ways and delighted in their abominations.'),
('ISA', 66, 4, 'ISA.66.4', 'So I will choose their punishment and I will bring terror upon them, because I called and no one answered, I spoke and no one listened. But they did evil in My sight and chose that in which I did not delight.”'),
('ISA', 66, 5, 'ISA.66.5', 'You who tremble at His word, hear the word of the LORD: “Your brothers who hate you and exclude you because of My name have said, ‘Let the LORD be glorified that we may see your joy!’ But they will be put to shame.”'),
('ISA', 66, 6, 'ISA.66.6', 'Hear the uproar from the city; listen to the voice from the temple! It is the voice of the LORD, repaying His enemies what they deserve!'),
('ISA', 66, 7, 'ISA.66.7', '“Before she was in labor, she gave birth; before she was in pain, she delivered a boy.'),
('ISA', 66, 8, 'ISA.66.8', 'Who has heard of such as this? Who has seen such things? Can a country be born in a day or a nation be delivered in an instant? Yet as soon as Zion was in labor, she gave birth to her children.'),
('ISA', 66, 9, 'ISA.66.9', 'Shall I bring a baby to the point of birth and not deliver it?” says the LORD. “Or will I who deliver close the womb?” says your God.'),
('ISA', 66, 10, 'ISA.66.10', 'Be glad for Jerusalem and rejoice over her, all who love her. Rejoice greatly with her, all who mourn over her,'),
('ISA', 66, 11, 'ISA.66.11', 'so that you may nurse and be satisfied at her comforting breasts; you may drink deeply and delight yourselves in her glorious abundance.'),
('ISA', 66, 12, 'ISA.66.12', 'For this is what the LORD says: “I will extend peace to her like a river, and the wealth of nations like a flowing stream; you will nurse and be carried on her arm, and bounced upon her knees.'),
('ISA', 66, 13, 'ISA.66.13', 'As a mother comforts her son, so will I comfort you, and you will be consoled over Jerusalem.”'),
('ISA', 66, 14, 'ISA.66.14', 'When you see, you will rejoice, and you will flourish like grass; then the hand of the LORD will be revealed to His servants, but His wrath will be shown to His enemies.'),
('ISA', 66, 15, 'ISA.66.15', 'For behold, the LORD will come with fire—His chariots are like a whirlwind—to execute His anger with fury and His rebuke with flames of fire.'),
('ISA', 66, 16, 'ISA.66.16', 'For by fire and by His sword, the LORD will execute judgment on all flesh, and many will be slain by the LORD.'),
('ISA', 66, 17, 'ISA.66.17', '“Those who consecrate and purify themselves to enter the groves—to follow one in the center of those who eat the flesh of swine and vermin and rats—will perish together,” declares the LORD.'),
('ISA', 66, 18, 'ISA.66.18', '“And I, knowing their deeds and thoughts, am coming to gather all nations and tongues, and they will come and see My glory.'),
('ISA', 66, 19, 'ISA.66.19', 'I will establish a sign among them, and I will send survivors from among them to the nations—to Tarshish, Put, and the archers of Lud; to Tubal, Javan, and the islands far away who have not heard of My fame or seen My glory. So they will proclaim My glory among the nations.'),
('ISA', 66, 20, 'ISA.66.20', 'And they will bring all your brothers from all the nations as a gift to the LORD on horses and chariots and wagons, on mules and camels, to My holy mountain Jerusalem,” says the LORD, “just as the Israelites bring an offering in a clean vessel to the house of the LORD.”'),
('ISA', 66, 21, 'ISA.66.21', '“And I will select some of them as priests and Levites,” says the LORD.'),
('ISA', 66, 22, 'ISA.66.22', '“For just as the new heavens and the new earth, which I will make, will endure before Me,” declares the LORD, “so your descendants and your name will endure.'),
('ISA', 66, 23, 'ISA.66.23', 'From one New Moon to another and from one Sabbath to another, all mankind will come to worship before Me,” says the LORD.'),
('ISA', 66, 24, 'ISA.66.24', '“As they go forth, they will see the corpses of the men who have rebelled against Me; for their worm will never die, their fire will never be quenched, and they will be a horror to all mankind.”'),
('JER', 1, 1, 'JER.1.1', 'These are the words of Jeremiah son of Hilkiah, one of the priests in Anathoth in the territory of Benjamin.'),
('JER', 1, 2, 'JER.1.2', 'The word of the LORD came to Jeremiah in the thirteenth year of the reign of Josiah son of Amon king of Judah,'),
('JER', 1, 3, 'JER.1.3', 'and through the days of Jehoiakim son of Josiah king of Judah, until the fifth month of the eleventh year of Zedekiah son of Josiah king of Judah, when the people of Jerusalem went into exile.'),
('JER', 1, 4, 'JER.1.4', 'The word of the LORD came to me, saying:'),
('JER', 1, 5, 'JER.1.5', '“Before I formed you in the womb I knew you, and before you were born I set you apart and appointed you as a prophet to the nations.”'),
('JER', 1, 6, 'JER.1.6', '“Ah, Lord GOD,” I said, “I surely do not know how to speak, for I am only a child!”'),
('JER', 1, 7, 'JER.1.7', 'But the LORD told me: “Do not say, ‘I am only a child.’ For to everyone I send you, you must go, and all that I command you, you must speak.'),
('JER', 1, 8, 'JER.1.8', 'Do not be afraid of them, for I am with you to deliver you,” declares the LORD.'),
('JER', 1, 9, 'JER.1.9', 'Then the LORD reached out His hand, touched my mouth, and said to me: “Behold, I have put My words in your mouth.'),
('JER', 1, 10, 'JER.1.10', 'See, I have appointed you today over nations and kingdoms to uproot and tear down, to destroy and overthrow, to build and plant.”'),
('JER', 1, 11, 'JER.1.11', 'And the word of the LORD came to me, asking, “Jeremiah, what do you see?” “I see a branch of an almond tree,” I replied.'),
('JER', 1, 12, 'JER.1.12', '“You have observed correctly,” said the LORD, “for I am watching over My word to accomplish it.”'),
('JER', 1, 13, 'JER.1.13', 'Again the word of the LORD came to me, asking, “What do you see?” “I see a boiling pot,” I replied, “and it is tilting toward us from the north.”'),
('JER', 1, 14, 'JER.1.14', 'Then the LORD said to me, “Disaster from the north will be poured out on all who live in the land.'),
('JER', 1, 15, 'JER.1.15', 'For I am about to summon all the clans and kingdoms of the north,” declares the LORD. “Their kings will come and set up their thrones at the entrance of the gates of Jerusalem. They will attack all her surrounding walls and all the other cities of Judah.'),
('JER', 1, 16, 'JER.1.16', 'I will pronounce My judgments against them for all their wickedness, because they have forsaken Me, and they have burned incense to other gods and worshiped the works of their own hands.'),
('JER', 1, 17, 'JER.1.17', 'Get yourself ready. Stand up and tell them everything that I command you. Do not be intimidated by them, or I will terrify you before them.'),
('JER', 1, 18, 'JER.1.18', 'Now behold, this day I have made you like a fortified city, an iron pillar, and bronze walls against the whole land—against the kings of Judah, its officials, its priests, and the people of the land.'),
('JER', 1, 19, 'JER.1.19', 'They will fight against you but will never overcome you, since I am with you to deliver you,” declares the LORD.'),
('JER', 2, 1, 'JER.2.1', 'Now the word of the LORD came to me, saying,'),
('JER', 2, 2, 'JER.2.2', '“Go and proclaim in the hearing of Jerusalem that this is what the LORD says: ‘I remember the devotion of your youth, your love as a bride, how you followed Me in the wilderness, in a land not sown.'),
('JER', 2, 3, 'JER.2.3', 'Israel was holy to the LORD, the firstfruits of His harvest. All who devoured her were found guilty; disaster came upon them,’” declares the LORD.'),
('JER', 2, 4, 'JER.2.4', 'Hear the word of the LORD, O house of Jacob, and all you families of the house of Israel.'),
('JER', 2, 5, 'JER.2.5', 'This is what the LORD says: “What fault did your fathers find in Me that they strayed so far from Me? They followed worthless idols, and became worthless themselves.'),
('JER', 2, 6, 'JER.2.6', 'They did not ask, ‘Where is the LORD who brought us up from the land of Egypt, who led us through the wilderness, through a land of deserts and pits, a land of drought and darkness, a land where no one travels and no one lives?’'),
('JER', 2, 7, 'JER.2.7', 'I brought you into a fertile land to eat its fruit and bounty, but you came and defiled My land and made My inheritance detestable.'),
('JER', 2, 8, 'JER.2.8', 'The priests did not ask, ‘Where is the LORD?’ The experts in the law no longer knew Me, and the leaders rebelled against Me. The prophets prophesied by Baal and followed useless idols.'),
('JER', 2, 9, 'JER.2.9', 'Therefore, I will contend with you again, declares the LORD, and I will bring a case against your children’s children.'),
('JER', 2, 10, 'JER.2.10', 'Cross over to the coasts of Cyprus and take a look; send to Kedar and consider carefully; see if there has ever been anything like this:'),
('JER', 2, 11, 'JER.2.11', 'Has a nation ever changed its gods? (Yet they are not gods at all.) But My people have exchanged their Glory for useless idols.'),
('JER', 2, 12, 'JER.2.12', 'Be stunned by this, O heavens; be shocked and utterly appalled,” declares the LORD.'),
('JER', 2, 13, 'JER.2.13', '“For My people have committed two evils: They have forsaken Me, the fountain of living water, and they have dug their own cisterns—broken cisterns that cannot hold water.'),
('JER', 2, 14, 'JER.2.14', 'Is Israel a slave? Was he born into slavery? Why then has he become prey?'),
('JER', 2, 15, 'JER.2.15', 'The young lions have roared at him; they have sounded their voices. They have laid waste his land; his cities lie in ruins, without inhabitant.'),
('JER', 2, 16, 'JER.2.16', 'The men of Memphis and Tahpanhes have shaved the crown of your head.'),
('JER', 2, 17, 'JER.2.17', 'Have you not brought this on yourself by forsaking the LORD your God when He led you in the way?'),
('JER', 2, 18, 'JER.2.18', 'Now what will you gain on your way to Egypt to drink the waters of the Nile? What will you gain on your way to Assyria to drink the waters of the Euphrates?'),
('JER', 2, 19, 'JER.2.19', 'Your own evil will discipline you; your own apostasies will reprimand you. Consider and realize how evil and bitter it is for you to forsake the LORD your God and to have no fear of Me,” declares the Lord GOD of Hosts.'),
('JER', 2, 20, 'JER.2.20', '“For long ago you broke your yoke and tore off your chains, saying, ‘I will not serve!’ Indeed, on every high hill and under every green tree you lay down as a prostitute.'),
('JER', 2, 21, 'JER.2.21', 'I had planted you like a choice vine from the very best seed. How could you turn yourself before Me into a rotten, wild vine?'),
('JER', 2, 22, 'JER.2.22', 'Although you wash with lye and use an abundance of soap, the stain of your guilt is still before Me,” declares the Lord GOD.'),
('JER', 2, 23, 'JER.2.23', '“How can you say, ‘I am not defiled; I have not run after the Baals’? Look at your behavior in the valley; acknowledge what you have done. You are a swift young she-camel galloping here and there,'),
('JER', 2, 24, 'JER.2.24', 'a wild donkey at home in the wilderness, sniffing the wind in the heat of her desire. Who can restrain her passion? All who seek her need not weary themselves; in mating season they will find her.'),
('JER', 2, 25, 'JER.2.25', 'You should have kept your feet from going bare and your throat from being thirsty. But you said, ‘It is hopeless! For I love foreign gods, and I must go after them.’'),
('JER', 2, 26, 'JER.2.26', 'As the thief is ashamed when he is caught, so the house of Israel is disgraced. They, their kings, their officials, their priests, and their prophets'),
('JER', 2, 27, 'JER.2.27', 'say to a tree, ‘You are my father,’ and to a stone, ‘You gave me birth.’ They have turned their backs to Me and not their faces. Yet in the time of trouble, they say, ‘Rise up and save us!’'),
('JER', 2, 28, 'JER.2.28', 'But where are the gods you made for yourselves? Let them rise up in your time of trouble and save you if they can; for your gods are as numerous as your cities, O Judah.'),
('JER', 2, 29, 'JER.2.29', 'Why do you bring a case against Me? You have all rebelled against Me,” declares the LORD.'),
('JER', 2, 30, 'JER.2.30', '“I have struck your sons in vain; they accepted no discipline. Your own sword has devoured your prophets like a voracious lion.”'),
('JER', 2, 31, 'JER.2.31', 'You people of this generation, consider the word of the LORD: “Have I been a wilderness to Israel or a land of dense darkness? Why do My people say, ‘We are free to roam; we will come to You no more’?'),
('JER', 2, 32, 'JER.2.32', 'Does a maiden forget her jewelry or a bride her wedding sash? Yet My people have forgotten Me for days without number.'),
('JER', 2, 33, 'JER.2.33', 'How skillfully you pursue love! Even the most immoral of women could learn from your ways.'),
('JER', 2, 34, 'JER.2.34', 'Moreover, your skirts are stained with the blood of the innocent poor, though you did not find them breaking in. But in spite of all these things'),
('JER', 2, 35, 'JER.2.35', 'you say, ‘I am innocent. Surely His anger will turn from me.’ Behold, I will judge you, because you say, ‘I have not sinned.’'),
('JER', 2, 36, 'JER.2.36', 'How impulsive you are, constantly changing your ways! You will be disappointed by Egypt just as you were by Assyria.'),
('JER', 2, 37, 'JER.2.37', 'Moreover, you will leave that place with your hands on your head, for the LORD has rejected those you trust; you will not prosper by their help.”'),
('JER', 3, 1, 'JER.3.1', '“If a man divorces his wife and she leaves him to marry another, can he ever return to her? Would not such a land be completely defiled? But you have played the harlot with many lovers—and you would return to Me?” declares the LORD.'),
('JER', 3, 2, 'JER.3.2', '“Lift up your eyes to the barren heights and see. Is there any place where you have not been violated? You sat beside the highways waiting for your lovers, like a nomad in the desert. You have defiled the land with your prostitution and wickedness.'),
('JER', 3, 3, 'JER.3.3', 'Therefore the showers have been withheld, and no spring rains have fallen. Yet you have the brazen look of a prostitute; you refuse to be ashamed.'),
('JER', 3, 4, 'JER.3.4', 'Have you not just called to Me, ‘My Father, You are my friend from youth.'),
('JER', 3, 5, 'JER.3.5', 'Will He be angry forever? Will He be indignant to the end?’ This you have spoken, but you keep doing all the evil you can.”'),
('JER', 3, 6, 'JER.3.6', 'Now in the days of King Josiah, the LORD said to me, “Have you seen what faithless Israel has done? She has gone up on every high hill and under every green tree to prostitute herself there.'),
('JER', 3, 7, 'JER.3.7', 'I thought that after she had done all these things, she would return to Me. But she did not return, and her unfaithful sister Judah saw it.'),
('JER', 3, 8, 'JER.3.8', 'She saw that because faithless Israel had committed adultery, I gave her a certificate of divorce and sent her away. Yet that unfaithful sister Judah had no fear and prostituted herself as well.'),
('JER', 3, 9, 'JER.3.9', 'Indifferent to her own infidelity, Israel had defiled the land and committed adultery with stones and trees.'),
('JER', 3, 10, 'JER.3.10', 'Yet in spite of all this, her unfaithful sister Judah did not return to Me with all her heart, but only in pretense,” declares the LORD.'),
('JER', 3, 11, 'JER.3.11', 'And the LORD said to me, “Faithless Israel has shown herself more righteous than unfaithful Judah.'),
('JER', 3, 12, 'JER.3.12', 'Go, proclaim this message toward the north: ‘Return, O faithless Israel,’ declares the LORD. ‘I will no longer look on you with anger, for I am merciful,’ declares the LORD. ‘I will not be angry forever.'),
('JER', 3, 13, 'JER.3.13', 'Only acknowledge your guilt, that you have rebelled against the LORD your God. You have scattered your favors to foreign gods under every green tree and have not obeyed My voice,’” declares the LORD.'),
('JER', 3, 14, 'JER.3.14', '“Return, O faithless children,” declares the LORD, “for I am your master, and I will take you—one from a city and two from a family—and bring you to Zion.'),
('JER', 3, 15, 'JER.3.15', 'Then I will give you shepherds after My own heart, who will feed you with knowledge and understanding.”'),
('JER', 3, 16, 'JER.3.16', '“In those days, when you multiply and increase in the land,” declares the LORD, “they will no longer discuss the ark of the covenant of the LORD. It will never come to mind, and no one will remember it or miss it, nor will another one be made.'),
('JER', 3, 17, 'JER.3.17', 'At that time they will call Jerusalem The Throne of the LORD, and all the nations will be gathered in Jerusalem to honor the name of the LORD. They will no longer follow the stubbornness of their evil hearts.'),
('JER', 3, 18, 'JER.3.18', 'In those days the house of Judah will walk with the house of Israel, and they will come together from the land of the north to the land that I gave to your fathers as an inheritance.'),
('JER', 3, 19, 'JER.3.19', 'Then I said, ‘How I long to make you My sons and give you a desirable land, the most beautiful inheritance of all the nations!’ I thought you would call Me ‘Father’ and never turn away from following Me.'),
('JER', 3, 20, 'JER.3.20', 'But as a woman may betray her husband, so you have betrayed Me, O house of Israel,” declares the LORD.'),
('JER', 3, 21, 'JER.3.21', 'A voice is heard on the barren heights, the children of Israel weeping and begging for mercy, because they have perverted their ways and forgotten the LORD their God.'),
('JER', 3, 22, 'JER.3.22', '“Return, O faithless children, and I will heal your faithlessness.” “Here we are. We come to You, for You are the LORD our God.'),
('JER', 3, 23, 'JER.3.23', 'Surely deception comes from the hills, and commotion from the mountains. Surely the salvation of Israel is in the LORD our God.'),
('JER', 3, 24, 'JER.3.24', 'From our youth, that shameful god has consumed what our fathers have worked for—their flocks and herds, their sons and daughters.'),
('JER', 3, 25, 'JER.3.25', 'Let us lie down in our shame; let our disgrace cover us. We have sinned against the LORD our God, both we and our fathers; from our youth even to this day we have not obeyed the voice of the LORD our God.”'),
('JER', 4, 1, 'JER.4.1', '“If you will return, O Israel, return to Me,” declares the LORD. “If you will remove your detestable idols from My sight and no longer waver,'),
('JER', 4, 2, 'JER.4.2', 'and if you can swear, ‘As surely as the LORD lives,’ in truth, in justice, and in righteousness, then the nations will be blessed by Him, and in Him they will glory.”'),
('JER', 4, 3, 'JER.4.3', 'For this is what the LORD says to the men of Judah and Jerusalem: “Break up your unplowed ground, and do not sow among the thorns.'),
('JER', 4, 4, 'JER.4.4', 'Circumcise yourselves to the LORD, and remove the foreskins of your hearts, O men of Judah and people of Jerusalem. Otherwise, My wrath will break out like fire and burn with no one to extinguish it, because of your evil deeds.”'),
('JER', 4, 5, 'JER.4.5', 'Announce in Judah, proclaim in Jerusalem, and say: “Blow the ram’s horn throughout the land. Cry aloud and say, ‘Assemble yourselves and let us flee to the fortified cities.’'),
('JER', 4, 6, 'JER.4.6', 'Raise a signal flag toward Zion. Seek refuge! Do not delay! For I am bringing disaster from the north, and terrible destruction.'),
('JER', 4, 7, 'JER.4.7', 'A lion has gone up from his thicket, and a destroyer of nations has set out. He has left his lair to lay waste your land. Your cities will be reduced to ruins and lie uninhabited.'),
('JER', 4, 8, 'JER.4.8', 'So put on sackcloth, mourn and wail, for the fierce anger of the LORD has not turned away from us.”'),
('JER', 4, 9, 'JER.4.9', '“In that day,” declares the LORD, “the king and officials will lose their courage. The priests will tremble in fear, and the prophets will be astounded.”'),
('JER', 4, 10, 'JER.4.10', 'Then I said, “Ah, Lord GOD, how completely You have deceived this people and Jerusalem by saying, ‘You will have peace,’ while a sword is at our throats.”'),
('JER', 4, 11, 'JER.4.11', 'At that time it will be said to this people and to Jerusalem, “A searing wind from the barren heights in the desert blows toward the daughter of My people, but not to winnow or to sift;'),
('JER', 4, 12, 'JER.4.12', 'a wind too strong for that comes from Me. Now I also pronounce judgments against them.”'),
('JER', 4, 13, 'JER.4.13', 'Behold, he advances like the clouds, his chariots like the whirlwind. His horses are swifter than eagles. Woe to us, for we are ruined!'),
('JER', 4, 14, 'JER.4.14', 'Wash the evil from your heart, O Jerusalem, so that you may be saved. How long will you harbor wicked thoughts within you?'),
('JER', 4, 15, 'JER.4.15', 'For a voice resounds from Dan, proclaiming disaster from the hills of Ephraim.'),
('JER', 4, 16, 'JER.4.16', 'Warn the nations now! Proclaim to Jerusalem: “A besieging army comes from a distant land; they raise their voices against the cities of Judah.'),
('JER', 4, 17, 'JER.4.17', 'They surround her like men guarding a field, because she has rebelled against Me,” declares the LORD.'),
('JER', 4, 18, 'JER.4.18', '“Your ways and deeds have brought this upon you. This is your punishment; how bitter it is, because it pierces to the heart!”'),
('JER', 4, 19, 'JER.4.19', 'My anguish, my anguish! I writhe in pain! Oh, the pain in my chest! My heart pounds within me; I cannot be silent. For I have heard the sound of the horn, the alarm of battle.'),
('JER', 4, 20, 'JER.4.20', 'Disaster after disaster is proclaimed, for the whole land is laid waste. My tents are destroyed in an instant, my curtains in a moment.'),
('JER', 4, 21, 'JER.4.21', 'How long must I see the signal flag and hear the sound of the horn?'),
('JER', 4, 22, 'JER.4.22', '“For My people are fools; they have not known Me. They are foolish children, without understanding. They are skilled in doing evil, but they know not how to do good.”'),
('JER', 4, 23, 'JER.4.23', 'I looked at the earth, and it was formless and void; I looked to the heavens, and they had no light.'),
('JER', 4, 24, 'JER.4.24', 'I looked at the mountains, and behold, they were quaking; all the hills were swaying.'),
('JER', 4, 25, 'JER.4.25', 'I looked, and no man was left; all the birds of the air had fled.'),
('JER', 4, 26, 'JER.4.26', 'I looked, and the fruitful land was a desert. All its cities were torn down before the LORD, before His fierce anger.'),
('JER', 4, 27, 'JER.4.27', 'For this is what the LORD says: “The whole land will be desolate, but I will not finish its destruction.'),
('JER', 4, 28, 'JER.4.28', 'Therefore the earth will mourn and the heavens above will grow dark. I have spoken, I have planned, and I will not relent or turn back.”'),
('JER', 4, 29, 'JER.4.29', 'Every city flees at the sound of the horseman and archer. They enter the thickets and climb among the rocks. Every city is abandoned; no inhabitant is left.'),
('JER', 4, 30, 'JER.4.30', 'And you, O devastated one, what will you do, though you dress yourself in scarlet, though you adorn yourself with gold jewelry, though you enlarge your eyes with paint? You adorn yourself in vain; your lovers despise you; they want to take your life.'),
('JER', 4, 31, 'JER.4.31', 'For I hear a cry like a woman in labor, a cry of anguish like one bearing her first child—the cry of the Daughter of Zion gasping for breath, stretching out her hands to say, “Woe is me, for my soul faints before the murderers!”'),
('JER', 5, 1, 'JER.5.1', '“Go up and down the streets of Jerusalem. Look now and take note; search her squares. If you can find a single person, anyone who acts justly, anyone who seeks the truth, then I will forgive the city.'),
('JER', 5, 2, 'JER.5.2', 'Although they say, ‘As surely as the LORD lives,’ they are swearing falsely.”'),
('JER', 5, 3, 'JER.5.3', 'O LORD, do not Your eyes look for truth? You struck them, but they felt no pain. You finished them off, but they refused to accept discipline. They have made their faces harder than stone and refused to repent.'),
('JER', 5, 4, 'JER.5.4', 'Then I said, “They are only the poor; they have played the fool, for they do not know the way of the LORD, the justice of their God.'),
('JER', 5, 5, 'JER.5.5', 'I will go to the powerful and speak to them. Surely they know the way of the LORD, the justice of their God.” But they too, with one accord, had broken the yoke and torn off the chains.'),
('JER', 5, 6, 'JER.5.6', 'Therefore a lion from the forest will strike them down, a wolf from the desert will ravage them. A leopard will lie in wait near their cities, and everyone who ventures out will be torn to pieces. For their rebellious acts are many, and their unfaithful deeds are numerous.'),
('JER', 5, 7, 'JER.5.7', '“Why should I forgive you? Your children have forsaken Me and sworn by gods that are not gods. I satisfied their needs, yet they committed adultery and assembled at the houses of prostitutes.'),
('JER', 5, 8, 'JER.5.8', 'They are well-fed, lusty stallions, each neighing after his neighbor’s wife.'),
('JER', 5, 9, 'JER.5.9', 'Should I not punish them for these things?” declares the LORD. “Should I not avenge Myself on such a nation as this?'),
('JER', 5, 10, 'JER.5.10', 'Go up through her vineyards and ravage them, but do not finish them off. Strip off her branches, for they do not belong to the LORD.'),
('JER', 5, 11, 'JER.5.11', 'For the house of Israel and the house of Judah have been utterly unfaithful to Me,” declares the LORD.'),
('JER', 5, 12, 'JER.5.12', 'They have lied about the LORD and said: “He will not do anything; harm will not come to us; we will not see sword or famine.'),
('JER', 5, 13, 'JER.5.13', 'The prophets are but wind, for the word is not in them. So let their own predictions befall them.”'),
('JER', 5, 14, 'JER.5.14', 'Therefore this is what the LORD God of Hosts says: “Because you have spoken this word, I will make My words a fire in your mouth and this people the wood it consumes.'),
('JER', 5, 15, 'JER.5.15', 'Behold, I am bringing a distant nation against you, O house of Israel,” declares the LORD. “It is an established nation, an ancient nation, a nation whose language you do not know and whose speech you do not understand.'),
('JER', 5, 16, 'JER.5.16', 'Their quivers are like open graves; they are all mighty men.'),
('JER', 5, 17, 'JER.5.17', 'They will devour your harvest and food; they will consume your sons and daughters; they will eat up your flocks and herds; they will feed on your vines and fig trees. With the sword they will destroy the fortified cities in which you trust.”'),
('JER', 5, 18, 'JER.5.18', '“Yet even in those days,” declares the LORD, “I will not make a full end of you.'),
('JER', 5, 19, 'JER.5.19', 'And when the people ask, ‘For what offense has the LORD our God done all these things to us?’ You are to tell them, ‘Just as you have forsaken Me and served foreign gods in your land, so will you serve foreigners in a land that is not your own.’”'),
('JER', 5, 20, 'JER.5.20', 'Declare this in the house of Jacob and proclaim it in Judah:'),
('JER', 5, 21, 'JER.5.21', '“Hear this, O foolish and senseless people, who have eyes but do not see, who have ears but do not hear.'),
('JER', 5, 22, 'JER.5.22', 'Do you not fear Me?” declares the LORD. “Do you not tremble before Me, the One who set the sand as the boundary for the sea, an enduring barrier it cannot cross? The waves surge, but they cannot prevail. They roar but cannot cross it.'),
('JER', 5, 23, 'JER.5.23', 'But these people have stubborn and rebellious hearts. They have turned aside and gone away.'),
('JER', 5, 24, 'JER.5.24', 'They have not said in their hearts, ‘Let us fear the LORD our God, who gives the rains, both autumn and spring, in season, who keeps for us the appointed weeks of harvest.’'),
('JER', 5, 25, 'JER.5.25', 'Your iniquities have diverted these from you; your sins have deprived you of My bounty.'),
('JER', 5, 26, 'JER.5.26', 'For among My people are wicked men; they watch like fowlers lying in wait; they set a trap to catch men.'),
('JER', 5, 27, 'JER.5.27', 'Like cages full of birds, so their houses are full of deceit. Therefore they have become powerful and rich.'),
('JER', 5, 28, 'JER.5.28', 'They have grown fat and sleek, and have excelled in the deeds of the wicked. They have not taken up the cause of the fatherless, that they might prosper; nor have they defended the rights of the needy.'),
('JER', 5, 29, 'JER.5.29', 'Should I not punish them for these things?” declares the LORD. “Should I not avenge Myself on such a nation as this?'),
('JER', 5, 30, 'JER.5.30', 'A horrible and shocking thing has happened in the land.'),
('JER', 5, 31, 'JER.5.31', 'The prophets prophesy falsely, and the priests rule by their own authority. My people love it so, but what will you do in the end?'),
('JER', 6, 1, 'JER.6.1', '“Run for cover, O sons of Benjamin; flee from Jerusalem! Sound the ram’s horn in Tekoa; send up a signal over Beth-haccherem, for disaster looms from the north, even great destruction.'),
('JER', 6, 2, 'JER.6.2', 'Though she is beautiful and delicate, I will destroy the Daughter of Zion.'),
('JER', 6, 3, 'JER.6.3', 'Shepherds and their flocks will come against her; they will pitch their tents all around her, each tending his own portion:'),
('JER', 6, 4, 'JER.6.4', '‘Prepare for battle against her; rise up, let us attack at noon. Woe to us, for the daylight is fading; the evening shadows grow long.'),
('JER', 6, 5, 'JER.6.5', 'Rise up, let us attack by night and destroy her fortresses!’”'),
('JER', 6, 6, 'JER.6.6', 'For this is what the LORD of Hosts says: “Cut down the trees and raise a siege ramp against Jerusalem. This city must be punished; there is nothing but oppression in her midst.'),
('JER', 6, 7, 'JER.6.7', 'As a well gushes its water, so she pours out her evil. Violence and destruction resound in her; sickness and wounds are ever before Me.'),
('JER', 6, 8, 'JER.6.8', 'Be forewarned, O Jerusalem, or I will turn away from you; I will make you a desolation, a land without inhabitant.”'),
('JER', 6, 9, 'JER.6.9', 'This is what the LORD of Hosts says: “Glean the remnant of Israel as thoroughly as a vine. Pass your hand once more like a grape gatherer over the branches.”'),
('JER', 6, 10, 'JER.6.10', 'To whom can I give this warning? Who will listen to me? Look, their ears are closed, so they cannot hear. See, the word of the LORD has become offensive to them; they find no pleasure in it.'),
('JER', 6, 11, 'JER.6.11', 'But I am full of the LORD’s wrath; I am tired of holding it back. “Pour it out on the children in the street, and on the young men gathered together. For both husband and wife will be captured, the old and the very old alike.'),
('JER', 6, 12, 'JER.6.12', 'Their houses will be turned over to others, their fields and wives as well, for I will stretch out My hand against the inhabitants of the land,” declares the LORD.'),
('JER', 6, 13, 'JER.6.13', '“For from the least of them to the greatest, all are greedy for gain; from prophet to priest, all practice deceit.'),
('JER', 6, 14, 'JER.6.14', 'They dress the wound of My people with very little care, saying, ‘Peace, peace,’ when there is no peace at all.'),
('JER', 6, 15, 'JER.6.15', 'Are they ashamed of the abomination they have committed? No, they have no shame at all; they do not even know how to blush. So they will fall among the fallen; when I punish them, they will collapse,” says the LORD.'),
('JER', 6, 16, 'JER.6.16', 'This is what the LORD says: “Stand at the crossroads and look. Ask for the ancient paths: ‘Where is the good way?’ Then walk in it, and you will find rest for your souls. But they said, ‘We will not walk in it!’'),
('JER', 6, 17, 'JER.6.17', 'I appointed watchmen over you and said, ‘Listen for the sound of the ram’s horn.’ But they answered, ‘We will not listen!’'),
('JER', 6, 18, 'JER.6.18', 'Therefore hear, O nations, and learn, O congregations, what will happen to them.'),
('JER', 6, 19, 'JER.6.19', 'Hear, O earth! I am bringing disaster on this people, the fruit of their own schemes, because they have paid no attention to My word and have rejected My instruction.'),
('JER', 6, 20, 'JER.6.20', 'What use to Me is frankincense from Sheba or sweet cane from a distant land? Your burnt offerings are not acceptable; your sacrifices do not please Me.”'),
('JER', 6, 21, 'JER.6.21', 'Therefore this is what the LORD says: “I will lay stumbling blocks before this people; fathers and sons alike will be staggered; friends and neighbors will perish.”'),
('JER', 6, 22, 'JER.6.22', 'This is what the LORD says: “Behold, an army is coming from the land of the north; a great nation is stirred up from the ends of the earth.'),
('JER', 6, 23, 'JER.6.23', 'They grasp the bow and spear; they are cruel and merciless. Their voice roars like the sea, and they ride upon horses, lined up like men in formation against you, O Daughter of Zion.”'),
('JER', 6, 24, 'JER.6.24', 'We have heard the report; our hands hang limp. Anguish has gripped us, pain like that of a woman in labor.'),
('JER', 6, 25, 'JER.6.25', 'Do not go out to the fields; do not walk the road. For the enemy has a sword; terror is on every side.'),
('JER', 6, 26, 'JER.6.26', 'O daughter of my people, dress yourselves in sackcloth and roll in ashes. Mourn with bitter wailing, as you would for an only son, for suddenly the destroyer will come upon us.'),
('JER', 6, 27, 'JER.6.27', '“I have appointed you to examine My people like ore, so you may know and try their ways.'),
('JER', 6, 28, 'JER.6.28', 'All are hardened rebels, walking around as slanderers. They are bronze and iron; all of them are corrupt.'),
('JER', 6, 29, 'JER.6.29', 'The bellows blow fiercely, blasting away the lead with fire. The refining proceeds in vain, for the wicked are not purged.'),
('JER', 6, 30, 'JER.6.30', 'They are called rejected silver, because the LORD has rejected them.”'),
('JER', 7, 1, 'JER.7.1', 'This is the word that came to Jeremiah from the LORD, saying,'),
('JER', 7, 2, 'JER.7.2', '“Stand in the gate of the house of the LORD and proclaim this message: Hear the word of the LORD, all you people of Judah who enter through these gates to worship the LORD.'),
('JER', 7, 3, 'JER.7.3', 'Thus says the LORD of Hosts, the God of Israel: Correct your ways and deeds, and I will let you live in this place.'),
('JER', 7, 4, 'JER.7.4', 'Do not trust in deceptive words, saying: ‘This is the temple of the LORD, the temple of the LORD, the temple of the LORD.’'),
('JER', 7, 5, 'JER.7.5', 'For if you really correct your ways and deeds, if you act justly toward one another,'),
('JER', 7, 6, 'JER.7.6', 'if you no longer oppress the foreigner and the fatherless and the widow, and if you no longer shed innocent blood in this place or follow other gods to your own harm,'),
('JER', 7, 7, 'JER.7.7', 'then I will let you live in this place, in the land that I gave to your fathers forever and ever.'),
('JER', 7, 8, 'JER.7.8', 'But look, you keep trusting in deceptive words to no avail.'),
('JER', 7, 9, 'JER.7.9', 'Will you steal and murder, commit adultery and perjury, burn incense to Baal, and follow other gods that you have not known,'),
('JER', 7, 10, 'JER.7.10', 'and then come and stand before Me in this house, which bears My Name, and say, ‘We are delivered, so we can continue with all these abominations’?'),
('JER', 7, 11, 'JER.7.11', 'Has this house, which bears My Name, become a den of robbers in your sight? Yes, I too have seen it, declares the LORD.'),
('JER', 7, 12, 'JER.7.12', 'But go now to the place in Shiloh where I first made a dwelling for My Name, and see what I did to it because of the wickedness of My people Israel.'),
('JER', 7, 13, 'JER.7.13', 'And now, because you have done all these things, declares the LORD, and because I have spoken to you again and again but you would not listen, and I have called to you but you would not answer,'),
('JER', 7, 14, 'JER.7.14', 'therefore what I did to Shiloh I will now do to the house that bears My Name, the house in which you trust, the place that I gave to you and your fathers.'),
('JER', 7, 15, 'JER.7.15', 'And I will cast you out of My presence, just as I have cast out all your brothers, all the descendants of Ephraim.'),
('JER', 7, 16, 'JER.7.16', 'As for you, do not pray for these people, do not offer a plea or petition on their behalf, and do not beg Me, for I will not listen to you.'),
('JER', 7, 17, 'JER.7.17', 'Do you not see what they are doing in the cities of Judah and in the streets of Jerusalem?'),
('JER', 7, 18, 'JER.7.18', 'The sons gather wood, the fathers light the fire, and the women knead the dough to make cakes for the Queen of Heaven; they pour out drink offerings to other gods to provoke Me to anger.'),
('JER', 7, 19, 'JER.7.19', 'But am I the One they are provoking? declares the LORD. Is it not themselves they spite, to their own shame?'),
('JER', 7, 20, 'JER.7.20', 'Therefore this is what the Lord GOD says: Behold, My anger and My fury will be poured out on this place, on man and beast, on the trees of the field and the produce of the land, and it will burn and not be extinguished.'),
('JER', 7, 21, 'JER.7.21', 'This is what the LORD of Hosts, the God of Israel, says: Add your burnt offerings to your other sacrifices and eat the meat yourselves!'),
('JER', 7, 22, 'JER.7.22', 'For when I brought your fathers out of the land of Egypt, I did not merely command them about burnt offerings and sacrifices,'),
('JER', 7, 23, 'JER.7.23', 'but this is what I commanded them: Obey Me, and I will be your God, and you will be My people. You must walk in all the ways I have commanded you, so that it may go well with you.'),
('JER', 7, 24, 'JER.7.24', 'Yet they did not listen or incline their ear, but they followed the stubborn inclinations of their own evil hearts. They went backward and not forward.'),
('JER', 7, 25, 'JER.7.25', 'From the day your fathers came out of the land of Egypt until this day, I have sent you all My servants the prophets again and again.'),
('JER', 7, 26, 'JER.7.26', 'Yet they would not listen to Me or incline their ear, but they stiffened their necks and did more evil than their fathers.'),
('JER', 7, 27, 'JER.7.27', 'When you tell them all these things, they will not listen to you. When you call to them, they will not answer.'),
('JER', 7, 28, 'JER.7.28', 'Therefore you must say to them, ‘This is the nation that would not listen to the voice of the LORD their God and would not receive correction. Truth has perished; it has disappeared from their lips.'),
('JER', 7, 29, 'JER.7.29', 'Cut off your hair and throw it away. Raise up a lamentation on the barren heights, for the LORD has rejected and forsaken the generation of His wrath.’'),
('JER', 7, 30, 'JER.7.30', 'For the people of Judah have done evil in My sight, declares the LORD. They have set up their abominations in the house that bears My Name, and so have defiled it.'),
('JER', 7, 31, 'JER.7.31', 'They have built the high places of Topheth in the Valley of Ben-hinnom so they could burn their sons and daughters in the fire—something I never commanded, nor did it even enter My mind.'),
('JER', 7, 32, 'JER.7.32', 'So behold, the days are coming, declares the LORD, when this place will no longer be called Topheth and the Valley of Ben-hinnom, but the Valley of Slaughter. For they will bury the dead in Topheth until there is no more room.'),
('JER', 7, 33, 'JER.7.33', 'The corpses of this people will become food for the birds of the air and the beasts of the earth, and there will be no one to scare them away.'),
('JER', 7, 34, 'JER.7.34', 'I will remove from the cities of Judah and the streets of Jerusalem the sounds of joy and gladness and the voices of the bride and bridegroom, for the land will become a wasteland.”'),
('JER', 8, 1, 'JER.8.1', '“At that time,” declares the LORD, “the bones of the kings of Judah, the bones of the officials, the bones of the priests, the bones of the prophets, and the bones of the people of Jerusalem will be removed from their graves.'),
('JER', 8, 2, 'JER.8.2', 'They will be exposed to the sun and moon, and to all the host of heaven which they have loved, served, followed, consulted, and worshiped. Their bones will not be gathered up or buried, but will become like dung lying on the ground.'),
('JER', 8, 3, 'JER.8.3', 'And wherever I have banished them, the remnant of this evil family will choose death over life,” declares the LORD of Hosts.'),
('JER', 8, 4, 'JER.8.4', 'So you are to tell them this is what the LORD says: “Do men fall and not get up again? Does one turn away and not return?'),
('JER', 8, 5, 'JER.8.5', 'Why then have these people turned away? Why does Jerusalem always turn away? They cling to deceit; they refuse to return.'),
('JER', 8, 6, 'JER.8.6', 'I have listened and heard; they do not speak what is right. No one repents of his wickedness, asking, ‘What have I done?’ Everyone has pursued his own course like a horse charging into battle.'),
('JER', 8, 7, 'JER.8.7', 'Even the stork in the sky knows her appointed seasons. The turtledove, the swift, and the thrush keep their time of migration, but My people do not know the requirements of the LORD.'),
('JER', 8, 8, 'JER.8.8', 'How can you say, ‘We are wise, and the Law of the LORD is with us,’ when in fact the lying pen of the scribes has produced a deception?'),
('JER', 8, 9, 'JER.8.9', 'The wise will be put to shame; they will be dismayed and trapped. Since they have rejected the word of the LORD, what wisdom do they really have?'),
('JER', 8, 10, 'JER.8.10', 'Therefore I will give their wives to other men and their fields to new owners. For from the least of them to the greatest, all are greedy for gain; from prophet to priest, all practice deceit.'),
('JER', 8, 11, 'JER.8.11', 'They dress the wound of the daughter of My people with very little care, saying, ‘Peace, peace,’ when there is no peace at all.'),
('JER', 8, 12, 'JER.8.12', 'Are they ashamed of the abomination they have committed? No, they have no shame at all; they do not even know how to blush. So they will fall among the fallen; when I punish them, they will collapse, says the LORD.'),
('JER', 8, 13, 'JER.8.13', 'I will take away their harvest, declares the LORD. There will be no grapes on the vine, nor figs on the tree, and even the leaf will wither. Whatever I have given them will be lost to them.”'),
('JER', 8, 14, 'JER.8.14', 'Why are we just sitting here? Gather together, let us flee to the fortified cities and perish there, for the LORD our God has doomed us. He has given us poisoned water to drink, because we have sinned against the LORD.'),
('JER', 8, 15, 'JER.8.15', 'We hoped for peace, but no good has come, for a time of healing, but there was only terror.'),
('JER', 8, 16, 'JER.8.16', 'The snorting of enemy horses is heard from Dan. At the sound of the neighing of mighty steeds, the whole land quakes. They come to devour the land and everything in it, the city and all who dwell in it.'),
('JER', 8, 17, 'JER.8.17', '“For behold, I will send snakes among you, vipers that cannot be charmed, and they will bite you,” declares the LORD.'),
('JER', 8, 18, 'JER.8.18', 'My sorrow is beyond healing; my heart is faint within me.'),
('JER', 8, 19, 'JER.8.19', 'Listen to the cry of the daughter of my people from a land far away: “Is the LORD no longer in Zion? Is her King no longer there?” “Why have they provoked Me to anger with their carved images, with their worthless foreign idols?”'),
('JER', 8, 20, 'JER.8.20', '“The harvest has passed, the summer has ended, but we have not been saved.”'),
('JER', 8, 21, 'JER.8.21', 'For the brokenness of the daughter of my people I am crushed. I mourn; horror has gripped me.'),
('JER', 8, 22, 'JER.8.22', 'Is there no balm in Gilead? Is no physician there? Why then has the health of the daughter of my people not been restored?'),
('JER', 9, 1, 'JER.9.1', 'Oh, that my head were a spring of water, and my eyes a fountain of tears! I would weep day and night over the slain daughter of my people.'),
('JER', 9, 2, 'JER.9.2', 'If only I had a traveler’s lodge in the wilderness, I would abandon my people and depart from them, for they are all adulterers, a crowd of faithless people.'),
('JER', 9, 3, 'JER.9.3', '“They bend their tongues like bows; lies prevail over truth in the land. For they proceed from evil to evil, and they do not take Me into account,” declares the LORD.'),
('JER', 9, 4, 'JER.9.4', '“Let everyone guard against his neighbor; do not trust any brother, for every brother deals craftily, and every friend spreads slander.'),
('JER', 9, 5, 'JER.9.5', 'Each one betrays his friend; no one tells the truth. They have taught their tongues to lie; they wear themselves out committing iniquity.'),
('JER', 9, 6, 'JER.9.6', 'You dwell in the midst of deception; in their deceit they refuse to know Me,” declares the LORD.'),
('JER', 9, 7, 'JER.9.7', 'Therefore this is what the LORD of Hosts says: “Behold, I will refine them and test them, for what else can I do because of the daughter of My people?'),
('JER', 9, 8, 'JER.9.8', 'Their tongues are deadly arrows; they speak deception. With his mouth a man speaks peace to his neighbor, but in his heart he sets a trap for him.'),
('JER', 9, 9, 'JER.9.9', 'Should I not punish them for these things? declares the LORD. Should I not avenge Myself on such a nation as this?”'),
('JER', 9, 10, 'JER.9.10', 'I will take up a weeping and wailing for the mountains, a dirge over the wilderness pasture, for they have been scorched so no one passes through, and the lowing of cattle is not heard. Both the birds of the air and the beasts have fled; they have gone away.'),
('JER', 9, 11, 'JER.9.11', '“And I will make Jerusalem a heap of rubble, a haunt for jackals; and I will make the cities of Judah a desolation, without inhabitant.”'),
('JER', 9, 12, 'JER.9.12', 'Who is the man wise enough to understand this? To whom has the mouth of the LORD spoken, that he may explain it? Why is the land destroyed and scorched like a desert, so no one can pass through it?'),
('JER', 9, 13, 'JER.9.13', 'And the LORD answered, “It is because they have forsaken My law, which I set before them; they have not walked in it or obeyed My voice.'),
('JER', 9, 14, 'JER.9.14', 'Instead, they have followed the stubbornness of their hearts and gone after the Baals, as their fathers taught them.”'),
('JER', 9, 15, 'JER.9.15', 'Therefore this is what the LORD of Hosts, the God of Israel, says: “Behold, I will feed this people wormwood and give them poisoned water to drink.'),
('JER', 9, 16, 'JER.9.16', 'I will scatter them among the nations that neither they nor their fathers have known, and I will send a sword after them until I have finished them off.”'),
('JER', 9, 17, 'JER.9.17', 'This is what the LORD of Hosts says: “Take note, and summon the wailing women; send for the most skillful among them.'),
('JER', 9, 18, 'JER.9.18', 'Let them come quickly and take up a lament over us, that our eyes may overflow with tears, and our eyelids may gush with water.'),
('JER', 9, 19, 'JER.9.19', 'For the sound of wailing is heard from Zion: ‘How devastated we are! How great is our shame! For we have abandoned the land because our dwellings have been torn down.’”'),
('JER', 9, 20, 'JER.9.20', 'Now, O women, hear the word of the LORD. Open your ears to the word of His mouth. Teach your daughters to wail, and one another to lament.'),
('JER', 9, 21, 'JER.9.21', 'For death has climbed in through our windows; it has entered our fortresses to cut off the children from the streets, the young men from the town squares.'),
('JER', 9, 22, 'JER.9.22', 'Declare that this is what the LORD says: “The corpses of men will fall like dung upon the open field, like newly cut grain behind the reaper, with no one to gather it.”'),
('JER', 9, 23, 'JER.9.23', 'This is what the LORD says: “Let not the wise man boast in his wisdom, nor the strong man in his strength, nor the wealthy man in his riches.'),
('JER', 9, 24, 'JER.9.24', 'But let him who boasts boast in this, that he understands and knows Me, that I am the LORD, who exercises loving devotion, justice and righteousness on the earth—for I delight in these things,” declares the LORD.'),
('JER', 9, 25, 'JER.9.25', '“Behold, the days are coming,” declares the LORD, “when I will punish all who are circumcised only in the flesh—'),
('JER', 9, 26, 'JER.9.26', 'Egypt, Judah, Edom, Ammon, Moab, and all the inhabitants of the desert who clip the hair of their temples. For all these nations are uncircumcised, and the whole house of Israel is uncircumcised in heart.”'),
('JER', 10, 1, 'JER.10.1', 'Hear the word that the LORD speaks to you, O house of Israel.'),
('JER', 10, 2, 'JER.10.2', 'This is what the LORD says: “Do not learn the ways of the nations or be terrified by the signs in the heavens, though the nations themselves are terrified by them.'),
('JER', 10, 3, 'JER.10.3', 'For the customs of the peoples are worthless; they cut down a tree from the forest; it is shaped with a chisel by the hands of a craftsman.'),
('JER', 10, 4, 'JER.10.4', 'They adorn it with silver and gold and fasten it with hammer and nails, so that it will not totter.'),
('JER', 10, 5, 'JER.10.5', 'Like scarecrows in a cucumber patch, their idols cannot speak. They must be carried because they cannot walk. Do not fear them, for they can do no harm, and neither can they do any good.”'),
('JER', 10, 6, 'JER.10.6', 'There is none like You, O LORD. You are great, and Your name is mighty in power.'),
('JER', 10, 7, 'JER.10.7', 'Who would not fear You, O King of nations? This is Your due. For among all the wise men of the nations, and in all their kingdoms, there is none like You.'),
('JER', 10, 8, 'JER.10.8', 'But they are altogether senseless and foolish, instructed by worthless idols made of wood!'),
('JER', 10, 9, 'JER.10.9', 'Hammered silver is brought from Tarshish, and gold from Uphaz—the work of a craftsman from the hands of a goldsmith. Their clothes are blue and purple, all fashioned by skilled workers.'),
('JER', 10, 10, 'JER.10.10', 'But the LORD is the true God; He is the living God and eternal King. The earth quakes at His wrath, and the nations cannot endure His indignation.'),
('JER', 10, 11, 'JER.10.11', 'Thus you are to tell them: “These gods, who have made neither the heavens nor the earth, will perish from this earth and from under these heavens.”'),
('JER', 10, 12, 'JER.10.12', 'The LORD made the earth by His power; He established the world by His wisdom and stretched out the heavens by His understanding.'),
('JER', 10, 13, 'JER.10.13', 'When He thunders, the waters in the heavens roar; He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
('JER', 10, 14, 'JER.10.14', 'Every man is senseless and devoid of knowledge; every goldsmith is put to shame by his idols. For his molten images are a fraud, and there is no breath in them.'),
('JER', 10, 15, 'JER.10.15', 'They are worthless, a work to be mocked. In the time of their punishment they will perish.'),
('JER', 10, 16, 'JER.10.16', 'The Portion of Jacob is not like these, for He is the Maker of all things, and Israel is the tribe of His inheritance—the LORD of Hosts is His name.'),
('JER', 10, 17, 'JER.10.17', 'Gather up your belongings from this land, you who live under siege.'),
('JER', 10, 18, 'JER.10.18', 'For this is what the LORD says: “Behold, at this time I will sling out the inhabitants of the land and bring distress upon them so that they may be captured.”'),
('JER', 10, 19, 'JER.10.19', 'Woe to me because of my brokenness; my wound is grievous! But I said, “This is truly my sickness, and I must bear it.”'),
('JER', 10, 20, 'JER.10.20', 'My tent is destroyed, and all its ropes are snapped. My sons have departed from me and are no more. I have no one left to pitch my tent or set up my curtains.'),
('JER', 10, 21, 'JER.10.21', 'For the shepherds have become senseless; they do not seek the LORD. Therefore they have not prospered, and all their flock is scattered.'),
('JER', 10, 22, 'JER.10.22', 'Listen! The sound of a report is coming—a great commotion from the land to the north. It will make the cities of Judah a desolation, a haunt for jackals.'),
('JER', 10, 23, 'JER.10.23', 'I know, O LORD, that a man’s way is not his own; no one who walks directs his own steps.'),
('JER', 10, 24, 'JER.10.24', 'Correct me, O LORD, but only with justice—not in Your anger, or You will bring me to nothing.'),
('JER', 10, 25, 'JER.10.25', 'Pour out Your wrath on the nations that do not acknowledge You, and on the families that do not call on Your name. For they have devoured Jacob; they have consumed him and finished him off; they have devastated his homeland.'),
('JER', 11, 1, 'JER.11.1', 'This is the word that came to Jeremiah from the LORD:'),
('JER', 11, 2, 'JER.11.2', '“Listen to the words of this covenant and tell them to the men of Judah and the residents of Jerusalem.'),
('JER', 11, 3, 'JER.11.3', 'You must tell them that this is what the LORD, the God of Israel, says: Cursed is the man who does not obey the words of this covenant,'),
('JER', 11, 4, 'JER.11.4', 'which I commanded your forefathers when I brought them out of the land of Egypt, out of the iron furnace, saying, ‘Obey Me, and do everything I command you, and you will be My people, and I will be your God.’'),
('JER', 11, 5, 'JER.11.5', 'This was in order to establish the oath I swore to your forefathers, to give them a land flowing with milk and honey, as it is to this day.” “Amen, LORD,” I answered.'),
('JER', 11, 6, 'JER.11.6', 'Then the LORD said to me, “Proclaim all these words in the cities of Judah and in the streets of Jerusalem, saying: Hear the words of this covenant and carry them out.'),
('JER', 11, 7, 'JER.11.7', 'For from the time I brought your fathers out of the land of Egypt until today, I strongly warned them again and again, saying, ‘Obey My voice.’'),
('JER', 11, 8, 'JER.11.8', 'Yet they would not obey or incline their ears, but each one followed the stubbornness of his evil heart. So I brought on them all the curses of this covenant I had commanded them to follow but they did not keep.”'),
('JER', 11, 9, 'JER.11.9', 'And the LORD told me, “There is a conspiracy among the men of Judah and the residents of Jerusalem.'),
('JER', 11, 10, 'JER.11.10', 'They have returned to the sins of their forefathers who refused to obey My words. They have followed other gods to serve them. The house of Israel and the house of Judah have broken the covenant I made with their fathers.'),
('JER', 11, 11, 'JER.11.11', 'Therefore this is what the LORD says: ‘I am about to bring upon them a disaster that they cannot escape. They will cry out to Me, but I will not listen to them.'),
('JER', 11, 12, 'JER.11.12', 'Then the cities of Judah and the residents of Jerusalem will go and cry out to the gods to which they have been burning incense, but these gods certainly will not save them in their time of disaster.'),
('JER', 11, 13, 'JER.11.13', 'Your gods are indeed as numerous as your cities, O Judah; the altars of shame you have set up—the altars to burn incense to Baal—are as many as the streets of Jerusalem.’'),
('JER', 11, 14, 'JER.11.14', 'As for you, do not pray for these people. Do not raise up a cry or a prayer on their behalf, for I will not be listening when they call out to Me in their time of disaster.'),
('JER', 11, 15, 'JER.11.15', 'What right has My beloved in My house, having carried out so many evil schemes? Can consecrated meat avert your doom? When you are wicked, then you rejoice.'),
('JER', 11, 16, 'JER.11.16', 'The LORD once called you a flourishing olive tree, beautiful with well-formed fruit. But with a mighty roar He will set it on fire, and its branches will be consumed.'),
('JER', 11, 17, 'JER.11.17', 'The LORD of Hosts, who planted you, has decreed disaster against you on account of the evil that the house of Israel and the house of Judah have brought upon themselves, provoking Me to anger by burning incense to Baal.”'),
('JER', 11, 18, 'JER.11.18', 'And the LORD informed me, so I knew. Then You showed me their deeds.'),
('JER', 11, 19, 'JER.11.19', 'For I was like a gentle lamb led to slaughter; I did not know that they had plotted against me: “Let us destroy the tree with its fruit; let us cut him off from the land of the living, that his name may be remembered no more.”'),
('JER', 11, 20, 'JER.11.20', 'O LORD of Hosts, who judges righteously, who examines the heart and mind, let me see Your vengeance upon them, for to You I have committed my cause.'),
('JER', 11, 21, 'JER.11.21', 'Therefore this is what the LORD says concerning the people of Anathoth who are seeking your life and saying, “You must not prophesy in the name of the LORD, or you will die by our hand.”'),
('JER', 11, 22, 'JER.11.22', 'So this is what the LORD of Hosts says: “I will punish them. Their young men will die by the sword, their sons and daughters by famine.'),
('JER', 11, 23, 'JER.11.23', 'There will be no remnant, for I will bring disaster on the people of Anathoth in the year of their punishment.”'),
('JER', 12, 1, 'JER.12.1', 'Righteous are You, O LORD, when I plead before You. Yet about Your judgments I wish to contend with You: Why does the way of the wicked prosper? Why do all the faithless live at ease?'),
('JER', 12, 2, 'JER.12.2', 'You planted them, and they have taken root. They have grown and produced fruit. You are ever on their lips, but far from their hearts.'),
('JER', 12, 3, 'JER.12.3', 'But You know me, O LORD; You see me and test my heart toward You. Drag away the wicked like sheep to the slaughter and set them apart for the day of carnage.'),
('JER', 12, 4, 'JER.12.4', 'How long will the land mourn and the grass of every field be withered? Because of the evil of its residents, the animals and birds have been swept away, for the people have said, “He cannot see what our end will be.”'),
('JER', 12, 5, 'JER.12.5', '“If you have raced with men on foot and they have worn you out, how can you compete with horses? If you stumble in a peaceful land, how will you do in the thickets of the Jordan?'),
('JER', 12, 6, 'JER.12.6', 'Even your brothers—your own father’s household—even they have betrayed you; even they have cried aloud against you. Do not trust them, though they speak well of you.'),
('JER', 12, 7, 'JER.12.7', 'I have forsaken My house; I have abandoned My inheritance. I have given the beloved of My soul into the hands of her enemies.'),
('JER', 12, 8, 'JER.12.8', 'My inheritance has become to Me like a lion in the forest. She has roared against Me; therefore I hate her.'),
('JER', 12, 9, 'JER.12.9', 'Is not My inheritance to Me like a speckled bird of prey with other birds of prey circling against her? Go, gather all the beasts of the field; bring them to devour her.'),
('JER', 12, 10, 'JER.12.10', 'Many shepherds have destroyed My vineyard; they have trampled My plot of ground. They have turned My pleasant field into a desolate wasteland.'),
('JER', 12, 11, 'JER.12.11', 'They have made it a desolation; desolate before Me, it mourns. All the land is laid waste, but no man takes it to heart.'),
('JER', 12, 12, 'JER.12.12', 'Over all the barren heights in the wilderness the destroyers have come, for the sword of the LORD devours from one end of the earth to the other. No flesh has peace.'),
('JER', 12, 13, 'JER.12.13', 'They have sown wheat but harvested thorns. They have exhausted themselves to no avail. Bear the shame of your harvest because of the fierce anger of the LORD.”'),
('JER', 12, 14, 'JER.12.14', 'This is what the LORD says: “As for all My evil neighbors who attack the inheritance that I bequeathed to My people Israel, I am about to uproot them from their land, and I will uproot the house of Judah from among them.'),
('JER', 12, 15, 'JER.12.15', 'But after I have uprooted them, I will once again have compassion on them and return each one to his inheritance and to his land.'),
('JER', 12, 16, 'JER.12.16', 'And if they will diligently learn the ways of My people and swear by My name, saying, ‘As surely as the LORD lives’—just as they once taught My people to swear by Baal—then they will be established among My people.'),
('JER', 12, 17, 'JER.12.17', 'But if they will not obey, then I will uproot that nation; I will uproot it and destroy it, declares the LORD.”'),
('JER', 13, 1, 'JER.13.1', 'This is what the LORD said to me: “Go and buy yourself a linen loincloth and put it around your waist, but do not let it touch water.”'),
('JER', 13, 2, 'JER.13.2', 'So I bought a loincloth in accordance with the word of the LORD, and I put it around my waist.'),
('JER', 13, 3, 'JER.13.3', 'Then the word of the LORD came to me a second time:'),
('JER', 13, 4, 'JER.13.4', '“Take the loincloth that you bought and are wearing, and go at once to Perath and hide it there in a crevice of the rocks.”'),
('JER', 13, 5, 'JER.13.5', 'So I went and hid it at Perath, as the LORD had commanded me.'),
('JER', 13, 6, 'JER.13.6', 'Many days later the LORD said to me, “Arise, go to Perath, and get the loincloth that I commanded you to hide there.”'),
('JER', 13, 7, 'JER.13.7', 'So I went to Perath and dug up the loincloth, and I took it from the place where I had hidden it. But now it was ruined—of no use at all.'),
('JER', 13, 8, 'JER.13.8', 'Then the word of the LORD came to me:'),
('JER', 13, 9, 'JER.13.9', '“This is what the LORD says: In the same way I will ruin the pride of Judah and the great pride of Jerusalem.'),
('JER', 13, 10, 'JER.13.10', 'These evil people, who refuse to listen to My words, who follow the stubbornness of their own hearts, and who go after other gods to serve and worship them, they will be like this loincloth—of no use at all.'),
('JER', 13, 11, 'JER.13.11', 'For just as a loincloth clings to a man’s waist, so I have made the whole house of Israel and the whole house of Judah cling to Me, declares the LORD, so that they might be My people for My renown and praise and glory. But they did not listen.'),
('JER', 13, 12, 'JER.13.12', 'Therefore you are to tell them that this is what the LORD, the God of Israel, says: ‘Every wineskin shall be filled with wine.’ And when they reply, ‘Don’t we surely know that every wineskin should be filled with wine?’'),
('JER', 13, 13, 'JER.13.13', 'then you are to tell them that this is what the LORD says: ‘I am going to fill with drunkenness all who live in this land—the kings who sit on David’s throne, the priests, the prophets, and all the people of Jerusalem.'),
('JER', 13, 14, 'JER.13.14', 'I will smash them against one another, fathers and sons alike, declares the LORD. I will allow no mercy or pity or compassion to keep Me from destroying them.’”'),
('JER', 13, 15, 'JER.13.15', 'Listen and give heed. Do not be arrogant, for the LORD has spoken.'),
('JER', 13, 16, 'JER.13.16', 'Give glory to the LORD your God before He brings darkness, before your feet stumble on the dusky mountains. You wait for light, but He turns it into deep gloom and thick darkness.'),
('JER', 13, 17, 'JER.13.17', 'But if you do not listen, I will weep in secret because of your pride. My eyes will overflow with tears, because the LORD’s flock has been taken captive.'),
('JER', 13, 18, 'JER.13.18', 'Say to the king and to the queen mother: “Take a lowly seat, for your glorious crowns have fallen from your heads.”'),
('JER', 13, 19, 'JER.13.19', 'The cities of the Negev have been shut tight, and no one can open them. All Judah has been carried into exile, wholly taken captive.'),
('JER', 13, 20, 'JER.13.20', 'Lift up your eyes and see those coming from the north. Where is the flock entrusted to you, the sheep that were your pride?'),
('JER', 13, 21, 'JER.13.21', 'What will you say when He sets over you close allies whom you yourself trained? Will not pangs of anguish grip you, as they do a woman in labor?'),
('JER', 13, 22, 'JER.13.22', 'And if you ask yourself, “Why has this happened to me?” It is because of the magnitude of your iniquity that your skirts have been stripped off and your body has been exposed.'),
('JER', 13, 23, 'JER.13.23', 'Can the Ethiopian change his skin, or the leopard his spots? Neither are you able to do good—you who are accustomed to doing evil.'),
('JER', 13, 24, 'JER.13.24', '“I will scatter you like chaff driven by the desert wind.'),
('JER', 13, 25, 'JER.13.25', 'This is your lot, the portion I have measured to you,” declares the LORD, “because you have forgotten Me and trusted in falsehood.'),
('JER', 13, 26, 'JER.13.26', 'So I will pull your skirts up over your face, that your shame may be seen.'),
('JER', 13, 27, 'JER.13.27', 'Your adulteries and lustful neighings, your shameless prostitution on the hills and in the fields—I have seen your detestable acts. Woe to you, O Jerusalem! How long will you remain unclean?”'),
('JER', 14, 1, 'JER.14.1', 'This is the word of the LORD that came to Jeremiah concerning the drought:'),
('JER', 14, 2, 'JER.14.2', '“Judah mourns and her gates languish. Her people wail for the land, and a cry goes up from Jerusalem.'),
('JER', 14, 3, 'JER.14.3', 'The nobles send their servants for water; they go to the cisterns, but find no water; their jars return empty. They are ashamed and humiliated; they cover their heads.'),
('JER', 14, 4, 'JER.14.4', 'The ground is cracked because no rain has fallen on the land. The farmers are ashamed; they cover their heads.'),
('JER', 14, 5, 'JER.14.5', 'Even the doe in the field deserts her newborn fawn because there is no grass.'),
('JER', 14, 6, 'JER.14.6', 'Wild donkeys stand on barren heights; they pant for air like jackals; their eyes fail for lack of pasture.”'),
('JER', 14, 7, 'JER.14.7', 'Although our iniquities testify against us, O LORD, act for the sake of Your name. Indeed, our rebellions are many; we have sinned against You.'),
('JER', 14, 8, 'JER.14.8', 'O Hope of Israel, its Savior in times of distress, why are You like a stranger in the land, like a traveler who stays but a night?'),
('JER', 14, 9, 'JER.14.9', 'Why are You like a man taken by surprise, like a warrior powerless to save? Yet You are among us, O LORD, and we are called by Your name. Do not forsake us!'),
('JER', 14, 10, 'JER.14.10', 'This is what the LORD says about this people: “Truly they love to wander; they have not restrained their feet. So the LORD does not accept them; He will now remember their iniquity and punish them for their sins.”'),
('JER', 14, 11, 'JER.14.11', 'Then the LORD said to me, “Do not pray for the well-being of this people.'),
('JER', 14, 12, 'JER.14.12', 'Although they may fast, I will not listen to their cry; although they may offer burnt offerings and grain offerings, I will not accept them. Instead, I will finish them off by sword and famine and plague.”'),
('JER', 14, 13, 'JER.14.13', '“Ah, Lord GOD!” I replied, “Look, the prophets are telling them, ‘You will not see the sword or suffer famine, but I will give you lasting peace in this place.’”'),
('JER', 14, 14, 'JER.14.14', '“The prophets are prophesying lies in My name,” replied the LORD. “I did not send them or appoint them or speak to them. They are prophesying to you a false vision, a worthless divination, the futility and delusion of their own minds.'),
('JER', 14, 15, 'JER.14.15', 'Therefore this is what the LORD says about the prophets who prophesy in My name: I did not send them, yet they say, ‘No sword or famine will touch this land.’ By sword and famine these very prophets will meet their end!'),
('JER', 14, 16, 'JER.14.16', 'And the people to whom they prophesy will be thrown into the streets of Jerusalem because of famine and sword. There will be no one to bury them or their wives, their sons or their daughters. I will pour out their own evil upon them.'),
('JER', 14, 17, 'JER.14.17', 'You are to speak this word to them: ‘My eyes overflow with tears; day and night they do not cease, for the virgin daughter of my people has been shattered by a crushing blow, a severely grievous wound.'),
('JER', 14, 18, 'JER.14.18', 'If I go out to the country, I see those slain by the sword; if I enter the city, I see those ravaged by famine! For both prophet and priest travel to a land they do not know.’”'),
('JER', 14, 19, 'JER.14.19', 'Have You rejected Judah completely? Do You despise Zion? Why have You stricken us so that we are beyond healing? We hoped for peace, but no good has come, and for the time of healing, but there was only terror.'),
('JER', 14, 20, 'JER.14.20', 'We acknowledge our wickedness, O LORD, the guilt of our fathers; indeed, we have sinned against You.'),
('JER', 14, 21, 'JER.14.21', 'For the sake of Your name do not despise us; do not disgrace Your glorious throne. Remember Your covenant with us; do not break it.'),
('JER', 14, 22, 'JER.14.22', 'Can the worthless idols of the nations bring rain? Do the skies alone send showers? Is this not by You, O LORD our God? So we put our hope in You, for You have done all these things.'),
('JER', 15, 1, 'JER.15.1', 'Then the LORD said to me: “Even if Moses and Samuel should stand before Me, My heart would not go out to this people. Send them from My presence, and let them go!'),
('JER', 15, 2, 'JER.15.2', 'If they ask you, ‘Where shall we go?’ you are to tell them that this is what the LORD says: ‘Those destined for death, to death; those destined for the sword, to the sword; those destined for famine, to famine; and those destined for captivity, to captivity.’'),
('JER', 15, 3, 'JER.15.3', 'I will appoint over them four kinds of destroyers, declares the LORD: the sword to kill, the dogs to drag away, and the birds of the air and beasts of the earth to devour and destroy.'),
('JER', 15, 4, 'JER.15.4', 'I will make them a horror to all the kingdoms of the earth because of what Manasseh son of Hezekiah king of Judah did in Jerusalem.'),
('JER', 15, 5, 'JER.15.5', 'Who will have pity on you, O Jerusalem? Who will mourn for you? Who will turn aside to ask about your welfare?'),
('JER', 15, 6, 'JER.15.6', 'You have forsaken Me, declares the LORD. You have turned your back. So I will stretch out My hand against you and I will destroy you; I am weary of showing compassion.'),
('JER', 15, 7, 'JER.15.7', 'I will scatter them with a winnowing fork at the gates of the land. I will bereave and destroy My people who have not turned from their ways.'),
('JER', 15, 8, 'JER.15.8', 'I will make their widows more numerous than the sand of the sea. I will bring a destroyer at noon against the mothers of young men. I will suddenly bring upon them anguish and dismay.'),
('JER', 15, 9, 'JER.15.9', 'The mother of seven will grow faint; she will breathe her last breath. Her sun will set while it is still day; she will be disgraced and humiliated. And the rest I will put to the sword in the presence of their enemies,” declares the LORD.'),
('JER', 15, 10, 'JER.15.10', 'Woe to me, my mother, that you have borne me, a man of strife and conflict in all the land. I have neither lent nor borrowed, yet everyone curses me.'),
('JER', 15, 11, 'JER.15.11', 'The LORD said: “Surely I will deliver you for a good purpose; surely I will intercede with your enemy in your time of trouble, in your time of distress.'),
('JER', 15, 12, 'JER.15.12', 'Can anyone smash iron—iron from the north—or bronze?'),
('JER', 15, 13, 'JER.15.13', 'Your wealth and your treasures I will give up as plunder, without charge for all your sins within all your borders.'),
('JER', 15, 14, 'JER.15.14', 'Then I will enslave you to your enemies in a land you do not know, for My anger will kindle a fire that will burn against you.”'),
('JER', 15, 15, 'JER.15.15', 'You understand, O LORD; remember me and attend to me. Avenge me against my persecutors. In Your patience, do not take me away. Know that I endure reproach for Your honor.'),
('JER', 15, 16, 'JER.15.16', 'Your words were found, and I ate them. Your words became my joy and my heart’s delight. For I bear Your name, O LORD God of Hosts.'),
('JER', 15, 17, 'JER.15.17', 'I never sat with the band of revelers, nor did I celebrate with them. Because Your hand was on me, I sat alone, for You have filled me with indignation.'),
('JER', 15, 18, 'JER.15.18', 'Why is my pain unending, and my wound incurable, refusing to be healed? You have indeed become like a mirage to me—water that is not there.'),
('JER', 15, 19, 'JER.15.19', 'Therefore this is what the LORD says: “If you return, I will restore you; you will stand in My presence. And if you speak words that are noble instead of worthless, you will be My spokesman. It is they who must turn to you, but you must not turn to them.'),
('JER', 15, 20, 'JER.15.20', 'Then I will make you a wall to this people, a fortified wall of bronze; they will fight against you but will not overcome you, for I am with you to save and deliver you, declares the LORD.'),
('JER', 15, 21, 'JER.15.21', 'I will deliver you from the hand of the wicked and redeem you from the grasp of the ruthless.”'),
('JER', 16, 1, 'JER.16.1', 'Then the word of the LORD came to me, saying,'),
('JER', 16, 2, 'JER.16.2', '“You must not marry or have sons or daughters in this place.”'),
('JER', 16, 3, 'JER.16.3', 'For this is what the LORD says concerning the sons and daughters born in this place, and the mothers who bore them, and the fathers who fathered them in this land:'),
('JER', 16, 4, 'JER.16.4', '“They will die from deadly diseases. They will not be mourned or buried, but will lie like dung on the ground. They will be finished off by sword and famine, and their corpses will become food for the birds of the air and beasts of the earth.”'),
('JER', 16, 5, 'JER.16.5', 'Indeed, this is what the LORD says: “Do not enter a house where there is a funeral meal. Do not go to mourn or show sympathy, for I have removed from this people My peace, My loving devotion, and My compassion,” declares the LORD.'),
('JER', 16, 6, 'JER.16.6', '“Both great and small will die in this land. They will not be buried or mourned, nor will anyone cut himself or shave his head for them.'),
('JER', 16, 7, 'JER.16.7', 'No food will be offered to comfort those who mourn the dead; not even a cup of consolation will be given for the loss of a father or mother.'),
('JER', 16, 8, 'JER.16.8', 'You must not enter a house where there is feasting and sit down with them to eat and drink.'),
('JER', 16, 9, 'JER.16.9', 'For this is what the LORD of Hosts, the God of Israel, says: I am going to remove from this place, before your very eyes and in your days, the sounds of joy and gladness, the voices of the bride and bridegroom.'),
('JER', 16, 10, 'JER.16.10', 'When you tell these people all these things, they will ask you, ‘Why has the LORD pronounced all this great disaster against us? What is our iniquity? What is the sin that we have committed against the LORD our God?’'),
('JER', 16, 11, 'JER.16.11', 'Then you are to answer them: ‘It is because your fathers have forsaken Me, declares the LORD, and followed other gods, and served and worshiped them. They abandoned Me and did not keep My instruction.'),
('JER', 16, 12, 'JER.16.12', 'And you have done more evil than your fathers. See how each of you follows the stubbornness of his evil heart instead of obeying Me.'),
('JER', 16, 13, 'JER.16.13', 'So I will cast you out of this land into a land that neither you nor your fathers have known. There you will serve other gods day and night, for I will show you no favor.’'),
('JER', 16, 14, 'JER.16.14', 'Yet behold, the days are coming, declares the LORD, when they will no longer say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of Egypt.’'),
('JER', 16, 15, 'JER.16.15', 'Instead they will say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of the north and all the other lands to which He had banished them.’ For I will return them to their land that I gave to their forefathers.'),
('JER', 16, 16, 'JER.16.16', 'But for now I will send for many fishermen, declares the LORD, and they will catch them. After that I will send for many hunters, and they will hunt them down on every mountain and hill, even from the clefts of the rocks.'),
('JER', 16, 17, 'JER.16.17', 'For My eyes are on all their ways. They are not hidden from My face, and their guilt is not concealed from My eyes.'),
('JER', 16, 18, 'JER.16.18', 'And I will first repay them double their iniquity and their sin, because they have defiled My land with the carcasses of their detestable idols, and they have filled My inheritance with their abominations.”'),
('JER', 16, 19, 'JER.16.19', 'O LORD, my strength and my fortress, my refuge in the day of distress, the nations will come to You from the ends of the earth, and they will say, “Our fathers inherited nothing but lies, worthless idols of no benefit at all.'),
('JER', 16, 20, 'JER.16.20', 'Can man make gods for himself? Such are not gods!”'),
('JER', 16, 21, 'JER.16.21', '“Therefore behold, I will inform them, and this time I will make them know My power and My might; then they will know that My name is the LORD.'),
('JER', 17, 1, 'JER.17.1', '“The sin of Judah is written with an iron stylus, engraved with a diamond point on the tablets of their hearts and on the horns of their altars.'),
('JER', 17, 2, 'JER.17.2', 'Even their children remember their altars and Asherah poles by the green trees and on the high hills.'),
('JER', 17, 3, 'JER.17.3', 'O My mountain in the countryside, I will give over your wealth and all your treasures as plunder, because of the sin of your high places, within all your borders.'),
('JER', 17, 4, 'JER.17.4', 'And you yourself will relinquish the inheritance that I gave you. I will enslave you to your enemies in a land that you do not know, for you have kindled My anger; it will burn forever.”'),
('JER', 17, 5, 'JER.17.5', 'This is what the LORD says: “Cursed is the man who trusts in mankind, who makes mere flesh his strength and turns his heart from the LORD.'),
('JER', 17, 6, 'JER.17.6', 'He will be like a shrub in the desert; he will not see when prosperity comes. He will dwell in the parched places of the desert, in a salt land where no one lives.'),
('JER', 17, 7, 'JER.17.7', 'But blessed is the man who trusts in the LORD, whose confidence is in Him.'),
('JER', 17, 8, 'JER.17.8', 'He is like a tree planted by the waters that sends out its roots toward the stream. It does not fear when the heat comes, and its leaves are always green. It does not worry in a year of drought, nor does it cease to produce fruit.'),
('JER', 17, 9, 'JER.17.9', 'The heart is deceitful above all things and beyond cure. Who can understand it?'),
('JER', 17, 10, 'JER.17.10', 'I, the LORD, search the heart; I examine the mind to reward a man according to his way, by what his deeds deserve.'),
('JER', 17, 11, 'JER.17.11', 'Like a partridge hatching eggs it did not lay is the man who makes a fortune unjustly. In the middle of his days his riches will desert him, and in the end he will be the fool.”'),
('JER', 17, 12, 'JER.17.12', 'A glorious throne, exalted from the beginning, is the place of our sanctuary.'),
('JER', 17, 13, 'JER.17.13', 'O LORD, the hope of Israel, all who abandon You will be put to shame. All who turn away will be written in the dust, for they have abandoned the LORD, the fountain of living water.'),
('JER', 17, 14, 'JER.17.14', 'Heal me, O LORD, and I will be healed; save me, and I will be saved, for You are my praise.'),
('JER', 17, 15, 'JER.17.15', 'Behold, they keep saying to me, “Where is the word of the LORD? Let it come now!”'),
('JER', 17, 16, 'JER.17.16', 'But I have not run away from being Your shepherd; I have not desired the day of despair. You know that the utterance of my lips was spoken in Your presence.'),
('JER', 17, 17, 'JER.17.17', 'Do not become a terror to me; You are my refuge in the day of disaster.'),
('JER', 17, 18, 'JER.17.18', 'Let my persecutors be put to shame, but do not let me be put to shame. Let them be terrified, but do not let me be terrified. Bring upon them the day of disaster and shatter them with double destruction.'),
('JER', 17, 19, 'JER.17.19', 'This is what the LORD said to me: “Go and stand at the gate of the people, through which the kings of Judah go in and out; and stand at all the other gates of Jerusalem.'),
('JER', 17, 20, 'JER.17.20', 'Say to them, ‘Hear the word of the LORD, O kings of Judah, all people of Judah and Jerusalem who enter through these gates.'),
('JER', 17, 21, 'JER.17.21', 'This is what the LORD says: Take heed for yourselves; do not carry a load or bring it through the gates of Jerusalem on the Sabbath day.'),
('JER', 17, 22, 'JER.17.22', 'You must not carry a load out of your houses or do any work on the Sabbath day, but you must keep the Sabbath day holy, just as I commanded your forefathers.'),
('JER', 17, 23, 'JER.17.23', 'Yet they would not listen or incline their ear, but they stiffened their necks and would not listen or receive My discipline.'),
('JER', 17, 24, 'JER.17.24', 'If, however, you listen carefully to Me, says the LORD, and bring no load through the gates of this city on the Sabbath day, and keep the Sabbath day holy, and do no work on it,'),
('JER', 17, 25, 'JER.17.25', 'then kings and princes will enter through the gates of this city. They will sit on the throne of David, riding in chariots and on horses with their officials, along with the men of Judah and the residents of Jerusalem, and this city will be inhabited forever.'),
('JER', 17, 26, 'JER.17.26', 'And people will come from the cities of Judah and the places around Jerusalem, from the land of Benjamin, and from the foothills, the hill country, and the Negev, bringing burnt offerings and sacrifices, grain offerings and frankincense, and thank offerings to the house of the LORD.'),
('JER', 17, 27, 'JER.17.27', 'But if you do not listen to Me to keep the Sabbath day holy by not carrying a load while entering the gates of Jerusalem on the Sabbath day, then I will kindle an unquenchable fire in its gates to consume the citadels of Jerusalem.’”'),
('JER', 18, 1, 'JER.18.1', 'This is the word that came to Jeremiah from the LORD:'),
('JER', 18, 2, 'JER.18.2', '“Go down at once to the potter’s house, and there I will give you My message.”'),
('JER', 18, 3, 'JER.18.3', 'So I went down to the potter’s house and saw him working at the wheel.'),
('JER', 18, 4, 'JER.18.4', 'But the vessel that he was shaping from the clay became flawed in his hand; so he formed it into another vessel, as it seemed best for him to do.'),
('JER', 18, 5, 'JER.18.5', 'Then the word of the LORD came to me, saying,'),
('JER', 18, 6, 'JER.18.6', '“O house of Israel, declares the LORD, can I not treat you as this potter treats his clay? Just like clay in the potter’s hand, so are you in My hand, O house of Israel.'),
('JER', 18, 7, 'JER.18.7', 'At any time I might announce that a nation or kingdom will be uprooted, torn down, and destroyed.'),
('JER', 18, 8, 'JER.18.8', 'But if that nation I warned turns from its evil, then I will relent of the disaster I had planned to bring.'),
('JER', 18, 9, 'JER.18.9', 'And if at another time I announce that I will build up and establish a nation or kingdom,'),
('JER', 18, 10, 'JER.18.10', 'and if it does evil in My sight and does not listen to My voice, then I will relent of the good I had intended for it.'),
('JER', 18, 11, 'JER.18.11', 'Now therefore, tell the men of Judah and the residents of Jerusalem that this is what the LORD says: ‘Behold, I am planning a disaster for you and devising a plan against you. Turn now, each of you, from your evil ways, and correct your ways and deeds.’'),
('JER', 18, 12, 'JER.18.12', 'But they will reply, ‘It is hopeless. We will follow our own plans, and each of us will act according to the stubbornness of his evil heart.’”'),
('JER', 18, 13, 'JER.18.13', 'Therefore this is what the LORD says: “Inquire among the nations: Who has ever heard things like these? Virgin Israel has done a most terrible thing.'),
('JER', 18, 14, 'JER.18.14', 'Does the snow of Lebanon ever leave its rocky slopes? Or do its cool waters flowing from a distance ever run dry?'),
('JER', 18, 15, 'JER.18.15', 'Yet My people have forgotten Me. They burn incense to worthless idols that make them stumble in their ways, leaving the ancient roads to walk on rutted bypaths instead of on the highway.'),
('JER', 18, 16, 'JER.18.16', 'They have made their land a desolation, a perpetual object of scorn; all who pass by will be appalled and shake their heads.'),
('JER', 18, 17, 'JER.18.17', 'I will scatter them before the enemy like the east wind. I will show them My back and not My face in the day of their calamity.”'),
('JER', 18, 18, 'JER.18.18', 'Then some said, “Come, let us make plans against Jeremiah, for the law will never be lost to the priest, nor counsel to the wise, nor an oracle to the prophet. Come, let us denounce him and pay no heed to any of his words.”'),
('JER', 18, 19, 'JER.18.19', 'Attend to me, O LORD. Hear what my accusers are saying!'),
('JER', 18, 20, 'JER.18.20', 'Should good be repaid with evil? Yet they have dug a pit for me. Remember how I stood before You to speak good on their behalf, to turn Your wrath from them.'),
('JER', 18, 21, 'JER.18.21', 'Therefore, hand their children over to famine; pour out the power of the sword upon them. Let their wives become childless and widowed; let their husbands be slain by disease, their young men struck down by the sword in battle.'),
('JER', 18, 22, 'JER.18.22', 'Let a cry be heard from their houses when You suddenly bring raiders against them, for they have dug a pit to capture me and have hidden snares for my feet.'),
('JER', 18, 23, 'JER.18.23', 'But You, O LORD, know all their deadly plots against me. Do not wipe out their guilt or blot out their sin from Your sight. Let them be overthrown before You; deal with them in the time of Your anger.'),
('JER', 19, 1, 'JER.19.1', 'This is what the LORD says: “Go and buy a clay jar from a potter. Take some of the elders of the people and leaders of the priests,'),
('JER', 19, 2, 'JER.19.2', 'and go out to the Valley of Ben-hinnom near the entrance of the Potsherd Gate. Proclaim there the words I speak to you,'),
('JER', 19, 3, 'JER.19.3', 'saying, ‘Hear the word of the LORD, O kings of Judah and residents of Jerusalem. This is what the LORD of Hosts, the God of Israel, says: I am going to bring such disaster on this place that the ears of all who hear of it will ring,'),
('JER', 19, 4, 'JER.19.4', 'because they have abandoned Me and made this a foreign place. They have burned incense in this place to other gods that neither they nor their fathers nor the kings of Judah have ever known. They have filled this place with the blood of the innocent.'),
('JER', 19, 5, 'JER.19.5', 'They have built high places to Baal on which to burn their children in the fire as offerings to Baal—something I never commanded or mentioned, nor did it even enter My mind.'),
('JER', 19, 6, 'JER.19.6', 'So behold, the days are coming, declares the LORD, when this place will no longer be called Topheth or the Valley of Ben-hinnom, but the Valley of Slaughter.'),
('JER', 19, 7, 'JER.19.7', 'And in this place I will ruin the plans of Judah and Jerusalem. I will make them fall by the sword before their enemies, by the hands of those who seek their lives, and I will give their carcasses as food to the birds of the air and the beasts of the earth.'),
('JER', 19, 8, 'JER.19.8', 'I will make this city a desolation and an object of scorn. All who pass by will be appalled and will scoff at all her wounds.'),
('JER', 19, 9, 'JER.19.9', 'I will make them eat the flesh of their sons and daughters, and they will eat one another’s flesh in the siege and distress inflicted on them by their enemies who seek their lives.’'),
('JER', 19, 10, 'JER.19.10', 'Then you are to shatter the jar in the presence of the men who accompany you,'),
('JER', 19, 11, 'JER.19.11', 'and you are to proclaim to them that this is what the LORD of Hosts says: I will shatter this nation and this city, like one shatters a potter’s jar that can never again be repaired. They will bury the dead in Topheth until there is no more room to bury them.'),
('JER', 19, 12, 'JER.19.12', 'This is what I will do to this place and to its residents, declares the LORD. I will make this city like Topheth.'),
('JER', 19, 13, 'JER.19.13', 'The houses of Jerusalem and the houses of the kings of Judah will be defiled like that place, Topheth—all the houses on whose rooftops they burned incense to all the host of heaven and poured out drink offerings to other gods.”'),
('JER', 19, 14, 'JER.19.14', 'Then Jeremiah returned from Topheth, where the LORD had sent him to prophesy, and he stood in the courtyard of the house of the LORD and proclaimed to all the people,'),
('JER', 19, 15, 'JER.19.15', '“This is what the LORD of Hosts, the God of Israel, says: ‘Behold, I am about to bring on this city and on all the villages around it every disaster I have pronounced against them, because they have stiffened their necks so as not to heed My words.’”'),
('JER', 20, 1, 'JER.20.1', 'When Pashhur the priest, the son of Immer and the chief official in the house of the LORD, heard Jeremiah prophesying these things,'),
('JER', 20, 2, 'JER.20.2', 'he had Jeremiah the prophet beaten and put in the stocks at the Upper Gate of Benjamin, which was by the house of the LORD.'),
('JER', 20, 3, 'JER.20.3', 'The next day, when Pashhur released Jeremiah from the stocks, Jeremiah said to him, “The LORD does not call you Pashhur, but Magor-missabib.'),
('JER', 20, 4, 'JER.20.4', 'For this is what the LORD says: ‘I will make you a terror to yourself and to all your friends. They will fall by the sword of their enemies before your very eyes. And I will hand Judah over to the king of Babylon, and he will carry them away to Babylon and put them to the sword.'),
('JER', 20, 5, 'JER.20.5', 'I will give away all the wealth of this city—all its products and valuables, and all the treasures of the kings of Judah—to their enemies. They will plunder them, seize them, and carry them off to Babylon.'),
('JER', 20, 6, 'JER.20.6', 'And you, Pashhur, and all who live in your house, will go into captivity. You will go to Babylon, and there you will die and be buried—you and all your friends to whom you have prophesied these lies.’”'),
('JER', 20, 7, 'JER.20.7', 'You have deceived me, O LORD, and I was deceived. You have overcome me and prevailed. I am a laughingstock all day long; everyone mocks me.'),
('JER', 20, 8, 'JER.20.8', 'For whenever I speak, I cry out; I proclaim violence and destruction. For the word of the LORD has become to me a reproach and derision all day long.'),
('JER', 20, 9, 'JER.20.9', 'If I say, “I will not mention Him or speak any more in His name,” His message becomes a fire burning in my heart, shut up in my bones, and I become weary of holding it in, and I cannot prevail.'),
('JER', 20, 10, 'JER.20.10', 'For I have heard the whispering of many: “Terror is on every side! Report him; let us report him!” All my trusted friends watch for my fall: “Perhaps he will be deceived so that we may prevail against him and take our vengeance upon him.”'),
('JER', 20, 11, 'JER.20.11', 'But the LORD is with me like a fearsome warrior. Therefore, my persecutors will stumble and will not prevail. Since they have not succeeded, they will be utterly put to shame, with an everlasting disgrace that will never be forgotten.'),
('JER', 20, 12, 'JER.20.12', 'O LORD of Hosts, who examines the righteous, who sees the heart and mind, let me see Your vengeance upon them, for to You I have committed my cause.'),
('JER', 20, 13, 'JER.20.13', 'Sing to the LORD! Praise the LORD! For He rescues the life of the needy from the hands of evildoers.'),
('JER', 20, 14, 'JER.20.14', 'Cursed be the day I was born! May the day my mother bore me never be blessed.'),
('JER', 20, 15, 'JER.20.15', 'Cursed be the man who brought my father the news, saying, “A son is born to you,” bringing him great joy.'),
('JER', 20, 16, 'JER.20.16', 'May that man be like the cities that the LORD overthrew without compassion. May he hear an outcry in the morning and a battle cry at noon,'),
('JER', 20, 17, 'JER.20.17', 'because he did not kill me in the womb so that my mother might have been my grave, and her womb forever enlarged.'),
('JER', 20, 18, 'JER.20.18', 'Why did I come out of the womb to see only trouble and sorrow, and to end my days in shame?'),
('JER', 21, 1, 'JER.21.1', 'This is the word that came to Jeremiah from the LORD when King Zedekiah sent to him Pashhur son of Malchijah and the priest Zephaniah son of Maaseiah. They said,'),
('JER', 21, 2, 'JER.21.2', '“Please inquire of the LORD on our behalf, since Nebuchadnezzar king of Babylon is waging war against us. Perhaps the LORD will perform for us something like all His past wonders, so that Nebuchadnezzar will withdraw from us.”'),
('JER', 21, 3, 'JER.21.3', 'But Jeremiah answered, “You are to tell Zedekiah that'),
('JER', 21, 4, 'JER.21.4', 'this is what the LORD, the God of Israel, says: ‘I will turn against you the weapons of war in your hands, with which you are fighting the king of Babylon and the Chaldeans who besiege you outside the wall, and I will assemble their forces in the center of this city.'),
('JER', 21, 5, 'JER.21.5', 'And I Myself will fight against you with an outstretched hand and a mighty arm, with anger, fury, and great wrath.'),
('JER', 21, 6, 'JER.21.6', 'I will strike down the residents of this city, both man and beast. They will die in a terrible plague.’'),
('JER', 21, 7, 'JER.21.7', '‘After that,’ declares the LORD, ‘I will hand over Zedekiah king of Judah, his officers, and the people in this city who survive the plague and sword and famine, to Nebuchadnezzar king of Babylon and to their enemies who seek their lives. He will put them to the sword; he will not spare them or show pity or compassion.’'),
('JER', 21, 8, 'JER.21.8', 'Furthermore, you are to tell this people that this is what the LORD says: ‘Behold, I set before you the way of life and the way of death.'),
('JER', 21, 9, 'JER.21.9', 'Whoever stays in this city will die by sword and famine and plague, but whoever goes out and surrenders to the Chaldeans who besiege you will live; he will retain his life like a spoil of war.'),
('JER', 21, 10, 'JER.21.10', 'For I have set My face against this city to bring disaster and not good, declares the LORD. It will be delivered into the hand of the king of Babylon, who will destroy it with fire.’'),
('JER', 21, 11, 'JER.21.11', 'Moreover, tell the house of the king of Judah to hear the word of the LORD.'),
('JER', 21, 12, 'JER.21.12', 'O house of David, this is what the LORD says: ‘Administer justice every morning, and rescue the victim of robbery from the hand of his oppressor, or My wrath will go forth like fire and burn with no one to extinguish it because of their evil deeds.'),
('JER', 21, 13, 'JER.21.13', 'Behold, I am against you who dwell above the valley, atop the rocky plateau—declares the LORD—you who say, “Who can come against us? Who can enter our dwellings?”'),
('JER', 21, 14, 'JER.21.14', 'I will punish you as your deeds deserve, declares the LORD. I will kindle a fire in your forest that will consume everything around you.’”'),
('JER', 22, 1, 'JER.22.1', 'This is what the LORD says: “Go down to the palace of the king of Judah and proclaim this message there,'),
('JER', 22, 2, 'JER.22.2', 'saying, ‘Hear the word of the LORD, O king of Judah, who sits on the throne of David—you and your officials and your people who enter these gates.'),
('JER', 22, 3, 'JER.22.3', 'This is what the LORD says: Administer justice and righteousness. Rescue the victim of robbery from the hand of his oppressor. Do no wrong or violence to the foreigner, the fatherless, or the widow. Do not shed innocent blood in this place.'),
('JER', 22, 4, 'JER.22.4', 'For if you will indeed carry out these commands, then kings who sit on David’s throne will enter through the gates of this palace riding on chariots and horses—they and their officials and their people.'),
('JER', 22, 5, 'JER.22.5', 'But if you do not obey these words, then I swear by Myself, declares the LORD, that this house will become a pile of rubble.’”'),
('JER', 22, 6, 'JER.22.6', 'For this is what the LORD says concerning the house of the king of Judah: “You are like Gilead to Me, like the summit of Lebanon; but I will surely turn you into a desert, like cities that are uninhabited.'),
('JER', 22, 7, 'JER.22.7', 'I will appoint destroyers against you, each man with his weapons, and they will cut down the choicest of your cedars and throw them into the fire.'),
('JER', 22, 8, 'JER.22.8', 'And many nations will pass by this city and ask one another, ‘Why has the LORD done such a thing to this great city?’'),
('JER', 22, 9, 'JER.22.9', 'Then people will reply, ‘Because they have forsaken the covenant of the LORD their God and have worshiped and served other gods.’”'),
('JER', 22, 10, 'JER.22.10', 'Do not weep for him who is dead; do not mourn his loss. Weep bitterly for him who is exiled, for he will never return to see his native land.'),
('JER', 22, 11, 'JER.22.11', 'For this is what the LORD says concerning Shallum son of Josiah, king of Judah, who succeeded his father Josiah but has gone forth from this place: “He will never return,'),
('JER', 22, 12, 'JER.22.12', 'but he will die in the place to which he was exiled; he will never see this land again.”'),
('JER', 22, 13, 'JER.22.13', '“Woe to him who builds his palace by unrighteousness, and his upper rooms without justice, who makes his countrymen serve without pay, and fails to pay their wages,'),
('JER', 22, 14, 'JER.22.14', 'who says, ‘I will build myself a great palace, with spacious upper rooms.’ So he cuts windows in it, panels it with cedar, and paints it with vermilion.'),
('JER', 22, 15, 'JER.22.15', 'Does it make you a king to excel in cedar? Did not your father have food and drink? He administered justice and righteousness, and so it went well with him.'),
('JER', 22, 16, 'JER.22.16', 'He took up the cause of the poor and needy, and so it went well with him. Is this not what it means to know Me?” declares the LORD.'),
('JER', 22, 17, 'JER.22.17', '“But your eyes and heart are set on nothing except your own dishonest gain, on shedding innocent blood, on practicing extortion and oppression.”'),
('JER', 22, 18, 'JER.22.18', 'Therefore this is what the LORD says concerning Jehoiakim son of Josiah king of Judah: “They will not mourn for him: ‘Alas, my brother! Alas, my sister!’ They will not mourn for him: ‘Alas, my master! Alas, his splendor!’'),
('JER', 22, 19, 'JER.22.19', 'He will be buried like a donkey, dragged away and thrown outside the gates of Jerusalem.'),
('JER', 22, 20, 'JER.22.20', 'Go up to Lebanon and cry out; raise your voice in Bashan; cry out from Abarim, for all your lovers have been crushed.'),
('JER', 22, 21, 'JER.22.21', 'I warned you when you were secure. You said, ‘I will not listen.’ This has been your way from youth, that you have not obeyed My voice.'),
('JER', 22, 22, 'JER.22.22', 'The wind will drive away all your shepherds, and your lovers will go into captivity. Then you will be ashamed and humiliated because of all your wickedness.'),
('JER', 22, 23, 'JER.22.23', 'O inhabitant of Lebanon, nestled in the cedars, how you will groan when pangs of anguish come upon you, agony like a woman in labor.”'),
('JER', 22, 24, 'JER.22.24', '“As surely as I live,” declares the LORD, “even if you, Coniah son of Jehoiakim king of Judah, were a signet ring on My right hand, I would pull you off.'),
('JER', 22, 25, 'JER.22.25', 'In fact, I will hand you over to those you dread, who want to take your life—to Nebuchadnezzar king of Babylon and to the Chaldeans.'),
('JER', 22, 26, 'JER.22.26', 'I will hurl you and the mother who gave you birth into another land, where neither of you were born—and there you both will die.'),
('JER', 22, 27, 'JER.22.27', 'You will never return to the land for which you long.”'),
('JER', 22, 28, 'JER.22.28', 'Is this man Coniah a despised and shattered pot, a jar that no one wants? Why are he and his descendants hurled out and cast into a land they do not know?'),
('JER', 22, 29, 'JER.22.29', 'O land, land, land, hear the word of the LORD!'),
('JER', 22, 30, 'JER.22.30', 'This is what the LORD says: “Enroll this man as childless, a man who will not prosper in his lifetime. None of his descendants will prosper to sit on the throne of David or to rule again in Judah.”'),
('JER', 23, 1, 'JER.23.1', '“Woe to the shepherds who destroy and scatter the sheep of My pasture!” declares the LORD.'),
('JER', 23, 2, 'JER.23.2', 'Therefore this is what the LORD, the God of Israel, says about the shepherds who tend My people: “You have scattered My flock and driven them away, and have not attended to them. Behold, I will attend to you for the evil of your deeds, declares the LORD.'),
('JER', 23, 3, 'JER.23.3', 'Then I Myself will gather the remnant of My flock from all the lands to which I have banished them, and I will return them to their pasture, where they will be fruitful and multiply.'),
('JER', 23, 4, 'JER.23.4', 'I will raise up shepherds over them who will tend them, and they will no longer be afraid or dismayed, nor will any go missing, declares the LORD.'),
('JER', 23, 5, 'JER.23.5', 'Behold, the days are coming, declares the LORD, when I will raise up for David a righteous Branch, and He will reign wisely as King and will administer justice and righteousness in the land.'),
('JER', 23, 6, 'JER.23.6', 'In His days Judah will be saved, and Israel will dwell securely. And this is His name by which He will be called: The LORD Our Righteousness.'),
('JER', 23, 7, 'JER.23.7', 'So behold, the days are coming, declares the LORD, when they will no longer say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of Egypt.’'),
('JER', 23, 8, 'JER.23.8', 'Instead they will say, ‘As surely as the LORD lives, who brought and led the descendants of the house of Israel up out of the land of the north and all the other lands to which He had banished them.’ Then they will dwell once more in their own land.”'),
('JER', 23, 9, 'JER.23.9', 'As for the prophets: My heart is broken within me, and all my bones tremble. I have become like a drunkard, like a man overcome by wine, because of the LORD, because of His holy words.'),
('JER', 23, 10, 'JER.23.10', 'For the land is full of adulterers—because of the curse, the land mourns and the pastures of the wilderness have dried up—their course is evil and their power is misused.'),
('JER', 23, 11, 'JER.23.11', '“For both prophet and priest are ungodly; even in My house I have found their wickedness,” declares the LORD.'),
('JER', 23, 12, 'JER.23.12', '“Therefore their path will become slick; they will be driven away into the darkness and fall into it. For I will bring disaster upon them in the year of their punishment,” declares the LORD.'),
('JER', 23, 13, 'JER.23.13', '“Among the prophets of Samaria I saw an offensive thing: They prophesied by Baal and led My people Israel astray.'),
('JER', 23, 14, 'JER.23.14', 'And among the prophets of Jerusalem I have seen a horrible thing: They commit adultery and walk in lies. They strengthen the hands of evildoers, so that no one turns his back on wickedness. They are all like Sodom to Me; the people of Jerusalem are like Gomorrah.”')
) as x(osis, chapter, verse, ref, body)
join public.books b on b.osis_code = x.osis
join public.bible_versions v on v.id = b.version_id and v.code = 'BSB'
join public.chapters c on c.book_id = b.id and c.number = x.chapter
on conflict (chapter_id, number) do update set osis_ref = excluded.osis_ref, text = excluded.text;
